#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <spi/spi.h>

#define SPI_BUS_PATH "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define SPI_CS_GPIO 8

struct spi_device *spi = NULL;

void exit_handler(int signum) {
    if (spi) {
        spi_close(spi);
    }
    printf("Exiting...\n");
    exit(0);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint8_t tx[4] = {0x01, 0x80, 0x00, 0x00};
    uint8_t rx[4] = {0x00, 0x00, 0x00, 0x00};
    int ret;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    spi = spi_open_device(SPI_BUS_PATH, SPI_CHANNEL, SPI_CS_GPIO, SPI_MODE, SPI_MAX_SPEED_HZ);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = sizeof(tx);
        xfer.speed_hz = SPI_MAX_SPEED_HZ;
        xfer.bits_per_word = 8;

        ret = spi_transfer(spi, &xfer);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            exit_handler(0);
        }

        int value = (rx[1] & 0x03) << 8 | rx[2];
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestr[20];
        strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("%s: %d\n", timestr, value);

        sleep(1);
    }

    exit_handler(0);
    return 0;
}

