#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_MUX 0x3000
#define ADS1115_CONFIG_PGA 0x0C00
#define ADS1115_CONFIG_DR 0x00E0
#define ADS1115_CONFIG_MODE 0x0000
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_MUX | ADS1115_CONFIG_PGA | ADS1115_CONFIG_DR | ADS1115_CONFIG_MODE)

static int i2c_file = -1;

void sigint_handler(int signum) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    int ret;
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_file, I2C_SLAVE, ADS1115_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    uint16_t config = htobe16(ADS1115_CONFIG_DEFAULT);
    ret = write(i2c_file, &config, sizeof(config));
    if (ret != sizeof(config)) {
        perror("Failed to write to I2C device");
        return EXIT_FAILURE;
    }

    while (1) {
        usleep(500000);

        ret = write(i2c_file, &ADS1115_REG_CONVERSION, sizeof(ADS1115_REG_CONVERSION));
        if (ret != sizeof(ADS1115_REG_CONVERSION)) {
            perror("Failed to write to I2C device");
            return EXIT_FAILURE;
        }

        uint16_t result;
        ret = read(i2c_file, &result, sizeof(result));
        if (ret != sizeof(result)) {
            perror("Failed to read from I2C device");
            return EXIT_FAILURE;
        }

        result = be16toh(result);
        float current = (float)result * 4.096 / 32767.0;
        printf("Current: %.3f A\n", current);
    }

    return EXIT_SUCCESS;
}

