#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <spi0.h>

#define SPI_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define SPI_CS_GPIO 8
#define FLAME_SENSOR_GPIO 4

struct gpiod_chip *chip = NULL;
struct gpiod_line *flame_sensor_line = NULL;
struct spi0_device *spi_device = NULL;
FILE *file = NULL;

void cleanup_and_exit(int signum) {
    if (spi_device)
        spi0_close(spi_device);
    if (flame_sensor_line)
        gpiod_line_release(flame_sensor_line);
    if (chip)
        gpiod_chip_close(chip);
    if (file)
        fclose(file);
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup_and_exit(-1);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor")) {
        perror("gpiod_line_request_input");
        cleanup_and_exit(-1);
    }

    spi_device = spi0_open(Spi0DeviceConfig{.cs_gpio = SPI_CS_GPIO, .speed_hz = SPI_SPEED_HZ});
    if (!spi_device) {
        perror("spi0_open");
        cleanup_and_exit(-1);
    }

    file = fopen("flame_data.csv", "w");
    if (!file) {
        perror("fopen");
        cleanup_and_exit(-1);
    }

    while (1) {
        int flame_detected = gpiod_line_get_value(flame_sensor_line);
        if (flame_detected < 0) {
            perror("gpiod_line_get_value");
            continue;
        }

        uint16_t adc_value;
        if (spi0_transfer(spi_device, (uint8_t[]){0x01, 0x80}, (uint8_t[]){0x00}, 2, &adc_value, 2)) {
            perror("spi0_transfer");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Approximate temperature using a simple linear mapping from ADC value to 0-100 degree Celsius
        float temperature = adc_value * 100.0f / 1023.0f;

        fprintf(file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
        fflush(file);

        sleep(1);
    }

    cleanup_and_exit(0);
}

