#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include "libgpiod.h"
#include "ads1115.h"

#define FLAME_SENSOR_GPIO 4
#define HEAT_SENSOR_I2C_BUS 1
#define HEAT_SENSOR_I2C_ADDR 0x48
#define HEAT_SENSOR_CHANNEL 0
#define BUZZER_GPIO 27
#define FILE_NAME "fire_log.txt"
#define DEBOUNCE_TIME 50
#define POLL_TIME 100
#define FIRE_TEMP 60
#define BUZZER_DURATION 2

struct gpiod_chip *chip;
struct gpiod_line *flame_sensor, *buzzer;
FILE *log_file;
struct ads1115_handle *ads1115;
int running = 1;

void handle_sigint(int signum) {
    running = 0;
}

void cleanup_and_exit(int code) {
    if (buzzer)
        gpiod_line_set_value(buzzer, 0);
    if (flame_sensor)
        gpiod_line_release(flame_sensor);
    if (buzzer)
        gpiod_line_release(buzzer);
    if (chip)
        gpiod_chip_close(chip);
    if (ads1115)
        ads1115_close(ads1115);
    if (log_file)
        fclose(log_file);
    exit(code);
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor) {
        fprintf(stderr, "Failed to get line %d: %s\n", FLAME_SENSOR_GPIO, strerror(errno));
        cleanup_and_exit(1);
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer) {
        fprintf(stderr, "Failed to get line %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_both_edges_events(flame_sensor, "flame_sensor")) {
        fprintf(stderr, "Failed to request line %d: %s\n", FLAME_SENSOR_GPIO, strerror(errno));
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0)) {
        fprintf(stderr, "Failed to request line %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup_and_exit(1);
    }

    ads1115 = ads1115_open(HEAT_SENSOR_I2C_BUS, HEAT_SENSOR_I2C_ADDR);
    if (!ads1115) {
        fprintf(stderr, "Failed to open ADS1115: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    if (ads1115_set_channel(ads1115, HEAT_SENSOR_CHANNEL, ADS1115_SINGLE_ENDED)) {
        fprintf(stderr, "Failed to set channel: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    log_file = fopen(FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    while (running) {
        int flame_value = gpiod_line_get_value(flame_sensor);
        int buzzer_value = gpiod_line_get_value(buzzer);
        int temp_value = ads1115_read_raw(ads1115);

        if (flame_value < 0 || buzzer_value < 0 || temp_value < 0) {
            fprintf(stderr, "Failed to read sensor: %s\n", strerror(errno));
            continue;
        }

        if (flame_value == 1 && temp_value > FIRE_TEMP) {
            if (buzzer_value == 0) {
                gpiod_line_set_value(buzzer, 1);
                sleep(BUZZER_DURATION);
                gpiod_line_set_value(buzzer, 0);
            }

            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            fprintf(log_file, "%s: Fire event detected!\n", timestamp);
            fflush(log_file);
        } else if (flame_value == 1) {
            fprintf(log_file, "Flame detected!\n");
            fflush(log_file);
        } else if (temp_value > FIRE_TEMP) {
            fprintf(log_file, "Temperature: %d\n", temp_value);
            fflush(log_file);
        }

        usleep(POLL_TIME * 1000);
    }

    cleanup_and_exit(0);
}

