    if (ret < 0) {
        perror("spi set order");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8);
    if (ret < 0) {
        perror("spi set bits per word");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000);
    if (ret < 0) {
        perror("spi set max speed");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip1");
    if (!chip) {
        chip = gpiod_chip_open(0);
        if (!chip) {
            perror("open gpio chip");
            return 1;
        }
    }

    line = gpiod_chip_get_line(chip, GPIO_FAN);
    if (!line) {
        perror("get gpio line");
        return 1;
    }

    ret = gpiod_line_request_output(line, "fan control", 0);
    if (ret < 0) {
        perror("request gpio line");
        return 1;
    }

    while (1) {
        xfer.tx_buf = (unsigned long)tx_buf;
        xfer.rx_buf = (unsigned long)rx_buf;
        xfer.len = 2;
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;
        xfer.delay_usecs = 0;
        xfer.cs_change = 0;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("spi transfer");
            return 1;
        }

        int value = (rx_buf[0] << 8) | rx_buf[1];
        if (value == 0 || value == 0xffff) {
            fprintf(stderr, "Sensor absent\n");
            continue;
