int main() {
    int ret;

    // Open I2C device
    i2c_dev = gpiod_device_open(I2C_BUS);
    if (!i2c_dev) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup_and_exit(-1);
    }

    // Request I2C line
    i2c_line = gpiod_device_get_line(i2c_dev, I2C_ADDR);
    if (!i2c_line) {
        fprintf(stderr, "Failed to get I2C line: %s\n", strerror(errno));
        cleanup_and_exit(-1);
    }

    // Open log file
    log_file = fopen(FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_and_exit(-1);
    }

    // Register signal handlers
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Main loop
    while (1) {
        // Read from sensor
