        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C slave");
        cleanup_and_exit(-1);
    }

    co_file = open(FILE_NAME, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (co_file == -1) {
        perror("Failed to open CO file");
        cleanup_and_exit(-1);
    }

    alert_file = open(ALERT_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (alert_file == -1) {
        perror("Failed to open alert file");
        cleanup_and_exit(-1);
    }

    char buffer[4];
    while (1) {
        if (read(i2c_file, buffer, 4) != 4) {
            perror("Failed to read from I2C device");
            cleanup_and_exit(-1);
        }

        // Convert the 16-bit ADC readings
        short ox = (buffer[0] << 8) | buffer[1];
        short red = (buffer[2] << 8) | buffer[3];

        // Convert the OX value to a CO concentration in ppm
        // This is a simplified conversion, actual conversion would require calibration
        float co_ppm = ox * 1.0f;

        char log_entry[32];
        sprintf(log_entry, "%f\n", co_ppm);
        if (write(co_file, log_entry, strlen(log_entry)) == -1) {
            perror("Failed to write to CO file");
            cleanup_and_exit(-1);
        }

        if (co_ppm >= ALERT_THRESHOLD) {
            sprintf(log_entry, "Alert: CO concentration exceeded %f ppm\n", ALERT_THRESHOLD);
            if (write(alert_file, log_entry, strlen(log_entry)) == -1) {
                perror("Failed to write to alert file");
                cleanup_and_exit(-1);
            }
        }

        sleep(5);
    }

    cleanup_and_exit(0);
}
