    gpiod_line_release(sda_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(signum);
}

void i2c_start() {
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);
    usleep(10);
    gpiod_line_set_value(scl_line, 0);
    usleep(10);
    gpiod_line_set_value(sda_line, 0);
    usleep(10);
}

void i2c_stop() {
    gpiod_line_set_value(scl_line, 0);
    usleep(10);
    gpiod_line_set_value(sda_line, 0);
    usleep(10);
    gpiod_line_set_value(scl_line, 1);
    usleep(10);
    gpiod_line_set_value(sda_line, 1);
    usleep(10);
}

int i2c_write(uint8_t data) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(scl_line, 0);
        usleep(10);
        gpiod_line_set_value(sda_line, (data >> i) & 1);
        usleep(10);
        gpiod_line_set_value(scl_line, 1);
        usleep(10);
    }

    gpiod_line_set_value(scl_line, 0);
    usleep(10);
    gpiod_line_set_value(sda_line, 1);
    usleep(10);
    gpiod_line_set_value(scl_line, 1);
    usleep(10);

