    gpiod_line_set_value(scl_line, 0);
    usleep(10);
    gpiod_line_set_value(sda_line, 0);
    usleep(10);

    return ack == 0;
}

float read_mic_level(int addr) {
    i2c_start();
    if (!i2c_write(addr)) {
        return -999.0;
    }
    i2c_stop();

    usleep(SAMPLE_RATE);

    i2c_start();
    if (!i2c_write(addr | 1)) {
        return -999.0;
    }

    int data = 0;
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(scl_line, 0);
        usleep(10);
        data |= gpiod_line_get_value(sda_line) << i;
        gpiod_line_set_value(scl_line, 1);
        usleep(10);
    }

    gpiod_line_set_value(scl_line, 0);
    usleep(10);
    gpiod_line_set_value(sda_line, 1);
    usleep(10);
    gpiod_line_set_value(scl_line, 1);
    usleep(10);

    i2c_stop();

    return data * 0.0000625; // convert to dB
}

int main() {
    chip = gpiod_chip_open_by_number(I2C_BUS);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    scl_line = gpiod_chip_get_line(chip, 2);
    if (!scl_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    sda_line = gpiod_chip_get_line(chip, 3);
    if (!sda_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(scl_line, "i2c_scl", 1) ||
        gpiod_line_request_output(sda_line, "i2c_sda", 1)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        float mic1_level = read_mic_level(MIC1_ADDR);
        float mic2_level = read_mic_level(MIC2_ADDR);

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %.1f %.1f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                mic1_level, mic2_level);

        fflush(log_file);
    }

    return 0;
}

