#include <spi0.h>

#define SPI_DEV "/dev/spi0"
#define CS0_GPIO 8
#define CS1_GPIO 9
#define LED_GPIO 27
#define SAMPLE_RATE 100
#define THRESHOLD 0.5
#define CS0_CHANNEL 0
#define CS1_CHANNEL 1

struct gpiod_chip *chip;
struct gpiod_line *cs0_line, *cs1_line, *led_line;
struct spi0_ctx *spi_ctx;
FILE *file;

void cleanup_and_exit(int signum) {
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(cs0_line);
    gpiod_line_release(cs1_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    spi0_close(spi_ctx);
    fclose(file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    cs0_line = gpiod_chip_get_line(chip, CS0_GPIO);
    if (!cs0_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    cs1_line = gpiod_chip_get_line(chip, CS1_GPIO);
    if (!cs1_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(cs0_line, "cs0", 1) ||
        gpiod_line_request_output(cs1_line, "cs1", 1) ||
        gpiod_line_request_output(led_line, "led", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    spi_ctx = spi0_open(SPI_DEV, CS0_GPIO, CS1_GPIO);
    if (!spi_ctx) {
        perror("spi0_open");
        return 1;
    }

    file = fopen("audio_events.csv", "w");
    if (!file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    double samples[2][SAMPLE_RATE];
    while (1) {
        for (int i = 0; i < SAMPLE_RATE; i++) {
            samples[0][i] = spi0_read(spi_ctx, CS0_CHANNEL);
            samples[1][i] = spi0_read(spi_ctx, CS1_CHANNEL);
        }

        double rms[2];
        for (int i = 0; i < 2; i++) {
            double sum = 0;
            for (int j = 0; j < SAMPLE_RATE; j++)
                sum += samples[i][j] * samples[i][j];
            rms[i] = sqrt(sum / SAMPLE_RATE);
        }

        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tmp);

        fprintf(file, "%s,%f,%f\n", timestamp, rms[0], rms[1]);

        if (rms[0] > THRESHOLD || rms[1] > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
        }
    }

    return 0;
}

