#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

#define ADS1115_CONFIG_DEFAULT 0x8583
#define ADS1115_CONFIG_DR_10Hz 0x0008
#define ADS1115_CONFIG_CH_AIN0 0x4000

#define ADS1115_OS_SINGLE 0x8000

#define ADS1115_TO_VOLTS(raw) ((raw) * 0.000244)
#define ADS1115_TO_CURRENT(volts) ((volts) * 0.0068)

#define CIRC_BUF_SIZE 100

struct state {
    int i2c_fd;
    struct gpiod_chip *gpio_chip;
    struct gpiod_line *gpio_line;
    int *circ_buf;
    int circ_buf_idx;
    double circ_buf_sum;
};

static void cleanup(struct state *st) {
    if (st->gpio_line)
        gpiod_line_set_value(st->gpio_line, 0);
    if (st->gpio_chip)
        gpiod_chip_close(st->gpio_chip);
    if (st->i2c_fd >= 0)
        close(st->i2c_fd);
    if (st->circ_buf)
        free(st->circ_buf);
    printf("Shutdown complete.\n");
}

static void sigint_handler(int signum) {
    static struct state *saved_state;
    if (!saved_state) {
        saved_state = malloc(sizeof(struct state));
        memset(saved_state, 0, sizeof(struct state));
        saved_state->i2c_fd = open("/dev/i2c-1", O_RDWR);
        ioctl(saved_state->i2c_fd, I2C_SLAVE, ADS1115_ADDRESS);
        saved_state->gpio_chip = gpiod_chip_open_by_name("gpiochip0");
        saved_state->gpio_line = gpiod_chip_get_line(saved_state->gpio_chip, 17);
        gpiod_line_request_output(saved_state->gpio_line, "current_sensor", 0);
    } else {
        cleanup(saved_state);
        free(saved_state);
        saved_state = NULL;
        exit(0);
    }
}

int main() {
    struct state st = {
        .i2c_fd = -1,
        .gpio_chip = NULL,
        .gpio_line = NULL,
        .circ_buf = NULL,
        .circ_buf_idx = 0,
        .circ_buf_sum = 0.0,
    };

    signal(SIGINT, sigint_handler);

    st.i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (st.i2c_fd < 0) {
        perror("open");
        goto error;
    }

    if (ioctl(st.i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("ioctl");
        goto error;
    }

    if (write(st.i2c_fd, &ADS1115_CONFIG_DEFAULT, 2) != 2) {
        perror("write");
        goto error;
    }

    st.gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!st.gpio_chip) {
        perror("gpiod_chip_open_by_name");
        goto error;
    }

    st.gpio_line = gpiod_chip_get_line(st.gpio_chip, 17);
    if (!st.gpio_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_output(st.gpio_line, "current_sensor", 0)) {
        perror("gpiod_line_request_output");
        goto error;
    }

    st.circ_buf = malloc(CIRC_BUF_SIZE * sizeof(int));
    if (!st.circ_buf) {
        perror("malloc");
        goto error;
    }

    while (1) {
        uint16_t config = ADS1115_OS_SINGLE | ADS1115_CONFIG_CH_AIN0 |
                          ADS1115_CONFIG_DR_10Hz;
        if (write(st.i2c_fd, &config, 2) != 2) {
            perror("write");
            goto error;
        }

        usleep(10000);

        uint16_t raw;
        if (read(st.i2c_fd, &raw, 2) != 2) {
            perror("read");
            goto error;
        }

        double volts = ADS1115_TO_VOLTS(raw);
        double current = ADS1115_TO_CURRENT(volts);

        st.circ_buf_sum -= st.circ_buf[st.circ_buf_idx];
        st.circ_buf[st.circ_buf_idx] = current;
        st.circ_buf_sum += current;
        st.circ_buf_idx = (st.circ_buf_idx + 1) % CIRC_BUF_SIZE;

        if (st.circ_buf_sum / CIRC_BUF_SIZE > 50.0) {
            gpiod_line_set_value(st.gpio_line, 1);
        } else {
            gpiod_line_set_value(st.gpio_line, 0);
        }
    }

    cleanup(&st);
    return 0;

error:
    cleanup(&st);
    return 1;
}

