#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_POWERON 0x01
#define TCS34725_IDREG 0x12
#define TCS34725_CDATAL 0x14

static int i2c_file;
static FILE *csv_file;
static volatile int running = 1;

static void handle_sig(int sig) {
    running = 0;
}

int main() {
    struct i2c_msg msgs[2];
    char id;
    unsigned short clear, red, green, blue;
    char buf[5];
    time_t t;
    struct tm *tm;
    char time_str[20];
    int i2c_fail_count = 0;

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Could not open I2C device");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Could not set I2C slave device");
        return 1;
    }

    msgs[0].addr = TCS34725_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buf;
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    msgs[1].addr = TCS34725_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 1;
    msgs[1].buf = &id;

    if (write(i2c_file, buf, 1) != 1 || read(i2c_file, &id, 1) != 1) {
        perror("Could not read sensor ID");
        return 1;
    }

    if (id != TCS34725_ID) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02x\n", id);
        return 1;
    }

    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = TCS34725_ENABLE_POWERON;
    if (write(i2c_file, buf, 2) != 2) {
        perror("Could not power on sensor");
        return 1;
    }

    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    csv_file = fopen("color_log.csv", "a");
    if (csv_file == NULL) {
        perror("Could not open CSV file");
        return 1;
    }

    if (fseek(csv_file, 0, SEEK_END) == 0 && ftell(csv_file) == 0) {
        fprintf(csv_file, "time,clear,red,green,blue\n");
    }

    while (running) {
        usleep(3000);

        for (int i = 0; i < 4; i++) {
            buf[0] = TCS34725_COMMAND_BIT | (TCS34725_CDATAL + (i * 2));
            if (write(i2c_file, buf, 1) != 1) {
                perror("Could not read sensor data");
                i2c_fail_count++;
                if (i2c_fail_count >= 3) {
                    fprintf(stderr, "Three consecutive I2C operations failed, exiting...\n");
                    running = 0;
                    break;
                }
                continue;
            }
            i2c_fail_count = 0;
            if (read(i2c_file, &buf[1], 2) != 2) {
                perror("Could not read sensor data");
                continue;
            }
            switch (i) {
                case 0:
                    clear = (buf[1] << 8) | buf[0];
                    break;
                case 1:
                    red = (buf[1] << 8) | buf[0];
                    break;
                case 2:
                    green = (buf[1] << 8) | buf[0];
                    break;
                case 3:
                    blue = (buf[1] << 8) | buf[0];
                    break;
            }
        }

        t = time(NULL);
        tm = localtime(&t);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(csv_file, "%s,%u,%u,%u,%u\n", time_str, clear, red, green, blue);
        fflush(csv_file);
    }

    fclose(csv_file);
    close(i2c_file);

    return 0;
}

