#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CHANNEL_1 0
#define CHANNEL_2 1
#define DELAY 5

static int fd;
static FILE *log_file;

void exit_handler(int signum) {
    close(fd);
    fclose(log_file);
    exit(0);
}

int send_and_receive(int value) {
    uint8_t tx_buffer[3] = {0x01, (0x08 + value) << 4, 0};
    uint8_t rx_buffer[3] = {0, 0, 0};
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buffer,
        .rx_buf = (unsigned long)rx_buffer,
        .len = 3,
        .delay_usecs = 1000,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    int result = (rx_buffer[1] & 0x03) << 8 | rx_buffer[2];
    return result;
}

int main() {
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    log_file = fopen("moisture_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        int moisture_1 = send_and_receive(CHANNEL_1);
        int moisture_2 = send_and_receive(CHANNEL_2);
        if (moisture_1 < 0 || moisture_2 < 0) {
            fprintf(stderr, "Error reading moisture sensors\n");
            exit_handler(0);
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_1, moisture_2);
        fflush(log_file);

        sleep(DELAY);
    }

    return 0;
}

