#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_LINE_CS 8
#define GPIO_LINE_MOTOR 17
#define MAX_TRIES 3
#define ADC_CHANNEL 0
#define ADC_REF_VOLT 3.3
#define ADC_MAX_VALUE 4095
#define CURRENT_LIMIT 10.0

struct gpiod_chip *chip = NULL;
struct gpiod_line *line_cs = NULL, *line_motor = NULL;
int spi_fd = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (line_cs)
        gpiod_line_release(line_cs);
    if (line_motor)
        gpiod_line_release(line_motor);
    if (chip)
        gpiod_chip_close(chip);
    if (spi_fd >= 0)
        close(spi_fd);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    int retries = 0;
    char line[128];
    struct spi_ioc_transfer xfer;
    uint16_t adc_value = 0;
    float current;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    line_cs = gpiod_chip_get_line(chip, GPIO_LINE_CS);
    if (!line_cs) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    line_motor = gpiod_chip_get_line(chip, GPIO_LINE_MOTOR);
    if (!line_motor) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line_cs, "cs", 1) ||
        gpiod_line_request_output(line_motor, "motor", 1)) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,current\n");
    }

    while (1) {
        xfer.tx_buf = (uint8_t *)&adc_value;
        xfer.rx_buf = (uint8_t *)&adc_value;
        xfer.len = 2;
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 16;
        xfer.delay_usecs = 0;
        xfer.cs_change = 1;

        while (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) && retries < MAX_TRIES) {
            usleep(1000);
            retries++;
        }

        if (retries == MAX_TRIES) {
            fprintf(stderr, "Failed to read from ADC\n");
            cleanup_and_exit(-1);
        }

        retries = 0;

        current = (float)adc_value * ADC_REF_VOLT / ADC_MAX_VALUE;

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%f\n", buffer, current);
        fflush(log_file);

        if (current > CURRENT_LIMIT) {
            gpiod_line_set_value(line_motor, 0);
            sleep(1);
            gpiod_line_set_value(line_motor, 1);
        }

        sleep(1);
    }

    return 0;
}

