#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define MLX90834_ADDR 0x2a
#define GPIO_LED 17

#define ADS1115_CONF_REG 0x01
#define ADS1115_CONF_SETUP 0x8583
#define ADS1115_CONF_MODE 0x0100
#define ADS1115_CONF_DR 0x0080
#define ADS1115_CONF_CM 0x0040
#define ADS1115_CONF_CP 0x0020
#define ADS1115_CONF_M 0x0010
#define ADS1115_CONF_PGA 0x000C
#define ADS1115_CONF_DEV 0x0002
#define ADS1115_CONF_COM 0x0001

#define ADS1115_CONF_AIN0 0x0000
#define ADS1115_CONF_AIN1 0x0001
#define ADS1115_CONF_AIN2 0x0002
#define ADS1115_CONF_AIN3 0x0003

#define ADS1115_CONV_REG 0x00
#define ADS1115_CONF_REG 0x01
#define ADS1115_LO_THRESH_REG 0x02
#define ADS1115_HI_THRESH_REG 0x03

#define MLX90834_PRESSURE_REG 0x00
#define MLX90834_TEMPERATURE_REG 0x01

struct gpiod_chip *chip;
struct gpiod_line *line;
int fd_i2c;

void cleanup(int signum) {
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    close(fd_i2c);
    exit(0);
}

int i2c_write_word(int reg, int val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = val >> 8;
    buf[2] = val & 0xff;
    return write(fd_i2c, buf, 3);
}

int i2c_read_word(int reg) {
    uint8_t reg_buf = reg;
    uint8_t val_buf[2];
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msgs[2];

    msgs[0].addr = ADS1115_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg_buf;

    msgs[1].addr = ADS1115_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = val_buf;

    msg.msgs = msgs;
    msg.nmsgs = 2;

    if (ioctl(fd_i2c, I2C_RDWR, &msg) < 0) {
        perror("ioctl");
        return -1;
    }

    return (val_buf[0] << 8) | val_buf[1];
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line, "pressure_sensor", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    fd_i2c = open("/dev/i2c-1", O_RDWR);
    if (fd_i2c < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd_i2c, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    i2c_write_word(ADS1115_CONF_REG, ADS1115_CONF_SETUP | ADS1115_CONF_AIN0);
    i2c_write_word(ADS1115_CONF_REG, ADS1115_CONF_SETUP | ADS1115_CONF_AIN1);

    while (1) {
        int pressure = i2c_read_word(ADS1115_CONF_REG);
        if (pressure < 0) {
            printf("Failed to read pressure, retrying...\n");
            continue;
        }

        int temperature = i2c_read_word(ADS1115_CONF_REG);
        if (temperature < 0) {
            printf("Failed to read temperature, retrying...\n");
            continue;
        }

        printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure * 0.0001220703125, temperature * 0.0001220703125 - 273.15);

        if (pressure > 105000) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    return 0;
}

