#include <signal.h>
#include <libgpiod.h>
#include <errno.h>
#include <mcp3008.h>

#define ADC_CHANNEL 0
#define OVERCURRENT_THRESHOLD 10000
#define LOG_FILE "current_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void cleanup(void)
{
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
}

void handle_signal(int signum)
{
    cleanup();
    exit(0);
}

int main(void)
{
    struct mcp3008_handle *handle;
    struct timespec ts;
    int ret, adc_value;

    handle = mcp3008_open(0, 8, 11, 10, 9);
    if (!handle) {
        fprintf(stderr, "Failed to open MCP3008: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, 27);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_output(line, "motor control", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        adc_value = mcp3008_read(handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC: %s\n", strerror(errno));
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: %d\n", ts.tv_sec, ts.tv_nsec, adc_value);
        fflush(log_file);

        if (adc_value > OVERCURRENT_THRESHOLD) {
            fprintf(log_file, "OVERCURRENT\n");
            fflush(log_file);
            gpiod_line_set_value(line, 1);
            cleanup();
            return 1;
        }

        usleep(100000);
    }

    return 0;
}

