#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libi2c.h>
#include <mlx90830.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct mlx90830_dev *mlx = NULL;
    struct i2c_dev *i2c = NULL;
    FILE *file = NULL;
    double pressure;
    char timestamp[20];
    struct tm *timeinfo;
    time_t now;
    struct sigaction action;

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    i2c = i2c_init(I2C_BUS);
    if (!i2c) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        goto cleanup;
    }

    mlx = mlx90830_init(i2c, I2C_ADDR);
    if (!mlx) {
        fprintf(stderr, "Failed to initialize MLX90830 sensor\n");
        goto cleanup;
    }

    file = fopen("pressure_log.txt", "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    while (!stop) {
        if (mlx90830_read_pressure(mlx, &pressure)) {
            fprintf(stderr, "Failed to read pressure\n");
            goto cleanup;
        }

        if (pressure < 0 || pressure > 100) {
            fprintf(stderr, "Invalid pressure value: %f\n", pressure);
            goto cleanup;
        }

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        if (fprintf(file, "%s %f\n", timestamp, pressure) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            goto cleanup;
        }

        fflush(file);
        sleep(1);
    }

cleanup:
    if (mlx)
        mlx90830_destroy(mlx);
    if (i2c)
        i2c_close(i2c);
    if (file)
        fclose(file);

    return 0;
}

