#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_LINE 8
#define LOG_FILE "humidity_log.txt"
#define HUMIDITY_THRESHOLD 80

struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, CS_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Main loop
    while (1) {
        // Read from ADC
        uint16_t data;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &data) < 0) {
            perror("Failed to read from ADC");
            return 1;
        }

        // Calculate humidity and temperature
        float humidity = data * 100.0 / 4095.0;
        float temperature = (data - 512) * 100.0 / 4095.0 + 25;

        // Write to log file
        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char buffer[80];
        strftime(buffer, 80, "%d/%m/%Y %H:%M:%S", tmp);
        fprintf(log_file, "%s,%.2f,%.2f\n", buffer, humidity, temperature);
        fflush(log_file);

        // Send email if humidity is too high
        if (humidity > HUMIDITY_THRESHOLD) {
            system("echo 'Humidity alert: current humidity is above 80%' | ssmtp your_email@example.com");
        }
    }

    return 0;
}

