    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "cs", 1)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    unsigned char buffer[2 * CHANNELS];
    memset(buffer, 0, sizeof(buffer));

    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            buffer[2 * i] = (1 << 7) | (i << 4);
        }

        gpiod_line_set_value(cs_line, 0);
        write(spi_fd, buffer, sizeof(buffer));
        gpiod_line_set_value(cs_line, 1);

        usleep(1000000 / SAMPLE_RATE);

        for (int i = 0; i < CHANNELS; i++) {
            int value = (buffer[2 * i + 1] << 8) | buffer[2 * i];
            if (value < 0 || value > 4095) {
                fprintf(stderr, "Invalid ADC value: %d\n", value);
                cleanup_and_exit(0);
            }

            time_t t = time(NULL);
            struct tm *tmp = localtime(&t);
            char time_str[16];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tmp);

            fprintf(log_file, "%s, %d\n", time_str, value);

            if (value > IMPACT_THRESHOLD) {
                fprintf(log_file, "IMPACT DETECTED\n");
            }
        }
    }

    return 0;
}

