#define SPI_DEV_PATH "/dev/spidev0.0"
#define CS_GPIO_PIN 8
#define LOG_FILE_NAME "flow_log.csv"
#define ADC_FULL_SCALE 4095
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0

struct spi_device *spi_dev;
FILE *log_file;
struct gpiod_chip *gpio_chip;
struct gpiod_line *cs_line;
int should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

void exit_handler(void) {
    fclose(log_file);
    spi_device_close(spi_dev);
    gpiod_line_release(cs_line);
    gpiod_chip_close(gpio_chip);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint16_t tx_buf = 0x01 << 12;
    uint16_t rx_buf;
    struct timespec ts;
    double flow_rate;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_dev = spi_device_open(SPI_DEV_PATH, "spi0");
    if (!spi_dev) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(cs_line, "cs_line", 1)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    atexit(exit_handler);

    log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        gpiod_line_set_value(cs_line, 0);

        xfer.tx_buf = (unsigned long)&tx_buf;
        xfer.rx_buf = (unsigned long)&rx_buf;
        xfer.len = sizeof(rx_buf);
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 16;
        xfer.delay_usecs = 0;
        xfer.cs_change = 1;

        if (spi_transfer(spi_dev, &xfer) < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            continue;
        }

        gpiod_line_set_value(cs_line, 1);

        flow_rate = (double)(rx_buf >> 2) / ADC_FULL_SCALE * 5.0;

        if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%06ld,%f\n",
                ts.tv_sec / 31536000 + 1970, (ts.tv_sec / 2592000) % 12 + 1, (ts.tv_sec / 86400) % 30 + 1,
                (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60, ts.tv_sec % 60, ts.tv_nsec / 1000, flow_rate);

        fflush(log_file);
    }

    return 0;
}

