        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(CSV_FILENAME, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file for writing");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        msgs[0].addr = SENSOR_ADDRESS;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = &cmd;

        msgs[1].addr = SENSOR_ADDRESS;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = sizeof(result);
        msgs[1].buf = result;

        msg_data.msgs = msgs;
        msg_data.nmsgs = 2;

        if (ioctl(i2c_file_descriptor, I2C_RDWR, &msg_data) < 0) {
            perror("Failed to read from I2C device");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int pressure = (result[0] << 12) | (result[1] << 4) | (result[2] >> 4);
        int temperature = ((result[2] & 0x0F) << 16) | (result[3] << 8) | result[4];

        float converted_pressure = 400.0 + pressure * 650.0 / 2097151.0;
        float converted_temperature = -45.0 + temperature * 175.0 / 32767.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", converted_pressure, converted_temperature);
