#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define LOG_FILE "moisture_log.txt"

struct spi_device *spi;
FILE *log_file;
int running = 1;

void handle_signal(int signum) {
    running = 0;
}

void write_log(int value) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);
    fprintf(log_file, "%s,%d\n", timestamp, value);
    if (ferror(log_file)) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi = spi_open_device(SPI_DEV, SPI_MODE, SPI_MAX_SPEED_HZ);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    while (running) {
        uint8_t tx_buf[3] = {1, ADC_CHANNEL << 4, 0};
        uint8_t rx_buf[3] = {0, 0, 0};
        if (spi_transfer_data(spi, tx_buf, rx_buf, 3)) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        int value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
        if (value < 0 || value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", value);
            exit(EXIT_FAILURE);
        }
        write_log(value);
        sleep(60);
    }

    spi_close_device(spi);
    fclose(log_file);

    return 0;
}

