#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_FREQ 1000000
#define SPI_CHANNEL 0
#define GPIO_BUZZER 18
#define MAX_RETRIES 3
#define LOG_FILE "flame_log.txt"
#define TEMP_FILE "ambient_temp.txt"

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;
int spi_fd;

void cleanup_and_exit(int sig) {
    gpiod_line_set_value(line, 0);
    close(spi_fd);
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(sig);
}

int main() {
    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_BUZZER);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line, "buzzer", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE)) {
        perror("ioctl");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_FREQ)) {
        perror("ioctl");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    unsigned char tx_buf[3] = {0x01, 0x80, 0x00};
    unsigned char rx_buf[3];
    int retries;
    double temp, voltage, adc_value;
    char timestamp[20];
    FILE *temp_file;
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_FREQ,
        .bits_per_word = 8,
    };

    while (1) {
        retries = 0;
        while (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0 && retries < MAX_RETRIES) {
            perror("ioctl");
            sleep(1);
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read from ADC after %d retries\n", MAX_RETRIES);
            fprintf(log_file, "Failed to read from ADC after %d retries\n", MAX_RETRIES);
            continue;
        }

        adc_value = ((rx_buf[1] & 0x0F) << 8) | rx_buf[2];

        temp_file = fopen(TEMP_FILE, "r");
        if (!temp_file || fscanf(temp_file, "%lf", &temp) != 1) {
            temp = 25.0;
        }
        if (temp_file) fclose(temp_file);

        voltage = adc_value * 3.3 / 1023.0;
        voltage = voltage * (1.0 + 0.0038 * (temp - 25.0));

        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, adc_value, voltage, voltage, temp, voltage > 1.0 ? "Yes" : "No");

        gpiod_line_set_value(line, voltage > 1.0 ? 1 : 0);

        sleep(500);
    }

    return 0;
}

