#define SPI_DEVICE_PATH "/dev/spidev0.0"
#define CS_GPIO_LINE 24
#define SCLK_GPIO_LINE 23
#define MOSI_GPIO_LINE 19
#define MISO_GPIO_LINE 21
#define CHANNEL_0 0
#define LPM_CONVERSION_RATE 60
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE_NAME "airflow_log.csv"

struct spi_device *spi;
struct gpiod_chip *gpio_chip;
struct gpiod_line *cs_line, *sclk_line, *mosi_line, *miso_line;
FILE *log_file;
volatile sig_atomic_t stop;

void cleanup_and_exit(int sig) {
    if (spi)
        spi_close(spi);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (log_file)
        fclose(log_file);
    if (sig)
        printf("\nExiting on signal %d\n", sig);
    exit(sig);
}

void handle_sig(int sig) {
    stop = 1;
}

int main() {
    struct spi_ioc_transfer xfer;
    unsigned char tx_buf[3], rx_buf[2];
    struct timespec ts;
    char timestamp[20];
    int ret;

    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    spi = spi_open_device(SPI_DEVICE_PATH);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_LINE);
    sclk_line = gpiod_chip_get_line(gpio_chip, SCLK_GPIO_LINE);
    mosi_line = gpiod_chip_get_line(gpio_chip, MOSI_GPIO_LINE);
    miso_line = gpiod_chip_get_line(gpio_chip, MISO_GPIO_LINE);

    if (!cs_line || !sclk_line || !mosi_line || !miso_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    fprintf(log_file, "timestamp,airflow_lpm\n");

    while (!stop) {
        tx_buf[0] = 0x01;
        tx_buf[1] = (CHANNEL_0 << 4) & 0x1F;
        tx_buf[2] = 0x00;

        xfer.tx_buf = (unsigned long)tx_buf;
        xfer.rx_buf = (unsigned long)rx_buf;
        xfer.len = sizeof(tx_buf);
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;
        xfer.delay_usecs = 0;
        xfer.cs_change = 1;

        ret = spi_transfer(spi, &xfer, 1);
        if (ret != 1) {
            fprintf(stderr, "SPI transfer failed\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s,%d\n", timestamp, ((rx_buf[0] & 0x03) << 8) | rx_buf[1]);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup_and_exit(0);
}

