    /* Register signal handlers */
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    /* Open SPI device */
    spi.spi = spi_open_device(SPI_BUS, SPI_CHANNEL, 500000, 0);
    if (!spi.spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
