#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define SPI_CS_GPIO 8
#define STUCK_ADDR 1023
#define STUCK_ADDR_LOW 0

static int spi_fd = -1;
static int gpio_fd = -1;

void cleanup_and_exit(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_fd != -1) {
        ioctl(gpio_fd, GPIOD_SET_VALUES, &SPI_CS_GPIO, 1, 1);
        close(gpio_fd);
    }
    exit(signum);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint16_t tx = 0x0102;
    uint16_t rx = 0;
    struct timespec ts;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        cleanup_and_exit(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("spi set mode");
        cleanup_and_exit(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("spi set speed");
        cleanup_and_exit(-1);
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("open gpiochip");
        cleanup_and_exit(-1);
    }

    if (ioctl(gpio_fd, GPIOD_SET_VALUES, &SPI_CS_GPIO, 1, 0) < 0) {
        perror("gpio set value");
        cleanup_and_exit(-1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("[%ld.%09ld] ", ts.tv_sec, ts.tv_nsec);

        if (ioctl(gpio_fd, GPIOD_SET_VALUES, &SPI_CS_GPIO, 1, 0) < 0) {
            perror("gpio set value");
            cleanup_and_exit(-1);
        }

        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)&tx;
        xfer.rx_buf = (unsigned long)&rx;
        xfer.len = 2;
        xfer.speed_hz = SPI_MAX_SPEED_HZ;
        xfer.bits_per_word = 16;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("spi transfer");
            cleanup_and_exit(-1);
        }

        if (ioctl(gpio_fd, GPIOD_SET_VALUES, &SPI_CS_GPIO, 1, 1) < 0) {
            perror("gpio set value");
            cleanup_and_exit(-1);
        }

        if (rx == STUCK_ADDR || rx == STUCK_ADDR_LOW) {
            fprintf(stderr, "Sensor absent or wiring fault\n");
            cleanup_and_exit(-1);
        }

        printf("ADC value: %d\n", rx);
        sleep(5);
    }

    return 0;
}

