#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <linux/spi/spidev.h>

#define DEVICE_PATH "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CS_DELAY 0
#define CS_HOLD 0
#define CS_ACTIVE 0
#define CS_INACTIVE 1
#define NUM_CHANNELS 4
#define FILENAME "environmental_data.csv"

static int spi_fd = -1;
static FILE* file = NULL;

void exit_handler(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (file != NULL) {
        fclose(file);
    }
    exit(signum);
}

int main() {
    struct spi_ioc_transfer xfer[NUM_CHANNELS];
    uint16_t tx[NUM_CHANNELS], rx[NUM_CHANNELS];
    int i;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    spi_fd = open(DEVICE_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Error setting SPI mode");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &CS_ACTIVE) < 0) {
        perror("Error setting SPI LSB first");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &CS_PIN) < 0) {
        perror("Error setting SPI bits per word");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error setting SPI speed");
        exit_handler(-1);
    }

    file = fopen(FILENAME, "w");
    if (file == NULL) {
        perror("Error opening file");
        exit_handler(-1);
    }

    memset(xfer, 0, sizeof(xfer));
    for (i = 0; i < NUM_CHANNELS; i++) {
        tx[i] = (0x8000 | (i << 8));
        xfer[i].tx_buf = (unsigned long)&tx[i];
        xfer[i].rx_buf = (unsigned long)&rx[i];
        xfer[i].len = 2;
        xfer[i].cs_change = (i != (NUM_CHANNELS - 1));
        xfer[i].delay_usecs = CS_DELAY;
        xfer[i].speed_hz = SPI_SPEED;
        xfer[i].bits_per_word = 16;
    }

    while (1) {
        if (spi_write_read(spi_fd, xfer, NUM_CHANNELS) < 0) {
            perror("Error reading from SPI device");
            exit_handler(-1);
        }

        for (i = 0; i < NUM_CHANNELS; i++) {
            fprintf(file, "%d, %d\n", i, rx[i]);
        }

        fflush(file);
        sleep(1);
    }

    return 0;
}

