#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define PUMP_GPIO 17
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define SCLK_GPIO 11
#define BUFFER_SIZE 20

struct gpiod_chip *chip;
struct gpiod_line *pump_line;
struct spi_device *spi;
int pump_state = 0;
int buffer_head = 0;
int buffer_tail = 0;
struct {
    int moisture;
    int pump_state;
    time_t timestamp;
} buffer[BUFFER_SIZE];

void handle_signal(int signum) {
    spi_close(spi);
    gpiod_line_set_value(pump_line, 0);
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    struct spi_config spi_cfg;
    struct spi_transfer_config xfer_cfg;
    uint8_t tx_buf[3] = {0x01, 0x80 + (MCP3008_CHANNEL << 4), 0x00};
    uint8_t rx_buf[3] = {0x00, 0x00, 0x00};
    int moisture;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO);
    if (!pump_line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_output(pump_line, "pump", 0)) {
        perror("gpiod_line_request_output");
        exit(1);
    }

    spi = spi_open(SPI_BUS, SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (!spi) {
        perror("spi_open");
        exit(1);
    }

    while (1) {
        spi_transfer(spi, tx_buf, rx_buf, sizeof(tx_buf));
        moisture = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        if (moisture < LOW_THRESHOLD && !pump_state) {
            gpiod_line_set_value(pump_line, 1);
            pump_state = 1;
        } else if (moisture > HIGH_THRESHOLD && pump_state) {
            gpiod_line_set_value(pump_line, 0);
            pump_state = 0;
        }

        buffer[buffer_head].moisture = moisture;
        buffer[buffer_head].pump_state = pump_state;
        buffer[buffer_head].timestamp = time(NULL);
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        if (buffer_head == buffer_tail)
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;

        for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE)
            printf("Moisture: %d, Pump: %d, Timestamp: %ld\n", buffer[i].moisture, buffer[i].pump_state, buffer[i].timestamp);

        sleep(5);
    }

    return 0;
}

