#define MAX30102_REG_PART_ID 0x06
#define MAX30102_PART_ID 0x10

struct gpiod_device *dev = NULL;
struct gpiod_line *line = NULL;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (dev)
        gpiod_device_close(dev);
    if (line)
        gpiod_line_release(line);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    struct tm *ts;
    time_t t;
    char timestamp[20];

    dev = gpiod_device_open_by_name("/dev/i2c-1");
    if (!dev) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    line = gpiod_device_get_line(dev, MAX30102_I2C_ADDR);
    if (!line) {
        fprintf(stderr, "Failed to get I2C line: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line, "MAX30102");
    if (ret < 0) {
        fprintf(stderr, "Failed to request I2C line: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_read(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C line: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (ret != MAX30102_PART_ID) {
        fprintf(stderr, "MAX30102 not found at address 0x%02X\n", MAX30102_I2C_ADDR);
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("health_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open health log file: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        // Sample SpO2 and heart rate
        // If SpO2 < 95% or heart rate > 100BPM, write to log file
        t = time(NULL);
        ts = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", ts);

        fprintf(log_file, "%s SpO2: %d, Heart rate: %d\n", timestamp, spo2, heart_rate);
