#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS 0
#define SPI_SPEED 1000000
#define MAX_TRIES 3

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

void write_to_file(int channel, int voltage, FILE *file) {
    time_t now = time(0);
    struct tm *time_info = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", time_info);
    fprintf(file, "%s,%d,%d\n", timestamp, channel, voltage);
}

int main() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    int spi_mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    int spi_speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    int spi_cs = CS;
    if (ioctl(spi_fd, SPI_IOC_WR_CS, &spi_cs) < 0) {
        perror("Failed to set SPI chip select");
        return 1;
    }

    FILE *file = fopen("analog_log.csv", "w");
    if (file == NULL) {
        perror("Failed to open file");
        return 1;
    }

    fprintf(file, "Timestamp,Channel,Voltage\n");

    signal(SIGINT, sigint_handler);

    while (!stop) {
        for (int channel = 0; channel < 3; channel++) {
            uint16_t tx_buf = 0x0003;
            tx_buf |= (channel << 8);
            uint16_t rx_buf;
            int tries = 0;
            int res;

            do {
                res = write(spi_fd, &tx_buf, sizeof(tx_buf));
                if (res < 0) {
                    perror("SPI write failed");
                    if (++tries >= MAX_TRIES) {
                        fprintf(stderr, "Too many SPI errors, aborting\n");
                        stop = 1;
                        break;
                    }
                }
            } while (res < 0);

            if (stop) break;

            do {
                res = read(spi_fd, &rx_buf, sizeof(rx_buf));
                if (res < 0) {
                    perror("SPI read failed");
                    if (++tries >= MAX_TRIES) {
                        fprintf(stderr, "Too many SPI errors, aborting\n");
                        stop = 1;
                        break;
                    }
                }
            } while (res < 0);

            if (stop) break;

            int voltage = ((rx_buf & 0x3FF) * 3300) / 1023;
            write_to_file(channel, voltage, file);
        }

        if (!stop) sleep(500);
    }

    fclose(file);
    close(spi_fd);

    return 0;
}

