    spi_close(spi);
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    spi = spi_open(SPI_DEV, SPI_MODE, SPI_MAX_SPEED_HZ);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        spi_close(spi);
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_BUZZER);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        spi_close(spi);
        return 1;
    }

    if (gpiod_line_request_output(line, "buzzer", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        spi_close(spi);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int value = spi_read(spi);
        if (value < 0) {
            fprintf(stderr, "Failed to read from SPI device\n");
            sigint_handler(0);
        }

        if (gpiod_line_set_value(line, value >= SPI_THRESHOLD ? 1 : 0)) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            sigint_handler(0);
        }

        usleep(500000);
    }

    return 0;
}
