#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS0 8
#define CS1 7
#define CS2 25
#define SPI_SPEED 1000000

int spi_fd = -1;
int cs_gpio[3] = {CS0, CS1, CS2};
int gpio_fd[3] = {-1, -1, -1};
int should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

void cleanup() {
    if (spi_fd != -1) close(spi_fd);
    for (int i = 0; i < 3; i++) {
        if (gpio_fd[i] != -1) close(gpio_fd[i]);
    }
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        cleanup();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        perror("Error setting SPI mode");
        cleanup();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, 0) < 0) {
        perror("Error setting SPI bit order");
        cleanup();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        perror("Error setting SPI bits per word");
        cleanup();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Error setting SPI speed");
        cleanup();
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        gpio_fd[i] = open("/dev/gpiomem", O_RDWR);
        if (gpio_fd[i] < 0) {
            perror("Error opening GPIO device");
            cleanup();
            return 1;
        }

        if (ioctl(gpio_fd[i], GPIO_SET_DIRECTION, &cs_gpio[i]) < 0) {
            perror("Error setting GPIO direction");
            cleanup();
            return 1;
        }

        if (ioctl(gpio_fd[i], GPIO_SET_VALUE, &cs_gpio[i]) < 0) {
            perror("Error setting GPIO value");
            cleanup();
            return 1;
        }
    }

    int fd = open("soil_moisture_log.csv", O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        perror("Error opening file");
        cleanup();
        return 1;
    }

    if (write(fd, "timestamp,sensor1,sensor2,sensor3\n", 35) < 0) {
        perror("Error writing to file");
        cleanup();
        return 1;
    }

    while (!should_exit) {
        char buf[3] = {0x01, 0x80, 0x00};
        char res[3];
        for (int i = 0; i < 3; i++) {
            if (ioctl(gpio_fd[i], GPIO_SET_VALUE, &cs_gpio[i]) < 0) {
                perror("Error setting GPIO value");
                cleanup();
                return 1;
            }

            if (write(spi_fd, buf, 3) < 0) {
                perror("Error writing to SPI device");
                cleanup();
                return 1;
            }

            if (read(spi_fd, res, 3) < 0) {
                perror("Error reading from SPI device");
                cleanup();
                return 1;
            }

            if (ioctl(gpio_fd[i], GPIO_SET_VALUE, &cs_gpio[i]) < 0) {
                perror("Error setting GPIO value");
                cleanup();
                return 1;
            }

            int val = (res[1] & 0x03) << 8 | res[2];
            char line[20];
            sprintf(line, "%d,", val);
            if (write(fd, line, strlen(line)) < 0) {
                perror("Error writing to file");
                cleanup();
                return 1;
            }
        }

        time_t t = time(NULL);
        char* ts = ctime(&t);
        ts[strlen(ts)-1] = '\0';
        if (write(fd, ts, strlen(ts)) < 0) {
            perror("Error writing to file");
            cleanup();
            return 1;
        }

        if (write(fd, "\n", 1) < 0) {
            perror("Error writing to file");
            cleanup();
            return 1;
        }

        sleep(5);
    }

    cleanup();
    return 0;
}

