    struct spi_device *spi;
    struct gpiod_chip *gpio;
    struct gpiod_line *cs_line;
    struct gpiod_line *pump_line;
    FILE *log_file;
    int threshold;
    int pump_duration;
    int sleep_interval;
    int stop;
};

void log_message(struct app_context *ctx, const char *fmt, ...) {
    va_list args;
    char buffer[256];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    sprintf(buffer, "%04d-%02d-%02d %02d:%02d:%02d ", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), fmt, args);
    va_end(args);

    fprintf(ctx->log_file, "%s\n", buffer);
    fflush(ctx->log_file);
}

void sig_handler(int signo) {
    struct app_context *ctx = &app_context;

    if (signo == SIGINT || signo == SIGTERM) {
        ctx->stop = 1;
    }
}

int main(int argc, char **argv) {
    struct app_context ctx;
    struct spi_ioc_transfer xfer;
    uint16_t tx_buf = 0x01 << 12;
    uint16_t rx_buf;
    int retries;
    int opt;

    memset(&ctx, 0, sizeof(ctx));

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                ctx.threshold = atoi(optarg);
                break;
            case 'd':
                ctx.pump_duration = atoi(optarg);
                break;
            case 's':
                ctx.sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (!ctx.threshold) ctx.threshold = DEFAULT_THRESHOLD;
    if (!ctx.pump_duration) ctx.pump_duration = DEFAULT_PUMP_DURATION;
    if (!ctx.sleep_interval) ctx.sleep_interval = DEFAULT_SLEEP_INTERVAL;

    ctx.spi = spi_open_device(SPI_BUS_PATH, SPI_MODE, SPI_MAX_SPEED_HZ);
    if (!ctx.spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    ctx.gpio = gpiod_chip_open_by_name("gpiochip0");
    if (!ctx.gpio) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        spi_close_device(ctx.spi);
        return 1;
    }

    ctx.cs_line = gpiod_chip_get_line(ctx.gpio, SPI_CS_GPIO);
    if (!ctx.cs_line) {
        fprintf(stderr, "Failed to get CS line\n");
        gpiod_chip_close(ctx.gpio);
        spi_close_device(ctx.spi);
        return 1;
    }

    if (gpiod_line_request_output(ctx.cs_line, "cs", 1)) {
        fprintf(stderr, "Failed to request CS line\n");
        gpiod_line_release(ctx.cs_line);
        gpiod_chip_close(ctx.gpio);
        spi_close_device(ctx.spi);
        return 1;
    }

    ctx.pump_line = gpiod_chip_get_line(ctx.gpio, 18);
    if (!ctx.pump_line) {
        fprintf(stderr, "Failed to get pump line\n");
        gpiod_line_release(ctx.cs_line);
        gpiod_chip_close(ctx.gpio);
        spi_close_device(ctx.spi);
        return 1;
    }

    if (gpiod_line_request_output(ctx.pump_line, "pump", 0)) {
        fprintf(stderr, "Failed to request pump line\n");
        gpiod_line_release(ctx.pump_line);
        gpiod_line_release(ctx.cs_line);
        gpiod_chip_close(ctx.gpio);
        spi_close_device(ctx.spi);
        return 1;
    }

    ctx.log_file = fopen(LOG_FILE, "a");
    if (!ctx.log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(ctx.pump_line);
        gpiod_line_release(ctx.cs_line);
        gpiod_chip_close(ctx.gpio);
        spi_close_device(ctx.spi);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!ctx.stop) {
        for (retries = 0; retries < SPI_RETRIES; retries++) {
            xfer.tx_buf = (unsigned long)&tx_buf;
            xfer.rx_buf = (unsigned long)&rx_buf;
            xfer.len = sizeof(rx_buf);
            xfer.speed_hz = SPI_MAX_SPEED_HZ;
            xfer.cs_change = 1;

            if (spi_transfer(ctx.spi, &xfer, 1) == 1) {
                int moisture = (rx_buf & 0x3FF) * 100 / 1023;
                log_message(&ctx, "Moisture level: %d%%", moisture);

                if (moisture <= ctx.threshold) {
                    log_message(&ctx, "Moisture level below threshold, activating pump");
                    gpiod_line_set_value(ctx.pump_line, 1);
                    sleep(ctx.pump_duration);
                    log_message(&ctx, "Deactivating pump");
                    gpiod_line_set_value(ctx.pump_line, 0);
                }

                break;
            } else {
                log_message(&ctx, "SPI communication error, retrying");
            }
        }

        if (retries == SPI_RETRIES) {
            log_message(&ctx, "All SPI retries failed, skipping irrigation cycle");
        }

        sleep(ctx.sleep_interval);
    }

    gpiod_line_set_value(ctx.pump_line, 0);
    gpiod_line_release(ctx.pump_line);
    gpiod_line_release(ctx.cs_line);
    gpiod_chip_close(ctx.gpio);
    spi_close_device(ctx.spi);
    fclose(ctx.log_file);

    return 0;
}
