        if (value < 0) {
            perror("spi_read");
            return 1;
        }

        if (value > THRESHOLD) {
            time_t t = time(NULL);
            struct tm *tmp = localtime(&t);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tmp);

            fprintf(log_file, "%s: Peak detected: %d\n", timestamp, value);
