#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define ADDR 0x48
#define REG  0x00

static int fd;

void sigint_handler(int signum) {
    close(fd);
    exit(0);
}

int main(void) {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    if (write(fd, &REG, 1) != 1) {
        perror("write");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    unsigned char dummy;
    if (read(fd, &dummy, 1) != 1) {
        perror("read");
        return 1;
    }

    while (1) {
        unsigned char value;
        if (read(fd, &value, 1) != 1) {
            perror("read");
            return 1;
        }

        printf("%hhu\n", value);
        usleep(100000);
    }

    return 0;
}

