#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <adafruit_ads1115.h>

#define ADC_I2C_BUS 1
#define ADC_I2C_ADDR ADS1115_ADDR_GND
#define ADC_CHANNEL ADS1115_CHANNEL_AIN0
#define ADC_GAIN ADS1115_GAIN_1
#define ADC_DATA_RATE ADS1115_DATA_RATE_1_HZ
#define CIRCULAR_BUFFER_SIZE 10
#define MAGNETIC_FIELD_THRESHOLD 500.0

static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static Adafruit_ADS1115 ads1115;
static double circular_buffer[CIRCULAR_BUFFER_SIZE];
static int circular_buffer_index = 0;
static bool threshold_crossed = false;

void sig_handler(int signo) {
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (gpio_line)
        gpiod_line_release(gpio_line);
    closelog();
    exit(0);
}

int main() {
    openlog("honeywell_sensor", LOG_PERROR, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpio_chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 27);
    if (!gpio_line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %m");
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "honeywell_sensor", 0)) {
        syslog(LOG_ERR, "Failed to request GPIO line as output: %m");
        return 1;
    }

    if (!ads1115.begin(ADC_I2C_BUS, ADC_I2C_ADDR)) {
        syslog(LOG_ERR, "Failed to initialize ADS1115: %m");
        return 1;
    }

    ads1115.setGain(ADC_GAIN);
    ads1115.setDataRate(ADC_DATA_RATE);

    while (1) {
        int16_t value = ads1115.readADC_SingleEnded(ADC_CHANNEL);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read ADC: %m");
            continue;
        }

        double voltage = ads1115.getConversion(value);
        if (voltage < 0.0 || voltage > 3.3) {
            syslog(LOG_ERR, "ADC voltage out of range: %f", voltage);
            continue;
        }

        double magnetic_field = voltage * MAGNETIC_FIELD_THRESHOLD;
        circular_buffer[circular_buffer_index] = magnetic_field;
        circular_buffer_index = (circular_buffer_index + 1) % CIRCULAR_BUFFER_SIZE;

        double average = 0.0;
        for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++)
            average += circular_buffer[i];
        average /= CIRCULAR_BUFFER_SIZE;

        if (average > MAGNETIC_FIELD_THRESHOLD && !threshold_crossed) {
            gpiod_line_set_value(gpio_line, 1);
            threshold_crossed = true;
            syslog(LOG_INFO, "Magnetic field threshold crossed: %f", average);
        } else if (average <= MAGNETIC_FIELD_THRESHOLD && threshold_crossed) {
            gpiod_line_set_value(gpio_line, 0);
            threshold_crossed = false;
            syslog(LOG_INFO, "Magnetic field threshold not crossed: %f", average);
        }
    }

    return 0;
}

