#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>
#include "mcp3008.h"

#define ADC_CHANNEL 0
#define WATERING_PUMP_GPIO 18
#define THRESHOLD 300
#define WATERING_DURATION 10
#define SAMPLE_RATE 60
#define LOG_FILE "watering_events.txt"

struct gpiod_chip *chip;
struct gpiod_line *pump_line;
FILE *log_file;
int should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

void log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, %d\n", timestamp, moisture_level);
    fflush(log_file);
}

void activate_pump() {
    gpiod_line_set_value(pump_line, 1);
    sleep(WATERING_DURATION);
    gpiod_line_set_value(pump_line, 0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    pump_line = gpiod_chip_get_line(chip, WATERING_PUMP_GPIO);
    if (!pump_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "pump", 0)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(pump_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    while (!should_exit) {
        int value = mcp3008_read_channel(ADC_CHANNEL);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC: %s\n", strerror(-value));
            continue;
        }

        log_event(value);

        if (value < THRESHOLD) {
            activate_pump();
        }

        sleep(SAMPLE_RATE);
    }

    activate_pump();  // Ensure pump is turned off on exit
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

