    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    pump_line = gpiod_chip_get_line(chip, WATERING_PUMP_GPIO);
    if (!pump_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "pump", 0)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(pump_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    while (!should_exit) {
        int value = mcp3008_read_channel(ADC_CHANNEL);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC: %s\n", strerror(-value));
            continue;
        }

        log_event(value);

        if (value < THRESHOLD) {
            activate_pump();
        }

        sleep(SAMPLE_RATE);
    }

    activate_pump();  // Ensure pump is turned off on exit
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}
