#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <unistd.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define VDD 3.3
#define ADC_FULL_SCALE 1023

struct gpiod_device *device;
struct gpiod_line *line;
int spi_fd;
volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct spi_ioc_transfer xfer;
    uint16_t tx[2] = {0x0000, 0x0000};
    uint16_t rx[2] = {0x0000, 0x0000};
    int ret;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    device = gpiod_chip_get_line(chip, SPI_CHANNEL);
    if (!device) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    while (!stop) {
        tx[0] = (SPI_MODE << 12) | (1 << 8) | ADC_CHANNEL;
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = 2;
        xfer.speed_hz = SPI_SPEED;
        xfer.bits_per_word = 16;
        xfer.delay_usecs = 0;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("ioctl");
            continue;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        int adc_value = ((rx[0] >> 8) & 0x1FFF);
        float intensity = (float)adc_value / ADC_FULL_SCALE * VDD;

        printf("%02d:%02d:%02d ADC: %d Intensity: %.2f mm/hr\n", tm.tm_hour, tm.tm_min, tm.tm_sec, adc_value, intensity);

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

