#define SPI_BUS "spi0"
#define SPI_CE0_CHIP "gpiochip0"
#define SPI_CE0_LINE 8
#define SPI_FREQ 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0

#define PWM_FREQ 1000
#define PWM_CHIP "pwmchip0"
#define PWM_LINE 18
#define PWM_RANGE 1024

struct gpiod_line *spi_ce0_line;
struct gpiod_chip *spi_ce0_chip;
struct gpiod_device *spi_dev;
struct gpiod_line *pwm_line;
struct gpiod_chip *pwm_chip;
struct gpiod_device *pwm_dev;

void stop_pwm_and_exit(int signum) {
    gpiod_line_set_value(pwm_line, 0);
    gpiod_line_release(spi_ce0_line);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(spi_ce0_chip);
    gpiod_chip_close(pwm_chip);
    exit(0);
}

int main() {
    int ret;

    signal(SIGINT, stop_pwm_and_exit);
    signal(SIGTERM, stop_pwm_and_exit);

    spi_ce0_chip = gpiod_chip_open_by_name(SPI_CE0_CHIP);
    if (!spi_ce0_chip) {
        fprintf(stderr, "Failed to open SPI CE0 chip: %s\n", strerror(errno));
        return 1;
    }

    spi_ce0_line = gpiod_chip_get_line(spi_ce0_chip, SPI_CE0_LINE);
    if (!spi_ce0_line) {
        fprintf(stderr, "Failed to get SPI CE0 line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_spi_alt(spi_ce0_line, "mcp3008", SPI_BUS, SPI_MODE, SPI_FREQ);
    if (ret < 0) {
        fprintf(stderr, "Failed to request SPI CE0 line: %s\n", strerror(-ret));
        return 1;
    }

    pwm_chip = gpiod_chip_open_by_name(PWM_CHIP);
    if (!pwm_chip) {
        fprintf(stderr, "Failed to open PWM chip: %s\n", strerror(errno));
        return 1;
    }

    pwm_line = gpiod_chip_get_line(pwm_chip, PWM_LINE);
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_pwm_output(pwm_line, "motor", PWM_FREQ, PWM_RANGE, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request PWM line: %s\n", strerror(-ret));
        return 1;
    }

    while (1) {
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000 };
        uint8_t tx[3] = { 128 | (SPI_MODE << 6) | ADC_CHANNEL, 0, 0 };
        uint8_t rx[3] = { 0, 0, 0 };

        nanosleep(&ts, NULL);

        ret = gpiod_line_spi_transfer(spi_ce0_line, tx, rx, 3);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(-ret));
            continue;
        }

        int adc_value = (rx[1] << 8) | rx[2];
        printf("ADC value: %d, PWM value: %d\n", adc_value, adc_value % PWM_RANGE);

        ret = gpiod_line_set_pwm_duty_cycle(pwm_line, adc_value % PWM_RANGE);
        if (ret < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(-ret));
            continue;
        }
    }

    return 0;
}

