#include <libgpiod.h>
#include <adafruit_ads1115.h>

#define ADC_I2C_BUS 1
#define ADC_I2C_ADDR ADS1115_ADDR_GND
#define ADC_CHANNEL ADS1115_CHANNEL_AIN0
#define ADC_PGA_GAIN ADS1115_PGA_4096
#define ADC_SPS ADS1115_SPS_250

#define GPIO_LED 17
#define BLINK_DUTY_CYCLE_MS 50
#define BLINK_TOTAL_MS 1000

static Adafruit_ADS1115 ads;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static bool stop = false;
static float threshold = 100.0;

void handle_signal(int signum) {
    stop = true;
}

void cleanup() {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip)
        gpiod_chip_close(chip);

    printf("Exiting...\n");
}

int main(int argc, char *argv[]) {
    int ret;
    int i;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (argc > 1 && strcmp(argv[1], "-t") == 0 && argc > 2) {
        threshold = atof(argv[2]);
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "ads1115", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    if (!ads.begin(ADC_I2C_BUS, ADC_I2C_ADDR)) {
        printf("Failed to initialize ADS1115\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop) {
        float val = ads.readADC_SingleEnded(ADC_CHANNEL, ADC_PGA_GAIN, ADC_SPS);
        if (val < 0) {
            printf("Failed to read ADC: %f\n", val);
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Magnetic field strength: %f Gauss\n", val);

        if (val > threshold) {
            for (i = 0; i < BLINK_TOTAL_MS / (2 * BLINK_DUTY_CYCLE_MS); i++) {
                gpiod_line_set_value(line, 1);
                usleep(BLINK_DUTY_CYCLE_MS * 1000);
                gpiod_line_set_value(line, 0);
                usleep(BLINK_DUTY_CYCLE_MS * 1000);
            }
        }

        usleep(100 * 1000);
    }

    cleanup();

    return EXIT_SUCCESS;
}

