struct mosquitto *mosq;

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void error_handler(int error_code, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_ERR, fmt, args);
    va_end(args);
    exit(error_code);
}

void mqtt_connect_callback(struct mosquitto *mosq, void *obj, int result) {
    if (result) {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
        exit(EXIT_FAILURE);
    }
    mosquitto_subscribe(mosq, NULL, TOPIC_PUMP_CONTROL, 0);
}

void mqtt_message_callback(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (strcmp(msg->payload, "pump_on") == 0) {
        if (gpiod_line_set_value(line, 1)) {
            error_handler(EXIT_FAILURE, "Failed to set GPIO line value: %m");
        }
    } else if (strcmp(msg->payload, "pump_off") == 0) {
        if (gpiod_line_set_value(line, 0)) {
            error_handler(EXIT_FAILURE, "Failed to set GPIO line value: %m");
        }
    }
}

int main() {
    openlog("soil_moisture_controller", LOG_PERROR, LOG_USER);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        error_handler(EXIT_FAILURE, "Failed to open GPIO chip: %m");
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        error_handler(EXIT_FAILURE, "Failed to get GPIO line: %m");
    }

    if (gpiod_line_request_output(line, "pump_controller", 0)) {
        error_handler(EXIT_FAILURE, "Failed to request GPIO line: %m");
    }

    spi_fd = open(SPI_BUS_PATH, O_RDWR);
    if (spi_fd < 0) {
        error_handler(EXIT_FAILURE, "Failed to open SPI device: %m");
    }

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        error_handler(EXIT_FAILURE, "Failed to create MQTT client: %m");
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    while (!stop) {
        mosquitto_loop(mosq, 100, 1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    mosquitto_destroy();

    closelog();

    return 0;
}
