#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_GPIO 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define MCP3008_CHANNELS 3
#define VREF 3.3

struct spi_device *spi;
FILE *csv_file;

void cleanup_and_exit(int signum) {
    spi_close(spi);
    gpiod_ctx_shutdown();
    fclose(csv_file);
    exit(signum);
}

int main() {
    int ret;
    struct spi_ioc_transfer xfer[MCP3008_CHANNELS];
    unsigned char tx[4] = {0x01, 0x80, 0x00, 0x00};
    unsigned char rx[MCP3008_CHANNELS * 4];
    float voltages[MCP3008_CHANNELS];

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    ret = gpiod_ctx_init();
    if (ret) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", strerror(errno));
        return 1;
    }

    spi = spi_open(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    csv_file = fopen("sensor_data.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return 1;
    }

    for (;;) {
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            tx[1] = (0x10 | (i << 4)) & 0x18;
            xfer[i].tx_buf = (unsigned long)tx;
            xfer[i].rx_buf = (unsigned long)rx + i * 4;
            xfer[i].len = 4;
            xfer[i].cs_change = 1;
        }

        ret = spi_transfer(spi, xfer, MCP3008_CHANNELS);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            return 1;
        }

        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            unsigned int raw_value = (rx[i * 4 + 1] << 8) | rx[i * 4 + 2];
            voltages[i] = ((float)raw_value / 1023) * VREF;
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(csv_file, "%s, %.3f, %.3f, %.3f\n", timestamp, voltages[0], voltages[1], voltages[2]);
        fflush(csv_file);

        sleep(5);
    }

    return 0;
}

