#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define CSV_FILE "tamper_log.csv"
#define MCP3008_CH0 0
#define BH1750_ADDR 0x23
#define BH1750_READ_LEN 2
#define SLEEP_TIME 5

volatile sig_atomic_t stop = 0;

int spi_fd, i2c_fd, csv_fd;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
        close(spi_fd);
        close(i2c_fd);
        fdatasync(csv_fd);
        close(csv_fd);
        exit(0);
    }
}

int main() {
    struct sigaction sig;
    memset(&sig, 0, sizeof(sig));
    sig.sa_handler = sig_handler;
    sigaction(SIGINT, &sig, NULL);
    sigaction(SIGTERM, &sig, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        exit(1);
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        exit(1);
    }

    csv_fd = open(CSV_FILE, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("Error opening CSV file");
        exit(1);
    }

    while (!stop) {
        int sound_level_db = 0, light_level_lux = 0, error_code = 0;

        // Read sound level
        char spi_tx_buf[2] = {MCP3008_CH0, 0}, spi_rx_buf[2] = {0};
        struct spi_ioc_transfer spi_transfer = {
            .tx_buf = (unsigned long)spi_tx_buf,
            .rx_buf = (unsigned long)spi_rx_buf,
            .len = 2,
            .cs_change = 1
        };
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            error_code |= 1;
        } else {
            // Convert ADC result to sound level in dB
            int adc_result = (spi_rx_buf[0] << 8) | spi_rx_buf[1];
            sound_level_db = (10 * log10(adc_result / 4095.0)) + 94;
        }

        // Read light level
        if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            error_code |= 2;
        } else {
            usleep(180000);
            char i2c_rx_buf[BH1750_READ_LEN] = {0};
            if (read(i2c_fd, i2c_rx_buf, BH1750_READ_LEN) != BH1750_READ_LEN) {
                error_code |= 2;
            } else {
                // Convert I2C result to light level in lux
                light_level_lux = (i2c_rx_buf[0] << 8) | i2c_rx_buf[1];
            }
