#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define GPIO_PIN 17
#define THRESHOLD 30
#define MAX_RETRIES 3

struct spi_device *spi;
struct gpiod_chip *gpiod_chip;
struct gpiod_line *gpiod_line;
int should_exit = 0;

void exit_handler(int signum) {
    should_exit = 1;
}

void turn_off_pump() {
    gpiod_line_set_value(gpiod_line, 0);
}

void close_spi() {
    spi_close(spi);
}

void log_reading(int reading) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    printf("%d-%02d-%02d %02d:%02d:%02d: Moisture reading: %d%%\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, reading);
}

int main() {
    int ret, i, j, retries;
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3];

    spi = spi_open(SPI_DEVICE, SPI_MODE, SPI_MAX_SPEED_HZ, SPI_BITS_PER_WORD);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpiod_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close_spi();
        return 1;
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (!gpiod_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        close_spi();
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpiod_line, "pump", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(-ret));
        close_spi();
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (!should_exit) {
        retries = 0;
        do {
            ret = spi_transfer(spi, tx, rx, sizeof(tx));
            if (ret < 0) {
                fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retrying...\n");
                    retries++;
                } else {
                    fprintf(stderr, "Max retries exceeded. Exiting...\n");
                    turn_off_pump();
                    close_spi();
                    gpiod_chip_close(gpiod_chip);
                    return 1;
                }
            }
        } while (ret < 0);

        int reading = ((rx[1] & 0x03) << 8) | rx[2];
        reading *= 100;
        reading /= 1023;

        log_reading(reading);

        if (reading < THRESHOLD) {
            printf("Moisture level below threshold, activating pump...\n");
            gpiod_line_set_value(gpiod_line, 1);
        } else {
            turn_off_pump();
        }

        sleep(60);
    }

    turn_off_pump();
    close_spi();
    gpiod_chip_close(gpiod_chip);

    return 0;
}

