#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>
#include <spi0.h>

#define SPI_DEV "/dev/spidev0.0"
#define CHANNEL 0
#define CO2_MAX 700
#define ADC_MAX 1023
#define VREF 3.3
#define CO2_CONC_FACTOR 5000

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void sig_handler(int signo) {
    if (line)
        gpiod_line_set_value(line, 0);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    exit(signo);
}

int main() {
    struct spi_device *spi;
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0x00, 0x00, 0x00};
    int adc_val, co2_val;
    time_t t;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    spi = spi_init(SPI_DEV, 0, 1000000, SPI_MODE_0);
    if (!spi) {
        fprintf(stderr, "Failed to init SPI\n");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_number(2);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 18);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "fan", 0)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("air_quality.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        tx[1] = (CHANNEL << 6);
        if (spi_transfer(spi, tx, rx, 24)) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        adc_val = (rx[1] & 0x03) << 8 | rx[2];
        if (adc_val > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_val);
            continue;
        }

        co2_val = (adc_val * VREF / ADC_MAX) * CO2_CONC_FACTOR;
        t = time(NULL);

        fprintf(log_file, "%ld,%d,%s\n", t, co2_val, co2_val > CO2_MAX ? "ON" : "OFF");
        if (co2_val > CO2_MAX)
            gpiod_line_set_value(line, 1);
        else
            gpiod_line_set_value(line, 0);

        fflush(log_file);
        sleep(5);
    }

    return 0;
}

