#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <spi0.h>

#define SPI_BUS_SPEED 1000000
#define SENSOR_CHANNEL 0
#define CE_CHIP_ENABLE 0
#define GPIO_RELAY 17
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "door_events.log"

struct gpiod_chip *chip;
struct gpiod_line *line;
int spi_fd;
FILE *log_file;

void cleanup_and_exit(int sig) {
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (spi_fd >= 0)
        close(spi_fd);
    if (log_file)
        fclose(log_file);
    exit(sig);
}

int main() {
    struct spi0_transfer_t transfer;
    struct spi0_config_t config;
    struct timespec ts;
    int distance, rc;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup_and_exit(-1);
    }

    config.speed = SPI_BUS_SPEED;
    config.mode = 0;
    config.bits_per_word = 16;
    if (ioctl(spi_fd, SPI0_IOC_SET_CONFIG, &config) < 0) {
        perror("Failed to set SPI configuration");
        cleanup_and_exit(-1);
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup_and_exit(-1);
    }

    line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup_and_exit(-1);
    }

    rc = gpiod_line_request_output(line, "door_sensor", 0);
    if (rc < 0) {
        perror("Failed to request GPIO line");
        cleanup_and_exit(-1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_and_exit(-1);
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        transfer.channel = SENSOR_CHANNEL;
        transfer.data = 0x8000 | (CE_CHIP_ENABLE << 8);
        if (write(spi_fd, &transfer, sizeof(transfer)) != sizeof(transfer)) {
            perror("Failed to read from sensor");
            cleanup_and_exit(-1);
        }

        distance = transfer.data & 0x3FF;
        if (distance < DISTANCE_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: Door opened\n", ts.tv_sec, ts.tv_nsec);
            fflush(log_file);

            gpiod_line_set_value(line, 1);
            usleep(1000000);
            gpiod_line_set_value(line, 0);
        }

        usleep(100000);
    }

    return 0;
}

