#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <spi/spi.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define SPI_RETRIES 5

struct spi_device *spi;
FILE *file;

void sig_handler(int signo) {
    spi_close(spi);
    fclose(file);
    exit(signo);
}

int spi_transfer(unsigned char *tx_data, unsigned char *rx_data, int len) {
    struct spi_transfer transfer = {
        .tx_buf = tx_data,
        .rx_buf = rx_data,
        .len = len,
    };
    struct spi_message message;
    spi_message_init(&message);
    spi_message_add_tail(&transfer, &message);

    return spi_sync(spi, &message);
}

int spi_read_adc(int channel, unsigned short *value) {
    unsigned char tx_data[2];
    unsigned char rx_data[2];
    int ret;

    tx_data[0] = (1 << 7) | (channel << 4);
    tx_data[1] = 0;

    ret = spi_transfer(tx_data, rx_data, sizeof(tx_data));
    if (ret < 0)
        return ret;

    *value = ((rx_data[0] & 0x03) << 8) | rx_data[1];

    return 0;
}

int main() {
    int ret, retry;
    unsigned short value;
    struct timespec ts;
    char time_str[20];

    spi = spi_open_device(SPI_DEV, SPI_MODE, SPI_MAX_SPEED_HZ, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    file = fopen("soil_data.txt", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        spi_close(spi);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        for (retry = 0; retry < SPI_RETRIES; retry++) {
            ret = spi_read_adc(SPI_CHANNEL, &value);
            if (ret == 0)
                break;

            fprintf(stderr, "SPI read failed, retrying...\n");
            usleep(1 << retry);
        }

        if (retry == SPI_RETRIES) {
            fprintf(stderr, "SPI read failed after %d retries\n", retry);
            fprintf(file, "ERROR: SPI read failed after %d retries\n", retry);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (value < 0 || value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", value);
            fprintf(file, "%s, ERROR: Invalid ADC value\n", time_str);
            continue;
        }

        // Convert ADC value to moisture percentage
        // This is a rough approximation and may not be accurate
        int moisture = (value * 100) / 1023;

        fprintf(file, "%s, %d\n", time_str, moisture);

        usleep(5000000);
    }

    return 0;
}

