    if (file == NULL)
        return;
    fprintf(file, "%lf %lf", last_distance, last_volume);
    fclose(file);
}

void exit_handler(int signum) {
    pwm_disable(pwm);
    pwm_free(pwm);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);
    save_config();
    exit(0);
}

int main() {
    load_config();
    signal(SIGINT, exit_handler);

    chip = gpiod_chip_open_by_path("/dev/gpiochip0");
    if (chip == NULL)
        goto error;

    trig_line = gpiod_chip_get_line(chip, TRIG_GPIO);
    if (gpiod_line_request_output(trig_line, "trig", 0) < 0)
        goto error;

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (gpiod_line_request_input(echo_line, "echo") < 0)
        goto error;

    adc = mcp3008_open(SPI_BUS_PATH, ADC_CHANNEL);
    if (adc == NULL)
        goto error;

    pwm = pwm_alloc(PWM_PATH, PWM_CHANNEL);
    if (pwm == NULL)
        goto error;
    if (pwm_config(pwm, PWM_PERIOD, PWM_PERIOD / 2) < 0)
        goto error;
    if (pwm_enable(pwm) < 0)
        goto error;

    while (1) {
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        int echo_value = gpiod_line_get_value(echo_line);
        if (echo_value < 0)
            goto error;

        double distance = echo_value * 1.0 / 10000;
        if (echo_value > 0)
            last_distance = distance;

        double volume = mcp3008_read(adc) / 1023.0;
        if (volume >= 0)
            last_volume = volume;

        double frequency = last_distance * 20000 + 1000;
        pwm_config(pwm, PWM_PERIOD / frequency, PWM_PERIOD / 2);
    }

    return 0;

error:
    fprintf(stderr, "Error: %s\n", strerror(errno));
    exit_handler(0);
    return 1;
}

