#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_BUS_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define GPIO_PIN_PUMP 18
#define GPIO_PUMP_ON 1
#define GPIO_PUMP_OFF 0
#define MOISTURE_THRESHOLD 300
#define LOG_FILE_NAME "irrigation.log"

struct spi_device *spi;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line_pump;
FILE *log_file;

void cleanup_and_exit(int signum) {
    fprintf(log_file, "%s: Pump turned off, shutting down.\n", asctime(localtime(&time(NULL))));
    gpiod_line_set_value(gpio_line_pump, GPIO_PUMP_OFF);
    spi_close(spi);
    gpiod_line_release(gpio_line_pump);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    struct spi_ioc_transfer xfer;
    uint16_t tx = 0x0000, rx = 0x0000;
    char buf[3];

    spi = spi_open_device(SPI_BUS_PATH, SPI_CHANNEL, SPI_MAX_SPEED_HZ, SPI_MODE);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return errno;
    }

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return errno;
    }

    gpio_line_pump = gpiod_chip_get_line(gpio_chip, GPIO_PIN_PUMP);
    if (!gpio_line_pump) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return errno;
    }

    ret = gpiod_line_request_output(gpio_line_pump, "pump", GPIO_PUMP_OFF);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        return errno;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return errno;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        tx = 0x01 << 12;
        buf[0] = tx >> 8;
        buf[1] = tx;
        xfer.tx_buf = (unsigned long)buf;
        xfer.rx_buf = (unsigned long)buf;
        xfer.len = 2;
        xfer.delay_usecs = 0;
        xfer.speed_hz = SPI_MAX_SPEED_HZ;
        xfer.bits_per_word = 0;

        ret = spi_transfer(spi, &xfer, 1);
        if (ret < 0) {
            fprintf(log_file, "%s: SPI transfer failed: %s\n", asctime(localtime(&time(NULL))), strerror(errno));
            continue;
        }

        rx = (buf[0] << 8) | buf[1];
        int moisture = (rx >> 4) & 0x3FF;
        fprintf(log_file, "%s: Moisture: %d\n", asctime(localtime(&time(NULL))), moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            gpiod_line_set_value(gpio_line_pump, GPIO_PUMP_ON);
            fprintf(log_file, "%s: Pump turned on.\n", asctime(localtime(&time(NULL))));
        } else {
            gpiod_line_set_value(gpio_line_pump, GPIO_PUMP_OFF);
            fprintf(log_file, "%s: Pump turned off.\n", asctime(localtime(&time(NULL))));
        }

        sleep(60);
    }

    return 0;
}

