#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <spi/spi.h>
#include <pthread.h>
#include <math.h>

#define SPI_BUS_PATH "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define PWM_PERIOD 1000000
#define PWM_DUTY_CYCLE_OFF 0
#define PWM_DUTY_CYCLE_MAX 100000
#define PWM_DUTY_CYCLE_STEP 1000
#define POT_MAX 4095
#define DELAY_5S 5
#define DELAY_2S 2

struct gpiod_chip *chip;
struct gpiod_line *lines[5];
struct spi_device *spi;
pthread_t thread;
int running = 1;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void *motor_control_thread(void *arg) {
    int direction1 = 0, direction2 = 1;
    while (running) {
        int pot1 = 0, pot2 = 0;
        int speed1 = 0, speed2 = 0;

        // Read potentiometer values
        for (int i = 0; i < 2; i++) {
            int ret = spi_read(spi, MCP3008_CHANNEL, &((int[]){&pot1, &pot2})[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read potentiometer: %s\n", strerror(-ret));
                exit(EXIT_FAILURE);
            }
        }

        // Map potentiometer values to speed
        speed1 = (pot1 * PWM_DUTY_CYCLE_MAX) / POT_MAX;
        speed2 = (pot2 * PWM_DUTY_CYCLE_MAX) / POT_MAX;

        // Accelerate motors
        for (int i = PWM_DUTY_CYCLE_OFF; i <= speed1; i += PWM_DUTY_CYCLE_STEP) {
            gpiod_line_set_value(lines[direction1 ? 2 : 3], i > speed1 - PWM_DUTY_CYCLE_STEP);
            gpiod_line_set_value(lines[direction2 ? 4 : 3], i > speed2 - PWM_DUTY_CYCLE_STEP);
            usleep(PWM_PERIOD / (2 * PWM_DUTY_CYCLE_MAX));
        }

        // Hold constant speed for 2 seconds
        sleep(DELAY_2S);

        // Decelerate motors
        for (int i = speed1; i >= PWM_DUTY_CYCLE_OFF; i -= PWM_DUTY_CYCLE_STEP) {
            gpiod_line_set_value(lines[direction1 ? 2 : 3], i > speed1 - PWM_DUTY_CYCLE_STEP);
            gpiod_line_set_value(lines[direction2 ? 4 : 3], i > speed2 - PWM_DUTY_CYCLE_STEP);
            usleep(PWM_PERIOD / (2 * PWM_DUTY_CYCLE_MAX));
        }

        // Pause for 5 seconds
        sleep(DELAY_5S);

        // Reverse direction
        direction1 ^= 1;
        direction2 ^= 1;
        gpiod_line_set_value(lines[2], direction1);
        gpiod_line_set_value(lines[4], direction2);
    }

    return NULL;
}

int main() {
    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open SPI device
    spi = spi_open(SPI_BUS_PATH, 1000000, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < 5; i++) {
        lines[i] = gpiod_chip_get_line(chip, (int[]){18, 24, 23, 25, 2}[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_output(lines[i], "motor_control", i < 2 ? 0 : 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(-ret));
            return EXIT_FAILURE;
        }
    }

    // Start motor control thread
    int ret = pthread_create(&thread, NULL, motor_control_thread, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to create thread: %s\n", strerror(-ret));
        return EXIT_FAILURE;
    }

    // Wait for motor control thread to finish
    pthread_join(thread, NULL);

    // Release GPIO lines
    for (int i = 0; i < 5; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close SPI device
    spi_close(spi);

    return EXIT_SUCCESS;
}

