    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct timespec ts = {0, 1000000};
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3] = {0, 0, 0};

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED) == -1) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_LINE_REQUEST, &GPIO_LINE) == -1) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);

        if (write(spi_fd, tx_buf, sizeof(tx_buf)) != sizeof(tx_buf)) {
            perror("Failed to write to SPI device");
            exit(EXIT_FAILURE);
        }

        if (read(spi_fd, rx_buf, sizeof(rx_buf)) != sizeof(rx_buf)) {
            perror("Failed to read from SPI device");
            exit(EXIT_FAILURE);
        }

        uint32_t adc_value = (rx_buf[1] << 8) | rx_buf[2];
        fprintf(log_file, "%ld|%u\n", ts.tv_nsec, adc_value);
        fflush(log_file);

        nanosleep(&ts, NULL);
    }

    return 0;
}

