#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define SPI_BUS_PATH "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_CHANNEL 0
#define LOG_FILE "gas_log.txt"

struct spi_ctx {
    int fd;
    FILE *log_file;
};

static struct spi_ctx spi_ctx;

static void spi_close(void)
{
    close(spi_ctx.fd);
    fclose(spi_ctx.log_file);
}

static void spi_init(void)
{
    spi_ctx.fd = open(SPI_BUS_PATH, O_RDWR);
    if (spi_ctx.fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    spi_ctx.log_file = fopen(LOG_FILE, "a");
    if (spi_ctx.log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_ctx.fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_ctx.fd, SPI_IOC_WR_LSB_FIRST, &lsbfirst) == -1) {
        fprintf(stderr, "Failed to set SPI endianness: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_ctx.fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_ctx.fd, SPI_IOC_WR_CHANNEL, &SPI_CHANNEL) == -1) {
        fprintf(stderr, "Failed to set SPI channel: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    atexit(spi_close);
}

static void sigint_handler(int signum)
{
    spi_close();
    exit(EXIT_SUCCESS);
}

static void read_gas_sensor(void)
{
    uint8_t tx_buf[3] = {1, 0, 0};
    uint8_t rx_buf[3] = {0, 0, 0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_ctx.fd, SPI_IOC_MESSAGE(1), &xfer) == -1) {
        fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(errno));
        return;
    }

    int adc_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
    double voltage = adc_value * 3.3 / 1023.0;

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(spi_ctx.log_file, "%s, %.3f, %d\n", timestamp, voltage, -1);
    printf("%s, %.3f, %d\n", timestamp, voltage, -1);
}

int main(void)
{
    signal(SIGINT, sigint_handler);
    spi_init();

    while (1) {
        read_gas_sensor();
        usleep(1000000);
    }

    return 0;
}

