        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_ctx.fd, SPI_IOC_MESSAGE(1), &xfer) == -1) {
        fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(errno));
        return;
    }

    int adc_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
    double voltage = adc_value * 3.3 / 1023.0;

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(spi_ctx.log_file, "%s, %.3f, %d\n", timestamp, voltage, -1);
    printf("%s, %.3f, %d\n", timestamp, voltage, -1);
}

int main(void)
{
    signal(SIGINT, sigint_handler);
    spi_init();

    while (1) {
        read_gas_sensor();
        usleep(1000000);
    }

    return 0;
}
```

This code initializes the SPI interface, sets up a SIGINT handler, and enters a loop that reads from the gas sensor, logs the results, and sleeps for 1 second. If the SPI initialization or any SPI operation fails, the program prints an error message and exits. If the SIGINT handler is triggered, it closes the SPI interface and exits gracefully.

