        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);
    exit(sig);
}

int main() {
    int ret;
    unsigned char tx[2], rx[2];
    struct sigaction act;

    act.sa_handler = cleanup_and_exit;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup_and_exit(-1);
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_output(cs_line, "cs", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
    }

    spi = spi_open(0, 0);
    if (!spi) {
        perror("spi_open");
        cleanup_and_exit(-1);
    }

    for (int i = 0; i < ADC_CHANNELS; i++) {
        kf[i] = kf_alloc(FILTER_ORDER, 1.0 / SAMPLE_RATE);
