            perror("kf_alloc");
            cleanup_and_exit(-1);
        }
    }

    while (1) {
        for (int ch = 0; ch < ADC_CHANNELS; ch++) {
            tx[0] = (ch << 4) | 0x80;
            tx[1] = 0;
