            if (ret < 0) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }
            ret = spi_transfer(spi, tx, rx, 2);
            if (ret < 0) {
                perror("spi_transfer");
                cleanup_and_exit(-1);
