            double filtered = kf_filter(kf[ch], (double)val / 1023.0 * 3.3);
            printf("Channel %d: %f g\n", ch, filtered);
        }
        sleep(1 / SAMPLE_RATE);
    }

    cleanup_and_exit(0);
