#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

#define FILE_NAME "magnetic_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *sensor1, *sensor2, *sensor3;
FILE *file;

void sigint_handler(int signum) {
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_line_release(sensor3);
    gpiod_chip_close(chip);
    fclose(file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    sensor3 = gpiod_chip_get_line(chip, SENSOR3_GPIO);

    if (!sensor1 || !sensor2 || !sensor3) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input(sensor1) ||
        gpiod_line_request_input(sensor2) ||
        gpiod_line_request_input(sensor3)) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n", strerror(errno));
        return 1;
    }

    file = fopen(FILE_NAME, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int val1, val2, val3;

        val1 = gpiod_line_get_value(sensor1);
        val2 = gpiod_line_get_value(sensor2);
        val3 = gpiod_line_get_value(sensor3);

        if (val1 < 0 || val2 < 0 || val3 < 0) {
            fprintf(stderr, "Failed to read GPIO lines: %s\n", strerror(errno));
            continue;
        }

        int sensor1_mT = val1 ? 100 : -100;
        int sensor2_mT = val2 ? 100 : -100;
        int sensor3_mT = val3 ? 100 : -100;

        if (sensor1_mT < -100 || sensor1_mT > 100 ||
            sensor2_mT < -100 || sensor2_mT > 100 ||
            sensor3_mT < -100 || sensor3_mT > 100) {
            fprintf(stderr, "Warning: Computed magnetic field outside range -100mT to +100mT\n");
        }

        fprintf(file, "%d,%d,%d\n", sensor1_mT, sensor2_mT, sensor3_mT);
        fflush(file);

        usleep(100000);
    }

    return 0;
}

