#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <spi0.h>

#define LOG_FILE "watering.log"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 500000
#define SPI_CHANNEL 0
#define GPIO_PUMP 17
#define MOISTURE_THRESHOLD 30
#define EVALUATION_INTERVAL 60

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

void handle_signal(int signum) {
    gpiod_line_set_value(line, 0);
    log_message("Signal received, turning pump off and exiting.");
    fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    struct spi_device *spi;

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }

    log_message("Program started.");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        log_message("Failed to open GPIO chip.");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (line == NULL) {
        log_message("Failed to get GPIO line.");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "pump", 0);
    if (ret < 0) {
        log_message("Failed to request GPIO line.");
        exit(EXIT_FAILURE);
    }

    spi = spi_init(SPI_DEVICE, SPI_MODE, SPI_MAX_SPEED_HZ);
    if (spi == NULL) {
        log_message("Failed to initialize SPI.");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int value = spi_read(spi, SPI_CHANNEL);
        if (value < 0) {
            log_message("Failed to read ADC.");
            continue;
        }

        int moisture = value * 100 / 1023;
        if (moisture < MOISTURE_THRESHOLD) {
            if (gpiod_line_get_value(line) == 0) {
                gpiod_line_set_value(line, 1);
                log_message("Moisture level below threshold, turning pump on.");
            }
        } else {
            if (gpiod_line_get_value(line) == 1) {
                gpiod_line_set_value(line, 0);
                log_message("Moisture level above threshold, turning pump off.");
            }
        }

        sleep(EVALUATION_INTERVAL);
    }

    spi_close(spi);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_message("Program terminated.");
    fclose(log_file);

    return 0;
}

