#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CSV_FILE "sensor_data.csv"
#define CHANNELS 3

int spi_fd = -1;
int csv_fd = -1;

void cleanup_and_exit(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (csv_fd != -1) {
        fdatasync(csv_fd);
        close(csv_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    csv_fd = open(CSV_FILE, O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        cleanup_and_exit(1);
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup_and_exit(1);
    }

    int bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup_and_exit(1);
    }

    int speed_hz = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        perror("Failed to set SPI speed");
        cleanup_and_exit(1);
    }

    signal(SIGINT, cleanup_and_exit);

    char buffer[CHANNELS * 4];
    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            buffer[i * 4] = 0x01;
            buffer[i * 4 + 1] = (i << 4) & 0x60;
            buffer[i * 4 + 2] = 0x00;
            buffer[i * 4 + 3] = 0x00;
        }

        if (write(spi_fd, buffer, CHANNELS * 4) < 0) {
            perror("Failed to write to SPI device");
            cleanup_and_exit(1);
        }

        if (read(spi_fd, buffer, CHANNELS * 4) < 0) {
            perror("Failed to read from SPI device");
            cleanup_and_exit(1);
        }

        for (int i = 0; i < CHANNELS; i++) {
            int value = (buffer[i * 4 + 2] << 8) | buffer[i * 4 + 3];
            dprintf(csv_fd, "%d,", value);
        }
        dprintf(csv_fd, "\n");

        sleep(1);
    }

    return 0;
}

