        cleanup_and_exit(1);
    }

    int bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup_and_exit(1);
    }

    int speed_hz = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        perror("Failed to set SPI speed");
        cleanup_and_exit(1);
    }

    signal(SIGINT, cleanup_and_exit);

    char buffer[CHANNELS * 4];
    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            buffer[i * 4] = 0x01;
            buffer[i * 4 + 1] = (i << 4) & 0x60;
            buffer[i * 4 + 2] = 0x00;
            buffer[i * 4 + 3] = 0x00;
        }

        if (write(spi_fd, buffer, CHANNELS * 4) < 0) {
            perror("Failed to write to SPI device");
            cleanup_and_exit(1);
        }

        if (read(spi_fd, buffer, CHANNELS * 4) < 0) {
            perror("Failed to read from SPI device");
            cleanup_and_exit(1);
        }

        for (int i = 0; i < CHANNELS; i++) {
            int value = (buffer[i * 4 + 2] << 8) | buffer[i * 4 + 3];
            dprintf(csv_fd, "%d,", value);
        }
        dprintf(csv_fd, "\n");

        sleep(1);
    }

    return 0;
}
```

This code opens the SPI device and CSV file, sets the SPI parameters, and installs the SIGINT handler. It then enters a loop where it sends a command to read the MCP3008 channels and then reads the responses. The readings are written to the CSV file. The loop repeats every second. If any error occurs during the open, ioctl, or read calls, the error is printed and the program exits. If the user presses Ctrl+C, the CSV file is closed and the SPI device is released before the program terminates.

