#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <paho_mqtt/MQTTClient.h>
#include <jansson.h>

#define LED_GPIO 17
#define MQTT_BROKER "tcp://mqtt.eclipseprojects.io:1883"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"

static struct gpiod_line *led_line;
static MQTTClient mqtt_client;
static int keep_running = 1;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

void mqtt_connect_failure(void *context, MQTTClient_connectOptions *opts) {
    fprintf(stderr, "MQTT connect failure: %s\n", MQTTClient_error_string(MQTTClient_get_last_error()));
}

void mqtt_message_arrived(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    json_error_t error;
    json_t *root = json_loads(message->payload, 0, &error);
    if (!root) {
        fprintf(stderr, "JSON parsing error on line %d: %s\n", error.line, error.text);
        return;
    }

    json_t *led_state = json_object_get(root, "led_state");
    if (!led_state || !json_is_boolean(led_state)) {
        fprintf(stderr, "Invalid JSON payload: led_state is missing or not a boolean\n");
        json_decref(root);
        return;
    }

    gpiod_line_set_value(led_line, json_boolean_value(led_state) ? 1 : 0);
    json_decref(root);
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0)) {
        perror("gpiod_line_request_output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_set_value(led_line, 0);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.onFailure = mqtt_connect_failure;
    conn_opts.username = "";
    conn_opts.password = "";

    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, 0);
    MQTTClient_setCallback(&mqtt_client, mqtt_message_arrived, NULL);

    while (keep_running) {
        if (MQTTClient_connect(mqtt_client, &conn_opts)) {
            fprintf(stderr, "MQTT connect failure: %s\n", MQTTClient_error_string(MQTTClient_get_last_error()));
            sleep(1);
            continue;
        }

        if (MQTTClient_subscribe(mqtt_client, MQTT_TOPIC, 0)) {
            fprintf(stderr, "MQTT subscribe failure: %s\n", MQTTClient_error_string(MQTTClient_get_last_error()));
            MQTTClient_disconnect(mqtt_client, 1000);
            continue;
        }

        while (keep_running) {
            MQTTClient_yield(mqtt_client, 1000);
        }

        MQTTClient_disconnect(mqtt_client, 1000);
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

