#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;
volatile sig_atomic_t stop;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM)
        stop = 1;
}

void log_message(const char *msg) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char buf[64];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s\n", buf, msg);
    printf("%s - %s\n", buf, msg);
}

int main() {
    struct sigaction sig_action;
    memset(&sig_action, 0, sizeof(sig_action));
    sig_action.sa_handler = sig_handler;
    sigaction(SIGINT, &sig_action, NULL);
    sigaction(SIGTERM, &sig_action, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto err_chip;
    }

    if (gpiod_line_request_falling_edge_events(line, "vibration-monitor")) {
        perror("gpiod_line_request_falling_edge_events");
        goto err_line;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        goto err_line;
    }

    while (!stop) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, NULL)) {
            if (errno == ETIMEDOUT)
                continue;
            perror("gpiod_line_event_wait");
            break;
        }

        if (gpiod_line_event_read(line, &event)) {
            perror("gpiod_line_event_read");
            break;
        }

        log_message("Vibration detected, shutting down...");
        system("sudo shutdown -h now");
    }

    fclose(log_file);
err_line:
    gpiod_line_release(line);
err_chip:
    gpiod_chip_close(chip);
    return 1;
}

