    struct tm *ptm;
    char timestamp[20];
    FILE *fp;
    int ret;

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c device");
        exit(1);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("set i2c slave");
        exit(1);
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        exit(1);
    }

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long) NULL,
        .rx_buf = (unsigned long) NULL,
        .len = 0,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    fp = fopen("environmental_log.txt", "a");
    if (fp == NULL) {
        perror("open log file");
        exit(1);
    }

    while (1) {
        gettimeofday(&tv, NULL);
        ptm = localtime(&tv.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ptm);

        // Read light sensor
        char buf[2];
        buf[0] = 0x10;
        ret = write(i2c_fd, buf, 1);
        if (ret < 0) {
            fprintf(fp, "%s, Light: error\n", timestamp);
        } else {
            ret = read(i2c_fd, buf, 2);
            if (ret < 0) {
                fprintf(fp, "%s, Light: error\n", timestamp);
            } else {
                int light = (buf[0] << 8) | buf[1];
                fprintf(fp, "%s, Light: %d lux\n", timestamp, light);
            }
        }

        // Read sound sensor
        xfer.tx_buf = (unsigned long) &SPI_CHANNEL;
        xfer.rx_buf = (unsigned long) buf;
        xfer.len = 3;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            fprintf(fp, "%s, Sound: error\n", timestamp);
        } else {
            int sound = (buf[1] & 0x0F) << 8 | buf[2];
            fprintf(fp, "%s, Sound: %d\n", timestamp, sound);
        }

        fprintf(fp, "\n");
        fflush(fp);

        sleep(1);
    }

    fclose(fp);
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

