    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line 17: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_REQ_FLAG_BIAS_PULL_DOWN)) {
        fprintf(stderr, "Failed to request line 17 for input: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen("flame_events.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Failed to get line value: %s\n", strerror(errno));
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        log_event(state);

        if (state) {
            printf("Flame detected!\n");
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

