#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "temperature_log.txt"
#define TMP36_ADC_CHANNEL 0
#define MCP3008_MAX_COUNT 4095
#define TMP36_MAX_VOLTAGE 1.32
#define MCP4725_I2C_ADDRESS 0x60
#define TEMP_TO_VOLT_CONST 1.2

volatile sig_atomic_t stop = 0;

int spi_fd, i2c_fd, log_fd;

void sigint_handler(int signum) {
    close(spi_fd);
    close(i2c_fd);
    fclose((FILE*)log_fd);
    stop = 1;
}

int spi_transfer(const char *tx_data, char *rx_data, int len) {
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx_data,
        .rx_buf = (unsigned long)rx_data,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };
    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
}

int i2c_write(const char *data, int len) {
    return write(i2c_fd, data, len);
}

int main() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    log_fd = fopen(LOG_FILE, "w");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    char tx_data[3] = {1, (TMP36_ADC_CHANNEL << 4), 0};
    char rx_data[3];
    char dac_data[2] = {0x01, 0x00};

    while (!stop) {
        if (spi_transfer(tx_data, rx_data, sizeof(rx_data)) < 0) {
            perror("SPI transfer failed");
            continue;
        }

        int adc_count = ((rx_data[1] & 0x03) << 8) | rx_data[2];
        float temp_c = adc_count * TMP36_MAX_VOLTAGE / MCP3008_MAX_COUNT;
        float dac_voltage = temp_c * TEMP_TO_VOLT_CONST;

        dac_data[1] = (int)(dac_voltage * 4095);
        if (i2c_write(dac_data, sizeof(dac_data)) < 0) {
            perror("I2C write failed");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_fd, "%s, %d, %.2f, %.2f\n", timestamp, adc_count, temp_c, dac_voltage);
        printf("%s, %d, %.2f, %.2f\n", timestamp, adc_count, temp_c, dac_voltage);

        sleep(500);
    }

    return 0;
}

