#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_FREQ 1000000
#define SPI_THRESHOLD 0x800
#define DEBOUNCE_DELAY 100000
#define LOG_FILE "sound_events.log"

struct gpiod_chip *chip;
struct gpiod_line *line_led;
struct spi_device *spi;
FILE *log_file;

void sigint_handler(int signum) {
    gpiod_line_set_value(line_led, 0);
    spi_close(spi);
    gpiod_line_release(line_led);
    fclose(log_file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line_led = gpiod_chip_get_line(chip, 16);
    if (!line_led) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line_led, "sound_sensor", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    spi = spi_open(SPI_DEV_PATH, SPI_MODE, SPI_FREQ);
    if (!spi) {
        perror("spi_open");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        uint16_t adc_value;
        if (spi_transfer(spi, 0, &adc_value, 1)) {
            perror("spi_transfer");
            return 1;
        }

        if (adc_value > SPI_THRESHOLD) {
            gpiod_line_set_value(line_led, 1);
            usleep(500000);
            gpiod_line_set_value(line_led, 0);

            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s: Sound event detected. ADC value: %u\n", timestamp, adc_value);
            fflush(log_file);

            usleep(DEBOUNCE_DELAY);
        }
    }

    return 0;
}

