#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <spi/spi.h>
#include <pthread.h>

#define RAIN_THRESHOLD 5
#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "rain_log.txt"
#define GPIO_ENA 27
#define GPIO_IN1 17
#define GPIO_IN2 18
#define PWM_DUTY 150
#define PWM_RANGE 255

struct spi_device *spi;
FILE *log_file;
struct gpiod_chip *chip;
struct gpiod_line *line_ena, *line_in1, *line_in2;
volatile sig_atomic_t stop;

void sig_handler(int signo) {
    stop = 1;
}

void cleanup() {
    if (spi)
        spi_close(spi);
    if (log_file)
        fclose(log_file);
    if (line_ena)
        gpiod_line_release(line_ena);
    if (line_in1)
        gpiod_line_release(line_in1);
    if (line_in2)
        gpiod_line_release(line_in2);
    if (chip)
        gpiod_chip_close(chip);
}

int main() {
    struct sigaction sig_action;
    struct spi_ioc_transfer spi_xfer;
    char spi_buf[4];
    int spi_fd, log_fd, ret, i;
    time_t t;
    struct tm *time;
    char time_str[20];

    memset(&sig_action, 0, sizeof(struct sigaction));
    sig_action.sa_handler = sig_handler;
    sigaction(SIGINT, &sig_action, NULL);
    sigaction(SIGTERM, &sig_action, NULL);

    spi = spi_open_device(SPI_DEV, 1000000, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", spi_strerror(spi_errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line_ena = gpiod_chip_get_line(chip, GPIO_ENA);
    if (!line_ena) {
        fprintf(stderr, "Failed to get ENA line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line_in1 = gpiod_chip_get_line(chip, GPIO_IN1);
    if (!line_in1) {
        fprintf(stderr, "Failed to get IN1 line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line_in2 = gpiod_chip_get_line(chip, GPIO_IN2);
    if (!line_in2) {
        fprintf(stderr, "Failed to get IN2 line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop) {
        spi_xfer.tx_buf = (unsigned long) spi_buf;
        spi_xfer.rx_buf = (unsigned long) spi_buf;
        spi_xfer.len = 4;
        spi_xfer.speed_hz = 1000000;
        spi_xfer.bits_per_word = 8;
        spi_xfer.delay_usecs = 0;

        ret = spi_transfer(spi, &spi_xfer);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer error: %s\n", spi_strerror(spi_errno));
            cleanup();
            return EXIT_FAILURE;
        }

        t = time(NULL);
        time = localtime(&t);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time);

        fprintf(log_file, "%s: %d\n", time_str, spi_buf[1]);
        fflush(log_file);

        if (spi_buf[1] > RAIN_THRESHOLD) {
            gpiod_line_set_value(line_in1, 1);
            gpiod_line_set_value(line_in2, 0);
            gpiod_line_set_value(line_ena, PWM_DUTY);
            sleep(3);
            gpiod_line_set_value(line_ena, 0);
        } else {
            gpiod_line_set_value(line_in1, 0);
            gpiod_line_set_value(line_in2, 1);
            gpiod_line_set_value(line_ena, PWM_DUTY);
            sleep(3);
            gpiod_line_set_value(line_ena, 0);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

