#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_LINE 17
#define MAX_TRIES 5

struct gpiod_chip *chip;
struct gpiod_line *line;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    FILE *file = fopen("distance_log.txt", "a");
    if (!file) {
        printf("Error opening file\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        printf("Error opening GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        printf("Error getting GPIO line\n");
        return 1;
    }

    if (gpiod_line_request_input(line, "distance_sensor")) {
        printf("Error requesting GPIO line\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int tries = 0;
    while (1) {
        int value;
        if (gpiod_line_get_value(line, &value)) {
            if (tries < MAX_TRIES) {
                printf("Error reading GPIO line, retrying...\n");
                sleep(1);
                tries++;
                continue;
            } else {
                printf("Error reading GPIO line after %d tries, exiting...\n", MAX_TRIES);
                return 1;
            }
        }

        time_t now = time(0);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(file, "%s,%d\n", timestamp, value);
        fflush(file);

        printf("%s: Distance: %d ", timestamp, value);
        printf(value < 200 ? "Feeder Activated\n" : "Feeder Idle\n");

        tries = 0;
        sleep(1);
    }

    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

