#define SPI_BUS_PATH "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_FREQUENCY 1000000
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define MOISTURE_THRESHOLD 30
#define GPIO_PUMP 17

struct spi_device *spi;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void cleanup_and_exit(int signum) {
    fprintf(log_file, "%s: Pump turned OFF\n", ctime(&time(NULL)));
    gpiod_line_set_value(line, 0);
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    spi_free_device(spi);
    exit(0);
}

int main() {
    spi = spi_init(SPI_BUS_PATH, SPI_CHANNEL, SPI_FREQUENCY, 0);
    if (!spi) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        spi_free_device(spi);
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        spi_free_device(spi);
        return 1;
    }

    if (gpiod_line_request_output(line, "pump", 0)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        spi_free_device(spi);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        spi_free_device(spi);
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        int adc_value = spi_read_adc(spi, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(log_file, "%s: Failed to read ADC\n", ctime(&time(NULL)));
            continue;
        }

        int moisture_percent = (adc_value * 100) / 1023;
        fprintf(log_file, "%s: Moisture level: %d%%\n", ctime(&time(NULL)), moisture_percent);

        if (moisture_percent < MOISTURE_THRESHOLD) {
            if (gpiod_line_get_value(line) == 0) {
                fprintf(log_file, "%s: Moisture level below threshold, turning pump ON\n", ctime(&time(NULL)));
                gpiod_line_set_value(line, 1);
            }
        } else {
            if (gpiod_line_get_value(line) == 1) {
                fprintf(log_file, "%s: Moisture level above threshold, turning pump OFF\n", ctime(&time(NULL)));
                gpiod_line_set_value(line, 0);
            }
        }

        sleep(60);
    }

    return 0;
}

