#include <signal.h>
#include <time.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "magnetic_log.txt"
#define GPIO_CS 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

static int spi_fd = -1;
static int gpio_fd = -1;
static FILE* log_file = NULL;

void exit_handler(int signum) {
    if (spi_fd != -1) close(spi_fd);
    if (gpio_fd != -1) close(gpio_fd);
    if (log_file != NULL) fclose(log_file);
    exit(signum);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[2], rx_buf[2];
    int32_t magnetic_field;
    struct timespec ts;
    double magnetic_field_double;
    char log_line[100];

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &lsbfirst) < 0) {
        perror("Failed to set SPI endianness");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        exit_handler(-1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        exit_handler(-1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit_handler(-1);
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

