    spi = spi_open(SPI_DEV, SPI_MODE, SPI_MAX_SPEED_HZ);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, SPI_CS_GPIO);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line: %s\n", strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "cs", 1)) {
        fprintf(stderr, "Failed to request CS line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0)) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        return 1;
    }

    file = fopen(FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

