        fprintf(file, "%d-%02d-%02d %02d:%02d:%02d: %.2f mT\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, field_strength);
        if (field_strength > FIELD_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
        usleep(100000);
    }

    return 0;
}

