    fprintf(log_file, "%s %.2f A\n", buffer, current);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_DEVICE, 1000000, 0);
    if (spi_handle < 0) {
