#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <libgen.h>
#include <limits.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#define GPIO_LINE 17
#define DEBOUNCE_TIME 200000000
#define POLL_TIME 50000000
#define DIRECTORY "/home/pi/security_cam/"

struct timespec ts = { .tv_nsec = 0 };
struct gpiod_line *line;
struct gpiod_chip *chip;
pid_t child;
volatile sig_atomic_t stop = false;

void capture(void) {
    char filename[PATH_MAX];
    struct tm *timeinfo;
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    assert(timeinfo != NULL);

    snprintf(filename, PATH_MAX, "%s%d-%02d-%02d_%02d:%02d:%02d.jpg", DIRECTORY,
             1900 + timeinfo->tm_year, 1 + timeinfo->tm_mon, timeinfo->tm_mday,
             timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    if (mkdir(DIRECTORY, 0700) == -1 && errno != EEXIST) {
        syslog(LOG_ERR, "Failed to create directory: %s", strerror(errno));
        return;
    }

    char *const argv[] = { "/usr/bin/libcamera-still", "-n", "-o", filename, NULL };
    child = fork();
    if (child == 0) {
        execvp(argv[0], argv);
        _exit(1);
    }

    int status;
    if (waitpid(child, &status, 0) == -1) {
        syslog(LOG_ERR, "Failed to wait for child: %s", strerror(errno));
        return;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        syslog(LOG_INFO, "Capture succeeded");
    else
        syslog(LOG_ERR, "Capture failed");
}

void handle_signal(int signum) {
    stop = true;
}

int main(void) {
    openlog("motion_detector", LOG_PERROR, LOG_USER);
    syslog(LOG_INFO, "Started");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input_events(line) == -1) {
        syslog(LOG_ERR, "Failed to request input events: %s", strerror(errno));
        return 1;
    }

    struct sigaction action = { .sa_handler = handle_signal };
    if (sigaction(SIGINT, &action, NULL) == -1 || sigaction(SIGTERM, &action, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        return 1;
    }

    bool last_state = false;
    while (!stop) {
        bool state = gpiod_line_get_value(line) == 1;
        if (state != last_state) {
            last_state = state;
            ts.tv_nsec += DEBOUNCE_TIME;
            nanosleep(&ts, NULL);
            bool confirm = gpiod_line_get_value(line) == 1;
            if (confirm == state)
                capture();
        }

        ts.tv_nsec += POLL_TIME;
        nanosleep(&ts, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();
    syslog(LOG_INFO, "Stopped");
    return 0;
}

