#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_FORMAT V4L2_PIX_FMT_GREY
#define IMAGE_SIZE 1280*720

int fd = -1;
char *mmap_ptr = NULL;
int image_number = 0;
int should_exit = 0;

void exit_handler(int signum) {
    should_exit = 1;
}

int main(int argc, char **argv) {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbuf;
    struct v4l2_buffer buf;
    struct timeval timeout;
    fd_set fds;
    int ret;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    const char *device = DEFAULT_DEVICE;
    if (argc > 1)
        device = argv[1];

    fd = open(device, O_RDWR);
    if (fd < 0) {
        printf("open %s failed: %s\n", device, strerror(errno));
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1280;
    fmt.fmt.pix.height = 720;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_ANY;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        printf("ioctl VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto error;
    }

    memset(&reqbuf, 0, sizeof(reqbuf));
    reqbuf.count = 1;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        printf("ioctl VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto error;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        printf("ioctl VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto error;
    }

    mmap_ptr = mmap(NULL, buf.length, PROT_READ, MAP_SHARED, fd, buf.m.offset);
    if (mmap_ptr == MAP_FAILED) {
        printf("mmap failed: %s\n", strerror(errno));
        goto error;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        printf("ioctl VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto error;
    }

    while (!should_exit) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        timeout.tv_sec = 2;
        timeout.tv_usec = 0;
