#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9

#define PWM_PERIOD_US 20000
#define MIN_DUTY 50
#define MAX_DUTY 100
#define MID_DUTY 75
#define STEP 5
#define SLEEP_US 50000

struct gpiod_chip *chip;
struct gpiod_line *pan_line, *tilt_line, *up_line, *down_line, *left_line, *right_line;

void sigint_handler(int signum)
{
    gpiod_line_set_pwm_duty_cycle(pan_line, MID_DUTY);
    gpiod_line_set_pwm_duty_cycle(tilt_line, MID_DUTY);
    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(up_line);
    gpiod_line_release(down_line);
    gpiod_line_release(left_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

int main()
{
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_PIN);
    up_line = gpiod_chip_get_line(chip, UP_PIN);
    down_line = gpiod_chip_get_line(chip, DOWN_PIN);
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);

    if (!pan_line || !tilt_line || !up_line || !down_line || !left_line || !right_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_pwm_mode(pan_line, PWM_PERIOD_US, MID_DUTY) ||
        gpiod_line_request_pwm_mode(tilt_line, PWM_PERIOD_US, MID_DUTY)) {
        perror("gpiod_line_request_pwm_mode");
        return 1;
    }

    if (gpiod_line_request_input_mode(up_line) ||
        gpiod_line_request_input_mode(down_line) ||
        gpiod_line_request_input_mode(left_line) ||
        gpiod_line_request_input_mode(right_line)) {
        perror("gpiod_line_request_input_mode");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (gpiod_line_get_value(up_line) && MID_DUTY + STEP <= MAX_DUTY)
            gpiod_line_set_pwm_duty_cycle(tilt_line, MID_DUTY += STEP);
        else if (gpiod_line_get_value(down_line) && MID_DUTY - STEP >= MIN_DUTY)
            gpiod_line_set_pwm_duty_cycle(tilt_line, MID_DUTY -= STEP);
        if (gpiod_line_get_value(left_pin) && MID_DUTY + STEP <= MAX_DUTY)
            gpiod_line_set_pwm_duty_cycle(pan_line, MID_DUTY += STEP);
        else if (gpiod_line_get_value(right_pin) && MID_DUTY - STEP >= MIN_DUTY)
            gpiod_line_set_pwm_duty_cycle(pan_line, MID_DUTY -= STEP);

        usleep(SLEEP_US);
    }

    return 0;
}

