#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_TIMEOUT_USEC 2000000

struct buffer {
    void *start;
    size_t length;
};

static int fd = -1;
static struct buffer *buffers = NULL;
static int n_buffers = 0;

static void cleanup_and_exit(int sig)
{
    if (fd >= 0) {
        for (int i = 0; i < n_buffers; i++) {
            if (buffers[i].start) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        close(fd);
    }
    exit(sig);
}

int main(void)
{
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct timeval tv;
    fd_set fds;
    int ret;

    signal(SIGINT, cleanup_and_exit);

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s\n", DEVICE_NAME);
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_G_FMT, &fmt);
    if (ret < 0) {
        fprintf(stderr, "Failed to get format\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request buffers\n");
        cleanup_and_exit(EXIT_FAILURE);
    }
    n_buffers = req.count;
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Failed to allocate buffer structures\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.index = i;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
        if (ret < 0) {
            fprintf(stderr, "Failed to query buffer %d\n", i);
            cleanup_and_exit(EXIT_FAILURE);
        }
        buffers[i].start = mmap(NULL, buf.length, PROT_READ, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Failed to mmap buffer %d\n", i);
            cleanup_and_exit(EXIT_FAILURE);
        }
        buffers[i].length = buf.length;

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            fprintf(stderr, "Failed to queue buffer %d\n", i);
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &fmt.type);
    if (ret < 0) {
        fprintf(stderr, "Failed to start streaming\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = FRAME_TIMEOUT_USEC / 1000000;
    tv.tv_usec = FRAME_TIMEOUT_USEC % 1000000;
    ret = select(fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) {
        fprintf(stderr, "select() failed\n");
        cleanup_and_exit(EXIT_FAILURE);
    }
    if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "Failed to dequeue buffer\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = ioctl(fd, VIDIOC_STREAMOFF, &fmt.type);
    if (ret < 0) {
        fprintf(stderr, "Failed to stop streaming\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

