        perror("Could not open device node");
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Could not query device capabilities");
        goto error;
    }

    printf("Device name: %s\n", cap.card);

    fmt.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == 0) {
        printf("Format: %s\n", fmt.description);

        frmsize.index = 0;
        frmsize.pixelformat = fmt.pixelformat;
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
            printf("  Frame size: %ux%u\n", frmsize.discrete.width, frmsize.discrete.height);

            frmival.index = 0;
            frmival.width = frmsize.discrete.width;
            frmival.height = frmsize.discrete.height;
            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
                printf("    Frame rate: %u/%u\n", frmival.discrete.numerator, frmival.discrete.denominator);
                frmival.index++;
            }

            frmsize.index++;
        }

        fmt.index++;
    }

    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl);
    if (ret < 0) {
        perror("Could not query autofocus capability");
        goto error;
    }

    printf("Autofocus supported: %s\n", queryctrl.flags & V4L2_CTRL_FLAG_DISABLED ? "No" : "Yes");

    close(fd);
    return EXIT_SUCCESS;

error:
    close(fd);
    return EXIT_FAILURE;
}
