#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define PWM_FREQ_HZ 50
#define PWM_CENTER_DUTY 1500
#define PWM_MIN_DUTY 1000
#define PWM_MAX_DUTY 2000
#define PWM_DUTY_STEP 10

struct gpiod_chip *chip;
struct gpiod_line *pan_servo_line, *tilt_servo_line, *up_button_line, *down_button_line, *left_button_line, *right_button_line;

void cleanup_and_exit(int signum)
{
    gpiod_line_set_pwm_duty_cycle(pan_servo_line, PWM_CENTER_DUTY);
    gpiod_line_set_pwm_duty_cycle(tilt_servo_line, PWM_CENTER_DUTY);
    gpiod_line_release(pan_servo_line);
    gpiod_line_release(tilt_servo_line);
    gpiod_line_release(up_button_line);
    gpiod_line_release(down_button_line);
    gpiod_line_release(left_button_line);
    gpiod_line_release(right_button_line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

int main()
{
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pan_servo_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_servo_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    up_button_line = gpiod_chip_get_line(chip, UP_BUTTON_PIN);
    down_button_line = gpiod_chip_get_line(chip, DOWN_BUTTON_PIN);
    left_button_line = gpiod_chip_get_line(chip, LEFT_BUTTON_PIN);
    right_button_line = gpiod_chip_get_line(chip, RIGHT_BUTTON_PIN);

    if (!pan_servo_line || !tilt_servo_line || !up_button_line || !down_button_line || !left_button_line || !right_button_line) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    if (gpiod_line_request_pwm_mode(pan_servo_line, PWM_FREQ_HZ, PWM_CENTER_DUTY) ||
        gpiod_line_request_pwm_mode(tilt_servo_line, PWM_FREQ_HZ, PWM_CENTER_DUTY) ||
        gpiod_line_request_input_mode(up_button_line) ||
        gpiod_line_request_input_mode(down_button_line) ||
        gpiod_line_request_input_mode(left_button_line) ||
        gpiod_line_request_input_mode(right_button_line)) {
        perror("Failed to set GPIO line mode");
        return 1;
    }

    printf("Started with pan and tilt at center position\n");

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        if (gpiod_line_get_value(up_button_line)) {
            int duty = gpiod_line_get_pwm_duty_cycle(tilt_servo_line);
            if (duty + PWM_DUTY_STEP <= PWM_MAX_DUTY)
                gpiod_line_set_pwm_duty_cycle(tilt_servo_line, duty + PWM_DUTY_STEP);
        }

        if (gpiod_line_get_value(down_button_line)) {
            int duty = gpiod_line_get_pwm_duty_cycle(tilt_servo_line);
            if (duty - PWM_DUTY_STEP >= PWM_MIN_DUTY)
                gpiod_line_set_pwm_duty_cycle(tilt_servo_line, duty - PWM_DUTY_STEP);
        }

        if (gpiod_line_get_value(left_button_line)) {
            int duty = gpiod_line_get_pwm_duty_cycle(pan_servo_line);
            if (duty - PWM_DUTY_STEP >= PWM_MIN_DUTY)
                gpiod_line_set_pwm_duty_cycle(pan_servo_line, duty - PWM_DUTY_STEP);
        }

        if (gpiod_line_get_value(right_button_line)) {
            int duty = gpiod_line_get_pwm_duty_cycle(pan_servo_line);
            if (duty + PWM_DUTY_STEP <= PWM_MAX_DUTY)
                gpiod_line_set_pwm_duty_cycle(pan_servo_line, duty + PWM_DUTY_STEP);
        }

        sleep(50);
    }

    return 0;
}

