struct libcamera::Pipeline *pipeline;
struct libcamera::Stream *stream;
struct libcamera::Request *request;
struct curl_slist *headers = NULL;
CURL *curl;

void init_gpiod() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "pir", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void init_camera() {
    pipeline = Pipeline::create();
    if (!pipeline) {
        fprintf(stderr, "Failed to create camera pipeline\n");
        exit(EXIT_FAILURE);
    }

    stream = pipeline->createStream("imx219", "imx219");
    if (!stream) {
        fprintf(stderr, "Failed to create camera stream\n");
        exit(EXIT_FAILURE);
    }

    stream->setControl(V4L2_CID_GAIN, 1.0);
    stream->setControl(V4L2_CID_EXPOSURE, 1.0);
    stream->setControl(V4L2_CID_HUE, 0.0);
    stream->setControl(V4L2_CID_SATURATION, 1.0);
    stream->setControl(V4L2_CID_BRIGHTNESS, 0.5);

    if (pipeline->configure()) {
        fprintf(stderr, "Failed to configure camera pipeline\n");
        exit(EXIT_FAILURE);
    }

    request = stream->createRequest();
    if (!request) {
        fprintf(stderr, "Failed to create camera request\n");
        exit(EXIT_FAILURE);
    }
}

void init_curl() {
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize cURL\n");
        exit(EXIT_FAILURE);
    }

    headers = curl_slist_append(headers, "Content-Type: multipart/form-data");
}

void capture_motion(struct payload *p) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(p->timestamp, sizeof(p->timestamp), "%Y-%m-%dT%H:%M:%S.%%06u", timeinfo);
    snprintf(p->filename, sizeof(p->filename), "/tmp/%s.jpg", p->timestamp);

    FILE *file = fopen(p->filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file %s: %s\n", p->filename, strerror(errno));
        return;
    }

    request->process([&](Request &req) {
        JpegEncoder encoder;
        encoder.setQuality(85);
        encoder.encode(req.buffer(), file);
    });

    fclose(file);
}

void post_data(struct payload *p) {
    // TODO: Implement JSON payload and POST
}

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    delete pipeline;
    curl_easy_cleanup(curl);
    curl_global_cleanup();
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    init_gpiod();
    init_camera();
    init_curl();

    struct payload p = { .motion = 0, .pin = 17 };

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (gpiod_line_get_value(line)) {
            p.motion = 1;
            capture_motion(&p);
            post_data(&p);
            sleep(2);
        } else {
            usleep(100000);
        }
    }

    return EXIT_SUCCESS;
}

