#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images/"
#define IMAGE_FORMAT "%Y%m%d_%H%M%S_%3d.jpg"
#define IMAGE_CMD "/usr/bin/raspistill"
#define IMAGE_ARGS IMAGE_CMD " -o " IMAGE_DIR "image.jpg -w 640 -h 480 -q 85 -t 2000 -n -x"
#define DEBOUNCE_TIMEOUT 50000000 /* 50 ms */

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;
int log_file_opened;

void log_message(const char *message) {
    if (!log_file_opened)
        return;

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            message);
    fflush(log_file);
}

void handle_signal(int signum) {
    log_message("Signal received, closing...");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file_opened)
        fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }
    log_file_opened = 1;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        log_message("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        log_message("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(line, "motion_detected")) {
        log_message("Failed to request falling edge events");
        return 1;
    }

    while (1) {
        if (gpiod_line_event_wait(line, NULL) < 0) {
            log_message("Failed to wait for event");
            return 1;
        }

        struct timespec ts = { .tv_sec = 0, .tv_nsec = DEBOUNCE_TIMEOUT };
        if (gpiod_line_event_wait_with_timeout(line, &ts) < 0)
            continue;

        log_message("Motion detected");

        char cmd[128];
        sprintf(cmd, IMAGE_ARGS);
        int ret = system(cmd);
        if (ret == -1 || WEXITSTATUS(ret) != 0)
            log_message("Failed to capture image");
        else
            log_message("Image captured successfully");
    }

    return 0;
}
```

This code uses the libgpiod library to monitor the GPIO line for falling edge events. When a motion event is detected, it triggers the raspistill command to capture an image. Any errors from the capture command are logged to the specified log file. The program handles SIGINT and SIGTERM signals to release resources and close file descriptors cleanly.

