struct buffer {
    void *start;
    size_t length;
};

struct buffer *buffers;
int fd, fd_out, n_buffers, stop;

void cleanup(int signum) {
    stop = 1;
    if (ioctl(fd, VIDIOC_STREAMOFF, &format) < 0)
        perror("VIDIOC_STREAMOFF"), exit(EXIT_FAILURE);
    if (munmap(buffers[0].start, buffers[0].length) < 0)
        perror("munmap"), exit(EXIT_FAILURE);
    if (close(fd) < 0)
        perror("close"), exit(EXIT_FAILURE);
    if (close(fd_out) < 0)
        perror("close"), exit(EXIT_FAILURE);
    free(buffers);
    exit(EXIT_SUCCESS);
}

int main() {
