        perror("VIDIOC_QUERYCAP"), exit(EXIT_FAILURE);

    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_G_FMT, &format) < 0)
        perror("VIDIOC_G_FMT"), exit(EXIT_FAILURE);

    format.fmt.pix.width = WIDTH;
    format.fmt.pix.height = HEIGHT;
    format.fmt.pix.pixelformat = FORMAT;
    format.fmt.pix.field = FIELD;
    if (ioctl(fd, VIDIOC_S_FMT, &format) < 0)
        perror("VIDIOC_S_FMT"), exit(EXIT_FAILURE);

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0)
        perror("VIDIOC_REQBUFS"), exit(EXIT_FAILURE);

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers)
        perror("calloc"), exit(EXIT_FAILURE);

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0)
            perror("VIDIOC_QUERYBUF"), exit(EXIT_FAILURE);

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ|PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers].start == MAP_FAILED)
            perror("mmap"), exit(EXIT_FAILURE);
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0)
            perror("VIDIOC_QBUF"), exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &format.type) < 0)
        perror("VIDIOC_STREAMON"), exit(EXIT_FAILURE);

    fd_out = open(FILE_NAME, O_CREAT|O_WRONLY, 0644);
    if (fd_out < 0)
        perror(FILE_NAME), exit(EXIT_FAILURE);

    while (!stop) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;
        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0 && errno == EINTR)
            continue;
        if (r < 0)
            perror("select"), exit(EXIT_FAILURE);
        if (r == 0)
            continue;
        if (!FD_ISSET(fd, &fds))
            continue;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0)
            perror("VIDIOC_DQBUF"), exit(EXIT_FAILURE);
        if (buf.bytesused != WIDTH * HEIGHT * 2)
            continue;
        b = &buffers[buf.index];
        p = b->start;
        size = WIDTH * HEIGHT * 2;
        for (q = p, r = 0; r < HEIGHT - 150; ++r, p += WIDTH * 2)
            ;
        for (; r < HEIGHT; ++r, p += WIDTH * 2)
            if ((ret = write(fd_out, p, WIDTH * 200)) < 0)
                perror("write"), exit(EXIT_FAILURE);
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0)
            perror("VIDIOC_QBUF"), exit(EXIT_FAILURE);
    }

    cleanup(0);
}

