#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define PAN_SERVO_GPIO 17
#define TILT_SERVO_GPIO 18
#define PWM_FREQ 50
#define STEP 5
#define NEUTRAL_POS 90
#define MIN_POS 0
#define MAX_POS 180

struct gpiod_chip *chip;
struct gpiod_line *pan_servo, *tilt_servo;

void error_exit(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(1);
}

void set_servo_position(struct gpiod_line *servo, int position) {
    if (position < MIN_POS || position > MAX_POS) {
        error_exit("Servo position out of range");
    }

    int pwm_duty_cycle = (position * 1000 / 180) + 500;
    if (gpiod_line_set_pwm(servo, PWM_FREQ, pwm_duty_cycle)) {
        error_exit("Failed to set servo position");
    }
}

void move_servo(struct gpiod_line *servo, int step) {
    int curr_pos;
    if (gpiod_line_get_pwm_duty_cycle(servo, &curr_pos)) {
        error_exit("Failed to get servo position");
    }

    curr_pos = (curr_pos * 180 / 1000) + step;
    set_servo_position(servo, curr_pos);
}

void handle_signal(int signum) {
    set_servo_position(pan_servo, NEUTRAL_POS);
    set_servo_position(tilt_servo, NEUTRAL_POS);
    gpiod_line_release_pwm(pan_servo);
    gpiod_line_release_pwm(tilt_servo);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        error_exit("Failed to open GPIO chip");
    }

    pan_servo = gpiod_chip_get_line(chip, PAN_SERVO_GPIO);
    tilt_servo = gpiod_chip_get_line(chip, TILT_SERVO_GPIO);

    if (gpiod_line_request_pwm_mode(pan_servo, "servo", 0)) {
        error_exit("Failed to set pan servo to PWM mode");
    }

    if (gpiod_line_request_pwm_mode(tilt_servo, "servo", 0)) {
        error_exit("Failed to set tilt servo to PWM mode");
    }

    set_servo_position(pan_servo, NEUTRAL_POS);
    set_servo_position(tilt_servo, NEUTRAL_POS);

    signal(SIGINT, handle_signal);

    char c;
    while (1) {
        c = getchar();
        switch (c) {
            case 'q':
                handle_signal(0);
                break;
            case 'a':
                move_servo(pan_servo, -STEP);
                break;
            case 'd':
                move_servo(pan_servo, STEP);
                break;
            case 'w':
                move_servo(tilt_servo, -STEP);
                break;
            case 's':
                move_servo(tilt_servo, STEP);
                break;
        }
        usleep(100000);
    }

    return 0;
}

