}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int read_file(const char *file, char *buf, size_t len) {
    int fd = open(file, O_RDONLY);
    if (fd == -1) {
        return -1;
    }

    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read == -1) {
        close(fd);
        return -1;
    }

    close(fd);
    return bytes_read;
}

int main(void) {
    signal(SIGINT, sigint_handler);

    i2c_file = open("/dev/i2c-" #I2C_BUS, O_RDWR);
    if (i2c_file == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, OLED_ADDR) == -1) {
        fprintf(stderr, "Failed to set OLED address\n");
        return 1;
    }

    if (ssd1306_start(&oled_config, i2c_file, 0x3C) == -1) {
        fprintf(stderr, "Failed to start OLED\n");
        return 1;
    }

    char cpu_temp_buf[10];
    char cpu_usage_buf[100];
    while (1) {
        int bytes_read = read_file(CPU_TEMP_FILE, cpu_temp_buf, sizeof(cpu_temp_buf));
        if (bytes_read == -1) {
            ssd1306_clear(&oled_config);
            ssd1306_draw_string(&oled_config, "Error reading", 0, 0);
            ssd1306_draw_string(&oled_config, "CPU temp", 0, 8);
            continue;
        }

        bytes_read = read_file(CPU_USAGE_FILE, cpu_usage_buf, sizeof(cpu_usage_buf));
        if (bytes_read == -1) {
            ssd1306_clear(&oled_config);
            ssd1306_draw_string(&oled_config, "Error reading", 0, 0);
            ssd1306_draw_string(&oled_config, "CPU usage", 0, 8);
            continue;
        }

        ssd1306_clear(&oled_config);
        ssd1306_draw_string(&oled_config, cpu_temp_buf, 0, 0);
        ssd1306_draw_string(&oled_config, cpu_usage_buf, 0, 8);

        sleep(1);
    }

    cleanup();
    return 0;
}
