#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <lcd.h>

#define GPIO_PIN 17
#define INTERVAL 1000000
#define PULSE_THRESHOLD 5

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_alert *alert;
struct lcd_t *lcd;

unsigned int pulses = 0;
int running = 1;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void error_check(int status, const char *message) {
    if (status < 0) {
        printf("%s: %s\n", message, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    lcd_free(lcd);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    error_check(chip == NULL, "gpiod_chip_open_by_name");

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    error_check(line == NULL, "gpiod_chip_get_line");

    int status = gpiod_line_request_alert_falling_edge_events(line, "water_flow");
    error_check(status, "gpiod_line_request_alert_falling_edge_events");

    lcd = lcd_init(1, 0x27, 16, 2);
    error_check(lcd == NULL, "lcd_init");

    lcd_clear(lcd);
    lcd_set_cursor(lcd, 0, 0);
    lcd_write_string(lcd, "Flow Rate:");

    while (running) {
        struct timespec ts = {.tv_sec = 0, .tv_nsec = INTERVAL};
        nanosleep(&ts, NULL);

        status = gpiod_line_handle_alert(line);
        if (status < 0) {
            if (errno == EAGAIN) {
                lcd_set_cursor(lcd, 0, 1);
                lcd_write_string(lcd, "No sensor detected.");
                continue;
            }
            error_check(status, "gpiod_line_handle_alert");
        }

        pulses += status;
        if (pulses < PULSE_THRESHOLD)
            continue;

        float flow_rate = (float) pulses / 10 * 60; // 1 pulse = 10 ml
        char buffer[15];
        sprintf(buffer, "%.2f L/min", flow_rate);

        lcd_set_cursor(lcd, 0, 1);
        lcd_write_string(lcd, buffer);

        pulses = 0;
    }

    cleanup();
    return 0;
}

