#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <assert.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define NUM_ROWS 8
#define NUM_COLS 8

#define ROW_GPIOS {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_GPIOS {5, 6, 12, 13, 19, 16, 26, 20}

#define SLEEP_TIME 800000L

static int row_gpios[NUM_ROWS] = ROW_GPIOS;
static int col_gpios[NUM_COLS] = COL_GPIOS;

static int gpio_fd[NUM_ROWS + NUM_COLS];

static void cleanup_and_exit(int signum)
{
    for (int i = 0; i < NUM_ROWS + NUM_COLS; i++) {
        if (gpio_fd[i] != -1) {
            close(gpio_fd[i]);
        }
    }
    exit(0);
}

int main(void)
{
    signal(SIGINT, cleanup_and_exit);

    for (int i = 0; i < NUM_ROWS + NUM_COLS; i++) {
        gpio_fd[i] = open("/dev/gpiochip0", O_RDWR);
        if (gpio_fd[i] == -1) {
            fprintf(stderr, "Failed to open /dev/gpiochip0: %s\n", strerror(errno));
            cleanup_and_exit(-1);
        }
    }

    for (int i = 0; i < NUM_ROWS + NUM_COLS; i++) {
        if (ioctl(gpio_fd[i], GPIO_SET_DIRECTION_OUT, i < NUM_ROWS ? row_gpios[i] : col_gpios[i - NUM_ROWS]) == -1) {
            fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
            cleanup_and_exit(-1);
        }
    }

    for (;;) {
        for (int i = 0; i < NUM_COLS; i++) {
            for (int j = 0; j < NUM_ROWS; j++) {
                if (ioctl(gpio_fd[j], GPIO_SET_VALUE, 1) == -1) {
                    fprintf(stderr, "Failed to set row GPIO value: %s\n", strerror(errno));
                    cleanup_and_exit(-1);
                }
                if (ioctl(gpio_fd[NUM_ROWS + i], GPIO_SET_VALUE, 0) == -1) {
                    fprintf(stderr, "Failed to set column GPIO value: %s\n", strerror(errno));
                    cleanup_and_exit(-1);
                }
                usleep(SLEEP_TIME);
                if (ioctl(gpio_fd[NUM_ROWS + i], GPIO_SET_VALUE, 1) == -1) {
                    fprintf(stderr, "Failed to set column GPIO value: %s\n", strerror(errno));
                    cleanup_and_exit(-1);
                }
                if (ioctl(gpio_fd[j], GPIO_SET_VALUE, 0) == -1) {
                    fprintf(stderr, "Failed to set row GPIO value: %s\n", strerror(errno));
                    cleanup_and_exit(-1);
                }
            }
        }
    }

    return 0;
}

