#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define MLX75031_ADDR 0x15
#define I2C_BUS 1
#define SAMPLE_RATE 100
#define LOG_FILE "depth_log.csv"

volatile sig_atomic_t stop = 0;
int i2c_file = -1;

void sigint_handler(int signum) {
    stop = 1;
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void write_log(FILE *file, double distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(file, "%s, %.2f\n", timestamp, distance);
}

int main() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return 1;
    }

    if (fseek(log_file, 0, SEEK_END) != 0) {
        log_error("Failed to seek log file");
        fclose(log_file);
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp, Distance\n");
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        log_error("Failed to open I2C bus");
        fclose(log_file);
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, MLX75031_ADDR) == -1) {
        log_error("Failed to set I2C slave address");
        close(i2c_file);
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        char buffer[2];
        if (read(i2c_file, buffer, 2) != 2) {
            write_log(log_file, -1);
            close(i2c_file);
            i2c_file = open("/dev/i2c-1", O_RDWR);
            if (i2c_file == -1 || ioctl(i2c_file, I2C_SLAVE, MLX75031_ADDR) == -1) {
                log_error("Failed to reopen I2C bus");
                fclose(log_file);
                return 1;
            }
        } else {
            double distance = (buffer[0] << 8 | buffer[1]) / 1000.0;
            write_log(log_file, distance);
        }

        usleep(SAMPLE_RATE * 1000);
    }

    close(i2c_file);
    fclose(log_file);

    return 0;
}

