#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include "Si1145.h"

#define SENSOR_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "biometric_log.txt"

static int i2c_file_descriptor;
static FILE *log_file;

void sigint_handler(int signum) {
    Si1145_close(i2c_file_descriptor);
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;
    struct tm *timeinfo;
    time_t now;
    char timestamp[20];
    Si1145_Data_t data;

    signal(SIGINT, sigint_handler);

    i2c_file_descriptor = Si1145_init(I2C_BUS, SENSOR_ADDR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    while (1) {
        ret = Si1145_read(&data, i2c_file_descriptor);
        if (ret < 0) {
            now = time(NULL);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(log_file, "%s Error reading sensor: %s\n", timestamp, strerror(-ret));
            fflush(log_file);
            continue;
        }

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
        fprintf(log_file, "%s Proximity: %d, Ambient: %d\n", timestamp, data.proximity, data.ambient);
        fflush(log_file);

        usleep(500000);
    }

    return 0;
}

