#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_SENSOR_LINE 4
#define GPIO_LED_LINE 17
#define LOG_FILE "proximity.log"

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL, *led_line = NULL;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (led_line)
        gpiod_line_release(led_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    int ret;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        chip = gpiod_chip_open_by_label("the library's API call");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR_LINE);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(sensor_line, "sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_line_wait_for_rising_edge(sensor_line, -1);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for sensor line\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", utc_time);

        fprintf(log_file, "%s Object detected\n", timestamp);
        fflush(log_file);

        gpiod_line_set_value(led_line, 1);
        usleep(100000);
        gpiod_line_set_value(led_line, 0);
    }

    return EXIT_SUCCESS;
}

