        ret = gpiod_line_wait_for_rising_edge(sensor_line, -1);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for sensor line\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", utc_time);

        fprintf(log_file, "%s Object detected\n", timestamp);
        fflush(log_file);

        gpiod_line_set_value(led_line, 1);
        usleep(100000);
        gpiod_line_set_value(led_line, 0);
    }

    return EXIT_SUCCESS;
}
