#include <signal.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define LOG_FILE "distance_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo;
FILE *log_file;

void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %d cm\n", timestamp, distance);
    if (distance < 15) {
        fprintf(log_file, "%s: Time to water the plant!\n", timestamp);
    }
}

void cleanup_and_exit(int signum) {
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(trigger, "trigger", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_input(echo, "echo")) {
        perror("gpiod_line_request_input");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        // Issue a 10us trigger pulse
        gpiod_line_set_value(trigger, 1);
        usleep(10);
        gpiod_line_set_value(trigger, 0);

        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 30000000 };
        if (gpiod_line_wait_for_rising_edge(echo, &timeout) < 0) {
            log_distance(-1);
            continue;
        }

        struct timespec timeout_width = { .tv_sec = 0, .tv_nsec = 30000000 };
        if (gpiod_line_wait_for_falling_edge(echo, &timeout_width) < 0) {
            log_distance(-2);
            continue;
        }

        // Compute distance
        int distance = gpiod_line_get_value(echo) * 100;
        if (distance < 2 || distance > 400) {
            log_distance(-3);
            continue;
        }

        log_distance(distance);
        sleep(60);
    }

    return 0;
}

