#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LOG_FILE "distance_log.txt"
#define GPIO_PIN 17

int i2c_file = -1;
FILE* log_file = NULL;

void sigint_handler(int signum) {
    if (i2c_file != -1) close(i2c_file);
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timeval start, end;
    struct timeval timeout;
    timeout.tv_sec = 0;
    timeout.tv_usec = 100000;

    signal(SIGINT, sigint_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Configure GPIO pin
    system("echo 17 > /sys/class/gpio/export");
    system("echo falling > /sys/class/gpio/gpio17/edge");

    while (1) {
        // Wait for GPIO pin to trigger
        char gpio_value[2];
        FILE* gpio_file = fopen("/sys/class/gpio/gpio17/value", "r");
        if (gpio_file == NULL) {
            perror("Failed to open GPIO value file");
            return 1;
        }
        fgets(gpio_value, sizeof(gpio_value), gpio_file);
        fclose(gpio_file);

        if (gpio_value[0] != '0') {
            continue;
        }

        // Trigger single distance measurement
        if (write(i2c_file, "\x01", 1) != 1) {
            perror("Failed to trigger distance measurement");
            return 1;
        }

        // Poll RESULT_INTERRUPT_STATUS
        gettimeofday(&start, NULL);
        while (1) {
            gettimeofday(&end, NULL);
            if (timercmp(&end, &start, >)) {
                perror("Timeout while waiting for measurement");
                return 1;
            }

            char status;
            if (read(i2c_file, &status, 1) != 1) {
                perror("Failed to read measurement status");
                return 1;
            }

            if (status == 0) {
                break;
            }

            select(0, NULL, NULL, NULL, &timeout);
        }

        // Read distance
        unsigned short distance;
        if (read(i2c_file, &distance, 2) != 2) {
            perror("Failed to read distance");
            return 1;
        }

        // Log distance
        struct timeval now;
        gettimeofday(&now, NULL);
        fprintf(log_file, "%ld,%hu\n", now.tv_sec, distance);
        fflush(log_file);
    }

    return 0;
}

