#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define TDK_CH101_ADDR 0x0E
#define I2C_BUS 1
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop = 0;

int i2c_file = -1;
FILE* log_file = NULL;

void sigint_handler(int signum) {
    stop = 1;
}

void close_resources() {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void print_error_and_exit(const char* message) {
    perror(message);
    close_resources();
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    if (sigaction(SIGINT, &action, NULL) < 0) {
        print_error_and_exit("sigaction");
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        print_error_and_exit("open");
    }

    if (ioctl(i2c_file, I2C_SLAVE, TDK_CH101_ADDR) < 0) {
        print_error_and_exit("ioctl");
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        print_error_and_exit("fopen");
    }

    char timestamp[20];
    while (!stop) {
        // trigger measurement
        if (write(i2c_file, "\x01", 1) != 1) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }
        usleep(50000);  // wait 50 ms

        // read result
        unsigned char distance;
        if (read(i2c_file, &distance, 1) != 1) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        char log_line[50];
        snprintf(log_line, sizeof(log_line), "%s, %u\n", timestamp, distance);

        if (fputs(log_line, log_file) == EOF || fputs(log_line, stdout) == EOF) {
            print_error_and_exit("fputs");
        }

        usleep(200000);  // wait 200 ms
    }

    close_resources();
    return 0;
}

