#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO18 18

struct gpiod_chip *chip = NULL;
struct gpiod_line *line1 = NULL, *line2 = NULL;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    printf("\nShutdown complete.\n");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO17, strerror(errno));
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO18);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO18, strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input(line1, "sensor1")) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO17, strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input(line2, "sensor2")) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO18, strerror(errno));
        return 1;
    }

    log_file = fopen("obstacle_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int val1, val2;

        val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO17, strerror(errno));
            continue;
        }

        val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO18, strerror(errno));
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, val1, val2);
        fflush(log_file);

        usleep(100000);
    }

    return 0;
}

