#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <unistd.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define GPIO_PIN 17
#define LED_ON_DISTANCE 20
#define SAMPLE_INTERVAL 100000 /* 100 ms */
#define LOG_FILE "distance_log.txt"

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

static void cleanup_and_exit(int signum)
{
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main(void)
{
    int ret;
    struct timespec ts;
    struct tm tm;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(gpio_line, "led_controller", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (1) {
        /* Read sensor data here and store in distance */
        int distance = 0;

        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm);

        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%06ldZ %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ts.tv_nsec / 1000,
                distance);

        if (distance < LED_ON_DISTANCE)
            gpiod_line_set_value(gpio_line, 1);
        else
            gpiod_line_set_value(gpio_line, 0);

        usleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

