#define SENSOR_ADDR 0x60
#define I2C_RETRIES 3
#define SAMPLE_DELAY 500

static int i2c_file_descriptor = -1;
static FILE* log_file = NULL;

static int sensor_read(int reg, uint8_t* data, int len) {
    int retries = I2C_RETRIES;
    while (retries--) {
        if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDR) == 0) {
            if (write(i2c_file_descriptor, &reg, 1) == 1) {
                if (read(i2c_file_descriptor, data, len) == len) {
                    return 0;
                }
            }
        }
        usleep(1000);
    }
    return -1;
}

static void sigint_handler(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_file_descriptor);
        return 1;
    }

    while (1) {
        uint8_t proximity, light;
        if (sensor_read(0x2E, &proximity, 1) == 0 && sensor_read(0x2F, &light, 1) == 0) {
            time_t now = time(NULL);
            struct tm* timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, light);
            fflush(log_file);
        } else {
            fprintf(log_file, "Failed to read sensor data\n");
            fflush(log_file);
        }
        usleep(SAMPLE_DELAY * 1000);
    }

    return 0;
}

