#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define ICU_20201_ADDR 0x70
#define ICU_20201_WHO_AM_I 0x0F
#define ICU_20201_WHO_AM_I_VALUE 0x20
#define DEFAULT_THRESHOLD 100
#define POLL_INTERVAL 50000000 /* 50 ms */

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static int threshold;

static void cleanup_and_exit(int sig)
{
    if (gpio_line)
        gpiod_line_set_value(gpio_line, 0);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    if (log_file)
        fclose(log_file);
    exit(sig ?: 0);
}

int main(int argc, char *argv[])
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    srand(ts.tv_nsec ^ (ts.tv_sec << 16));
    signal(SIGINT, cleanup_and_exit);

    threshold = argc > 1 ? atoi(argv[1]) : DEFAULT_THRESHOLD;
    if (threshold < 0) {
        fprintf(stderr, "Invalid threshold: %d\n", threshold);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICU_20201_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 17);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "ICU-20201", 0) < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    log_file = fopen("tof_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1 || who_am_i != ICU_20201_WHO_AM_I_VALUE) {
        fprintf(stderr, "ICU-20201 not found at address 0x%02X\n", ICU_20201_ADDR);
        return 1;
    }

    while (1) {
        uint16_t distance;
        if (read(i2c_fd, &distance, 2) != 2) {
            fprintf(stderr, "Failed to read distance\n");
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: %hu\n", ts.tv_sec, ts.tv_nsec, distance);
        if (distance < threshold)
            gpiod_line_set_value(gpio_line, 1);
        else
            gpiod_line_set_value(gpio_line, 0);

        usleep(POLL_INTERVAL);
    }

    return 0;
}

