#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDRESS 0x29
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "intrusion_log.txt"
#define COMMAND_FRAME {0x00, 0x00, 0x00, 0x05}
#define HEADER_VALUE 0x01
#define DISTANCE_OFFSET 11
#define SAMPLE_COUNT 10
#define SAMPLE_DELAY 100000

static int i2c_fd = -1;
static FILE* log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

static void handle_error(const char* message) {
    perror(message);
    cleanup_and_exit(-1);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd == -1) {
        handle_error("Failed to open I2C device file");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        handle_error("Failed to set I2C slave address");
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
    }

    unsigned char command[sizeof(COMMAND_FRAME)] = COMMAND_FRAME;
    unsigned char response[15];
    int total_distance = 0;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            handle_error("Failed to write I2C command frame");
        }

        usleep(SAMPLE_DELAY);

        if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
            handle_error("Failed to read I2C response frame");
        }

        if (response[0] != HEADER_VALUE) {
            fprintf(stderr, "Invalid response header: 0x%02x\n", response[0]);
            continue;
        }

        int distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
        total_distance += distance;
    }

    int average_distance = total_distance / SAMPLE_COUNT;

    if (average_distance < 1000) {
        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d\n", timestamp, average_distance);
    }

    cleanup_and_exit(0);
}

