#include <linux/i2c-dev.h>

#define VL53L0X_I2C_ADDRESS 0x29
#define VL53L0X_MODEL_ID 0xEE

#define VL53L0X_REG_MODEL_ID 0x000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x10B

static int i2c_file = -1;

void cleanup(void) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main(void) {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file, I2C_SLAVE, VL53L0X_I2C_ADDRESS) == -1) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (read(i2c_file, &model_id, sizeof(model_id)) != sizeof(model_id)) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: got 0x%02X, expected 0x%02X\n", model_id, VL53L0X_MODEL_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t interrupt_status;
        if (read(i2c_file, &interrupt_status, sizeof(interrupt_status)) != sizeof(interrupt_status)) {
            fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
            fprintf(stderr, "Warning: continuing to the next iteration.\n");
            continue;
        }

        uint16_t distance;
        if (read(i2c_file, &distance, sizeof(distance)) != sizeof(distance)) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            fprintf(stderr, "Warning: continuing to the next iteration.\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestr[20];
        strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("%s Distance: %u mm\n", timestr, distance);

        usleep(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

