#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_TRIGGER 17
#define GPIO_ECHO 18
#define SLEEP_TIME 1000000
#define MAX_ECHO_TIME 200000

struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    trigger = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    if (!trigger) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    echo = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_output(trigger, "trigger", 0)) {
        perror("gpiod_line_request_output");
        exit(1);
    }

    if (gpiod_line_request_input(echo, "echo")) {
        perror("gpiod_line_request_input");
        exit(1);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        struct timespec start, end;
        int rising, falling;

        // Send trigger pulse
        gpiod_line_set_value(trigger, 1);
        usleep(10);
        gpiod_line_set_value(trigger, 0);

        rising = gpiod_line_wait_for_rising_edge(echo, MAX_ECHO_TIME);
        if (rising < 0) {
            printf("Echo line timeout on rising edge\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &start);

        falling = gpiod_line_wait_for_falling_edge(echo, MAX_ECHO_TIME);
        if (falling < 0) {
            printf("Echo line timeout on falling edge\n");
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);

        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration <= 0 || duration > 38000) {
            printf("Invalid pulse duration: %ld\n", duration);
            continue;
        }

        printf("Distance: %ld µs\n", duration);

        usleep(SLEEP_TIME);
    }

    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return 0;
}

