#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <termios.h>

#define LED_PIN 17
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define MAGIC_WORD_LEN 8
#define PROFILE_DATA_LEN 128
#define DISTANCE_THRESHOLD 1000
#define ALERT_DURATION 2

struct gpiod_chip *chip;
struct gpiod_line *led_line;
int uart_fd;

void handle_signal(int signum) {
    gpiod_line_set_value(led_line, 0);
    close(uart_fd);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    struct termios options;
    struct timespec ts;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *log_file;
    uint16_t distance;
    int ret, i;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "led_blinker", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("open");
        return 1;
    }

    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) {
        perror("tcsetattr");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("intrusion_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    while (1) {
        char magic_word[MAGIC_WORD_LEN];
        uint16_t profile_data[PROFILE_DATA_LEN / sizeof(uint16_t)];

        if (read(uart_fd, magic_word, MAGIC_WORD_LEN) != MAGIC_WORD_LEN) {
            perror("read");
            return 1;
        }

        if (read(uart_fd, profile_data, PROFILE_DATA_LEN) != PROFILE_DATA_LEN) {
            perror("read");
            return 1;
        }

        for (i = 0; i < PROFILE_DATA_LEN / sizeof(uint16_t); i++) {
            if (profile_data[i] <= DISTANCE_THRESHOLD) {
                time(&ts.tv_sec);
                timeinfo = localtime(&ts.tv_sec);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                fprintf(log_file, "%s,%.2f\n", timestamp, profile_data[i] / 1000.0);
                fflush(log_file);

                gpiod_line_set_value(led_line, 1);
                nanosleep(&ts, NULL);
                gpiod_line_set_value(led_line, 0);
                ts.tv_sec = ALERT_DURATION;
                ts.tv_nsec = 0;
                nanosleep(&ts, NULL);
                break;
            }
        }
    }

    fclose(log_file);
    close(uart_fd);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

