#include <time.h>

#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_SENSOR_LINE 17
#define GPIO_BUZZER_LINE 18
#define LOG_FILE "obstacle_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *buzzer_line;
FILE *log_file;

void sig_handler(int signo) {
    if (chip)
        gpiod_chip_close(chip);
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (buzzer_line)
        gpiod_line_release(buzzer_line);
    if (log_file)
        fclose(log_file);
    exit(signo);
}

int main() {
    int ret;
    int buzzer_state = 0;
    struct timespec ts;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR_LINE);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(sensor_line, "sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line\n");
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, GPIO_BUZZER_LINE);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request buzzer line\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int sensor_state = gpiod_line_get_value(sensor_line);
        if (sensor_state < 0) {
            fprintf(stderr, "Failed to read sensor state\n");
            return EXIT_FAILURE;
        }

