#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include "vl53l1x.h"

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LOG_FILE "distance_log.csv"

static int i2c_file = -1;
static VL53L1X_Dev_t vl53l1x;

void sig_handler(int signo) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    VL53L1X_Close(&vl53l1x);
    exit(signo);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    VL53L1X_Error err = VL53L1X_Init(&vl53l1x, (VL53L1X_I2C_Dev_t *)&i2c_file);
    if (err != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to initialise sensor: %d\n", err);
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (fseek(log_file, 0, SEEK_END) != 0 || ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }

    while (1) {
        err = VL53L1X_PerformSingleMeasurement(&vl53l1x);
        if (err != VL53L1X_ERROR_NONE) {
            fprintf(stderr, "Failed to perform measurement: %d\n", err);
            continue;
        }

        uint32_t distance_mm = 0;
        err = VL53L1X_GetMeasurement(&vl53l1x, &distance_mm);
        if (err != VL53L1X_ERROR_NONE) {
            fprintf(stderr, "Failed to get measurement: %d\n", err);
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
        fflush(log_file);

        if (distance_mm < 300) {
            printf("STOP\n");
        } else if (distance_mm < 600) {
            printf("APPROACH\n");
        } else if (distance_mm < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        sleep(0.1);
    }

    fclose(log_file);
    close(i2c_file);
    VL53L1X_Close(&vl53l1x);

    return 0;
}

