#include <string.h>

#define CH201_I2C_ADDR 0x72
#define LED_GPIO 18
#define I2C_BUS 1
#define I2C_RETRIES 3
#define I2C_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup_and_exit(int signum) {
    if (line)
        gpiod_line_set_value(line, 0);
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, CH201_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(line, "led_blink", 0) < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    while (1) {
        int distance, ret, blink_freq;
        for (ret = 0; ret < I2C_RETRIES; ++ret) {
            if (read(i2c_fd, &distance, sizeof(distance)) == sizeof(distance))
                break;
            usleep(I2C_DELAY_MS * 1000);
        }

        if (ret == I2C_RETRIES) {
            printf("Failed to read from sensor, retries exhausted\n");
            continue;
        }

        blink_freq = 1000 / (distance / 29.0 + 1);
        gpiod_line_set_value(line, gpiod_line_get_value(line) ^ 1);
        usleep(blink_freq * 1000);
    }

    return 0;
}

