#define MLX75030_ADDR 0x29
#define MLX75030_MEASURE_CMD 0x00
#define MLX75030_DISTANCE_L_REG 0x02
#define MLX75030_DISTANCE_H_REG 0x03
#define I2C_RETRIES 5

static int should_exit = 0;

static void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        should_exit = 1;
    }
}

int main() {
    int fd, ret, i;
    struct gpiod_device *dev;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    unsigned char cmd = MLX75030_MEASURE_CMD;
    unsigned char data[2];
    char filename[] = "/home/pi/distance_log.csv";
    char line_buf[32];

    chip = gpiod_chip_open_by_number(1);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, MLX75030_ADDR);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto err_chip;
    }

    ret = gpiod_line_request_output(line, "mlx75030", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        goto err_line;
    }

    fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        goto err_line;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!should_exit) {
        for (i = 0; i < I2C_RETRIES; i++) {
            ret = write(fd, &cmd, sizeof(cmd));
            if (ret == sizeof(cmd))
                break;
            else if (ret < 0)
                perror("write cmd");
        }
