#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO27 27
#define POLL_INTERVAL_MS 10
#define DEBOUNCE_INTERVAL_MS 50

struct gpiod_chip *chip = NULL;
struct gpiod_line *line1 = NULL, *line2 = NULL;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (log_file)
        fclose(log_file);
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);
    exit(signum);
}

void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
    fprintf(log_file, "%s Sensor%d %s\n", timestamp, sensor_id, event_type);
}

int main() {
    int ret;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d\n", GPIO17);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d\n", GPIO27);
        return 1;
    }

    ret = gpiod_line_request_both_edges_events(line1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d\n", GPIO17);
        return 1;
    }

    ret = gpiod_line_request_both_edges_events(line2);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d\n", GPIO27);
        return 1;
    }

    log_file = fopen("proximity_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int prev_val1 = gpiod_line_get_value(line1);
    int prev_val2 = gpiod_line_get_value(line2);

    while (1) {
        usleep(POLL_INTERVAL_MS * 1000);

        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 != prev_val1) {
            if (val1 == 0)
                log_event(1, "DETECTED");
            else
                log_event(1, "CLEARED");
            prev_val1 = val1;
            usleep(DEBOUNCE_INTERVAL_MS * 1000);
        }

        if (val2 != prev_val2) {
            if (val2 == 0)
                log_event(2, "DETECTED");
            else
                log_event(2, "CLEARED");
            prev_val2 = val2;
            usleep(DEBOUNCE_INTERVAL_MS * 1000);
        }
    }

    return 0;
}

