#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define SENSOR_ADDRESS 0x70
#define MEAS_STATUS_REG 0x00
#define DISTANCE_L_REG 0x01
#define DISTANCE_H_REG 0x02
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "distance_log.csv"

static int i2c_file_descriptor = -1;
static FILE* csv_file = NULL;

static void write_csv(int distance) {
    struct timespec ts;
    char timestamp[20];
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    fprintf(csv_file, "%s.%09ld,%d\n", timestamp, ts.tv_nsec, distance);
    fflush(csv_file);
}

static void close_resources(int signal) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
        i2c_file_descriptor = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    exit(0);
}

int main() {
    int ret;
    unsigned char status, distance_l, distance_h;
    int distance;

    signal(SIGINT, close_resources);
    signal(SIGTERM, close_resources);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set slave address: %s\n", strerror(errno));
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return 1;
    }

    fprintf(csv_file, "timestamp,distance_mm\n");

    while (1) {
        ret = write(i2c_file_descriptor, &MEAS_STATUS_REG, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
            continue;
        }

        ret = read(i2c_file_descriptor, &status, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            continue;
        }

        if (!(status & 0x01)) {
            usleep(TIMEOUT_MS * 1000);
            continue;
        }

        ret = write(i2c_file_descriptor, &DISTANCE_L_REG, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
            continue;
        }

        ret = read(i2c_file_descriptor, &distance_l, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            continue;
        }

        ret = read(i2c_file_descriptor, &distance_h, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            continue;
        }

        distance = (distance_h << 8) | distance_l;
        write_csv(distance);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return 0;
}

