#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_SLAVE_7BIT 0
#define VL53L5CX_I2C_ADDR 0x29
#define VL53L5CX_REG_SYSRANGE_START 0x00
#define VL53L5CX_REG_RESULT_INTERRUPT_STATUS 0x0B
#define VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x70

static int fd;
static volatile int stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("write");
        return -1;
    }
    return 0;
}

int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("read");
        return -1;
    }
    return 0;
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE_7BIT, VL53L5CX_I2C_ADDR) < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    if (write_register(fd, VL53L5CX_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L5CX_I2C_ADDR) < 0) {
        printf("Failed to set I2C slave device address\n");
        return EXIT_FAILURE;
    }

    if (write_register(fd, VL53L5CX_REG_SYSRANGE_START, 0x01) < 0) {
        printf("Failed to start ranging\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        uint8_t status;
        if (read_register(fd, VL53L5CX_REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            printf("Failed to read interrupt status\n");
            return EXIT_FAILURE;
        }

        if (status & 0x01) {
            for (int i = 0; i < 64; i++) {
                uint8_t distance;
                if (read_register(fd, 0x10 + i, &distance) < 0) {
                    printf("Failed to read distance for zone %d\n", i);
                    return EXIT_FAILURE;
                }
                printf("Zone %d distance: %d\n", i, distance);
            }
            if (write_register(fd, VL53L5CX_REG_SYSRANGE_START, 0x01) < 0) {
                printf("Failed to start ranging\n");
                return EXIT_FAILURE;
            }
        }

        usleep(500000);
    }

    close(fd);

    return EXIT_SUCCESS;
}

