#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define MLX75030_ADDR 0x15
#define MLX75030_REG_DISTANCE 0x00
#define I2C_RETRIES 3
#define I2C_DELAY_MS 10

static int i2c_fd = -1;
static struct gpiod_ctx *gpiod_ctx = NULL;

static void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (gpiod_ctx != NULL) {
        gpiod_ctx_close(gpiod_ctx);
        gpiod_ctx = NULL;
    }
    printf("Exiting...\n");
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    gpiod_ctx = gpiod_ctx_open();
    if (gpiod_ctx == NULL) {
        fprintf(stderr, "Failed to initialize gpiod context\n");
        cleanup_and_exit(0);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup_and_exit(0);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) == -1) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        cleanup_and_exit(0);
    }

    while (1) {
        uint16_t distance;
        int retries = 0;
        while (retries <= I2C_RETRIES) {
            if (read(i2c_fd, &distance, sizeof(distance)) == sizeof(distance)) {
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                printf("Distance: %u at %ld.%09ld\n", distance, ts.tv_sec, ts.tv_nsec);
                break;
            } else {
                if (retries < I2C_RETRIES) {
                    usleep(I2C_DELAY_MS * 1000);
                    retries++;
                } else {
                    fprintf(stderr, "Failed to read distance\n");
                    cleanup_and_exit(0);
                }
            }
        }
        usleep(100 * 1000);
    }

    return 0;
}

