#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define VL53L4CX_I2C_ADDRESS 0x29
#define VL53L4CX_RESULT_INT_STATUS 0x18
#define VL53L4CX_INTERRUPT_CLEAR 0x0B

static int i2c_file_descriptor = -1;

void cleanup_and_exit(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    exit(0);
}

int main() {
    struct timespec ts;
    uint8_t interrupt_status;
    int ret;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, VL53L4CX_I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave");
        cleanup_and_exit(0);
    }

    while (1) {
        ret = read(i2c_file_descriptor, &interrupt_status, 1);
        if (ret < 0) {
            perror("Failed to read interrupt status");
            cleanup_and_exit(0);
        }

        if (interrupt_status & 0x01) {
            ret = write(i2c_file_descriptor, VL53L4CX_INTERRUPT_CLEAR, 1);
            if (ret < 0) {
                perror("Failed to clear interrupt");
                cleanup_and_exit(0);
            }

            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Timestamp: %ld-%.2ld-%.2ld %.2ld:%.2ld:%.2ld.%.6ld, Distance: %d mm\n",
                   ts.tv_sec / 31536000 + 1970, (ts.tv_sec / 2592000) % 12 + 1, (ts.tv_sec / 86400) % 30 + 1,
                   (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60, ts.tv_sec % 60, ts.tv_nsec / 1000,
                   interrupt_status);
        }

        usleep(500000);
    }

    return EXIT_SUCCESS;
}

