#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_BUZZER 22

struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;
VL53L1X_Dev_t vl53l1x;

void cleanup_and_exit(int signum) {
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_BUZZER);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_output(line, "buzzer", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        return 1;
    }

    if (VL53L1X_Init(&vl53l1x, I2C_BUS, I2C_ADDR)) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        return 1;
    }

    if (VL53L1X_SetDeviceMode(&vl53l1x, VL53L1X_CONTINUOUS_RANGING_MODE)) {
        fprintf(stderr, "Failed to set VL53L1X to continuous ranging mode\n");
        return 1;
    }

    while (1) {
        int distance;
        if (VL53L1X_GetDistance(&vl53l1x, &distance)) {
            fprintf(stderr, "Failed to get distance from VL53L1X sensor\n");
            continue;
        }

        if (distance < 100) {
            gpiod_line_set_value(line, 1);
            sleep(1);
            gpiod_line_set_value(line, 0);
        }

        sleep(500);
    }

    cleanup_and_exit(0);
}

