#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 17
#define MAX_ECHO_TIME 50000
#define TRIGGER_PULSE_DURATION 10
#define UPDATE_INTERVAL 200000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_ANGLE -90
#define MAX_ANGLE 90

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line, *servo_line;
FILE *log_file;

void stop_and_exit(int signum) {
    fclose(log_file);
    gpiod_line_set_value(servo_line, 0);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(servo_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("gpiod_line_request_input");
        return 1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, stop_and_exit);
    signal(SIGTERM, stop_and_exit);

    while (1) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_DURATION);
        gpiod_line_set_value(trigger_line, 0);

        struct timespec start_time, current_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        int echo_value;
        do {
            echo_value = gpiod_line_get_value(echo_line);
            clock_gettime(CLOCK_MONOTONIC, &current_time);
        } while (echo_value == 0 && (current_time.tv_nsec - start_time.tv_nsec) < MAX_ECHO_TIME);

        if (echo_value == 1) {
            int distance = (current_time.tv_nsec - start_time.tv_nsec) / 58;
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                int angle = MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
                gpiod_line_set_value(servo_line, angle);

                time_t now = time(NULL);
                struct tm *local = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local);

                fprintf(log_file, "%s, %d\n", timestamp, distance);
            }
        }

        usleep(UPDATE_INTERVAL);
    }

    stop_and_exit(0);
    return 0;
}

