#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define BUZZER_GPIO 22
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define TIMEOUT_US 25000

struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo, *buzzer;
struct timespec start, end;
volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    gpiod_line_set_value(buzzer, 0);
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_line_release(buzzer);
    gpiod_chip_close(chip);
    stop = 1;
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trigger, "trigger", 0)) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(echo, "echo")) {
        perror("gpiod_line_request_rising_edge_events");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0)) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        gpiod_line_set_value(trigger, 1);
        nanosleep((const struct timespec[]){{0, 10000}}, NULL);
        gpiod_line_set_value(trigger, 0);

        if (clock_gettime(CLOCK_MONOTONIC, &start)) {
            perror("clock_gettime");
            return EXIT_FAILURE;
        }

        struct gpiod_edge_event event;
        if (gpiod_line_event_wait(echo, (struct timespec[]){{0, TIMEOUT_US * 1000}}, &event)) {
            if (errno == ETIMEDOUT) {
                printf("No echo received\n");
                continue;
            }
            perror("gpiod_line_event_wait");
            return EXIT_FAILURE;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &end)) {
            perror("clock_gettime");
            return EXIT_FAILURE;
        }

        long long time_diff = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        double distance = time_diff / 2.0 / 1000000.0 * 340.29;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading: %f\n", distance);
            continue;
        }

        printf("Distance: %f\n", distance);

        if (distance < 30) {
            gpiod_line_set_value(buzzer, 1);
        } else {
            gpiod_line_set_value(buzzer, 0);
        }
    }

    return EXIT_SUCCESS;
}

