#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 200000
#define MIN_ECHO_PULSE_US 100
#define MAX_ECHO_PULSE_US 30000
#define ECHO_TIMEOUT_US 60000

struct gpiod_chip *chip;
struct gpiod_line *trig_line, *echo_line;
