    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    exit(signo);
}

int main() {
    struct timespec ts;
    struct gpiod_line_request_config echo_config = {
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
        .event_buffer_size = 10,
    };
    struct gpiod_line_request_config trig_config = {
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_value = 0,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(trig_line, &trig_config, 0)) {
        perror("gpiod_line_request");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_events(echo_line, &echo_config)) {
        perror("gpiod_line_request_events");
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        gpiod_line_set_value(trig_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trig_line, 0);

        struct gpiod_line_event event;
        if (gpiod_line_event_wait(echo_line, &ts)) {
            fprintf(log_file, "Timeout warning at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
            fflush(log_file);
            continue;
