        uint64_t pulse_width = event.falling_edge.ts.tv_nsec - event.rising_edge.ts.tv_nsec;
        if (pulse_width < MIN_ECHO_PULSE_US || pulse_width > MAX_ECHO_PULSE_US) {
            fprintf(log_file, "Invalid echo reading at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
            fflush(log_file);
            continue;
        }

        double distance = pulse_width * 1.0 / 29 / 1000.0;
        fprintf(log_file, "Distance reading at %ld.%09ld: %f\n", ts.tv_sec, ts.tv_nsec, distance);
        fflush(log_file);
    }

    return EXIT_SUCCESS;
}

