#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x29
#define SENSOR_SHUTDOWN_GPIO 23
#define SENSOR_INTERRUPT_GPIO 24
#define SERVO_GPIO 18
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define OPEN_DISTANCE 50
#define CLOSE_DISTANCE 60
#define LOG_FILE "parking_log.txt"

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_shutdown_line = NULL, *sensor_interrupt_line = NULL, *servo_line = NULL;
VL53L1X_Dev_t sensor;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (chip)
        gpiod_chip_close(chip);
    if (sensor_shutdown_line)
        gpiod_line_release(sensor_shutdown_line);
    if (sensor_interrupt_line)
        gpiod_line_release(sensor_interrupt_line);
    if (servo_line)
        gpiod_line_release(servo_line);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup_and_exit(-1);
    }

    sensor_shutdown_line = gpiod_chip_get_line(chip, SENSOR_SHUTDOWN_GPIO);
    if (!sensor_shutdown_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    sensor_interrupt_line = gpiod_chip_get_line(chip, SENSOR_INTERRUPT_GPIO);
    if (!sensor_interrupt_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_output(sensor_shutdown_line, "sensor_shutdown", 1)) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_input(sensor_interrupt_line, "sensor_interrupt")) {
        perror("gpiod_line_request_input");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_output(servo_line, "servo", 0)) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
    }

    if (VL53L1X_Init(&sensor, I2C_BUS, SENSOR_ADDR, SENSOR_INTERRUPT_GPIO)) {
        fprintf(stderr, "Failed to initialize sensor\n");
        cleanup_and_exit(-1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        cleanup_and_exit(-1);
    }

    int servo_pulse = SERVO_MIN_PULSE;
    int gate_state = 0;

    while (1) {
        int distance = VL53L1X_GetDistance(&sensor);
        if (distance < 0) {
            fprintf(stderr, "Failed to get distance\n");
            cleanup_and_exit(-1);
        }

        if (distance < OPEN_DISTANCE && gate_state == 0) {
            servo_pulse = SERVO_MAX_PULSE;
            gate_state = 1;
        } else if (distance > CLOSE_DISTANCE && gate_state == 1) {
            servo_pulse = SERVO_MIN_PULSE;
            gate_state = 0;
        }

        gpiod_line_set_value(servo_line, servo_pulse);

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(log_file, "%s: Gate %s, Distance: %d\n", timestamp, gate_state ? "Open" : "Closed", distance);
        fflush(log_file);
    }

    cleanup_and_exit(0);
}

