#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include "vl53l1x.h"

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define LOG_FILE "gate_events.log"
#define TIMEOUT_MS 500

struct gpiod_chip *chip;
struct gpiod_line *line_open, *line_close;
int fd, log_file;
VL53L1X_Dev_t vl53l1x;
volatile int run = 1;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM)
        run = 0;
}

int main() {
    struct sigaction sig_action;
    memset(&sig_action, 0, sizeof(sig_action));
    sig_action.sa_handler = sig_handler;
    sigaction(SIGINT, &sig_action, NULL);
    sigaction(SIGTERM, &sig_action, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line_open = gpiod_chip_get_line(chip, GPIO_OPEN);
    if (!line_open) {
        perror("gpiod_chip_get_line");
        goto err_chip;
    }

    line_close = gpiod_chip_get_line(chip, GPIO_CLOSE);
    if (!line_close) {
        perror("gpiod_chip_get_line");
        goto err_open;
    }

    if (gpiod_line_request_output(line_open, "open", 0) ||
        gpiod_line_request_output(line_close, "close", 0)) {
        perror("gpiod_line_request_output");
        goto err_close;
    }

    fd = open("/dev/i2c-" #I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        goto err_gpio;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR)) {
        perror("ioctl");
        goto err_i2c;
    }

    if (VL53L1X_Init(&vl53l1x, fd, I2C_ADDR) ||
        VL53L1X_SetDeviceMode(&vl53l1x, VL53L1X_MODE_CONTINUOUS_RANGING) ||
        VL53L1X_SetMeasurementTimingBudget(&vl53l1x, 50000) ||
        VL53L1X_StartRanging(&vl53l1x)) {
        fprintf(stderr, "VL53L1X init failed\n");
        goto err_i2c;
    }

    log_file = open(LOG_FILE, O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (log_file < 0) {
        perror("open");
        goto err_i2c;
    }

    while (run) {
        int status, distance;
        struct timespec ts;

        clock_gettime(CLOCK_REALTIME, &ts);

        status = VL53L1X_GetDistance(&vl53l1x, &distance);
        if (status) {
            fprintf(stderr, "VL53L1X_GetDistance failed: %d\n", status);
            continue;
        }

        if (distance < 200) {
            gpiod_line_set_value(line_open, 1);
            gpiod_line_set_value(line_close, 0);
            dprintf(log_file, "%lu.%09lu: Open\n", ts.tv_sec, ts.tv_nsec);
        } else {
            gpiod_line_set_value(line_open, 0);
            gpiod_line_set_value(line_close, 1);
            dprintf(log_file, "%lu.%09lu: Close\n", ts.tv_sec, ts.tv_nsec);
        }

        usleep(TIMEOUT_MS * 1000);
    }

    close(log_file);
    VL53L1X_StopRanging(&vl53l1x);
    VL53L1X_Close(&vl53l1x);

err_i2c:
    close(fd);
err_gpio:
    gpiod_line_release(line_close);
err_close:
    gpiod_line_release(line_open);
err_open:
    gpiod_chip_close(chip);
err_chip:
    return 1;
}

