#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_MOTOR_FWD 17
#define GPIO_MOTOR_BCK 18
#define GPIO_TRIGGER 24

static VL53L1X_Dev_t sensor;
static int i2c_handle;
static volatile int stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void set_motor_state(int state) {
    gpioWrite(GPIO_MOTOR_FWD, state & 1);
    gpioWrite(GPIO_MOTOR_BCK, state & 2);
}

void trigger_handler(int gpio, int level, uint32_t tick) {
    int retry = 0;
    int status;
    uint16_t distance;

    while (retry < 10) {
        i2cWriteByte(i2c_handle, 0x00);
        i2cWriteByte(i2c_handle, 0x01);
        delay(1000);
        i2cWriteByte(i2c_handle, 0x00);
        i2cWriteByte(i2c_handle, 0x02);

        do {
            i2cReadWord(i2c_handle, 0x00, &status);
        } while ((status & 0x01) == 0);

        i2cReadWord(i2c_handle, 0x00, &distance);

        if (status == 0 && distance > 0) {
            if (distance < 100) {
                set_motor_state(1);
            } else if (distance > 300) {
                set_motor_state(2);
            } else {
                set_motor_state(0);
            }
            printf("Distance: %d\n", distance);
            return;
        }

        delay(1 << retry);
        retry++;
    }

    set_motor_state(0);
    printf("Failed to read distance\n");
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_MOTOR_FWD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BCK, PI_OUTPUT);
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetISRFunc(GPIO_TRIGGER, PI_RISING_EDGE, trigger_handler);

    while (!stop) {
        sleep(1);
    }

    set_motor_state(0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

