#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c.h>

#define SENSOR_ADDR 0x5A
#define TOUCH_STATUS_REG 0x0
#define LED_PINS 4
#define LED_PINS_BCM_GPIO {17, 18, 27, 22}

int i2c_file_descriptor;
int gpio_file_descriptors[LED_PINS];

void cleanup_and_exit(int signum) {
    for (int i = 0; i < LED_PINS; i++) {
        close(gpio_file_descriptors[i]);
    }
    close(i2c_file_descriptor);
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < LED_PINS; i++) {
        gpio_file_descriptors[i] = open("/sys/class/gpio/export", O_WRONLY);
        if (gpio_file_descriptors[i] < 0) {
            perror("Failed to open GPIO export file");
            exit(EXIT_FAILURE);
        }

        dprintf(gpio_file_descriptors[i], "%d", LED_PINS_BCM_GPIO[i]);
        close(gpio_file_descriptors[i]);

        char gpio_dir_path[64];
        sprintf(gpio_dir_path, "/sys/class/gpio/gpio%d/direction", LED_PINS_BCM_GPIO[i]);
        gpio_file_descriptors[i] = open(gpio_dir_path, O_WRONLY);
        if (gpio_file_descriptors[i] < 0) {
            perror("Failed to open GPIO direction file");
            exit(EXIT_FAILURE);
        }

        dprintf(gpio_file_descriptors[i], "out");
        close(gpio_file_descriptors[i]);
    }

    while (1) {
        uint8_t touch_status;
        if (read(i2c_file_descriptor, &touch_status, sizeof(touch_status)) != sizeof(touch_status)) {
            perror("Failed to read touch status");
            cleanup_and_exit(-1);
        }

