#define MPR121_REG_FDL  0x00
#define MPR121_REG_FDM  0x01
#define MPR121_REG_FHH  0x02
#define MPR121_REG_FHL  0x03
#define MPR121_REG_RIN  0x04
#define MPR121_REG_DRDY 0x05
#define MPR121_REG_ELE  0x06
#define MPR121_REG_ECR  0x07
#define MPR121_REG_CDC  0x08
#define MPR121_REG_CDT  0x09
#define MPR121_REG_IOCT 0x0A
#define MPR121_REG_IOCH 0x0B
#define MPR121_REG_DR   0x0C
#define MPR121_REG_DI   0x0D
#define MPR121_REG_AFE  0x0E
#define MPR121_REG_BIAS 0x0F
#define MPR121_REG_FBI  0x10
#define MPR121_REG_FBL  0x11
#define MPR121_REG_FSI  0x12
#define MPR121_REG_FSL  0x13
#define MPR121_REG_FUBI 0x14
#define MPR121_REG_FUBL 0x15
#define MPR121_REG_FUSI 0x16
#define MPR121_REG_FUSL 0x17

#define LED_GPIO_PIN 27

static int mpr121_i2c_fd = MPR121_I2C_FD;

static void cleanup(int signum) {
    close(mpr121_i2c_fd);
    exit(0);
}

static int mpr121_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(mpr121_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to MPR121\n");
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *val) {
    if (write(mpr121_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to MPR121\n");
        return -1;
    }
    if (read(mpr121_i2c_fd, val, 1) != 1) {
        fprintf(stderr, "Failed to read from MPR121\n");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    mpr121_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (mpr121_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -1;
    }

    if (ioctl(mpr121_i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return -1;
    }

    uint8_t dev_id;
    if (mpr121_read_reg(MPR121_REG_BASE, &dev_id) < 0) {
        return -1;
    }
    if (dev_id != MPR121_DEV_ID) {
        fprintf(stderr, "Invalid device ID\n");
        return -1;
    }

    // Configure MPR121 registers...

    // Monitor proximity event
    uint8_t ele;
    while (1) {
        if (mpr121_read_reg(MPR121_REG_ELE, &ele) < 0) {
            return -1;
        }
        if (ele & 0x01) {
            // Proximity event detected
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
            printf("Proximity event detected at %s\n", timestamp);

            // Turn LED on for one second
            // (Assuming gpio library is available)
            gpioWrite(LED_GPIO_PIN, 1);
            sleep(1);
            gpioWrite(LED_GPIO_PIN, 0);
        }
    }

    return 0;
}

