#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define MAX_ECHO_TIME 30000 /* 30 ms */
#define MIN_ECHO_TIME 5000 /* 5 ms */
#define SOUND_SPEED 343000 /* speed of sound in m/s */
#define MIN_DISTANCE 20000 /* 20 cm in mm */
#define MAX_DISTANCE 400000 /* 400 cm in mm */

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;
FILE *log_file;
volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct timespec ts;
    struct tm *timeinfo;
    char buffer[26];
    int rc;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    rc = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (rc < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    rc = gpiod_line_request_input(echo_line, "echo");
    if (rc < 0) {
        perror("gpiod_line_request_input");
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        /* Trigger the sensor */
        gpiod_line_set_value(trigger_line, 1);
        usleep(10000); /* 10 ms */
        gpiod_line_set_value(trigger_line, 0);

        /* Wait for the echo */
        rc = gpiod_line_wait_for_rising_edge(echo_line, MAX_ECHO_TIME);
        if (rc < 0) {
            fprintf(log_file, "Error: Echo never rose\n");
            fflush(log_file);
            continue;
        }

        /* Measure the echo pulse width */
        clock_gettime(CLOCK_MONOTONIC, &ts);
        rc = gpiod_line_wait_for_falling_edge(echo_line, MAX_ECHO_TIME);
        if (rc < 0) {
            fprintf(log_file, "Error: Echo never fell\n");
            fflush(log_file);
            continue;
        }

        /* Compute the distance */
        long long echo_time = ts.tv_nsec + (ts.tv_sec * 1000000000);
        clock_gettime(CLOCK_MONOTONIC, &ts);
        echo_time = (ts.tv_nsec + (ts.tv_sec * 1000000000)) - echo_time;
        if (echo_time < MIN_ECHO_TIME || echo_time > MAX_ECHO_TIME) {
            fprintf(log_file, "Error: Invalid echo time: %lld\n", echo_time);
            fflush(log_file);
            continue;
        }

        long long distance = echo_time * SOUND_SPEED / 2;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "Error: Invalid distance: %lld\n", distance);
            fflush(log_file);
            continue;
        }

        /* Log the distance */
        timeinfo = gmtime(&ts.tv_sec);
        strftime(buffer, 26, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
        fprintf(log_file, "%s %lld\n", buffer, distance);
        fflush(log_file);

        /* Wait a second before the next measurement */
        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

