struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;
FILE *log_file;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpiod_line_set_flags(trigger_line, GPIOD_LINE_FLAG_IS_INACTIVE_HIGH);
        fclose(log_file);
        gpiod_chip_close(chip);
        exit(0);
    }
}

void trigger_pulse_width_cb(struct gpiod_line *line, void *data) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (!gpiod_line_get_value(echo_line))
        ;
    clock_gettime(CLOCK_MONOTONIC, &end);
    double pulse_width = (end.tv_sec - start.tv_sec) * 1e9 + (end.tv_nsec - start.tv_nsec);
    if (pulse_width > 58e3 && pulse_width < 25e6) {
        double distance = pulse_width * 340.29 / 2 / 1e6;
        fprintf(log_file, "%ld,%.2f\n", time(NULL), distance);
    }
}

