        double distance = pulse_width * 340.29 / 2 / 1e6;
        fprintf(log_file, "%ld,%.2f\n", time(NULL), distance);
    }
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_both_edges_events(echo_line, "echo", trigger_pulse_width_cb, NULL)) {
        perror("gpiod_line_request_both_edges_events");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        gpiod_line_set_flags(trigger_line, GPIOD_LINE_FLAG_IS_ACTIVE_LOW);
        sleep(1);
        gpiod_line_set_flags(trigger_line, GPIOD_LINE_FLAG_IS_INACTIVE_HIGH);
    }

    return 0;
}
```

This code uses the libgpiod library to interact with the GPIO pins on the Raspberry Pi. It sets up an interrupt on the echo line, which triggers a callback function that measures the width of the echo pulse. The distance is then calculated from this pulse width and logged to a file. The program also handles signals to ensure a clean shutdown.

