    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    syslog(LOG_INFO, "Exiting on signal %d", signum);
    closelog();
    exit(0);
}

int main() {
    openlog("sensor_logger", LOG_PID, LOG_USER);
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_XSHUT);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %m");
        return 1;
    }

    if (gpiod_line_request_output(line, "sensor_logger", 1)) {
        syslog(LOG_ERR, "Failed to set GPIO line as output: %m");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %m");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR)) {
        syslog(LOG_ERR, "Failed to set I2C address: %m");
        return 1;
    }

    while (1) {
        uint8_t buffer[2];
        ssize_t bytes_read = read(i2c_fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            syslog(LOG_ERR, "Failed to read from sensor: %m");
            continue;
        }

        uint16_t distance = (buffer[0] << 8) | buffer[1];
        syslog(LOG_INFO, "Distance: %u mm", distance);

        usleep(100000);
    }

    return 0;
}

