#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_LINE 24
#define LOG_FILE "gate_log.txt"
#define OPEN_STATE 1
#define CLOSE_STATE 0

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static FILE *log_file;

static void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
}

static void cleanup_and_exit(int signum) {
    close(i2c_fd);
    gpiod_line_set_value(gpio_line, CLOSE_STATE);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;
    uint16_t distance;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    gpio_chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        exit(1);
    }

    ret = gpiod_line_request_output(gpio_line, "gate_controller", CLOSE_STATE);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        ret = read(i2c_fd, &distance, sizeof(distance));
        if (ret < 0) {
            perror("Failed to read distance");
            log_message("Error reading distance");
            continue;
        }

        distance = (distance >> 10) * 129 / 1000; // Convert to centimeters

        log_message(distance < 20 ? "Gate opened" : "Gate closed");

        ret = gpiod_line_set_value(gpio_line, distance < 20 ? OPEN_STATE : CLOSE_STATE);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
            log_message("Error setting GPIO line value");
        }

        usleep(100000); // 100 ms
    }

    return 0;
}

