#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TIMEOUT 30000
#define INTERVAL 100000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define INVALID_DISTANCE -1.0
#define DEFAULT_ANGLE 90

static volatile sig_atomic_t stop = 0;
static unsigned int pulse_width = 0;
static volatile int new_pulse = 0;

FILE *log_file;

void sigint_handler(int signum) {
    stop = 1;
}

void echo_callback(int echo_pin, unsigned level, int tick, void *data) {
    if (level == 0) {
        pulse_width = gpioTick() - tick;
        new_pulse = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_request trigger_req, echo_req;
    int servo_fd;
    unsigned int i, j;
    unsigned int samples[5];
    unsigned int sum;
    double distance;
    struct sigaction action;

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_rising_edge_events(echo_line, "echo", echo_callback, NULL)) {
        perror("gpiod_line_request_rising_edge_events");
        return 1;
    }

    servo_fd = servo_open(SERVO_PIN);
    if (servo_fd < 0) {
        perror("servo_open");
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    fprintf(log_file, "timestamp,distance,angle\n");

    for (i = 0; !stop; i = (i + 1) % 5) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        for (j = 0; j < INTERVAL && !new_pulse; j++)
            usleep(1);

        if (new_pulse) {
            new_pulse = 0;
            samples[i] = pulse_width;
            sum = 0;
            for (j = 0; j < 5; j++)
                sum += samples[(i + j) % 5];
            distance = (double)sum / (5 * 10000);
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE)
                distance = INVALID_DISTANCE;
        } else {
            distance = INVALID_DISTANCE;
        }

        fprintf(log_file, "%u,%.1f,%d\n", gpioTick(), distance, DEFAULT_ANGLE);
        fflush(log_file);

        if (distance != INVALID_DISTANCE)
            servo_set(servo_fd, DEFAULT_ANGLE);

        usleep(INTERVAL - j);
    }

    servo_set(servo_fd, 0);
    fclose(log_file);
    servo_close(servo_fd);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    servo_cleanup();

    return 0;
}

