#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_LED 17
#define BUF_SIZE 10
#define RANGE_CHECK 0x0010
#define XTALK_CHECK 0x0008

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_file;
int buf[BUF_SIZE];
int buf_idx = 0;
int running = 1;

void sigint_handler(int signum) {
    running = 0;
    gpiod_line_set_value(line, 0);
    close(i2c_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int i2c_write(int reg, int val) {
    char buf[2] = {reg, val};
    if (write(i2c_file, buf, 2) != 2) {
        printf("I2C write error\n");
        return -1;
    }
    return 0;
}

int i2c_read(int reg, int *val) {
    char buf = reg;
    if (write(i2c_file, &buf, 1) != 1) {
        printf("I2C write error\n");
        return -1;
    }
    if (read(i2c_file, val, 1) != 1) {
        printf("I2C read error\n");
        return -1;
    }
    return 0;
}

int sensor_init() {
    if (i2c_write(0x88, 0x00) < 0) return -1;
    if (i2c_write(0x80, 0x01) < 0) return -1;
    if (i2c_write(0xFF, 0x01) < 0) return -1;
    if (i2c_write(0x00, RANGE_CHECK | XTALK_CHECK) < 0) return -1;
    if (i2c_write(0xFF, 0x00) < 0) return -1;
    if (i2c_write(0x80, 0x00) < 0) return -1;
    if (i2c_write(0x83, 0x00) < 0) return -1;
    if (i2c_write(0x86, 0x30) < 0) return -1;
    if (i2c_write(0x88, 0x00) < 0) return -1;
    if (i2c_write(0x80, 0x01) < 0) return -1;
    if (i2c_write(0x86, 0x20) < 0) return -1;
    if (i2c_write(0x80, 0x00) < 0) return -1;
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    line = gpiod_chip_get_line(chip, GPIO_LED);
    gpiod_line_request_output(line, "sensor", 0);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to set sensor address\n");
        sigint_handler(0);
    }

    if (sensor_init() < 0) {
