int i2c_write(int reg, int val) {
    char buf[2] = {reg, val};
    if (write(i2c_file, buf, 2) != 2) {
        printf("I2C write error\n");
        return -1;
    }
    return 0;
}

int i2c_read(int reg, int *val) {
    char buf = reg;
    if (write(i2c_file, &buf, 1) != 1) {
        printf("I2C write error\n");
        return -1;
    }
    if (read(i2c_file, val, 1) != 1) {
        printf("I2C read error\n");
        return -1;
    }
    return 0;
}

