#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define PWM_GPIO 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define PULSE_WIDTH 10
#define TIMEOUT 200000
#define DUTY_CYCLE 50

struct gpiod_line *trigger_line, *echo_line, *pwm_line;
struct gpiod_chip *chip;
int pi;
unsigned int prev_frequency = MIN_FREQUENCY;

void stop(int signum) {
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(chip);
    stop_pigpio(pi);
    exit(0);
}

int main() {
    pi = start_pigpio(0, 0);
    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return -1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        printf("Failed to get trigger line\n");
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        printf("Failed to get echo line\n");
        return -1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm_line) {
        printf("Failed to get PWM line\n");
        return -1;
    }

    gpiod_line_request_output(trigger_line, "trigger", 0);
    gpiod_line_request_rising_edge_events(echo_line, "echo");
    set_mode(PWM_GPIO, PWM_MODE);
    set_PWM_frequency(PWM_GPIO, MIN_FREQUENCY);
    set_PWM_dutycycle(PWM_GPIO, DUTY_CYCLE);

    signal(SIGINT, stop);
    signal(SIGTERM, stop);

    while (1) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(PULSE_WIDTH);
        gpiod_line_set_value(trigger_line, 0);

        struct timespec timeout;
        timeout.tv_sec = TIMEOUT / 1000000;
        timeout.tv_nsec = (TIMEOUT % 1000000) * 1000;

        int ret = gpiod_line_wait_for_rising_edge(echo_line, &timeout);
        if (ret < 0) {
            printf("Failed to wait for echo\n");
            set_PWM_frequency(PWM_GPIO, prev_frequency);
            continue;
        }

        unsigned int distance = gpiod_line_get_rising_edge_event_timestamp(echo_line);
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Distance out of range\n");
            set_PWM_frequency(PWM_GPIO, prev_frequency);
            continue;
        }

        unsigned int frequency = MIN_FREQUENCY * pow(MAX_FREQUENCY / (double)MIN_FREQUENCY, (distance - MIN_DISTANCE) / (double)(MAX_DISTANCE - MIN_DISTANCE));
        set_PWM_frequency(PWM_GPIO, frequency);
        prev_frequency = frequency;
    }

    return 0;
}

