#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define BUZZER_GPIO 18
#define PULSE_US 10
#define TIMEOUT_US 100000
#define MIN_DISTANCE 5
#define MAX_DISTANCE 50
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL, *echo_line = NULL;
static int buzzer_gpio = -1;
static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

void cleanup() {
    if (buzzer_gpio >= 0) {
        // Stop the buzzer
        stopPWM(buzzer_gpio);
    }
    if (echo_line) {
        // Release the echo line
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        // Release the trigger line
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        // Close the GPIO chip
        gpiod_chip_close(chip);
    }
    // Shut down the pigpio daemon
    piStop();
}

int main() {
    // Initialize the pigpio daemon
    if (piInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request the trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        return EXIT_FAILURE;
    }

    // Set the trigger line to output
    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        fprintf(stderr, "Failed to set trigger line to output\n");
        return EXIT_FAILURE;
    }

    // Request the echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        return EXIT_FAILURE;
    }

    // Set the echo line to input
    if (gpiod_line_request_input(echo_line, "echo")) {
        fprintf(stderr, "Failed to set echo line to input\n");
        return EXIT_FAILURE;
    }

    // Set up the buzzer
    buzzer_gpio = piSetPWMfrequency(BUZZER_GPIO, MIN_FREQUENCY);
    if (buzzer_gpio < 0) {
        fprintf(stderr, "Failed to set buzzer frequency\n");
        return EXIT_FAILURE;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!stop) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 0);
        usleep(PULSE_US);
        gpiod_line_set_value(trigger_line, 1);

        // Wait for the echo
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if ((now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                // Use the last valid distance
                break;
            }
        }

        // Measure the echo pulse width
        clock_gettime(CLOCK_MONOTONIC, &end);
        int distance = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Map the distance to a frequency
        int frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
        if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

        // Set the buzzer frequency
        if (piSetPWMfrequency(buzzer_gpio, frequency) < 0) {
            fprintf(stderr, "Failed to set buzzer frequency\n");
            return EXIT_FAILURE;
        }

        // Print the distance and frequency
        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);

        // Wait before the next reading
        usleep(10000);
    }

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

