            if ((now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                // Use the last valid distance
                break;
            }
        }

        // Measure the echo pulse width
        clock_gettime(CLOCK_MONOTONIC, &end);
        int distance = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Map the distance to a frequency
        int frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
        if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

        // Set the buzzer frequency
        if (piSetPWMfrequency(buzzer_gpio, frequency) < 0) {
            fprintf(stderr, "Failed to set buzzer frequency\n");
            return EXIT_FAILURE;
        }

        // Print the distance and frequency
        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);

        // Wait before the next reading
        usleep(10000);
    }

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}
