#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define TIMEOUT_US 50000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;
int exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        goto err_close_chip;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        goto err_put_trigger_line;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("gpiod_line_request_output");
        goto err_put_echo_line;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("gpiod_line_request_input");
        goto err_release_trigger_line;
    }

    signal(SIGINT, sigint_handler);

    while (!exit_flag) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        struct timespec timeout = { .tv_sec = 0, .tv_nsec = TIMEOUT_US * 1000 };
        int res = gpiod_line_wait_for_rising_edge(echo_line, &timeout);

        if (res == -1) {
            perror("gpiod_line_wait_for_rising_edge");
            continue;
        } else if (res == 0) {
            printf("Timeout\n");
            continue;
        }

        unsigned long long timestamp = gpiod_line_get_rising_edge_timestamp_ns(echo_line);
        res = gpiod_line_wait_for_falling_edge(echo_line, &timeout);

        if (res == -1) {
            perror("gpiod_line_wait_for_falling_edge");
            continue;
        } else if (res == 0) {
            printf("Timeout\n");
            continue;
        }

        unsigned long long end_timestamp = gpiod_line_get_falling_edge_timestamp_ns(echo_line);
        int distance = (end_timestamp - timestamp) / 29 / 1000;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %d cm\n", distance);
            if (distance < 10) {
                printf("Too close!\n");
            }
        }

        usleep(500000);
    }

    gpiod_line_release(echo_line);
err_release_trigger_line:
    gpiod_line_release(trigger_line);
err_put_echo_line:
    gpiod_line_put(echo_line);
err_put_trigger_line:
    gpiod_line_put(trigger_line);
err_close_chip:
    gpiod_chip_close(chip);

    return 0;
}

