#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define CS_GPIO 8
#define CS_FLAGS GPIOD_LINE_REQUEST_OUTPUT
#define LOG_FILE "distance_log.csv"

struct gpiod_line *cs_line;
struct spi_device *spi_dev;
FILE *log_file;

void exit_handler(int signum) {
    fclose(log_file);
    spi_close(spi_dev);
    gpiod_line_release(cs_line);
    exit(0);
}

int main() {
    int ret;
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[2] = {0x10, 0x00};
    uint8_t rx_buf[2];
    struct timespec ts;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    spi_dev = spi_open_device(SPI_DEV_PATH, 0, 1000000);
    if (!spi_dev) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(1);
    }

    cs_line = gpiod_line_request("gpiochip0", CS_GPIO, CS_FLAGS, "cs_line");
    if (!cs_line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }

    while (1) {
        gpiod_line_set_value(cs_line, 0);

        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)tx_buf;
        xfer.rx_buf = (unsigned long)rx_buf;
        xfer.len = sizeof(tx_buf);
        xfer.speed_hz = 1000000;
        xfer.cs_change = 1;

        ret = spi_transfer(spi_dev, &xfer, 1);
        if (ret != 1) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            continue;
        }

        gpiod_line_set_value(cs_line, 1);

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %d\n", ts.tv_sec, ts.tv_nsec, (rx_buf[0] << 8) | rx_buf[1]);
        fflush(log_file);

        usleep(100000);
    }

    exit_handler(0);
    return 0;
}

