#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define SENSOR_ADDRESS 0x60
#define ALS_REGISTER 0x20
#define I2C_BUS 1

int i2c_file_descriptor;
int log_file_descriptor;
volatile sig_atomic_t stop_signal = 0;

void close_resources(void) {
    close(i2c_file_descriptor);
    close(log_file_descriptor);
}

void signal_handler(int signum) {
    stop_signal = 1;
}

int main(void) {
    struct i2c_msg msgs[2];
    uint8_t als_register[1] = { ALS_REGISTER };
    uint16_t als_value;
    uint8_t als_value_bytes[2];
    struct tm *timeinfo;
    char timestamp[20];

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Could not open I2C device file");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Could not set sensor address");
        return EXIT_FAILURE;
    }

    log_file_descriptor = open("proximity_log.csv", O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (log_file_descriptor < 0) {
        perror("Could not open log file");
        return EXIT_FAILURE;
    }

    if (dprintf(log_file_descriptor, "timestamp,als_visible\n") < 0) {
        perror("Could not write to log file");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    atexit(close_resources);

    while (!stop_signal) {
        msgs[0].addr = SENSOR_ADDRESS;
        msgs[0].flags = 0;
        msgs[0].len = sizeof(als_register);
        msgs[0].buf = als_register;

        msgs[1].addr = SENSOR_ADDRESS;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = sizeof(als_value_bytes);
        msgs[1].buf = als_value_bytes;

        if (i2c_file_descriptor < 0 || i2c_rdwr(i2c_file_descriptor, msgs, 2) < 0) {
            perror("Could not read from sensor");
            return EXIT_FAILURE;
        }

        als_value = (als_value_bytes[0] << 8) | als_value_bytes[1];

        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        if (dprintf(log_file_descriptor, "%s,%u\n", timestamp, als_value) < 0) {
            perror("Could not write to log file");
            return EXIT_FAILURE;
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

