#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1120_ADDR 0x60
#define SI1120_PART_ID 0x0020

static int si1120_fd = -1;
static FILE* log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (si1120_fd != -1) {
        close(si1120_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(sig == SIGINT ? 0 : 1);
}

static int retry_i2c_op(int op, int retries, int delay_ms) {
    int ret;
    while (retries-- > 0) {
        ret = op;
        if (ret >= 0) {
            return ret;
        }
        usleep(delay_ms * 1000);
    }
    return ret;
}

int main() {
    si1120_fd = open(I2C_DEVICE, O_RDWR);
    if (ioctl(si1120_fd, I2C_SLAVE, SI1120_ADDR) < 0) {
        fprintf(stderr, "Failed to set Si1120 address\n");
        cleanup_and_exit(1);
    }

    log_file = fopen("si1120_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(1);
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        uint16_t part_id;
        if (retry_i2c_op(read(si1120_fd, &part_id, sizeof(part_id)), 3, 10) != sizeof(part_id)) {
            fprintf(stderr, "Failed to read Si1120 part ID\n");
            cleanup_and_exit(1);
        }

        if (part_id != SI1120_PART_ID) {
            fprintf(stderr, "Invalid Si1120 part ID\n");
            cleanup_and_exit(1);
        }

        uint16_t als, prox;
        if (retry_i2c_op(read(si1120_fd, &als, sizeof(als)), 3, 10) != sizeof(als)) {
            fprintf(stderr, "Failed to read Si1120 ALS\n");
            cleanup_and_exit(1);
        }

        if (retry_i2c_op(read(si1120_fd, &prox, sizeof(prox)), 3, 10) != sizeof(prox)) {
            fprintf(stderr, "Failed to read Si1120 proximity\n");
            cleanup_and_exit(1);
        }

        time_t now = time(NULL);
        struct tm* now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, ALS: %u, Prox: %u\n", timestamp, als, prox);
        fflush(log_file);

        usleep(500 * 1000);
    }

    return 0;
}

