#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define SENSOR_ADDRESS 0x60
#define PS1_DATA0 0x22
#define PS1_DATA1 0x23
#define MAX_RETRIES 3

int i2c_file_descriptor;
FILE* log_file;

void sig_handler(int signo) {
    if (i2c_file_descriptor > 0) {
        close(i2c_file_descriptor);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signo);
}

void log_error(const char* message) {
    time_t now = time(NULL);
    struct tm* time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int read_proximity_data(unsigned short* data) {
    unsigned char buffer[2];
    int retries = 0;

    while (retries <= MAX_RETRIES) {
        if (ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
            log_error("Failed to set sensor address");
            retries++;
            continue;
        }

        if (write(i2c_file_descriptor, &PS1_DATA0, 1) != 1) {
            log_error("Failed to write to sensor");
            retries++;
            continue;
        }

        if (read(i2c_file_descriptor, buffer, 2) != 2) {
            log_error("Failed to read from sensor");
            retries++;
            continue;
        }

        *data = (buffer[1] << 8) | buffer[0];
        return 0;
    }

    return -1;
}

int main() {
    struct sigaction action;
    unsigned short proximity_data;

    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        log_error("Failed to open I2C device");
        fclose(log_file);
        return -1;
    }

    while (1) {
        if (read_proximity_data(&proximity_data) == 0) {
            time_t now = time(NULL);
            struct tm* time_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(log_file, "[%s] Proximity: %hu\n", timestamp, proximity_data);
            fflush(log_file);
        }
    }

    return 0;
}

