#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MIN_DISTANCE 20
#define SAMPLE_PERIOD 1

struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo, *buzzer;
struct timespec start_time, end_time;
int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void error_check(int status, const char *message) {
    if (status < 0) {
        fprintf(stderr, "%s: %s\n", message, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    error_check(chip == NULL, "Failed to open GPIO chip");

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    error_check(trigger == NULL, "Failed to get trigger line");
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    error_check(echo == NULL, "Failed to get echo line");
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    error_check(buzzer == NULL, "Failed to get buzzer line");

    error_check(gpiod_line_request_output(trigger, "trigger", 0), "Failed to request trigger line");
    error_check(gpiod_line_request_rising_edge_events(echo, "echo"), "Failed to request echo line");
    error_check(gpiod_line_request_output(buzzer, "buzzer", 0), "Failed to request buzzer line");
}

void trigger_pulse() {
    gpiod_line_set_value(trigger, 1);
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    usleep(10);
    gpiod_line_set_value(trigger, 0);
}

void measure_distance() {
    int64_t start, end;
    int status;

    while (running) {
        status = gpiod_line_event_wait(echo, NULL);
        error_check(status < 0, "Failed to wait for echo event");

        if (status) {
            status = gpiod_line_event_read(echo, &end_time);
            error_check(status < 0, "Failed to read echo event");

            start = (int64_t)start_time.tv_sec * 1000000 + start_time.tv_nsec / 1000;
            end = (int64_t)end_time.tv_sec * 1000000 + end_time.tv_nsec / 1000;

            int distance = (end - start) * 17 / 2;
            printf("Distance: %d cm\n", distance);

            if (distance < MIN_DISTANCE) {
                gpiod_line_set_value(buzzer, 1);
            } else {
                gpiod_line_set_value(buzzer, 0);
            }
        }

        usleep(SAMPLE_PERIOD * 1000000);
        trigger_pulse();
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    init_gpio();
    trigger_pulse();
    measure_distance();

    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_line_release(buzzer);
    gpiod_chip_close(chip);

    return 0;
}

