#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

static volatile int stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

double measure_distance(int trigger_pin, int echo_pin) {
    struct timespec start, end;
    int value;

    gpioCfgIntr(echo_pin, INTR_EDGE_RISING);
    gpioSetClock(echo_pin, 1);

    gpioWrite(trigger_pin, 0);
    delay(2);
    gpioWrite(trigger_pin, 1);
    delay(10);
    gpioWrite(trigger_pin, 0);

    if (clock_gettime(CLOCK_REALTIME, &start) == -1) {
        perror("clock_gettime");
        return -1.0;
    }

    while (!gpioReadIntr(echo_pin)) {
        if (stop) {
            return -1.0;
        }
    }

    if (clock_gettime(CLOCK_REALTIME, &end) == -1) {
        perror("clock_gettime");
        return -1.0;
    }

    value = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return (double)value * 17 / 2 / 10000;
}

void set_servo_angle(int servo_pin, double distance) {
    int pulse;

    if (distance < 20) {
        pulse = 2500;
    } else if (distance > 200) {
        pulse = 500;
    } else {
        pulse = 500 + (int)((distance - 20) * 10);
    }

    gpioServo(servo_pin, pulse);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        double distance = measure_distance(TRIGGER_PIN, ECHO_PIN);

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(SERVO_PIN, distance);
        }

        delay(100);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

