void sigint_handler(int signum) {
    set_servo_angle(SERVO_GPIO, 0);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    printf("\nShutting down...\n");
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("gpiod_line_request_output");
        exit(1);
    }

    if (gpiod_line_request_rising_edge_events(echo_line, "echo")) {
        perror("gpiod_line_request_rising_edge_events");
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        struct timespec timeout = { .tv_sec = 0, .tv_nsec = TIMEOUT_US * 1000 };
        struct gpiod_edge_event event;
        int ret = gpiod_line_wait_rising_edge(echo_line, &timeout);

        if (ret < 0) {
            printf("-1.0,0\n");
        } else {
            uint64_t start_time = event.timestamp;
            ret = gpiod_line_wait_falling_edge(echo_line, &timeout);
            if (ret < 0) {
                printf("-1.0,0\n");
            } else {
                uint64_t end_time = event.timestamp;
                double distance = (end_time - start_time) * 1.0 / 29 / 1000;
                int angle = 0;
