                    angle = 0;
                } else if (distance > 200) {
                    angle = 180;
                } else {
                    angle = (distance - 20) * 160 / 380;
                }
                printf("%.1f,%d\n", distance, angle);
                set_servo_angle(SERVO_GPIO, angle);
            }
        }

        usleep(SLEEP_US);
    }

    return 0;
}

