#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define MPU6050_ADDR 0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_DATA_START 0x3B

static int fd;
static volatile int stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("\nShutting down...\n");
        close(fd);
        exit(0);
    }
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave device");
        exit(1);
    }

    printf("Starting up...\n");

    unsigned char who_am_i[1];
    if (read(fd, who_am_i, 1) != 1 || who_am_i[0] != MPU6050_WHO_AM_I) {
        printf("Failed to detect MPU6050\n");
        exit(1);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    unsigned char data[14];
    while (!stop) {
        if (lseek(fd, MPU6050_DATA_START, SEEK_SET) != MPU6050_DATA_START) {
            perror("Failed to seek to data start");
            exit(1);
        }

        if (read(fd, data, 14) != 14) {
            perror("Failed to read data");
            exit(1);
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        printf("Accel: %d %d %d, Temp: %d, Gyro: %d %d %d\n", accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(100000);
    }

    printf("Shutting down...\n");
    close(fd);

    return 0;
}

