void cleanup_and_exit(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    printf("Exiting...\n");
    exit(0);
}

int sht40_crc(const unsigned char *data, size_t length) {
    unsigned char crc = SHT40_CRC_INITIAL;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct i2c_msg msgs[2];
    unsigned char write_buf[2] = { (SHT40_MEASURE_HM_REP_HIGH_CMD >> 8) & 0xFF, SHT40_MEASURE_HM_REP_HIGH_CMD & 0xFF };
    unsigned char read_buf[6];

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        if (i2c_file_descriptor == -1) {
            i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
            if (i2c_file_descriptor == -1) {
                fprintf(stderr, "Failed to open I2C bus.\n");
                sleep(1);
                continue;
            }
        }

        if (ioctl(i2c_file_descriptor, I2C_SLAVE, SHT40_ADDR) == -1) {
            fprintf(stderr, "Failed to set I2C slave address.\n");
            close(i2c_file_descriptor);
            i2c_file_descriptor = -1;
            sleep(1);
            continue;
        }

        msgs[0].addr = SHT40_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = sizeof(write_buf);
        msgs[0].buf = write_buf;

        msgs[1].addr = SHT40_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = sizeof(read_buf);
        msgs[1].buf = read_buf;

        if (i2c_file_descriptor == -1 || i2c_rdwr(i2c_file_descriptor, msgs, 2) == -1) {
            fprintf(stderr, "Failed to read from I2C device.\n");
            close(i2c_file_descriptor);
            i2c_file_descriptor = -1;
            sleep(1);
            continue;
        }

        if (sht40_crc(read_buf, 2) != read_buf[2] || sht40_crc(read_buf + 3, 2) != read_buf[5]) {
            fprintf(stderr, "CRC check failed.\n");
            sleep(1);
            continue;
        }

        int temperature = (read_buf[0] << 8) | read_buf[1];
        int humidity = (read_buf[3] << 8) | read_buf[4];

        printf("Temperature: %.2f C, Humidity: %.2f%%\n", (6250.0 * temperature - 4500.0) / 100.0, 100.0 * humidity / 65535.0);

        sleep(5);
    }

    return 0;
}

