    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    fd = open("/dev/i2c-" #I2C_BUS, O_RDWR);
    if (fd < 0) {
        error_file = fopen(ERROR_FILENAME, "a");
        if (error_file) {
            fprintf(error_file, "Failed to open I2C bus: %s\n", strerror(errno));
            fclose(error_file);
        }
        cleanup_and_exit(-1);
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        error_file = fopen(ERROR_FILENAME, "a");
        if (error_file) {
            fprintf(error_file, "Failed to set sensor address: %s\n", strerror(errno));
            fclose(error_file);
        }
        cleanup_and_exit(-1);
    }

    log_file = fopen(FILENAME, "a");
    if (!log_file) {
        error_file = fopen(ERROR_FILENAME, "a");
        if (error_file) {
            fprintf(error_file, "Failed to open log file: %s\n", strerror(errno));
            fclose(error_file);
        }
        cleanup_and_exit(-1);
