    while (1) {
        char buffer[2];
        if (read(fd, buffer, 2) != 2) {
            error_file = fopen(ERROR_FILENAME, "a");
            if (error_file) {
                fprintf(error_file, "Failed to read temperature: %s\n", strerror(errno));
                fclose(error_file);
            }
            cleanup_and_exit(-1);
        }

        float temperature = (buffer[0] << 8 | buffer[1]) * 0.005;
        fprintf(log_file, "%f\n", temperature);

        sleep(5);
    }

    cleanup_and_exit(0);
}

