struct sdp31_data {
    unsigned int pressure_pa;
    unsigned int temperature_c;
};

struct sdp31_data read_sdp31_data(int i2c_handle) {
    unsigned char buffer[SENSIRION_READ_LENGTH];
    struct sdp31_data data;

    if (i2c_write_device(i2c_handle, SDP31_I2C_ADDR, &SDP31_MEASURE_COMMAND, sizeof(SDP31_MEASURE_COMMAND)) < 0) {
        fprintf(stderr, "Failed to write to SDP31 sensor\n");
        exit(EXIT_FAILURE);
    }

    usleep(1000);  // Wait at least 1 ms after the trigger

    if (i2c_read_device(i2c_handle, SDP31_I2C_ADDR, buffer, SDP31_READ_LENGTH) < 0) {
        fprintf(stderr, "Failed to read from SDP31 sensor\n");
        exit(EXIT_FAILURE);
    }

    // Convert the values to pressure in pascals and temperature in degrees Celsius
    data.pressure_pa = (buffer[0] << 8) | buffer[1];
    data.temperature_c = (buffer[3] << 8) | buffer[4];

    return data;
}

void log_data(FILE *log_file, struct sdp31_data data) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            data.pressure_pa, data.temperature_c);

    fflush(log_file);
}

void cleanup(int i2c_handle, FILE *log_file) {
    i2c_close(i2c_handle);
    fclose(log_file);
    libgpiod_cleanup();
}

