    int i2c_handle = i2c_open(1);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(i2c_handle, NULL);
        exit(EXIT_FAILURE);
    }

