static FILE* log_file = NULL;

void cleanup_and_exit(int sig) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(sig);
}

int i2c_write_read(int cmd, char* buf, int len) {
    int retries = I2C_RETRIES;
    while (retries--) {
        if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDRESS) == 0) {
            if (write(i2c_file, &cmd, 1) == 1) {
                usleep(I2C_DELAY);
                if (read(i2c_file, buf, len) == len) {
                    return 0;
                }
            }
        }
        usleep(I2C_DELAY);
    }
    return -1;
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_and_exit(1);
