                time_t now = time(NULL);
                struct tm* timeinfo = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temp, humidity);
                printf("%s, Temp: %.2f C, Humidity: %.2f%%\n", timestamp, temp, humidity);
                fflush(log_file);
            } else {
                fprintf(stderr, "Failed to read humidity: %s\n", strerror(errno));
                cleanup_and_exit(1);
            }
        } else {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            cleanup_and_exit(1);
        }
        sleep(5);
    }

    return 0;
}

