#define STS30_CRC_POLYNOMIAL 0x31
#define STS30_CRC_INIT 0xFF

int i2c_file = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;

void cleanup_and_exit(int signum) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    exit(signum);
}

int compute_crc8(const unsigned char *data, int length) {
    int crc = STS30_CRC_INIT;
    for (int i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = ((crc << 1) ^ STS30_CRC_POLYNOMIAL);
            } else {
                crc <<= 1;
            }
        }
    }
    return crc & 0xFF;
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    log_file = fopen("enclosure_temp_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_and_exit(-1);
    }

    error_log_file = fopen("error_log.txt", "w");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        cleanup_and_exit(-1);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device file");
        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSIRION_STS30_DIS_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    while (1) {
        unsigned char cmd_buf[2] = {STS30_MEASUREMENT_CMD >> 8, STS30_MEASUREMENT_CMD & 0xFF};
        if (write(i2c_file, cmd_buf, 2) != 2) {
            perror("Failed to write I2C command");
            cleanup_and_exit(-1);
        }

        usleep(15000);  // Wait at least 15 ms for conversion.

        unsigned char read_buf[3];
        if (read(i2c_file, read_buf, 3) != 3) {
            perror("Failed to read I2C response");
            cleanup_and_exit(-1);
        }

        int computed_crc = compute_crc8(read_buf, 2);
        if (computed_crc != read_buf[2]) {
            fprintf(error_log_file, "CRC mismatch: computed %02X, read %02X\n", computed_crc, read_buf[2]);
            cleanup_and_exit(-1);
        }

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local_time);

        float temperature = ((read_buf[0] << 8) | read_buf[1]) * (175.72 / 65535.0) - 46.85;
        fprintf(log_file, "%s: %.2f °C\n", timestamp, temperature);
    }

    cleanup_and_exit(0);
}

