#define SHT40_ADDR 0x70
#define SHT40_MEASURE_HIGH_REP 0xFD
#define LOG_FILE "sht40_log.txt"

int i2c_file_descriptor;
FILE* log_file;

int sht40_crc8(const unsigned char *data, int length) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc <<= 1;
                crc ^= 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int signum) {
    fclose(log_file);
    close(i2c_file_descriptor);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    unsigned char command = SHT40_MEASURE_HIGH_REP;
    unsigned char data[6];

    while (1) {
        if (write(i2c_file_descriptor, &command, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }

        usleep(8500);

        if (read(i2c_file_descriptor, &data, 6) != 6) {
            perror("Failed to read from I2C device");
            continue;
        }

        int t_crc = sht40_crc8(&data[0], 2);
        int rh_crc = sht40_crc8(&data[3], 2);

        if (t_crc != data[2] || rh_crc != data[5]) {
            fprintf(log_file, "CRC failure: T_CRC = %d, RH_CRC = %d\n", t_crc, rh_crc);
            continue;
        }

        int temperature = (data[0] << 8) | data[1];
        int humidity = (data[3] << 8) | data[4];

        time_t now = time(NULL);
        struct tm* time_info = localtime(&now);
        char time_string[20];
        strftime(time_string, 20, "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s: Temperature = %d, Humidity = %d\n", time_string, temperature, humidity);

        fflush(log_file);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

