#define SDP800_ADDR 0x76
#define SDP800_MEASURE_CMD 0x50
#define SDP800_PRESSURE_MSB 0x00
#define SDP800_PRESSURE_LSB 0x01
#define SDP800_TEMP_MSB 0x02
#define SDP800_TEMP_LSB 0x03
#define SDP800_CRC 0x04
#define SDP800_POLY 0x31
#define SDP800_INIT 0xFF

int fd, file_desc;
volatile sig_atomic_t stop;

void handle_sigint(int signum) {
    stop = 1;
}

unsigned char sdp800_crc(unsigned char *data, int len) {
    unsigned char crc = SDP800_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SDP800_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave");
        close(fd);
        return 1;
    }

    if (write(fd, &SDP800_MEASURE_CMD, 1) != 1) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    unsigned char data[6];
    file_desc = open("airflow_data.txt", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (file_desc < 0) {
        perror("Failed to open file");
        close(fd);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        usleep(1000);
        if (read(fd, data, 6) != 6) {
            perror("Failed to read from I2C device");
            close(fd);
            close(file_desc);
            return 1;
        }

        if (sdp800_crc(data, 2) != data[SDP800_PRESSURE_LSB] || sdp800_crc(data + 3, 2) != data[SDP800_TEMP_LSB]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int pressure = (data[SDP800_PRESSURE_MSB] << 8) | data[SDP800_PRESSURE_LSB];
        int temperature = (data[SDP800_TEMP_MSB] << 8) | data[SDP800_TEMP_LSB];
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        char line[100];
        sprintf(line, "%s,%d,%d\n", timestamp, pressure, temperature);
        if (write(file_desc, line, strlen(line)) != strlen(line)) {
            perror("Failed to write to file");
            close(fd);
            close(file_desc);
            return 1;
        }
    }

    close(fd);
    close(file_desc);
    return 0;
}

