            continue;
        }
        unsigned char command = 0xF3;
        if (write(i2c_file, &command, 1) != 1) {
            fprintf(stderr, "Failed to write command\n");
            continue;
        }
        unsigned char data[2];
        if (read(i2c_file, data, 2) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        int temperature = (data[0] << 8) | data[1];
        return temperature;
    }
    fprintf(stderr, "Failed to read temperature after %d retries\n", I2C_RETRIES);
    return -1;
}

void add_to_buffer(int value) {
    circular_buffer[buffer_head] = value;
    if (buffer_full) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    } else if (buffer_head == buffer_tail) {
        buffer_full = 1;
    }
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

