    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }
    line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }
    if (gpiod_line_request_output(line, "fan_controller", 0)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    int fan_on = 0;
    while (1) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Sensor not present or other error\n");
            return 1;
        }
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: %d\n", ts.tv_sec, ts.tv_nsec, temperature);
        add_to_buffer(temperature);

        if (temperature > TURN_ON_TEMP && !fan_on) {
            gpiod_line_set_value(line, 1);
            fan_on = 1;
        } else if (temperature < TURN_OFF_TEMP && fan_on) {
            gpiod_line_set_value(line, 0);
            fan_on = 0;
        }

        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

