int buffer_tail = 0;

int crc8(const uint8_t *data, size_t nbytes) {
    uint8_t crc = 0;
    for (size_t i = 0; i < nbytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

void sig_handler(int signo) {
    if (i2c_file >= 0)
        close(i2c_file);
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    exit(signo);
}

