#define SHT35_ADDR 0x44
#define SHT35_MEASURE_HIGH_REP 0x2C06
#define SHT35_I2C_BUS 1
#define SHT35_MAX_RETRIES 3
#define SHT35_RETRY_DELAY 1
#define SHT35_LOG_FILE "environmental_data.txt"

static int i2c_file_descriptor = -1;
static FILE* log_file = NULL;

static int sht35_crc8(const unsigned char *data, int length) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc <<= 1;
                crc ^= 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sht35_read_data(float* temperature, float* humidity) {
    unsigned char buffer[6];
    struct i2c_msg msgs[] = {
        {
            .addr = SHT35_ADDR,
            .flags = 0,
            .len = 2,
            .buf = (unsigned char*)&SHT35_MEASURE_HIGH_REP
        },
        {
            .addr = SHT35_ADDR,
            .flags = I2C_M_RD,
            .len = sizeof(buffer),
            .buf = buffer
        }
    };

    if (ioctl(i2c_file_descriptor, I2C_RDWR, msgs) < 0) {
        return -1;
    }

    if (sht35_crc8(buffer, 2) != buffer[2] || sht35_crc8(buffer + 3, 2) != buffer[5]) {
        return -1;
    }

    unsigned int temp_raw = (buffer[0] << 8) | buffer[1];
    unsigned int humidity_raw = (buffer[3] << 8) | buffer[4];

    *temperature = -45 + 175 * temp_raw / 65535.0;
    *humidity = 100 * humidity_raw / 65535.0;

    return 0;
}

static void sht35_log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm* timeinfo = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

static void sht35_handle_signal(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    signal(SIGINT, sht35_handle_signal);
    signal(SIGTERM, sht35_handle_signal);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SHT35_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    log_file = fopen(SHT35_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (1) {
        float temperature, humidity;
        int retries = 0;
        while (sht35_read_data(&temperature, &humidity) != 0) {
            if (retries++ >= SHT35_MAX_RETRIES) {
                sht35_log_data(NAN, NAN);
                sleep(SHT35_RETRY_DELAY);
                retries = 0;
            }
        }

        sht35_log_data(temperature, humidity);
        sleep(5);
    }

    return EXIT_SUCCESS;
}

