#define SDP810_I2C_ADDR 0x76
#define SDP810_MEASURE_CMD 0x00
#define SDP810_DATA_LEN 9

volatile sig_atomic_t stop = 0;
int fd_i2c, fd_csv;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int validate_crc(const unsigned char *data, int len, unsigned char crc) {
    unsigned char crc_calc = crc8(data, len);
    return crc_calc == crc;
}

void log_data(double pressure, double temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fd_csv, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fd_csv);
}

int main() {
    fd_i2c = open("/dev/i2c-1", O_RDWR);
    if (fd_i2c < 0) {
        perror("open i2c");
        return EXIT_FAILURE;
    }

    if (ioctl(fd_i2c, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        perror("ioctl i2c");
        return EXIT_FAILURE;
    }

    fd_csv = fopen("airflow.csv", "w");
    if (fd_csv == NULL) {
        perror("fopen csv");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    unsigned char data[SDP810_DATA_LEN];
    while (!stop) {
        if (write(fd_i2c, &SDP810_MEASURE_CMD, 1) != 1) {
            perror("write cmd");
            break;
        }

        usleep(45000);

        if (read(fd_i2c, data, SDP810_DATA_LEN) != SDP810_DATA_LEN) {
            perror("read data");
            break;
        }

        if (!validate_crc(data, 1, data[0]) ||
            !validate_crc(data + 1, 1, data[1]) ||
            !validate_crc(data + 2, 1, data[2])) {
            fprintf(stderr, "crc error\n");
            continue;
        }

        double pressure = ((data[0] << 8) | data[1]) * 250.0;
        double temperature = ((data[2] << 8) | data[3]) * 175.72 / 65535.0 - 46.85;

        log_data(pressure, temperature);

        sleep(1);
    }

    fclose(fd_csv);
    close(fd_i2c);

    return EXIT_SUCCESS;
}

