#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define SHT35_ADDR 0x44
#define SHT35_MEASURE_HM_TO_READ_MS 15
#define SHT35_MEASURE_HM_CMD 0x2C06
#define SHT35_CRC_POLYNOMIAL 0x31
#define SHT35_CRC_INITIAL 0xFF

#define I2C_DEV_PATH "/dev/i2c-1"
#define CSV_PATH "environment.csv"

static int i2c_file_descriptor = -1;

static int sht35_crc(const unsigned char *data, size_t length) {
    unsigned char crc = SHT35_CRC_INITIAL;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc <<= 1;
                crc ^= SHT35_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sht35_read_data(float *temperature, float *humidity) {
    unsigned char buffer[6];
    struct i2c_msg msgs[] = {
        {
            .addr = SHT35_ADDR,
            .flags = I2C_M_RD,
            .len = sizeof(buffer),
            .buf = buffer,
        },
    };

    if (ioctl(i2c_file_descriptor, I2C_RDWR, msgs) < 0) {
        perror("I2C read failed");
        return -1;
    }

    if (sht35_crc(buffer, 2) != buffer[2] || sht35_crc(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    *temperature = ((buffer[0] << 8 | buffer[1]) >> 2) * 175.0 / 65535.0 - 45;
    *humidity = ((buffer[3] << 8 | buffer[4]) >> 2) * 100.0 / 65535.0;

    return 0;
}

static void sht35_log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    FILE *file = fopen(CSV_PATH, "a");
    if (file == NULL) {
        perror("Failed to open CSV file for writing");
        return;
    }

    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Temperature,Humidity\n");
    }

    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
            local_time->tm_hour, local_time->tm_min, local_time->tm_sec,
            temperature, humidity);

    fclose(file);
}

static void sht35_shutdown(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    signal(SIGINT, sht35_shutdown);
    signal(SIGTERM, sht35_shutdown);

    i2c_file_descriptor = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device file");
        return 1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SHT35_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    while (1) {
        float temperature, humidity;
        if (sht35_read_data(&temperature, &humidity) < 0) {
            return 1;
        }
        sht35_log_data(temperature, humidity);
        sleep(5);
    }

    return 0;
}

