#define SDP800_I2C_ADDRESS 0x76
#define SDP800_MEASUREMENT_COMMAND 0xF4
#define SDP800_RESPONSE_LENGTH 9
#define SDP800_CRC_POLYNOMIAL 0x31

int i2c_file_descriptor;
FILE *log_file;

void exit_handler(int signum) {
    close(i2c_file_descriptor);
    fclose(log_file);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Could not open I2C device");
        exit(1);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        perror("Could not set I2C slave address");
        exit(1);
    }

    log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        perror("Could not open log file");
        exit(1);
    }

    while (1) {
        unsigned char write_buffer = SDP800_MEASUREMENT_COMMAND;
        if (write(i2c_file_descriptor, &write_buffer, 1) != 1) {
            perror("Could not write to I2C device");
            continue;
        }

        usleep(45000);

        unsigned char read_buffer[SDP800_RESPONSE_LENGTH];
        if (read(i2c_file_descriptor, read_buffer, SDP800_RESPONSE_LENGTH) != SDP800_RESPONSE_LENGTH) {
            perror("Could not read from I2C device");
            continue;
        }

        unsigned char calculated_crc = 0;
        for (int i = 0; i < SDP800_RESPONSE_LENGTH - 1; i++) {
            calculated_crc ^= read_buffer[i];
            for (int j = 0; j < 8; j++) {
                if (calculated_crc & 0x80) {
                    calculated_crc <<= 1;
                    calculated_crc ^= SDP800_CRC_POLYNOMIAL;
                } else {
                    calculated_crc <<= 1;
                }
            }
        }

        if (calculated_crc != read_buffer[SDP800_RESPONSE_LENGTH - 1]) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

        fprintf(log_file, "%s: %.2f\n", timestamp, (float)((read_buffer[0] << 12) | (read_buffer[1] << 4) | (read_buffer[2] >> 4)) / 100.0);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

