#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include "lps33hw.h"

#define LOG_FILE "/home/pi/environmental_data.txt"
#define I2C_BUS 1
#define I2C_ADDRESS 0x5C

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    int fd, i2c_file, ret;
    struct lps33hw_data data;
    struct tm tm;
    char timestamp[26];
    struct sigaction action;

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        close(fd);
        return 1;
    }

    ret = ioctl(i2c_file, I2C_SLAVE, I2C_ADDRESS);
    if (ret == -1) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(fd);
        close(i2c_file);
        return 1;
    }

    while (!stop) {
        ret = lps33hw_read_data(&data);
        if (ret != 0) {
            time_t now = time(NULL);
            localtime_r(&now, &tm);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(stderr, "%s: Failed to read data\n", timestamp);
            fprintf(fd, "%s: Failed to read data\n", timestamp);
            fflush(fd);
            continue;
        }

        now = time(NULL);
        localtime_r(&now, &tm);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fd, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
        fflush(fd);
        sleep(1);
    }

    close(fd);
    close(i2c_file);
    lps33hw_cleanup();

    return 0;
}

