#include <libgpiod.h>

#define I2C_BUS_PATH "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x48
#define GPIO_LINE_OFFSET 17
#define CIRCULAR_BUFFER_SIZE 10
#define TEMP_THRESHOLD 280

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_file;
double circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;
double average = 0;

void cleanup_and_exit(int signum) {
    gpiod_line_set_value(line, 0);
    close(i2c_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(line, "led_control", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    i2c_file = open(I2C_BUS_PATH, O_RDWR);
    if (i2c_file < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    while (1) {
        char temp_data[2];
        if (read(i2c_file, temp_data, 2) != 2) {
            perror("read");
            continue;
        }

        int temp_raw = (temp_data[0] << 8) | temp_data[1];
        double temp_c = (temp_raw >> 5) * 0.125;

        circular_buffer[buffer_index] = temp_c;
        buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;

        double sum = 0;
        for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
            sum += circular_buffer[i];
        }

        average = sum / CIRCULAR_BUFFER_SIZE;

        if (average > TEMP_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    return 0;
}

