#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define SDP32_ADDR 0x76
#define SDP32_REG_PRESSURE 0x00
#define SDP32_REG_TEMPERATURE 0x02
#define SDP32_REG_SCALE_FACTOR 0x04
#define SDP32_REG_CRC 0x06
#define SDP32_REG_RESET 0x08

#define SDP32_CRC8_POLYNOMIAL 0x31

int fd;

void exit_handler(int signum) {
    close(fd);
    exit(signum == SIGINT || signum == SIGTERM ? 0 : 1);
}

unsigned char sdp32_crc8(const unsigned char *data, size_t len) {
    unsigned char crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SDP32_CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main(int argc, char *argv[]) {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, SDP32_ADDR) < 0) {
        perror("ioctl");
        exit_handler(1);
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    int interval = argc > 1 ? atoi(argv[1]) : 1000;
    unsigned char buf[9];
    while (1) {
        if (read(fd, buf, 9) != 9) {
            fprintf(stderr, "read failed\n");
            exit_handler(1);
        }

        if (sdp32_crc8(buf, 3) != buf[3] || sdp32_crc8(buf + 4, 3) != buf[7] || sdp32_crc8(buf + 8, 1) != buf[8]) {
            fprintf(stderr, "CRC check failed\n");
            exit_handler(1);
        }

        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", local_time);
        printf("%s: %02x %02x %02x %02x %02x %02x %02x %02x %02x\n", timestamp, buf[0], buf[1], buf[2], buf[4], buf[5], buf[6], buf[7], buf[8]);

        usleep(interval * 1000);
    }

    return 0;
}

