#include <linux/i2c-dev.h>
#include <signal.h>

#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x01
#define I2C_DEV_FILE "/dev/i2c-1"

static int i2c_file_descriptor = -1;

void exit_handler(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    exit(signum);
}

int main() {
    struct i2c_msg msgs[2];
    uint16_t temp, humidity;
    float temp_c, humidity_pct;
    int ret;

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    i2c_file_descriptor = open(I2C_DEV_FILE, O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open %s\n", I2C_DEV_FILE);
        exit_handler(EXIT_FAILURE);
    }

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, HDC1000_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set slave address to %d\n", HDC1000_ADDR);
        exit_handler(EXIT_FAILURE);
    }

    while (1) {
        // Start temperature and humidity conversion
        ret = write(i2c_file_descriptor, &TEMP_REG, sizeof(TEMP_REG));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to sensor\n");
            continue;
        }

        usleep(20000); // Wait at least 20 ms

        // Read temperature
        msgs[0].addr = HDC1000_ADDR;
        msgs[0].flags = I2C_M_RD;
        msgs[0].len = sizeof(temp);
        msgs[0].buf = (uint8_t *)&temp;

        ret = read(i2c_file_descriptor, &temp, sizeof(temp));
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature from sensor\n");
            continue;
        }

        temp_c = ((temp >> 6) * 175.72) / 65536.0 - 46.85;

        // Start humidity conversion
        ret = write(i2c_file_descriptor, &HUMIDITY_REG, sizeof(HUMIDITY_REG));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to sensor\n");
            continue;
        }

        usleep(20000); // Wait at least 20 ms

        // Read humidity
        ret = read(i2c_file_descriptor, &humidity, sizeof(humidity));
        if (ret < 0) {
            fprintf(stderr, "Failed to read humidity from sensor\n");
            continue;
        }

        humidity_pct = ((humidity >> 6) * 100.0) / 65536.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, humidity_pct);

        sleep(5);
    }

    exit_handler(EXIT_SUCCESS);
}

