#include <string.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define SENSOR_ADDRESS 0x60
#define I2C_DEVICE "/dev/i2c-1"

int fd;

void sig_handler(int signo) {
    close(fd);
    exit(signo);
}

int main() {
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set sensor address\n");
        exit(EXIT_FAILURE);
    }

    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    while (1) {
        // Trigger measurement
        if (write(fd, "\x00", 1) != 1) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        usleep(7000);

        // Read results
        char buffer[3];
        if (read(fd, buffer, 3) != 3) {
            fprintf(stderr, "Failed to read results\n");
            continue;
        }

        // Check if all bytes match the default
        if (buffer[0] == 0x80 && buffer[1] == 0x00 && buffer[2] == 0x00) {
            fprintf(stderr, "Sensor not present\n");
            continue;
        }

        // Temperature and pressure calculation
        // Assuming the sensor's data format
        int temperature = (buffer[0] & 0x7F) * 256 + buffer[1];
        int pressure = buffer[2] * 10000;

        // Print results with ISO-8601 timestamp
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature / 100.0, pressure);

        sleep(5);
    }

    close(fd);
    return 0;
}

