        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature / 100.0, pressure);

