#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SDA_GPIO 2
#define SCL_GPIO 3
#define SDP800_ADDR 0x76
#define I2C_BUS 1
#define I2C_DEV_PATH "/dev/i2c-" #I2C_BUS

#define WORD_LEN 2
#define CRC_LEN 1
#define SAMPLE_LEN (WORD_LEN * 3 + CRC_LEN * 3)

#define POLY 0x31
#define INIT_VAL 0xFF

volatile sig_atomic_t stop = 0;
int i2c_file = -1;

void cleanup(void) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    exit(0);
}

void signal_handler(int signum) {
    stop = 1;
}

unsigned char crc8(const unsigned char *data, int len, unsigned char poly, unsigned char init_val) {
    unsigned char crc = init_val;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(void) {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(cleanup);

    i2c_file = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SDP800_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    unsigned char sample[SAMPLE_LEN];
    while (!stop) {
        // Trigger measurement
        if (write(i2c_file, "\xF4", 1) != 1) {
            perror("Failed to write to I2C device");
            return 1;
        }

        usleep(45000);

        // Read sample
        if (read(i2c_file, sample, SAMPLE_LEN) != SAMPLE_LEN) {
            perror("Failed to read from I2C device");
            return 1;
        }

        // Validate CRCs
        for (int i = 0; i < 3; i++) {
            unsigned char word[WORD_LEN];
            memcpy(word, sample + i * (WORD_LEN + CRC_LEN), WORD_LEN);
            if (crc8(word, WORD_LEN, POLY, INIT_VAL) != sample[i * (WORD_LEN + CRC_LEN) + WORD_LEN]) {
                fprintf(stderr, "CRC validation failed for word %d\n", i);
                continue;
            }
        }

        // Log sample
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s,%02X%02X,%02X%02X\n", timestamp, sample[0], sample[1], sample[4], sample[5]);
        fflush(log_file);
    }

    fclose(log_file);
    return 0;
}

