    int ret;

    msgs[0].addr = SDP800_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = out_len;
    msgs[0].buf = out;

    msgs[1].addr = SDP800_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = in_len;
    msgs[1].buf = in;

    msg.msgs = msgs;
    msg.nmsgs = 2;

    ret = ioctl(file, I2C_RDWR, &msg);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    fd = open(FILENAME, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    if (access(FILENAME, F_OK) == 0) {
        if (write(fd, "Timestamp,Pressure\n", 19) == -1) {
            perror("write");
            return 1;
        }
    }

    char cmd = 0xF6;
    char buf[3];
    int ret;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    while (!stop) {
        ret = i2c_write_read(fd, &cmd, 1, buf, 3);
        if (ret == -1) {
            printf("Error reading from sensor\n");
            continue;
        }

        // TODO: Verify CRC-8

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[20];
        sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

        char line[30];
        sprintf(line, "%s,%02x%02x%02x\n", timestamp, buf[0], buf[1], buf[2]);

        if (write(fd, line, strlen(line)) == -1) {
            perror("write");
            return 1;
        }

        usleep(8000);
    }

    close(fd);

    return 0;
}

