#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define MLX90821_I2C_ADDR 0x2A
#define I2C_BUS 1
#define MAX_RETRIES 1
#define SAFE_PRESSURE_MIN 200
#define SAFE_PRESSURE_MAX 250

struct gpiod_device *dev = NULL;
struct gpiod_line *line = NULL;
FILE *csv_file = NULL;

void cleanup_and_exit(int signum) {
    if (dev)
        gpiod_device_close(dev);
    if (csv_file) {
        fclose(csv_file);
    }
    exit(signum);
}

int main() {
    dev = gpiod_device_open_by_name("i2c-1");
    if (!dev) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_device_get_line(dev, MLX90821_I2C_ADDR);
    if (!line) {
        fprintf(stderr, "Failed to get I2C line: %s\n", strerror(errno));
        return 1;
    }

    csv_file = fopen("pressure_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    int retries = 0;
    while (1) {
        float pressure;
        int err = gpiod_line_read(line, &pressure);
        if (err) {
            fprintf(stderr, "Failed to read pressure: %s\n", strerror(errno));
            if (retries < MAX_RETRIES) {
                gpiod_line_close(line);
                line = gpiod_device_get_line(dev, MLX90821_I2C_ADDR);
                if (!line) {
                    fprintf(stderr, "Failed to get I2C line after retry: %s\n", strerror(errno));
                    return 1;
                }
                retries++;
                continue;
            } else {
                cleanup_and_exit(-1);
            }
        }

        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tmp);

        if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
            fprintf(stderr, "Warning: pressure out of safe range: %.2f kPa\n", pressure);
        }

        if (ftell(csv_file) == 0) {
            fprintf(csv_file, "timestamp,pressure_kPa\n");
        }
        fprintf(csv_file, "%s,%.2f\n", timestamp, pressure);
        fflush(csv_file);

        sleep(1);
    }

    cleanup_and_exit(0);
}

