#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define SENSOR_ADDRESS 0x27
#define I2C_BUS 1
#define LOG_FILE "/home/pi/environmental_data.log"
#define LOG_MAX_SIZE (1024 * 1024)

int i2c_file_descriptor = -1;
int log_file_descriptor = -1;
volatile sig_atomic_t stop_flag = 0;

void close_resources(void) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file_descriptor != -1) {
        close(log_file_descriptor);
    }
    exit(0);
}

void handle_sigint(int signum) {
    stop_flag = 1;
}

int main(void) {
    struct sigaction action;
    struct stat st;
    char log_buffer[128];
    int ret;

    action.sa_handler = handle_sigint;
    action.sa_flags = 0;
    sigemptyset(&action.sa_mask);
    sigaction(SIGINT, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        close_resources();
        return 1;
    }

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set sensor address\n");
        close_resources();
        return 1;
    }

    log_file_descriptor = open(LOG_FILE, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (log_file_descriptor < 0) {
        fprintf(stderr, "Failed to open log file\n");
        close_resources();
        return 1;
    }

    while (!stop_flag) {
        ret = fstat(log_file_descriptor, &st);
        if (ret < 0) {
            fprintf(stderr, "Failed to check log file size\n");
            close_resources();
            return 1;
        }

        if (st.st_size > LOG_MAX_SIZE) {
            ret = ftruncate(log_file_descriptor, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to truncate log file\n");
                close_resources();
                return 1;
            }
        }

        // Trigger measurement
        ret = write(i2c_file_descriptor, "\xF3", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            close_resources();
            return 1;
        }

        usleep(40000);

        // Read data
        ret = read(i2c_file_descriptor, log_buffer, 3);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            close_resources();
            return 1;
        }

        // Validate status bits
        if ((log_buffer[0] & 0x3F) != 0x00) {
            fprintf(stderr, "Invalid sensor status\n");
            close_resources();
            return 1;
        }

        // Write to log
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%dT%H:%M:%S", now_tm);
        sprintf(log_buffer + strlen(log_buffer), " humidity: %.2f%% temperature: %.2fC\n",
                (log_buffer[1] * 256 + log_buffer[2]) / 100.0,
                (log_buffer[1] * 256 + log_buffer[2]) / 100.0 - 32 * 5 / 9);

        ret = write(log_file_descriptor, log_buffer, strlen(log_buffer));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            close_resources();
            return 1;
        }

        sleep(5);
    }

    close_resources();
    return 0;
}

