#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_LINE 4
#define SLEEP_TIME 3000
#define SYNC_PULSE 56
#define MIN_PULSE 12
#define MAX_PULSE 271

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;

void exit_handler(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line.\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "MLX90824")) {
        fprintf(stderr, "Failed to request GPIO line as input.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen("pressure_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    while (1) {
        struct timespec ts = { .tv_nsec = SLEEP_TIME };
        int value = gpiod_line_wait_for_rising_edge(line, &ts);
        if (value < 0) {
            fprintf(stderr, "Failed to wait for rising edge.\n");
            exit_handler(0);
        }

        int pulse = 0;
        while (gpiod_line_get_value(line)) {
            nanosleep(&ts, NULL);
            pulse++;
        }

        if (pulse < MIN_PULSE || pulse > MAX_PULSE) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse);
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (pulse == SYNC_PULSE) {
            fprintf(log_file, "%s, Synchronization pulse detected\n", timestamp);
        } else {
            float pressure = (pulse - MIN_PULSE) * 1000.0f;
            fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        }

        fflush(log_file);
    }

    return 0;
}

