#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libi2c.h>
#include <endian.h>

#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_ID 0x03
#define TMP117_ID 0x11

FILE *file_stream;
int i2c_handle;

void exit_handler(int signum) {
    i2c_close(i2c_handle);
    fclose(file_stream);
    exit(0);
}

int main() {
    file_stream = fopen("greenhouse_temps.dat", "wb");
    if (file_stream == NULL) {
        perror("Failed to open file");
        exit(1);
    }

    i2c_handle = i2c_open_device(TMP117_ADDR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C device");
        exit_handler(0);
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    int id = i2c_read_word(i2c_handle, TMP117_REG_ID);
    if (id != TMP117_ID) {
        fprintf(stderr, "Invalid sensor ID: %x\n", id);
        exit_handler(0);
    }

    while (1) {
        int temp_raw = i2c_read_word(i2c_handle, TMP117_REG_TEMP);
        if (temp_raw < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(-temp_raw));
            continue;
        }

        float temp_c = (float)temp_raw / 32.0;
        uint32_t temp_le = htole32(*(uint32_t*)&temp_c);

        if (fwrite(&temp_le, sizeof(temp_le), 1, file_stream) != 1) {
            perror("Failed to write to file");
            exit_handler(0);
        }

        sleep(60);
    }

    exit_handler(0);
}

