#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define SHT40_ADDR 0x70
#define SHT40_CMD_MEASURE_H_TO_LOW_POWER 0xF3
#define SHT40_CMD_WRITE_RESET 0xBE
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int fd;

static void cleanup_and_exit(int sig) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose((FILE*)fd);
    exit(0);
}

static int calc_crc(const unsigned char *data, int len) {
    int crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC_POLYNOMIAL : (crc << 1);
    }
    return crc;
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    fd = open("environmental_data.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    while (1) {
        unsigned char cmd[] = {SHT40_CMD_MEASURE_H_TO_LOW_POWER};
        unsigned char data[6];
        struct timespec ts;

        if (write(fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
            perror("write cmd");
            return 1;
        }

        if (read(fd, data, sizeof(data)) != sizeof(data)) {
            perror("read data");
            return 1;
        }

        if (calc_crc(data, 2) != data[2] || calc_crc(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        char line_str[100];
        sprintf(line_str, "%s, Temp: %d.%02d, Humidity: %d.%02d\n", time_str,
                (data[0] << 8 | data[1]) >> 4, ((data[0] << 8 | data[1]) & 0xF) * 25,
                data[3] << 8 | data[4], ((data[3] << 8 | data[4]) & 0xF) * 25);

        if (write(fd, line_str, strlen(line_str)) != strlen(line_str)) {
            perror("write line");
            return 1;
        }

        fflush(fd);
        usleep(5000000);
    }

    return 0;
}

