#define TMP117_CONFIG_REG 0x01
#define TMP117_CONVERSION_RATE 5
#define TMP117_BUFFER_SIZE 100

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_file;
int should_exit = 0;
int buffer[TMP117_BUFFER_SIZE];
int buffer_index = 0;

void write_to_file() {
    int fd = open("temperature_log.dat", O_WRONLY | O_CREAT, 0666);
    if (fd == -1) {
        perror("Failed to open file");
        return;
    }
    if (write(fd, buffer, TMP117_BUFFER_SIZE * sizeof(int)) == -1) {
        perror("Failed to write to file");
    }
    close(fd);
}

void handle_exit(int signum) {
    should_exit = 1;
}

int main() {
