#include <errno.h>
#include <libgpiod.h>
#include <shtc3.h>

#define SHTC3_I2C_ADDR 0x70
#define SHTC3_I2C_BUS 1

struct shtc3_dev *shtc3_dev;
struct gpiod_chip *chip;
struct gpiod_line *line;

void sigint_handler(int signum) {
    shtc3_close(shtc3_dev);
    printf("Sensor closed.\n");
    exit(0);
}

int main() {
    int ret;
    struct tm *timeinfo;
    time_t rawtime;
    char timestamp[20];
    FILE *logfile;

    shtc3_dev = shtc3_open(SHTC3_I2C_BUS, SHTC3_I2C_ADDR);
    if (!shtc3_dev) {
        fprintf(stderr, "Failed to open SHTC3 sensor: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    logfile = fopen("shtc3_environment.log", "w");
    if (!logfile) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        shtc3_close(shtc3_dev);
        return 1;
    }

    while (1) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        ret = shtc3_read_sensor_data(shtc3_dev);
        if (ret) {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            continue;
        }

        float temperature = shtc3_get_temperature(shtc3_dev);
        float humidity = shtc3_get_humidity(shtc3_dev);

        if (temperature < -40 || temperature > 125 || humidity < 0 || humidity > 100) {
            fprintf(stderr, "Reading out of range: Temperature = %.2f C, Humidity = %.2f %%\n", temperature, humidity);
            continue;
        }

        printf("Temperature = %.2f C, Humidity = %.2f %%\n", temperature, humidity);
        fprintf(logfile, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        fflush(logfile);
        sleep(5);
    }

    fclose(logfile);
    shtc3_close(shtc3_dev);

    return 0;
}

