#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libi2c.h>
#include <time.h>

#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00

FILE *log_file;
int i2c_handle;

void sigint_handler(int signum) {
    i2c_close(i2c_handle);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    i2c_handle = i2c_open_port(1);
    if (i2c_handle < 0) {
        printf("Failed to open I2C port\n");
        fclose(log_file);
        return 1;
    }

    int retries = 0;
    while (1) {
        if (i2c_set_slave_addr(i2c_handle, TMP117_ADDR, I2C_SLAVE_ADDR_10BIT) < 0) {
            printf("Failed to set slave address\n");
            if (retries < 3) {
                printf("Retrying...\n");
                retries++;
                sleep(1);
                continue;
            } else {
                fclose(log_file);
                i2c_close(i2c_handle);
                return 1;
            }
        }

        int16_t temp;
        if (i2c_read_word_data(i2c_handle, TMP117_TEMP_REG, &temp) < 0) {
            printf("Failed to read temperature\n");
            fclose(log_file);
            i2c_close(i2c_handle);
            return 1;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, (float)temp / 100.0);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    return 0;
}

