#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SENSOR_ADDRESS 0x5F
#define MAX_RETRIES 5

volatile sig_atomic_t stop = 0;

int i2c_file_descriptor = -1;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
        if (i2c_file_descriptor != -1) {
            close(i2c_file_descriptor);
        }
    }
}

int i2c_init() {
    int file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(file_descriptor, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave");
        return -1;
    }

    return file_descriptor;
}

int read_sensor_data(int file_descriptor, unsigned char *buffer) {
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = read(file_descriptor, buffer, 4);
        if (bytes_read == 4) {
            return 0;
        }

        perror("Failed to read from sensor");
        retries++;
    }

    return -1;
}

void log_data(FILE *file, time_t timestamp, unsigned int flow, unsigned int temperature) {
    fprintf(file, "%ld, %u, %u\n", timestamp, flow, temperature);
}

int main() {
    FILE *log_file = fopen("flow_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = i2c_init();
    if (i2c_file_descriptor < 0) {
        return EXIT_FAILURE;
    }

    unsigned char buffer[4];
    time_t timestamp;
    unsigned int flow, temperature;

    while (!stop) {
        if (read_sensor_data(i2c_file_descriptor, buffer) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            close(i2c_file_descriptor);
            i2c_file_descriptor = i2c_init();
            if (i2c_file_descriptor < 0) {
                return EXIT_FAILURE;
            }
            continue;
        }

        timestamp = time(NULL);
        flow = (buffer[0] << 6) | (buffer[1] >> 2);
        temperature = ((buffer[1] & 0x3) << 8) | buffer[2];

        log_data(log_file, timestamp, flow, temperature);

        sleep(1);
    }

    fclose(log_file);

    return EXIT_SUCCESS;
}

