    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = i2c_init();
    if (i2c_file_descriptor < 0) {
        return EXIT_FAILURE;
    }

    unsigned char buffer[4];
    time_t timestamp;
    unsigned int flow, temperature;

    while (!stop) {
        if (read_sensor_data(i2c_file_descriptor, buffer) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            close(i2c_file_descriptor);
            i2c_file_descriptor = i2c_init();
            if (i2c_file_descriptor < 0) {
                return EXIT_FAILURE;
            }
            continue;
        }

        timestamp = time(NULL);
        flow = (buffer[0] << 6) | (buffer[1] >> 2);
        temperature = ((buffer[1] & 0x3) << 8) | buffer[2];

        log_data(log_file, timestamp, flow, temperature);

        sleep(1);
    }

    fclose(log_file);

    return EXIT_SUCCESS;
}
