        return 1;
    }
    write(gpio_fd, GPIO_PIN, 1);
    close(gpio_fd);

    direction_fd = open(GPIO_DIRECTION_PATH, O_WRONLY);
    if (direction_fd == -1) {
        perror("Failed to open GPIO direction file");
        return 1;
    }
    write(direction_fd, "out", 3);
    close(direction_fd);

    value_fd = open(GPIO_VALUE_PATH, O_RDWR);
    if (value_fd == -1) {
        perror("Failed to open GPIO value file");
        return 1;
    }

    while (1) {
        write(value_fd, "0", 1);
        usleep(18000);
        write(value_fd, "1", 1);
        usleep(40000);

        gettimeofday(&start, NULL);
        for (i = 0; i < 1000000; i++) {
            gettimeofday(&end, NULL);
            if ((end.tv_sec - start.tv_sec) > 1) {
                log_error("Sensor not responding");
                break;
            }
            lseek(value_fd, 0, SEEK_SET);
            read(value_fd, &value, 1);
            if (value == '0') {
