            for (i = 0; i < 1000000; i++) {
                lseek(value_fd, 0, SEEK_SET);
                read(value_fd, &value, 1);
                if (value == '1') {
                    break;
                }
            }
            usleep(50000);
            lseek(value_fd, 0, SEEK_SET);
            read(value_fd, &value, 1);
            buffer[bit / 8] = (buffer[bit / 8] << 1) | (value == '1');
        }

        if (buffer[4] != ((buffer[0] + buffer[1] + buffer[2] + buffer[3]) & 0xff)) {
            log_error("Checksum failed");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
        fprintf(log_file, "%s %d %d %d %d\n", timestamp, buffer[0], buffer[1], buffer[2], buffer[3]);
    }

    return 0;
}

