#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define SHT31_ADDR 0x44
#define SHT31_CMD_MEASURE_H_RES 0x24
#define SHT31_CMD_WRITE_RESET 0x30
#define SHT31_CRC_POLY 0x31
#define SHT31_CRC_INIT 0xFF

#define MAX_TRIES 3
#define LOG_FILE "sht31d_data.log"

struct gpiod_device *dev = NULL;
struct gpiod_line *line = NULL;
int i2c_fd = -1;
int log_fd = -1;

void cleanup_and_exit(int signum) {
    if (dev)
        gpiod_device_close(dev);
    if (line)
        gpiod_line_release(line);
    if (i2c_fd != -1)
        close(i2c_fd);
    if (log_fd != -1)
        close(log_fd);
    exit(signum);
}

int sht31d_crc8(const unsigned char *data, size_t len) {
    unsigned char crc = SHT31_CRC_INIT;

    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];

        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SHT31_CRC_POLY;
            else
                crc <<= 1;
        }
    }

    return crc;
}

int sht31d_write_cmd(unsigned char cmd) {
    unsigned char buf[1] = {cmd};
    return write(i2c_fd, buf, 1);
}

int sht31d_read_data(unsigned char *data, size_t len) {
    return read(i2c_fd, data, len);
}

void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    dprintf(log_fd, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    dev = gpiod_device_open_by_name("pinctrl-bcm2835");
    if (!dev) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return 1;
    }

    line = gpiod_device_get_line(dev, 1);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        for (int i = 0; i < MAX_TRIES; i++) {
            if (sht31d_write_cmd(SHT31_CMD_MEASURE_H_RES) != -1)
                break;
            if (i == MAX_TRIES - 1) {
                fprintf(stderr, "Failed to write command\n");
                return 1;
            }
        }

        usleep(15000);

        unsigned char data[6];
        for (int i = 0; i < MAX_TRIES; i++) {
            if (sht31d_read_data(data, sizeof(data)) != -1)
                break;
            if (i == MAX_TRIES - 1) {
                fprintf(stderr, "Failed to read data\n");
                return 1;
            }
        }

        if (sht31d_crc8(data, 2) != data[2] || sht31d_crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            return 1;
        }

        float temperature = ((data[0] << 8) | data[1]) * 175.72 / 65535.0 - 46.85;
        float humidity = ((data[3] << 8) | data[4]) * 100.0 / 65535.0;

        log_data(temperature, humidity);

        sleep(5);
    }

    return 0;
}

