#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define ADPD105_ADDR 0x39
#define ADPD105_REG_COMMAND 0x00
#define ADPD105_REG_DATA_LOW 0x02
#define ADPD105_REG_DATA_HIGH 0x03

int i2c_file;
char *log_file = "cct_log.csv";
FILE *log_fp;

void exit_handler(int signum) {
    close(i2c_file);
    fclose(log_fp);
    exit(0);
}

int i2c_write_reg(int file, int addr, char *data, int len) {
    char buf[2];
    buf[0] = addr;
    memcpy(&buf[1], data, len);
    if (write(file, buf, len + 1) != len + 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int file, int addr, char *data, int len) {
    if (write(file, &addr, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    if (read(file, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        exit(1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, ADPD105_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        exit(1);
    }

    log_fp = fopen(log_file, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        exit(1);
    }

    if (fseek(log_fp, 0, SEEK_END) != 0 || ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Average_CCT\n");
    }

    while (1) {
        char data[2];
        if (i2c_read_reg(i2c_file, ADPD105_REG_DATA_LOW, data, 2) < 0) {
            fprintf(log_fp, "%ld,Error\n", time(NULL));
            continue;
        }

        int cct = (data[1] << 8) | data[0];
        fprintf(log_fp, "%ld,%d\n", time(NULL), cct);
        fflush(log_fp);

        sleep(1);
    }

    return 0;
}

