#define SENSOR_ADDRESS 0x30
#define I2C_BUS 1
#define LOG_FILE "pressure_log.txt"

static int should_exit = 0;
static FILE *log_file = NULL;
static int sensor_handle = -1;

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(log_file, "%s - ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

void exit_handler(int signum) {
    should_exit = 1;
    if (sensor_handle != -1) {
        mlx90824_cleanup(sensor_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = exit_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    sensor_handle = mlx90824_init(I2C_BUS, SENSOR_ADDRESS);
    if (sensor_handle == -1) {
        log_error("Failed to initialize sensor");
        exit_handler(0);
        return 1;
    }

    while (!should_exit) {
        float pressure, temperature;
        int result = mlx90824_read(sensor_handle, &pressure, &temperature);
        if (result == -1) {
            log_error("Failed to read from sensor");
        } else {
            time_t now = time(NULL);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            fprintf(log_file, "%s - Pressure: %.2f, Temperature: %.2f\n", timestamp, pressure, temperature);
            fflush(log_file);
        }

        sleep(2);
    }

    return 0;
}

