#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x48
#define I2C_FILE "/dev/i2c-1"
#define GPIO_LINE 18
#define SAMPLE_COUNT 60
#define TURN_ON_TEMP 280
#define TURN_OFF_TEMP 260

struct gpiod_line *line;
struct gpiod_chip *chip;
int i2c_file;
float samples[SAMPLE_COUNT];
int sample_index = 0;
float sample_sum = 0.0;
float last_temp = 0.0;
int fan_on = 0;

void handle_signal(int signum) {
    if (gpiod_line_set_value(line, 0) < 0)
        perror("Failed to turn off GPIO line");
    if (gpiod_chip_close(chip) < 0)
        perror("Failed to close GPIO chip");
    close(i2c_file);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_line("gpiochip0", GPIO_LINE, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);
    if (chip == NULL) {
        perror("Failed to open GPIO line");
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        return 1;
    }

    i2c_file = open(I2C_FILE, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device file");
        return 1;
    }
    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    while (1) {
        char buffer[2];
        if (read(i2c_file, buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }

        short temp = (buffer[0] << 8) | buffer[1];
        float temp_f = (float)temp / 16.0;

        sample_sum -= samples[sample_index];
        samples[sample_index] = temp_f;
        sample_sum += temp_f;
        sample_index = (sample_index + 1) % SAMPLE_COUNT;

        float avg_temp = sample_sum / SAMPLE_COUNT;
        if (avg_temp > TURN_ON_TEMP && !fan_on) {
            if (gpiod_line_set_value(line, 1) < 0)
                perror("Failed to set GPIO line value");
            fan_on = 1;
        } else if (avg_temp < TURN_OFF_TEMP && fan_on) {
            if (gpiod_line_set_value(line, 0) < 0)
                perror("Failed to set GPIO line value");
            fan_on = 0;
        }

        sleep(1);
    }

    return 0;
}

