#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define SDP810_I2C_ADDR 0x76
#define SDP810_CMD_START_MEASUREMENT 0x50
#define SDP810_DATA_LEN 9
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_CRC_INITIAL_VALUE 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

static unsigned char crc8(const unsigned char *data, size_t len, unsigned char crc) {
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) == -1) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        cleanup_and_exit(-1);
    }

    log_file = fopen("airflow.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(-1);
    }

    unsigned char cmd = SDP810_CMD_START_MEASUREMENT;
    unsigned char data[SDP810_DATA_LEN];
    while (1) {
        if (write(i2c_fd, &cmd, 1) != 1) {
            fprintf(stderr, "Failed to write to I2C device\n");
            cleanup_and_exit(-1);
        }
        usleep(45000);
        if (read(i2c_fd, data, SDP810_DATA_LEN) != SDP810_DATA_LEN) {
            fprintf(stderr, "Failed to read from I2C device\n");
            cleanup_and_exit(-1);
        }
        unsigned char crc = crc8(data, SDP810_DATA_LEN - 1, SDP810_CRC_INITIAL_VALUE);
        if (crc != data[SDP810_DATA_LEN - 1]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        double pressure = (data[1] << 8) | data[0];
        double temperature = (data[3] << 8) | data[2];
        temperature -= 27315;
        temperature /= 100.0;
        if (pressure > 5000) {
            fprintf(stderr, "Pressure exceeds 5.0 Pa\n");
        }
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(log_file);
        sleep(1);
    }

    return 0;
}

