#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_ADDR 0x48
#define I2C_DEV_PATH "/dev/i2c-1"
#define GPIO_CONSUMER "temperature-led"
#define GPIO_LINE 17
#define TEMP_THRESHOLD 28

static struct gpiod_line *gpio_line;
static int i2c_fd;

static void cleanup_and_exit(int signum)
{
    gpiod_line_set_value(gpio_line, 0);
    close(i2c_fd);
    gpiod_line_release(gpio_line);
    exit(0);
}

int main(void)
{
    int ret;
    uint16_t temp;
    int prev_state = 0;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    gpio_line = gpiod_line_open_by_gpio(GPIO_CONSUMER, GPIO_LINE, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (!gpio_line) {
        perror("Failed to open GPIO line");
        return 1;
    }

    while (1) {
        ret = read(i2c_fd, &temp, sizeof(temp));
        if (ret < 0) {
            perror("Failed to read temperature");
            cleanup_and_exit(0);
        }

        temp >>= 8;
        temp *= 100;
        printf("Temperature: %u.%02u °C\n", temp / 100, temp % 100);

        if (temp > TEMP_THRESHOLD * 100 && !prev_state) {
            gpiod_line_set_value(gpio_line, 1);
            prev_state = 1;
        } else if (temp <= TEMP_THRESHOLD * 100 && prev_state) {
            gpiod_line_set_value(gpio_line, 0);
            prev_state = 0;
        }

        sleep(1);
    }

    return 0;
}

