static int crc8(const unsigned char *data, size_t nbytes, unsigned char poly, unsigned char init) {
    unsigned char crc = init;
    for (size_t i = 0; i < nbytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ poly;
            else
                crc <<= 1;
        }
    }
    return crc;
