#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define TEMP_REG 0xF3
#define HUMIDITY_REG 0xF5
#define SENSOR_ID_REG 0x43
#define SENSOR_ID 0x11
#define MAX_TRIES 3
#define LOG_FILE "environment.log"

static int i2c_fd = -1;
static FILE *log_file = NULL;

static int write_read_i2c_data(const unsigned char reg, unsigned char *data, const int len) {
    int tries = 0;
    int ret;

    while (tries < MAX_TRIES) {
        ret = write(i2c_fd, &reg, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write register\n");
            tries++;
            continue;
        }

        ret = read(i2c_fd, data, len);
        if (ret < 0) {
            fprintf(stderr, "Failed to read data\n");
            tries++;
            continue;
        }

        return 0;
    }

    return -1;
}

static void sig_handler(int signo) {
    if (i2c_fd >= 0)
        close(i2c_fd);
    if (log_file != NULL)
        fclose(log_file);
    exit(signo);
}

int main() {
    unsigned char id;
    unsigned char temp[2];
    unsigned char humidity[2];
    struct sigaction sigIntHandler;
    struct timespec ts;
    char timestamp[20];
    int ret;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return -1;
    }

    ret = write_read_i2c_data(SENSOR_ID_REG, &id, 1);
    if (ret < 0 || id != SENSOR_ID) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    while (1) {
        ret = write_read_i2c_data(TEMP_REG, temp, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        ret = write_read_i2c_data(HUMIDITY_REG, humidity, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temp, humidity);
        printf("%s, %.2f, %.2f\n", timestamp, temp, humidity);
        fflush(log_file);

        sleep(60);
    }

    return 0;
}

