#include <linux/i2c-dev.h>

#define DEVICE_BUS 1
#define DEVICE_ADDRESS 0x48
#define LOG_FILE "temperature_log.txt"

volatile sig_atomic_t stop = 0;

int i2c_file_descriptor = -1;
int log_file_descriptor = -1;

void cleanup_and_exit(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (log_file_descriptor != -1) {
        close(log_file_descriptor);
    }
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup_and_exit(0);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, DEVICE_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set slave address\n");
        cleanup_and_exit(0);
    }

    log_file_descriptor = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_file_descriptor < 0) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(0);
    }

    while (!stop) {
        unsigned char buffer[3];
        if (write(i2c_file_descriptor, "\x2E", 1) != 1) {
            fprintf(stderr, "Failed to trigger temperature measurement\n");
            continue;
        }
        usleep(10000);
        if (read(i2c_file_descriptor, buffer, 3) != 3) {
            fprintf(stderr, "Failed to read temperature measurement\n");
            continue;
        }

        // CRC8 calculation
        unsigned char crc = buffer[0];
        crc ^= buffer[1];
        crc ^= buffer[2];
        if (crc != 0) {
            fprintf(stderr, "CRC8 mismatch\n");
            continue;
        }

        // Convert to temperature
        int temperature = (buffer[0] << 8) | buffer[1];
        temperature = (temperature * 175.72) / 65536 - 46.85;

        // Write to log file
        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
        dprintf(log_file_descriptor, "%s, %d\n", timestamp, temperature);

        sleep(5);
    }

    cleanup_and_exit(0);
}

