#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <gpiod.h>

#define SDP810_I2C_ADDR 0x76
#define SDP810_PRESSURE_REG 0x00
#define SDP810_TEMP_REG 0x02
#define SDP810_CRC_POLY 0x31
#define SDP810_CRC_INIT 0xFF

struct sdp810_data {
    int pressure;
    int temperature;
    unsigned char scale_factor[3];
};

struct sdp810_data data;
FILE *log_file;
int i2c_file;

void handle_sigint(int signum) {
    close(i2c_file);
    fclose(log_file);
    exit(signum);
}

int sdp810_crc(const unsigned char *data, int len) {
    int crc = SDP810_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SDP810_CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
