#define MLX90614_OBJECT_TEMP_REG 0x07
#define MLX90614_RETRIES 3
#define MLX90614_DELAY 10000
#define TEMP_LOG_FILE "temperature_log.txt"
#define FAN_GPIO 18
#define TURN_ON_TEMP 30
#define TURN_OFF_TEMP 28

static int i2c_fd = -1;
