        perror("gpiod_line_request_output");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR)) {
        perror("ioctl");
        return 1;
    }

    log_file = fopen(TEMP_LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    int fan_state = 0;
    while (1) {
        int object_temp = 0;
        int retries = MLX90614_RETRIES;
        while (retries--) {
            if (write(i2c_fd, &MLX90614_OBJECT_TEMP_REG, 1) == 1 &&
