        object_temp >>= 2;

        if (object_temp < TURN_OFF_TEMP)
            fan_state = 0;
        else if (object_temp > TURN_ON_TEMP)
            fan_state = 1;

        gpiod_line_set_value(fan_line, fan_state);

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, object_temp);
        fflush(log_file);

        sleep(2);
    }

    return 0;
}

