#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define SHT40_ADDR 0x70
#define SHT40_TRIGGER_T_MEASURE_HM 0x2400
#define SHT40_TRIGGER_RH_MEASURE_HM 0x2500
#define SHT40_CMD_SIZE 2
#define SHT40_DATA_SIZE 6
#define I2C_RETRIES 3
#define HTTP_PORT 8080

volatile sig_atomic_t stop = 0;
int i2c_file = -1;

void sig_handler(int signo) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    stop = 1;
}

int i2c_write_read(int file, const char *out, size_t out_len, char *in, size_t in_len) {
    int retries = I2C_RETRIES;
    while (retries--) {
        if (write(file, out, out_len) == out_len) {
            if (read(file, in, in_len) == in_len) {
                return 0;
            }
        }
        usleep(10000);
    }
    return -1;
}

int main() {
    struct sockaddr_in http_addr;
    int http_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (http_sock == -1) {
        perror("socket");
        return 1;
    }

    memset(&http_addr, 0, sizeof(http_addr));
    http_addr.sin_family = AF_INET;
    http_addr.sin_addr.s_addr = INADDR_ANY;
    http_addr.sin_port = htons(HTTP_PORT);

    if (bind(http_sock, (struct sockaddr *)&http_addr, sizeof(http_addr)) == -1) {
        perror("bind");
        return 1;
    }

    if (listen(http_sock, 5) == -1) {
        perror("listen");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SHT40_ADDR) == -1) {
        perror("ioctl");
        return 1;
    }

    char cmd[SHT40_CMD_SIZE], data[SHT40_DATA_SIZE];
    while (!stop) {
        cmd[0] = SHT40_TRIGGER_T_MEASURE_HM >> 8;
        cmd[1] = SHT40_TRIGGER_T_MEASURE_HM & 0xFF;
        if (i2c_write_read(i2c_file, cmd, SHT40_CMD_SIZE, data, SHT40_DATA_SIZE) == -1) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        int t = (data[0] << 8) | data[1];
        float temperature = -45 + 175 * t / 65535.0;

        cmd[0] = SHT40_TRIGGER_RH_MEASURE_HM >> 8;
        cmd[1] = SHT40_TRIGGER_RH_MEASURE_HM & 0xFF;
        if (i2c_write_read(i2c_file, cmd, SHT40_CMD_SIZE, data, SHT40_DATA_SIZE) == -1) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        int rh = (data[0] << 8) | data[1];
        float humidity = 100 * rh / 65535.0;
        if (humidity < 0) humidity = 0;
        else if (humidity > 100) humidity = 100;

        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(http_sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock == -1) {
            perror("accept");
            continue;
        }

        char response[128];
        snprintf(response, sizeof(response),
                 "HTTP/1.0 200 OK\r\nContent-Type: text/html\r\n\r\n"
                 "<html><body><p>Temperature: %.2f&deg;C</p><p>Humidity: %.2f%%</p></body></html>",
                 temperature, humidity);
        if (write(client_sock, response, strlen(response)) == -1) {
            perror("write");
        }

        close(client_sock);
    }

    close(i2c_file);
    return 0;
}

