#include <stdio.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define TMP102_ADDR 0x48
#define TMP102_TEMP_REG 0x00

int i2c_file_descriptor = -1;

void sigint_handler(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, TMP102_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_file_descriptor);
        return 1;
    }

    FILE *file = fopen("temperature_log.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        close(i2c_file_descriptor);
        return 1;
    }

    while (1) {
        uint8_t reg = TMP102_TEMP_REG;
        if (write(i2c_file_descriptor, &reg, sizeof(reg)) != sizeof(reg)) {
            fprintf(stderr, "Failed to write to TMP102: %s\n", strerror(errno));
            continue;
        }

        uint16_t temp;
        if (read(i2c_file_descriptor, &temp, sizeof(temp)) != sizeof(temp)) {
            fprintf(stderr, "Failed to read from TMP102: %s\n", strerror(errno));
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(file, "%s,%.2f\n", timestamp, (float)temp / 16.0);
        fflush(file);

        sleep(5);
    }

    fclose(file);
    close(i2c_file_descriptor);
    return 0;
}

