    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        close(i2c_file_descriptor);
        return 1;
    }

    while (1) {
        uint8_t reg = TMP102_TEMP_REG;
        if (write(i2c_file_descriptor, &reg, sizeof(reg)) != sizeof(reg)) {
            fprintf(stderr, "Failed to write to TMP102: %s\n", strerror(errno));
            continue;
        }

        uint16_t temp;
        if (read(i2c_file_descriptor, &temp, sizeof(temp)) != sizeof(temp)) {
            fprintf(stderr, "Failed to read from TMP102: %s\n", strerror(errno));
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(file, "%s,%.2f\n", timestamp, (float)temp / 16.0);
        fflush(file);

        sleep(5);
    }

    fclose(file);
    close(i2c_file_descriptor);
    return 0;
}
