#include <unistd.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define HDC2010_ADDR 0x3F
#define MEASUREMENT_CONFIG 0x02
#define MAX_RETRIES 5

volatile sig_atomic_t stop = 0;
int i2c_file_descriptor;

void signal_handler(int signum) {
    stop = 1;
    close(i2c_file_descriptor);
}

int i2c_write_read(int file, char *out, int out_len, char *in, int in_len) {
    int retries = 0;
    while (retries <= MAX_RETRIES) {
        if (write(file, out, out_len) == out_len) {
            if (read(file, in, in_len) == in_len) {
                return 0;
            }
        }
        retries++;
    }
    return -1;
}

int main() {
    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = SA_RESTART;
    sigaction(SIGINT, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, HDC2010_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    while (!stop) {
        char reg[1] = {MEASUREMENT_CONFIG};
        char data[1];
        if (i2c_write_read(i2c_file_descriptor, reg, 1, data, 1) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        if ((data[0] & 1) == 0) {
            char temp[2] = {0x00, 0x00};
            char hum[2] = {0x02, 0x00};
            if (i2c_write_read(i2c_file_descriptor, temp, 1, temp, 2) < 0 ||
                i2c_write_read(i2c_file_descriptor, hum, 1, hum, 2) < 0) {
                fprintf(stderr, "Failed to read temperature and humidity\n");
                continue;
            }

            float temperature = ((temp[0] << 8) | temp[1]) * 0.0625f;
            float humidity = ((hum[0] << 8) | hum[1]) * 0.03125f;
            printf("Temperature: %.2f C, Humidity: %.2f%%\n", temperature, humidity);
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

