#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c.h>

#define SDP800_I2C_ADDRESS 0x76
#define SDP800_I2C_BUS 1
#define SDP800_MEASUREMENT_DELAY 45000
#define SDP800_READ_DELAY 500000

static int i2c_file_descriptor = -1;

static void cleanup_and_exit(int signum) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    exit(signum);
}

static int calculate_crc8(const unsigned char *data, int length) {
    unsigned char crc = 0;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C bus");
        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    unsigned char buffer[6];
    while (1) {
        usleep(SDP800_MEASUREMENT_DELAY);

        if (write(i2c_file_descriptor, "\x00", 1) != 1) {
            perror("Failed to write to SDP800");
            cleanup_and_exit(-1);
        }

        usleep(SDP800_READ_DELAY);

        if (read(i2c_file_descriptor, buffer, 6) != 6) {
            perror("Failed to read from SDP800");
            cleanup_and_exit(-1);
        }

        int pressure_crc = calculate_crc8(buffer, 2);
        if (pressure_crc != buffer[2]) {
            fprintf(stderr, "Pressure CRC check failed\n");
            continue;
        }

        int temperature_crc = calculate_crc8(buffer + 3, 2);
        if (temperature_crc != buffer[5]) {
            fprintf(stderr, "Temperature CRC check failed\n");
            continue;
        }

        int pressure = (buffer[0] << 8) | buffer[1];
        int temperature = (buffer[3] << 8) | buffer[4];

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
    }

    cleanup_and_exit(0);
}

