int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <setpoint>\n", argv[0]);
        return -1;
    }

    float setpoint = atof(argv[1]);
    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    pwm_line = gpiod_chip_get_line(chip, GPIO_PWM);
    if (!pwm_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    if (gpiod_line_request_output(pwm_line, "heater", 0) ||
        gpiod_line_request_output(relay_line, "relay", 0)) {
        perror("gpiod_line_request_output");
        return -1;
    }

