            return -1;
        }

        float temp = atof(temp_str + 2) / 1000.0;
        dprintf(log_fd, "%ld,%.2f,%.2f,0,0\n", time(NULL), temp, setpoint);
        close(fd);
        sleep(5);
    }

    return 0;
}

