static int socket_file_descriptor;

static void cleanup_and_exit(int signum) {
    close(i2c_file_descriptor);
    close(socket_file_descriptor);
    syslog(LOG_INFO, "Shutdown gracefully");
    exit(0);
}

static int send_http_request(float humidity) {
    char buffer[1024];
    sprintf(buffer, "POST %s HTTP/1.1\r\n"
                    "Host: api.example.com\r\n"
                    "Content-Type: application/json\r\n"
                    "Content-Length: %d\r\n"
                    "\r\n"
                    "{\"humidity\":%.2f}",
            API_ENDPOINT, strlen(buffer), humidity);

    if (send(socket_file_descriptor, buffer, strlen(buffer), 0) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request");
        return -1;
    }

    return 0;
}

static float read_humidity() {
    unsigned char buffer[2];
    struct i2c_msg msgs[] = {
        {
            .addr = HTU21D_I2C_ADDR,
            .flags = 0,
            .len = 1,
            .buf = (char *)&HTU21D_READ_HUMIDITY_HOLD,
        },
        {
            .addr = HTU21D_I2C_ADDR,
            .flags = I2C_M_RD,
            .len = 2,
            .buf = buffer,
        },
    };

    if (i2c_file_descriptor < 0) {
        syslog(LOG_ERR, "I2C file descriptor not open");
        return -1;
    }

    if (i2c_smbus_read_byte_data(i2c_file_descriptor, HTU21D_READ_HUMIDITY_HOLD) < 0) {
        syslog(LOG_ERR, "Failed to read humidity");
        return -1;
    }

    return (float)((buffer[0] << 8 | buffer[1]) & 0xFFF) / 1024.0;
}

int main() {
    openlog("htu21d_reader", LOG_PERROR, LOG_USER);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, HTU21D_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address");
        return -1;
    }

    socket_file_descriptor = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_file_descriptor < 0) {
        syslog(LOG_ERR, "Failed to create socket");
        return -1;
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(80);
    inet_pton(AF_INET, "api.example.com", &server_address.sin_addr);

    if (connect(socket_file_descriptor, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server");
        return -1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        float humidity = read_humidity();
        if (humidity < 0) {
            syslog(LOG_ERR, "Failed to read humidity");
            return -1;
        }

        if (send_http_request(humidity) < 0) {
            syslog(LOG_ERR, "Failed to send HTTP request");
            return -1;
        }

        sleep(60);
    }

    return 0;
}

