#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_CONTROL 0xF4
#define BMP280_REG_PRESSURE 0xF7

static int i2c_file = -1;

static void exit_handler(int signum) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    int retries = 3;
    while (retries--) {
        i2c_file = open("/dev/i2c-1", O_RDWR);
        if (i2c_file < 0) {
            perror("Failed to open I2C device");
            continue;
        }

        if (ioctl(i2c_file, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
            perror("Failed to set I2C slave");
            close(i2c_file);
            i2c_file = -1;
            continue;
        }

        unsigned char buf[1] = { BMP280_REG_CHIP_ID };
        if (write(i2c_file, buf, 1) != 1) {
            perror("Failed to write to I2C device");
            close(i2c_file);
            i2c_file = -1;
            continue;
        }

        unsigned char chip_id;
        if (read(i2c_file, &chip_id, 1) != 1) {
            perror("Failed to read from I2C device");
            close(i2c_file);
            i2c_file = -1;
            continue;
        }

        if (chip_id != BMP280_CHIP_ID) {
            fprintf(stderr, "Unexpected chip ID: 0x%02x\n", chip_id);
            close(i2c_file);
            i2c_file = -1;
            continue;
        }

        break;
    }

    if (i2c_file == -1) {
        fprintf(stderr, "Failed to initialize I2C device\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit_handler(EXIT_FAILURE);
    }

    unsigned char buf[2] = { BMP280_REG_CONTROL, 0x34 };
    if (write(i2c_file, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        exit_handler(EXIT_FAILURE);
    }

    while (1) {
        usleep(10000);

        unsigned char pressure_buf[3];
        if (read(i2c_file, &pressure_buf, 3) != 3) {
            perror("Failed to read from I2C device");
            exit_handler(EXIT_FAILURE);
        }

        int32_t raw_pressure = (pressure_buf[0] << 12) | (pressure_buf[1] << 4) | (pressure_buf[2] >> 4);
        double pressure = raw_pressure * 0.00001;

        if (pressure > 1020.0 || pressure < 980.0) {
            time_t now = time(NULL);
            struct tm *local_time = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

            fprintf(log_file, "%s: %.2f hPa\n", timestamp, pressure);
            fflush(log_file);
        }
    }

    return EXIT_SUCCESS;
}

