        gpiod_line_set_value(motor_ena_line, 0);
    if (chip)
        gpiod_chip_close(chip);
    printf("%s: Motor stopped and GPIO lines released.\n", asctime(localtime(&sig)));
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("%s: Failed to open GPIO chip.\n", asctime(localtime(NULL)));
        return 1;
    }

    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_GPIO);
