    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_GPIO);
    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_GPIO);

    if (!rain_sensor_line || !motor_ena_line || !motor_in1_line || !motor_in2_line) {
        printf("%s: Failed to get GPIO lines.\n", asctime(localtime(NULL)));
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor")) {
        printf("%s: Failed to request input for rain sensor.\n", asctime(localtime(NULL)));
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(motor_ena_line, "motor_ena", 0)) {
        printf("%s: Failed to request output for motor ENA.\n", asctime(localtime(NULL)));
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0)) {
        printf("%s: Failed to request output for motor IN1.\n", asctime(localtime(NULL)));
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0)) {
        printf("%s: Failed to request output for motor IN2.\n", asctime(localtime(NULL)));
        cleanup_and_exit(0);
        return 1;
    }

    while (1) {
        int value = gpiod_line_get_value(rain_sensor_line);
        if (value < 0) {
            printf("%s: Failed to get value for rain sensor.\n", asctime(localtime(NULL)));
            cleanup_and_exit(0);
            return 1;
        }

        if (value == 1) {
            printf("%s: Rain detected, starting motor.\n", asctime(localtime(NULL)));
            gpiod_line_set_value(motor_ena_line, 1);
            gpiod_line_set_value(motor_in1_line, 1);
            gpiod_line_set_value(motor_in2_line, 0);
            sleep(MOTOR_DURATION_SEC);
            printf("%s: Stopping motor.\n", asctime(localtime(NULL)));
            gpiod_line_set_value(motor_ena_line, 0);
        }

        sleep(SLEEP_TIME_SEC);
    }

    return 0;
}

