#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <bcm2835.h>

#define BMP280_ADDR 0x76
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_MSB 0xF7

static int i2c_handle = -1;
static int udp_handle = -1;

static void cleanup(int signum) {
    if (i2c_handle != -1) {
        bcm2835_i2c_device_delete(i2c_handle);
    }
    if (udp_handle != -1) {
        close(udp_handle);
    }
    bcm2835_close();
    exit(signum);
}

int main(void) {
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = bcm2835_i2c_bare_device_create(BMP280_ADDR);
    if (i2c_handle == -1) {
        fprintf(stderr, "bcm2835_i2c_bare_device_create failed\n");
        cleanup(-1);
    }

    udp_handle = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_handle == -1) {
        fprintf(stderr, "socket failed\n");
        cleanup(-1);
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(5000);
    if (inet_aton("192.168.1.100", &addr.sin_addr) == 0) {
        fprintf(stderr, "inet_aton failed\n");
        cleanup(-1);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    char buf[16];
    while (1) {
        bcm2835_i2c_write_reg(i2c_handle, BMP280_REG_TEMP_XLSB);
        uint8_t temp[3];
        if (bcm2835_i2c_read(temp, 3) != 3) {
            fprintf(stderr, "bcm2835_i2c_read failed\n");
            cleanup(-1);
        }

        bcm2835_i2c_write_reg(i2c_handle, BMP280_REG_PRESS_XLSB);
        uint8_t press[3];
        if (bcm2835_i2c_read(press, 3) != 3) {
            fprintf(stderr, "bcm2835_i2c_read failed\n");
            cleanup(-1);
        }

        int32_t temperature = ((temp[0] << 12) | (temp[1] << 4) | (temp[2] >> 4));
        int32_t pressure = ((press[0] << 12) | (press[1] << 4) | (press[2] >> 4));

        snprintf(buf, sizeof(buf), "{\"temp\":%ld,\"press\":%ld}", temperature, pressure);
        if (sendto(udp_handle, buf, strlen(buf), 0, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
            fprintf(stderr, "sendto failed\n");
            cleanup(-1);
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

