#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <spi0.h>

#define SPI_CHANNEL 0
#define SPI_FREQUENCY 500000
#define SPI_MODE 0
#define SPI_CS_GPIO 8
#define FAN_GPIO 18
#define FAN_FREQUENCY 1000
#define FAN_DUTY_CYCLE_MAX 255
#define CIRCULAR_BUFFER_SIZE 20

struct circular_buffer {
    struct timespec timestamp[CIRCULAR_BUFFER_SIZE];
    float temperature[CIRCULAR_BUFFER_SIZE];
    int duty_cycle[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
};

struct spi_device *spi;
struct gpiod_chip *chip;
struct gpiod_line *fan_line;
struct circular_buffer buffer;

void print_buffer(void) {
    int i = buffer.tail;
    while (i != buffer.head) {
        printf("%ld.%.9ld %.2f %d\n", buffer.timestamp[i].tv_sec, buffer.timestamp[i].tv_nsec, buffer.temperature[i], buffer.duty_cycle[i]);
        i = (i + 1) % CIRCULAR_BUFFER_SIZE;
    }
}

void sigint_handler(int signum) {
    gpiod_line_set_value(fan_line, 0);
    spi_close(spi);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    print_buffer();
    spi_exit();
    exit(0);
}

int main(void) {
    signal(SIGINT, sigint_handler);

    spi_init();
    spi = spi_open(SPI_CHANNEL, SPI_FREQUENCY, SPI_MODE);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(1);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        fprintf(stderr, "Failed to get fan GPIO line\n");
        exit(1);
    }

    if (gpiod_line_request_pwm_output(fan_line, "fan", FAN_FREQUENCY, 0)) {
        fprintf(stderr, "Failed to request fan GPIO line as PWM output\n");
        exit(1);
    }

    while (1) {
        float temperature;
        if (spi_read_max31855(spi, SPI_CS_GPIO, &temperature)) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        int duty_cycle;
        if (temperature < 25) {
            duty_cycle = 0;
        } else if (temperature < 40) {
            duty_cycle = (temperature - 25) / 15 * 50;
        } else if (temperature < 60) {
            duty_cycle = 50 + (temperature - 40) / 20 * 150;
        } else {
            duty_cycle = FAN_DUTY_CYCLE_MAX;
        }

        clock_gettime(CLOCK_REALTIME, &buffer.timestamp[buffer.head]);
        buffer.temperature[buffer.head] = temperature;
        buffer.duty_cycle[buffer.head] = duty_cycle;
        buffer.head = (buffer.head + 1) % CIRCULAR_BUFFER_SIZE;
        if (buffer.head == buffer.tail) {
            buffer.tail = (buffer.tail + 1) % CIRCULAR_BUFFER_SIZE;
        }

        gpiod_line_set_pwm_duty_cycle(fan_line, duty_cycle);
        sleep(1);
    }

    return 0;
}

