#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CAL 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_DATA 0xF6
#define BMP180_OSS 3

#define GPIO2 2

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_fd != -1)
        close(i2c_fd);
    if (log_file)
        fclose(log_file);
    exit(sig);
}

int main() {
    int ret;
    struct gpiod_line_request gpio_req;
    unsigned char buf[2];

    signal(SIGINT, cleanup_and_exit);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open i2c");
        cleanup_and_exit(-1);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR);
    if (ret == -1) {
        perror("set i2c slave");
        cleanup_and_exit(-1);
    }

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpio_chip) {
        perror("open gpio chip");
        cleanup_and_exit(-1);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO2);
    if (!gpio_line) {
        perror("get gpio line");
        cleanup_and_exit(-1);
    }

    gpio_req.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP | GPIOD_LINE_REQUEST_FLAG_EDGE_FALLING;
    gpio_req.consumer = "bmp180_interrupt";
    gpio_req.request_type = GPIOD_LINE_REQUEST_EVENT_RISING;
    gpio_req.data = NULL;

    ret = gpiod_line_request_event(gpio_line, &gpio_req);
    if (ret) {
        perror("request gpio event");
        cleanup_and_exit(-1);
    }

    log_file = fopen("altitude_log.txt", "w");
    if (!log_file) {
        perror("open log file");
        cleanup_and_exit(-1);
    }

    buf[0] = BMP180_REG_CAL;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        perror("write i2c");
        cleanup_and_exit(-1);
    }

    buf[0] = BMP180_REG_CONTROL;
    buf[1] = BMP180_OSS;
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("write i2c");
        cleanup_and_exit(-1);
    }

    while (1) {
        struct gpiod_line_event event;
        struct timespec ts;
        int temperature, pressure;

        ret = gpiod_line_event_wait(gpio_line, NULL);
        if (ret < 0) {
            perror("wait gpio event");
            cleanup_and_exit(-1);
        }

        ret = gpiod_line_event_read(gpio_line, &event);
        if (ret < 0) {
            perror("read gpio event");
            cleanup_and_exit(-1);
        }

        clock_gettime(CLOCK_REALTIME, &ts);

        buf[0] = BMP180_REG_DATA;
        ret = write(i2c_fd, buf, 1);
        if (ret != 1) {
            perror("write i2c");
            cleanup_and_exit(-1);
        }

        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("read i2c");
            cleanup_and_exit(-1);
        }

        temperature = (buf[0] << 8) | buf[1];

        buf[0] = BMP180_REG_DATA + 2;
        ret = write(i2c_fd, buf, 1);
        if (ret != 1) {
            perror("write i2c");
            cleanup_and_exit(-1);
        }

        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("read i2c");
            cleanup_and_exit(-1);
        }

        pressure = (buf[0] << 8) | buf[1];

        fprintf(log_file, "%ld,%d,%d\n", ts.tv_sec, temperature, pressure);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

