#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CS_PIN 8

#define MAX31865_CONFIG_REG_VALUE 0x00000000
#define MAX31865_FAULT_REG_ADDR 0x00000002

static int spi_fd = -1;
static FILE* log_file = NULL;

void cleanup_and_exit(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    int ret;
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BAUD_RATE, &SPI_SPEED);
    if (ret != 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &CS_PIN);
    if (ret != 0) {
        fprintf(stderr, "Failed to set CS pin: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    log_file = fopen("rtd_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    uint32_t config_reg_value = MAX31865_CONFIG_REG_VALUE;
    uint32_t fault_reg_value;
    uint32_t temp_reg_value;
    while (1) {
        ret = write(spi_fd, &config_reg_value, sizeof(config_reg_value));
        if (ret != sizeof(config_reg_value)) {
            fprintf(stderr, "Failed to write to SPI device: %s\n", strerror(errno));
            cleanup_and_exit(1);
        }

        ret = read(spi_fd, &fault_reg_value, sizeof(fault_reg_value));
        if (ret != sizeof(fault_reg_value)) {
            fprintf(stderr, "Failed to read fault register: %s\n", strerror(errno));
            cleanup_and_exit(1);
        }

        if (fault_reg_value != 0) {
            fprintf(stderr, "Sensor fault detected: 0x%08X\n", fault_reg_value);
            cleanup_and_exit(1);
        }

        ret = read(spi_fd, &temp_reg_value, sizeof(temp_reg_value));
        if (ret != sizeof(temp_reg_value)) {
            fprintf(stderr, "Failed to read temperature register: %s\n", strerror(errno));
            cleanup_and_exit(1);
        }

        double temp_c = ((double)temp_reg_value * 0.0625) - 273.15;
        time_t now = time(NULL);
        struct tm* now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s, %.2f\n", timestamp, temp_c);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

