#define BMP180_ADDR 0x77
#define BMP180_CAL_REG 0xAA
#define BMP180_CONTROL 0xF4
#define BMP180_TEMP_DATA 0xF6
#define BMP180_PRESS_DATA 0xF6
#define BMP180_OS_0 0

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup_and_exit(int sig) {
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    exit(sig);
}

static void handle_error(const char *msg) {
    perror(msg);
    cleanup_and_exit(-1);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0)
        handle_error("Failed to open I2C device");

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0)
        handle_error("Failed to set I2C slave address");

    uint16_t cal_data;
    if (read(i2c_fd, &cal_data, sizeof(cal_data)) != sizeof(cal_data))
        handle_error("Failed to read calibration data");

    if (cal_data == 0xFFFF)
        handle_error("Invalid calibration data");

    if (write(i2c_fd, &BMP180_OS_0, sizeof(BMP180_OS_0)) != sizeof(BMP180_OS_0))
        handle_error("Failed to set oversampling rate");

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835.0");
    if (!chip)
        handle_error("Failed to open GPIO chip");

    line = gpiod_chip_get_line(chip, 18);
    if (!line)
        handle_error("Failed to get GPIO line");

    if (gpiod_line_request_rising_edge_events(line) < 0)
        handle_error("Failed to request GPIO event");

    FILE *fp = fopen("bmp180_log.txt", "w");
    if (!fp)
        handle_error("Failed to open log file");

    while (1) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, NULL) < 0)
            handle_error("Failed to wait for GPIO event");

        if (gpiod_line_event_read(line, &event) < 0)
            handle_error("Failed to read GPIO event");

        uint16_t temp_data, press_data;
        if (read(i2c_fd, &temp_data, sizeof(temp_data)) != sizeof(temp_data))
            handle_error("Failed to read temperature data");

        if (read(i2c_fd, &press_data, sizeof(press_data)) != sizeof(press_data))
            handle_error("Failed to read pressure data");

        fprintf(fp, "Temperature: %d C, Pressure: %d Pa\n", temp_data, press_data);
        fflush(fp);
    }

    fclose(fp);
    cleanup_and_exit(0);
}

