#define PWM_PERIOD 40000000L  /* 25kHz */
#define PWM_CHANNEL 0
#define GPIO_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *line;
int pwm_fd;
FILE *log_file;

void cleanup_and_exit(int signum) {
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (pwm_fd >= 0)
        close(pwm_fd);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    struct pwm_args {
        struct pwm_device *pwm;
        struct pwm_config config;
    } pwm_args;

    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_pwm_output(line, "fan_pwm", 0)) {
        fprintf(stderr, "Failed to request PWM output: %s\n", strerror(errno));
        return 1;
    }

    pwm_fd = open("/dev/pwm", O_RDWR);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to open PWM device: %s\n", strerror(errno));
        return 1;
    }

    pwm_args.pwm = pwm_get(pwm_fd, PWM_CHANNEL);
    if (!pwm_args.pwm) {
        fprintf(stderr, "Failed to get PWM device: %s\n", strerror(errno));
        return 1;
    }

    pwm_args.config.period = PWM_PERIOD;

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int temp;
        FILE *temp_file = fopen(TEMP_FILE, "r");
        if (!temp_file) {
            fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
            return 1;
        }

        if (fscanf(temp_file, "%d", &temp) != 1) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            return 1;
        }

        fclose(temp_file);

        if (temp < 40000)
            temp = 40000;
        else if (temp > 70000)
            temp = 70000;

        pwm_args.config.duty_cycle = (temp - 40000) * (PWM_PERIOD / 30000);
        if (pwm_config(pwm_args.pwm, &pwm_args.config)) {
            fprintf(stderr, "Failed to configure PWM: %s\n", strerror(errno));
            return 1;
        }

        if (pwm_enable(pwm_args.pwm)) {
            fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
            return 1;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d, %ld\n", timestamp, temp, pwm_args.config.duty_cycle);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

