#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x48
#define BUF_SIZE 60
#define ALERT_TEMP 280

int i2c_fd;
float buf[BUF_SIZE];
int buf_idx = 0;
float avg = 0;
sem_t mutex;
int gpio_line;

void init_i2c(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void init_gpio(void) {
    int ret;

    ret = gpiod_line_request_output(gpio_line, "alert_led", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
}

void *alert_thread(void *arg) {
    while (1) {
        sem_wait(&mutex);
        if (avg > ALERT_TEMP)
            gpiod_line_set_value(gpio_line, 1);
        else
            gpiod_line_set_value(gpio_line, 0);
        sem_post(&mutex);
        sleep(1);
    }

    return NULL;
}

int main(void) {
    pthread_t thread;
    int ret, i;
    float temp;

    init_i2c();
    init_gpio();

    sem_init(&mutex, 0, 1);
    pthread_create(&thread, NULL, alert_thread, NULL);

    while (1) {
        ret = read(i2c_fd, &temp, sizeof(temp));
        if (ret < 0) {
            perror("Failed to read temperature");
            continue;
        }

        sem_wait(&mutex);
        buf[buf_idx] = temp;
        buf_idx = (buf_idx + 1) % BUF_SIZE;
        avg = 0;
        for (i = 0; i < BUF_SIZE; i++)
            avg += buf[i];
        avg /= BUF_SIZE;
        sem_post(&mutex);
    }

    pthread_cancel(thread);
    gpiod_line_release(gpio_line);
    close(i2c_fd);
    sem_destroy(&mutex);

    return 0;
}

