#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c.h>

#define BMP180_ADDR 0x77
#define BMP180_CAL_START 0xAA
#define BMP180_CAL_END 0xBF
#define BMP180_CONTROL 0xF4
#define BMP180_TEMPDATA 0xF6
#define BMP180_PRESSUREDATA 0xF6
#define BMP180_CONVERSION_TIME 5

#define GPIO_INT 27

struct bmp180_calibration_data {
    int16_t AC1, AC2, AC3;
    uint16_t AC4, AC5, AC6;
    int16_t B1, B2;
    int8_t MB, MC, MD;
};

struct bmp180_data {
    int i2c_fd;
    struct gpiod_chip *gpio_chip;
    struct gpiod_line *gpio_line;
    struct bmp180_calibration_data cal;
    FILE *log_file;
    int logging;
};

static void bmp180_close(struct bmp180_data *data)
{
    if (data->log_file)
        fclose(data->log_file);
    if (data->gpio_line)
        gpiod_line_release(data->gpio_line);
    if (data->gpio_chip)
        gpiod_chip_close(data->gpio_chip);
    if (data->i2c_fd >= 0)
        close(data->i2c_fd);
    free(data);
}

static void bmp180_log_pressure(struct bmp180_data *data, int pressure)
{
    if (!data->logging)
        return;
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    fprintf(data->log_file, "%04d-%02d-%02d %02d:%02d:%02d %d\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, pressure);
    fflush(data->log_file);
}

static void bmp180_handle_interrupt(struct bmp180_data *data)
{
    gpiod_line_update(data->gpio_line);
    enum gpiod_line_value value = gpiod_line_get_value(data->gpio_line);
    if (value == GPIOD_LINE_VALUE_ACTIVE) {
        data->logging = !data->logging;
        if (data->logging) {
            data->log_file = fopen("pressure_log.txt", "a");
            if (!data->log_file) {
                perror("fopen");
                data->logging = 0;
            }
        } else {
            fclose(data->log_file);
            data->log_file = NULL;
        }
    }
}

static void bmp180_read_calibration_data(struct bmp180_data *data)
{
    struct bmp180_calibration_data *cal = &data->cal;
    uint8_t addr[2] = {BMP180_CAL_START, 0};
    if (write(data->i2c_fd, addr, 2) != 2) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    if (read(data->i2c_fd, (uint8_t *)cal, sizeof(*cal)) != sizeof(*cal)) {
        perror("read");
        exit(EXIT_FAILURE);
    }
}

static void bmp180_read_pressure(struct bmp180_data *data)
{
    uint8_t cmd = 0x34;
    if (write(data->i2c_fd, &cmd, 1) != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    usleep(BMP180_CONVERSION_TIME * 1000);
    uint8_t buf[3];
    if (read(data->i2c_fd, buf, 3) != 3) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    int32_t raw_pressure = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    int32_t pressure = (raw_pressure * data->cal.AC5 - 128) / 256;
    bmp180_log_pressure(data, pressure);
}

static void bmp180_main_loop(struct bmp180_data *data)
{
    while (1) {
        bmp180_read_pressure(data);
        usleep(2000000);
        bmp180_handle_interrupt(data);
    }
}

static void bmp180_init(struct bmp180_data *data)
{
    data->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (data->i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(data->i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    bmp180_read_calibration_data(data);
    data->gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!data->gpio_chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }
    data->gpio_line = gpiod_chip_get_line(data->gpio_chip, GPIO_INT);
    if (!data->gpio_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_falling_edge_events(data->gpio_line) < 0) {
        perror("gpiod_line_request_falling_edge_events");
        exit(EXIT_FAILURE);
    }
}

static void bmp180_signal_handler(int signum)
{
    bmp180_close(data);
    exit(EXIT_SUCCESS);
}

int main()
{
    struct bmp180_data *data = calloc(1, sizeof(*data));
    bmp180_init(data);
    struct sigaction action;
    action.sa_handler = bmp180_signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);
    bmp180_main_loop(data);
    bmp180_close(data);
    return 0;
}
