    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red = gpiod_chip_get_line(chip, 17);
    green = gpiod_chip_get_line(chip, 18);
    blue = gpiod_chip_get_line(chip, 27);
    if (!red || !green || !blue) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_pwm_output(red, "red", PWM_FREQ) ||
        gpiod_line_request_pwm_output(green, "green", PWM_FREQ) ||
        gpiod_line_request_pwm_output(blue, "blue", PWM_FREQ)) {
        perror("gpiod_line_request_pwm_output");
        return EXIT_FAILURE;
    }

    temp_file = fopen(TEMP_FILE, "r");
    if (!temp_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    while (!stop) {
        int temp, ret;
        if (fscanf(temp_file, "%d", &temp) != 1 || ferror(temp_file)) {
            clearerr(temp_file);
            printf("Failed to read temperature\n");
            continue;
