        if (temp < 40000) {
            ret = gpiod_line_set_pwm_duty_cycle(blue, PWM_DUTY_OFF);
        } else if (temp < 60000) {
            ret = gpiod_line_set_pwm_duty_cycle(green, PWM_DUTY_OFF);
