    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, void *stream) {
    (void)ptr;
    (void)stream;
    return size * nmemb;
}

int main(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "dht22", 1)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    CURL *curl;
    CURLcode res;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    for (int i = 0; i < MAX_TRIES; i++) {
        gpiod_line_set_value(line, 0);
        usleep(2000);
        gpiod_line_set_value(line, 1);
        usleep(50000);

        if (gpiod_line_get_value(line) == 0) {
            fprintf(stderr, "DHT22 not responding\n");
            continue;
        }

        char payload[100];
        sprintf(payload, "{\"temperature\": %d, \"humidity\": %d}", rand() % 100, rand() % 100); // replace with actual sensor reading

        curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "cURL Error: %s\n", curl_easy_strerror(res));
            continue;
        }

        cleanup();
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return EXIT_SUCCESS;
    }

    cleanup();
    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return EXIT_FAILURE;
}

