#define BMP180_REG_DATA 0xF6
#define BMP180_OSS 3

#define GPIO_PIN 4
#define GPIO_EDGE GPIOD_EDGE_FALLING
#define DEBOUNCE_TICKS 200000

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_file;
static FILE *log_file;
static volatile sig_atomic_t stop;

static void close_resources(void) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_file);
    if (log_file)
        fclose(log_file);
}

static void handle_interrupt(int signum) {
    stop = 1;
    close_resources();
    exit(0);
}

static int read_calibration_data(int *data) {
    unsigned char buffer[22];
    int rc = ioctl(i2c_file, I2C_RDWR, buffer);
    if (rc < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    // TODO: Parse and check the data.
    return 0;
}

static int read_pressure(int *pressure) {
    unsigned char buffer[2];
    int rc = ioctl(i2c_file, I2C_RDWR, buffer);
    if (rc < 0) {
        fprintf(stderr, "Failed to read pressure: %s\n", strerror(errno));
        return -1;
    }
    *pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main(void) {
    struct gpiod_line_request req = {
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
        .request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE,
        .consumer_label = "bmp180_logger",
    };

    struct sigaction action = {
        .sa_handler = handle_interrupt,
        .sa_flags = SA_RESTART,
    };

    struct i2c_rdwr_ioctl_data msg = {
        .msgs = (struct i2c_msg[]) {
            {
                .addr = BMP180_I2C_ADDR,
                .flags = I2C_M_RD,
                .len = 22,
                .buf = (unsigned char[]) { BMP180_REG_CAL },
            },
            {
                .addr = BMP180_I2C_ADDR,
                .flags = I2C_M_RD,
                .len = 2,
                .buf = (unsigned char[]) { BMP180_REG_DATA },
            },
        },
        .nmsgs = 2,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_event(line, &req)) {
        fprintf(stderr, "Failed to request GPIO event: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file, I2C_SLAVE, BMP180_I2C_ADDR)) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (read_calibration_data(NULL))
        return EXIT_FAILURE;

    if (sigaction(SIGINT, &action, NULL)) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (!stop) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, NULL)) {
            fprintf(stderr, "Failed to wait for GPIO event: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
        if (gpiod_line_event_read(line, &event)) {
            fprintf(stderr, "Failed to read GPIO event: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Debounce.
            if (gpiod_line_event_wait_with_timeout(line, &event, DEBOUNCE_TICKS)) {
                fprintf(stderr, "Failed to wait for GPIO event: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                log_file = fopen("pressure_log.txt", "a");
                if (!log_file) {
                    fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
                    return EXIT_FAILURE;
                }
                printf("Logging enabled.\n");
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Debounce.
            if (gpiod_line_event_wait_with_timeout(line, &event, DEBOUNCE_TICKS)) {
                fprintf(stderr, "Failed to wait for GPIO event: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                fclose(log_file);
                log_file = NULL;
                printf("Logging disabled.\n");
            }
        }
    }

    return EXIT_SUCCESS;
}

