int main(void) {
    int ret, tries = 0;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    openlog("dht22", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %m");
        exit(1);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        ret = gpiod_line_request_rising_edge_events(line, "dht22");
        if (ret < 0) {
            if (tries++ < MAX_TRIES) {
                syslog(LOG_ERR, "Failed to request rising edge events: %m");
                sleep(2);
                continue;
            } else {
                syslog(LOG_ERR, "Too many failures, exiting.");
                exit(1);
            }
        }

        /* Read the sensor here and log the data */

        gpiod_line_release(line);
        sleep(10);
    }

    return 0;
}

