#include <sys/stat.h>
#include <time.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

int max_fan_state = 3;
int current_fan_state = -1;
int should_exit = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        should_exit = 1;
    }
}

void log_fan_state_change(int new_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s - Fan state changed to %d\n", timestamp, new_state);
    fclose(log_file);
}

int read_temp() {
    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (temp_file == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    int temp;
    if (fscanf(temp_file, "%d", &temp) != 1) {
        perror("Failed to read temperature");
        fclose(temp_file);
        return -1;
    }

    fclose(temp_file);
    return temp / 1000;
}

int read_fan_state() {
    FILE *fan_state_file = fopen(FAN_STATE_FILE, "r");
    if (fan_state_file == NULL) {
        perror("Failed to open fan state file");
        return -1;
    }

    int state;
    if (fscanf(fan_state_file, "%d", &state) != 1) {
        perror("Failed to read fan state");
        fclose(fan_state_file);
        return -1;
    }

    fclose(fan_state_file);
    return state;
}

void write_fan_state(int state) {
    FILE *fan_state_file = fopen(FAN_STATE_FILE, "w");
    if (fan_state_file == NULL) {
        perror("Failed to open fan state file for writing");
        return;
    }

    if (fprintf(fan_state_file, "%d", state) < 0) {
        perror("Failed to write fan state");
    }

    fclose(fan_state_file);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int max_state_file = open(MAX_STATE_FILE, O_RDONLY);
    if (max_state_file < 0) {
        perror("Failed to open max state file");
        return 1;
    }

    char max_state_str[2];
    if (read(max_state_file, max_state_str, 1) != 1) {
        perror("Failed to read max state");
        close(max_state_file);
        return 1;
    }

    max_fan_state = max_state_str[0] - '0';
    close(max_state_file);

    while (!should_exit) {
        int temp = read_temp();
        if (temp < 0) {
            continue;
        }

        int new_state;
        if (temp < 45) {
            new_state = 0;
        } else if (temp < 55) {
            new_state = 1;
        } else if (temp < 65) {
            new_state = 2;
        } else {
            new_state = max_fan_state;
        }

        if (new_state != current_fan_state) {
            write_fan_state(new_state);
            current_fan_state = new_state;
            log_fan_state_change(new_state);
        }

        sleep(5);
    }

    write_fan_state(0);
    log_fan_state_change(0);

    return 0;
}

