#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 100
#define TARGET_TEMP 50.0
#define FAILSAFE_TEMP_HIGH 100.0
#define FAILSAFE_TEMP_LOW 0.0

#define KP 1.0
#define KI 0.1
#define KD 0.01

struct pid_control {
    double Kp;
    double Ki;
    double Kd;
    double error;
    double integral;
    double derivative;
    double output;
};

struct app_data {
    struct spi_device *spi;
    struct gpiod_chip *gpiod;
    struct gpiod_line *pwm_line;
    struct gpiod_line *thermocouple_line;
    struct pid_control pid;
    FILE *log_file;
};

void sig_handler(int signo) {
    struct app_data *app = &app_data;

    fprintf(app->log_file, "Signal received, shutting down...\n");

    // Turn off the heater
    gpiod_line_set_value(app->pwm_line, 0);

    // Close the SPI interface
    spi_close(app->spi);

    // Close the log file
    fclose(app->log_file);

    exit(0);
}

void pid_init(struct pid_control *pid, double Kp, double Ki, double Kd) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->error = 0.0;
    pid->integral = 0.0;
    pid->derivative = 0.0;
    pid->output = 0.0;
}

double pid_compute(struct pid_control *pid, double setpoint, double measurement, double dt) {
    pid->error = setpoint - measurement;
    pid->integral += pid->error * dt;
    pid->derivative = (pid->error - pid->error_prev) / dt;
    pid->output = pid->Kp * pid->error + pid->Ki * pid->integral + pid->Kd * pid->derivative;
    pid->error_prev = pid->error;
    return pid->output;
}

int main() {
    struct app_data app;
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    double temp, pwm_duty_cycle, pid_output;
    struct timespec ts;
    int ret;

    // Open the SPI device
    app.spi = spi_open_device(SPI_DEVICE, SPI_MODE, SPI_MAX_SPEED_HZ, SPI_BITS_PER_WORD);
    if (!app.spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Open the GPIO chip
    app.gpiod = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!app.gpiod) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the PWM line
    app.pwm_line = gpiod_chip_get_line(app.gpiod, GPIO_PWM);
    if (!app.pwm_line) {
        fprintf(stderr, "Failed to get PWM line: %s\n", strerror(errno));
        return 1;
    }

    // Request the thermocouple line
    app.thermocouple_line = gpiod_chip_get_line(app.gpiod, GPIO_THERMOCOUPLE);
    if (!app.thermocouple_line) {
        fprintf(stderr, "Failed to get thermocouple line: %s\n", strerror(errno));
        return 1;
    }

