            gpiod_line_set_value(app.pwm_line, 0);
            pid_init(&app.pid, KP, KI, KD);
            continue;
        }

        // Convert the temperature
        temp = ((rx_buf[1] << 8) | rx_buf[2]) * 0.0625;

        // Check for failsafe conditions
        if (temp > FAILSAFE_TEMP_HIGH || temp < FAILSAFE_TEMP_LOW) {
            fprintf(app.log_file, "Failsafe condition detected: %s\n", temp > FAILSAFE_TEMP_HIGH ? "temperature too high" : "temperature too low");
            // Disable the heater and reset the PID state
            gpiod_line_set_value(app.pwm_line, 0);
            pid_init(&app.pid, KP, KI, KD);
            continue;
        }

        // Compute the PID output
        pid_output = pid_compute(&app.pid, TARGET_TEMP, temp, 1.0);

        // Clamp the PID output to the PWM duty cycle range
        pwm_duty_cycle = pid_output < PWM_DUTY_CYCLE_MIN ? PWM_DUTY_CYCLE_MIN : (pid_output > PWM_DUTY_CYCLE_MAX ? PWM_DUTY_CYCLE_MAX : pid_output);

        // Set the PWM duty cycle
        gpiod_line_set_value(app.pwm_line, pwm_duty_cycle);

        // Log the temperature, PWM duty cycle, and PID output
        fprintf(app.log_file, "%f, %f, %f\n", temp, pwm_duty_cycle, pid_output);

        // Sleep for 1 second
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return 0;
}

