        printf("Error opening GPIO chip\n");
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (pwm_line == NULL) {
        printf("Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_pwm_mode(pwm_line, NULL) < 0) {
        printf("Error setting PWM mode\n");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    pwm_duty_cycle = PWM_DUTY_CYCLE_MIN;
    if (gpiod_line_set_pwm(pwm_line, PWM_FREQ, pwm_duty_cycle) < 0) {
        printf("Error setting PWM frequency and duty cycle\n");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (!should_exit) {
        int temp = /* read CPU temperature here */;
        if (temp < TEMP_LOW)
            pwm_duty_cycle = PWM_DUTY_CYCLE_MIN;
        else if (temp > TEMP_HIGH)
            pwm_duty_cycle = PWM_DUTY_CYCLE_MAX;
        else
            pwm_duty_cycle = (temp - TEMP_LOW) * (PWM_DUTY_CYCLE_MAX - PWM_DUTY_CYCLE_MIN) / (TEMP_HIGH - TEMP_LOW) + PWM_DUTY_CYCLE_MIN;

        if (gpiod_line_set_pwm(pwm_line, PWM_FREQ, pwm_duty_cycle) < 0)
