    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line_a = gpiod_chip_get_line(chip, GPIO_A);
    if (!line_a) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (!line_b) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_input(line_a, "encoder_a")) {
        perror("gpiod_line_request_input");
        return 1;
    }

    if (gpiod_line_request_input(line_b, "encoder_b")) {
        perror("gpiod_line_request_input");
        return 1;
    }

    log_file = fopen("encoder_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        int val_a = gpiod_line_get_value(line_a);
        int val_b = gpiod_line_get_value(line_b);

        int new_state = (val_b << 1) | val_a;

        if (new_state != state) {
            state = new_state;

            switch (state) {
            case 0b00: position += 1.0; break;
            case 0b01: position += 1.0; break;
            case 0b10: position -= 1.0; break;
            case 0b11: position -= 1.0; break;
            }

            if (position < 0.0) position += 360.0;
            if (position >= 360.0) position -= 360.0;

            time_t t = time(NULL);
            struct tm *tmp = localtime(&t);
            char buffer[15];
            strftime(buffer, 15, "%H:%M:%S", tmp);

            fprintf(log_file, "%s, %.2f\n", buffer, position);
        }
    }

    return 0;
}

