#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define ADPD144RI_I2C_ADDR 0x20
#define ADPD144RI_I2C_DEV  "/dev/i2c-1"
#define ADPD144RI_LED_GPIO 17
#define ADPD144RI_IR_THRESHOLD 2000

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (led_line)
        gpiod_line_release(led_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_fd != -1)
        close(i2c_fd);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main(void) {
    int ret;
    uint16_t red, ir;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    i2c_fd = open(ADPD144RI_I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_I2C_ADDR);
    if (ret == -1) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(gpio_chip, ADPD144RI_LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "adpd144ri_led", 0);
    if (ret) {
        perror("Failed to request GPIO line as output");
        return EXIT_FAILURE;
    }

    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,red,ir\n");

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        ret = read(i2c_fd, &red, sizeof(red));
        if (ret != sizeof(red)) {
            perror("Failed to read red data from sensor");
            return EXIT_FAILURE;
        }

        ret = read(i2c_fd, &ir, sizeof(ir));
        if (ret != sizeof(ir)) {
            perror("Failed to read IR data from sensor");
            return EXIT_FAILURE;
        }

        fprintf(log_file, "%ld.%09ld,%hu,%hu\n", ts.tv_sec, ts.tv_nsec, red, ir);
        fflush(log_file);

        if (ir > ADPD144RI_IR_THRESHOLD)
            gpiod_line_set_value(led_line, 1);
        else
            gpiod_line_set_value(led_line, 0);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

