#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_LINE 18

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;
pthread_mutex_t pulse_count_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long pulse_count = 0;

void isr(struct gpiod_line *line, void *data)
{
    pthread_mutex_lock(&pulse_count_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_count_mutex);
}

void sig_handler(int signum)
{
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_count_mutex);
    exit(0);
}

int main()
{
    struct gpiod_line_request req;
    struct sigaction act;
    struct timespec ts;
    double rpm;
    char timestamp[20];

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;
    req.type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req.handler = isr;
    req.data = NULL;

    if (gpiod_line_request(line, &req)) {
        perror("gpiod_line_request");
        return 1;
    }

    log_file = fopen("rpm_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    memset(&act, 0, sizeof(act));
    act.sa_handler = sig_handler;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    while (1) {
        sleep(1);
        pthread_mutex_lock(&pulse_count_mutex);
        rpm = pulse_count ? pulse_count * 60.0 : 0.0;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_count_mutex);
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(log_file, "%s.%09ld %.2f\n", timestamp, ts.tv_nsec, rpm);
        fflush(log_file);
    }

    return 0;
}

