#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_INPUT 17
#define GPIO_OUTPUT 18

struct gpiod_chip *chip = NULL;
struct gpiod_line *input_line = NULL;
struct gpiod_line *output_line = NULL;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (input_line)
        gpiod_line_release(input_line);
    if (output_line)
        gpiod_line_release(output_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    input_line = gpiod_chip_get_line(chip, GPIO_INPUT);
    if (!input_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    output_line = gpiod_chip_get_line(chip, GPIO_OUTPUT);
    if (!output_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_rising_edge_events(input_line, "audio_detector")) {
        perror("gpiod_line_request_rising_edge_events");
        return 1;
    }

    if (gpiod_line_set_value(output_line, 0)) {
        perror("gpiod_line_set_value");
        return 1;
    }

    log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    printf("Started audio detector with 60dB gain.\n");

    struct timespec ts = { .tv_sec = 0, .tv_nsec = 10000000 };
    while (1) {
        if (gpiod_line_event_wait(input_line, &ts)) {
            if (errno == ETIMEDOUT)
                continue;
            perror("gpiod_line_event_wait");
            return 1;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(input_line, &event)) {
            perror("gpiod_line_event_read");
            return 1;
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char buf[30];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s LEVEL %d\n", buf, event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0);
        fflush(log_file);
    }

    return 0;
}

