#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SENSOR_ADDRESS 0x72
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "flow_log.csv"

volatile sig_atomic_t stop = 0;
FILE *log_file;
int i2c_file;

void handle_sigint(int signum) {
    close(i2c_file);
    fclose(log_file);
    exit(0);
}

int validate_crc(unsigned char *data, int len, unsigned char poly, unsigned char init) {
    unsigned char crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ poly;
            else
                crc <<= 1;
        }
    }
    return crc == data[len];
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_file = open(I2C_FILE, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device file");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set sensor address");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    unsigned char buffer[3];
    while (!stop) {
        if (read(i2c_file, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from sensor");
            continue;
        }

        if (!validate_crc(buffer, 2, 0x31, 0xFF)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%02x%02x\n", timestamp, buffer[0], buffer[1]);
        fflush(log_file);
    }

    return 0;
}

