#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define SENSOR_ADDRESS 0x58
#define I2C_FILE_NAME "/dev/i2c-1"
#define LOG_FILE_NAME "air_quality_log.csv"

int i2c_file_descriptor;
FILE *log_file;

int read_from_sensor(unsigned char command, unsigned char *data, int length) {
    int ret;

    ret = write(i2c_file_descriptor, &command, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to write command to sensor\n");
        return ret;
    }

    ret = read(i2c_file_descriptor, data, length);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return ret;
    }

    return 0;
}

void sigint_handler(int signum) {
    close(i2c_file_descriptor);
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;
    unsigned char command, data[2];
    struct sigaction action;

    i2c_file_descriptor = open(I2C_FILE_NAME, O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C device file\n");
        return 1;
    }

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, SENSOR_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set sensor address\n");
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);

    while (1) {
        command = 0x04;
        ret = read_from_sensor(command, data, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        int tvoc = (data[0] << 8) | data[1];

        command = 0x06;
        ret = read_from_sensor(command, data, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        int eco2 = (data[0] << 8) | data[1];

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s,%d,%d\n", timestamp, eco2, tvoc);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

