#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_LINE 17
#define CONSUMER_LABEL "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_DURATION_SEC 5

struct gpiod_line *line;
struct gpiod_chip *chip;
struct timespec poll_interval, intrusion_duration;
int intrusion_detected;

void cleanup_and_exit(int signum)
{
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main(void)
{
    int ret;

    chip = gpiod_chip_open_by_number(5);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup_chip;
    }

    ret = gpiod_line_request_rising_edge_events(line, CONSUMER_LABEL);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        goto cleanup_line;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    clock_getres(CLOCK_MONOTONIC, &poll_interval);
    poll_interval.tv_nsec *= POLL_INTERVAL_MS;
    poll_interval.tv_sec += poll_interval.tv_nsec / 1000000000;
    poll_interval.tv_nsec %= 1000000000;

    intrusion_duration.tv_sec = INTRUSION_DURATION_SEC;
    intrusion_duration.tv_nsec = 0;

    while (1) {
        struct timespec ts;

        ret = gpiod_line_event_wait(line, &poll_interval);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
            goto cleanup_line;
        }

        if (ret == 0) {
            if (intrusion_detected) {
                intrusion_detected = 0;
                printf("Intrusion alert reset\n");
            }
            continue;
        }

        ret = gpiod_line_event_read(line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
            goto cleanup_line;
        }

        if (!intrusion_detected && ts.tv_sec >= intrusion_duration.tv_sec) {
            intrusion_detected = 1;
            printf("Intrusion alert\n");
        }
    }

cleanup_line:
    gpiod_line_release(line);
cleanup_chip:
    gpiod_chip_close(chip);
    return ret;
}

