#include <gpiod.h>

#define PCM_DEVICE "hw:0,0"
#define PCM_CHANNELS 2
#define PCM_RATE 44100
#define PCM_FORMAT SND_PCM_FORMAT_S16_LE
#define PCM_FILE "audio_capture.pcm"
#define GPIO_LINE 17

snd_pcm_t *pcm_handle;
int pcm_file;
struct gpiod_line *gpio_line;

void cleanup_and_exit(int sig) {
    if (pcm_handle)
        snd_pcm_close(pcm_handle);
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (pcm_file != -1)
        close(pcm_file);
    if (sig)
        printf("\nExiting on signal %d\n", sig);
    exit(sig);
}

int main() {
    int err;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device
    if ((err = snd_pcm_open(&pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Set up hardware parameters
    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "Error allocating hardware parameter structure: %s\n", snd_strerror(err));
        cleanup_and_exit(EXIT_FAILURE);
    }
    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting up hardware parameters: %s\n", snd_strerror(err));
        cleanup_and_exit(EXIT_FAILURE);
    }
    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, PCM_FORMAT)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        cleanup_and_exit(EXIT_FAILURE);
