#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pthread.h>

#define SENSOR_GPIO 4
#define FAN_GPIO 18
#define DEBOUNCE_TIME 50000
#define SENSOR_TIMEOUT 10000000

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *fan_line;
FILE *log_file;
int pwm_duty_cycle = 0;
int running = 1;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(log_file, "%s %s\n", timestamp, event);
    fflush(log_file);
}

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void *fan_control_thread(void *arg) {
    while (1) {
        gpiod_line_set_value(fan_line, pwm_duty_cycle > 0);
        usleep(10000);
        pwm_duty_cycle = (pwm_duty_cycle + 1) % 101;
    }
    return NULL;
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "sensor")) {
        perror("gpiod_line_request_input");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "fan", 0)) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    log_event("Program start");

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    pthread_t thread;
    pthread_create(&thread, NULL, fan_control_thread, NULL);

    int sensor_value = 1;
    int sensor_timeout = 0;
    while (running) {
        int rc = gpiod_line_get_value(sensor_line);
        if (rc < 0) {
            perror("gpiod_line_get_value");
            return EXIT_FAILURE;
        }

        if (rc != sensor_value) {
            sensor_value = rc;
            sensor_timeout = 0;
            log_event(sensor_value ? "Flame end" : "Flame detection");
        } else if (++sensor_timeout * 1000000 > SENSOR_TIMEOUT) {
            fprintf(stderr, "Sensor absent\n");
            return EXIT_FAILURE;
        }

        usleep(DEBOUNCE_TIME);
    }

    pthread_cancel(thread);

    gpiod_line_release(sensor_line);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    log_event("Program shutdown");

    return EXIT_SUCCESS;
}

