#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_FRAME_TRIGGER 23
#define GPIO_DATA_READY 24
#define LOG_FILE "mmwave_log.bin"
#define CONFIG_STRUCT_SIZE 100
#define FRAME_SIZE 32768
#define MAGIC_NUMBER 4144

struct gpiod_chip *chip;
struct gpiod_line *frame_trigger, *data_ready;
struct spi_device *spi;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_release(frame_trigger);
    gpiod_line_release(data_ready);
    spi_close(spi);
    fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    struct timespec ts;

    // Open SPI device
    spi = spi_open_device(SPI_DEVICE, 1000000, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    frame_trigger = gpiod_chip_get_line(chip, GPIO_FRAME_TRIGGER);
    if (!frame_trigger) {
        fprintf(stderr, "Failed to get frame trigger line\n");
        exit(EXIT_FAILURE);
    }

    data_ready = gpiod_chip_get_line(chip, GPIO_DATA_READY);
    if (!data_ready) {
        fprintf(stderr, "Failed to get data ready line\n");
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Open log file
    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    // Write file header
    fwrite(&MAGIC_NUMBER, sizeof(int), 1, log_file);
    clock_gettime(CLOCK_REALTIME, &ts);
    fwrite(&ts, sizeof(struct timespec), 1, log_file);
    // Assuming config_struct is a global or static variable
    fwrite(&config_struct, CONFIG_STRUCT_SIZE, 1, log_file);

    // Main capture loop
    while (1) {
        // Wait for data ready
        ret = gpiod_line_wait_for_rising_edge(data_ready, -1);
        if (ret < 0) {
            fprintf(stderr, "Data ready wait failed\n");
            exit(EXIT_FAILURE);
        }

        // Trigger frame capture
        gpiod_line_set_value(frame_trigger, 1);
        usleep(100);
        gpiod_line_set_value(frame_trigger, 0);

        // Read frame
        unsigned char *frame = malloc(FRAME_SIZE);
        if (!frame) {
            fprintf(stderr, "Failed to allocate frame buffer\n");
            exit(EXIT_FAILURE);
        }

        ret = spi_read(spi, frame, FRAME_SIZE);
        if (ret < 0) {
            fprintf(stderr, "SPI read failed\n");
            exit(EXIT_FAILURE);
        }

        // Write frame to log file
        clock_gettime(CLOCK_REALTIME, &ts);
        fwrite(&ts, sizeof(struct timespec), 1, log_file);
        fwrite(frame, FRAME_SIZE, 1, log_file);

        free(frame);
    }

    return 0;
}

