#include <libgpiod.h>
#include <signal.h>

#define GPIO_LINE 20
#define FILE_NAME "flame_log.txt"

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *file;
int old_val;

void write_to_file(int val) {
    time_t now = time(0);
    struct tm *utc = gmtime(&now);
    char buffer[20];
    strftime(buffer, 20, "%FT%TZ", utc);

    fprintf(file, "%s %s\n", buffer, val ? "flame detected" : "flame cleared");
    fflush(file);
}

void handle_signal(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(file);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_sensor")) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    file = fopen(FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    old_val = gpiod_line_get_value(line);
    while (1) {
        int new_val = gpiod_line_get_value(line);
        if (new_val != old_val) {
            write_to_file(new_val);
            old_val = new_val;
        }
        usleep(100000);
    }

    return 0;
}

