#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define OPT3001_ADDR 0x44
#define OPT3001_CONFIG_REG 0x01
#define OPT3001_LOW_THRESH_REG 0x02
#define OPT3001_HIGH_THRESH_REG 0x03
#define OPT3001_MANUFACTURER_ID_REG 0x7E
#define OPT3001_DEVICE_ID_REG 0x7F

#define OPT3001_CONTINUOUS_CONV_MODE 0x43
#define OPT3001_MANUFACTURER_ID 0x5449
#define OPT3001_DEVICE_ID 0x3001

static int fd = -1;
static struct gpiod_device *dev = NULL;

static void cleanup_and_exit(int signum) {
    if (dev)
        gpiod_put(dev);
    if (fd != -1)
        close(fd);
    exit(0);
}

int main() {
    fd = open("light_data.txt", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    dev = gpiod_open_device("/dev/i2c-1");
    if (!dev) {
        perror("gpiod_open_device");
        cleanup_and_exit(-1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (gpiod_i2c_check(dev, OPT3001_ADDR)) {
        fprintf(stderr, "No device at address 0x%02x\n", OPT3001_ADDR);
        cleanup_and_exit(-1);
    }

    uint16_t manufacturer_id = gpiod_i2c_read_word(dev, OPT3001_ADDR, OPT3001_MANUFACTURER_ID_REG);
    if (manufacturer_id != OPT3001_MANUFACTURER_ID) {
        fprintf(stderr, "Unexpected manufacturer ID: 0x%04x\n", manufacturer_id);
        cleanup_and_exit(-1);
    }

    uint16_t device_id = gpiod_i2c_read_word(dev, OPT3001_ADDR, OPT3001_DEVICE_ID_REG);
    if (device_id != OPT3001_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04x\n", device_id);
        cleanup_and_exit(-1);
    }

    gpiod_i2c_write_word(dev, OPT3001_ADDR, OPT3001_CONFIG_REG, OPT3001_CONTINUOUS_CONV_MODE);

    while (1) {
        uint16_t lux = gpiod_i2c_read_word(dev, OPT3001_ADDR, 0);

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // remove trailing newline

        char buf[128];
        snprintf(buf, sizeof(buf), "%s: %u lux\n", timestamp, lux);

        write(fd, buf, strlen(buf));

        usleep(100000); // 100 ms
    }

    return 0;
}

