#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

static struct gpiod_line *line;
static struct gpiod_chip *chip;
static struct gpiod_line_request *request;
static volatile sig_atomic_t stop;

static void sigint_handler(int signum)
{
    stop = 1;
}

int main(void)
{
    struct sigaction action;
    struct timespec ts;
    int ret;

    action.sa_handler = sigint_handler;
    action.sa_flags = 0;
    sigemptyset(&action.sa_mask);
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %m\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line 17: %m\n");
        ret = EXIT_FAILURE;
        goto close_chip;
    }

    request = gpiod_line_request_input_falling_edge_events(line, "flame_detect");
    if (!request) {
        fprintf(stderr, "Failed to request line: %m\n");
        ret = EXIT_FAILURE;
        goto release_line;
    }

    while (!stop) {
        clock_gettime(CLOCK_REALTIME, &ts);

        printf("%04d-%02d-%02d %02d:%02d:%02d ",
               ts.tv_sec / 86400 / 10000,
               (ts.tv_sec / 86400 % 10000) / 100,
               ts.tv_sec / 86400 % 100,
               ts.tv_sec / 3600 % 24,
               ts.tv_sec / 60 % 60,
               ts.tv_sec % 60);

        if (gpiod_line_request_read(request) == 0) {
            printf("Flame Detected: %s\n",
                   gpiod_line_request_get_value(request) ? "NO" : "YES");
        } else {
            printf("Failed to read line: %m\n");
        }

        sleep(1);
    }

    gpiod_line_request_release(request);
release_line:
    gpiod_line_release(line);
close_chip:
    gpiod_chip_close(chip);

    return ret;
}

