#include <signal.h>
#include <libgpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_LINES 8
#define LINE_OFFSETS {2, 3, 4, 5, 6, 7, 8, 9}
#define POLL_TIMEOUT_US 100000

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_LINES];
int running;

void sigint_handler(int signum) {
    running = 0;
}

void close_lines() {
    for (int i = 0; i < NUM_LINES; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
}

void close_chip_and_lines() {
    close_lines();
    if (chip)
        gpiod_chip_close(chip);
}

int main() {
    running = 1;
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open chip %s\n", CHIP_NAME);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, LINE_OFFSETS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", LINE_OFFSETS[i]);
            close_chip_and_lines();
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d\n", LINE_OFFSETS[i]);
            close_chip_and_lines();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_LINES; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to get value of line %d\n", LINE_OFFSETS[i]);
                close_chip_and_lines();
                return EXIT_FAILURE;
            }

            printf("Line %d: %d\n", LINE_OFFSETS[i], value);
        }

        usleep(POLL_TIMEOUT_US);
    }

    close_chip_and_lines();
    return EXIT_SUCCESS;
}

