#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

struct gpiod_chip *chip;
struct gpiod_line *lines[8];
int exit_loop;

void sig_handler(int signum) {
    exit_loop = 1;
}

int main(void) {
    struct timespec ts;
    int ret;
    int i;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, 2 + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", 2 + i, strerror(errno));
            goto err_release_lines;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d: %s\n", 2 + i, strerror(errno));
            goto err_release_lines;
        }
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!exit_loop) {
        printf("[+%ld ms] ", ts.tv_nsec / 1000000);
        for (i = 0; i < 8; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to get value of line %d: %s\n", 2 + i, strerror(errno));
                goto err_release_lines;
            }
            printf("CH%d=%d ", i + 1, ret);
        }
        printf("\n");

        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;  // 100 ms
        nanosleep(&ts, NULL);
    }

err_release_lines:
    for (i = 0; i < 8; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

