int exit_status = EXIT_SUCCESS;

void sigint_handler(int signum) {
    exit_status = EXIT_FAILURE;
}

int main(void) {
    struct timespec ts;
    struct tm tm;
    char csv_line[CSV_LINE_LEN];
    int i;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            exit_status = EXIT_FAILURE;
            goto release_lines;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE)) {
            perror("gpiod_line_request_input");
            exit_status = EXIT_FAILURE;
            goto release_lines;
        }
    }

    while (!exit_status) {
        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm);

        strftime(csv_line, CSV_LINE_LEN, "%Y-%m-%dT%H:%M:%S", &tm);

        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                perror("gpiod_line_get_value");
                exit_status = EXIT_FAILURE;
                goto release_lines;
            }

            snprintf(csv_line + strlen(csv_line), CSV_LINE_LEN - strlen(csv_line), ",%d", val);
        }

        printf("%s\n", csv_line);

        struct timespec delay = { .tv_nsec = 50000000 };
        nanosleep(&delay, NULL);
    }

release_lines:
    for (i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);

    return exit_status;
}

