#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>

struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

void cleanup_and_exit(int sig) {
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    exit(sig);
}

void sigint_handler(int sig) {
    cleanup_and_exit(sig);
}

int main() {
    int ret;
    int last_value = -1;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 4);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line, "tilt_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(-ret));
        cleanup_and_exit(EXIT_FAILURE);
    }

    printf("Tilt sensor monitoring started.\n");

    while (1) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to get GPIO line value: %s\n", strerror(-ret));
            cleanup_and_exit(EXIT_FAILURE);
        }

        if (ret != last_value) {
            last_value = ret;
            fflush(stdout);
            printf("%s\n", ret ? "Not Tilted" : "Tilted");
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

