#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define SI1145_I2C_ADDR 0x60
#define SI1145_PARAM_WR 0x10
#define SI1145_PARAM_RD 0x11
#define SI1145_REVID 0x11
#define SI1145_COMMAND 0x70
#define SI1145_UV_INDEX 0x21
#define SI1145_ALS_VISIBLE 0x23

static int si1145_i2c_file_descriptor;
static FILE *log_file;

static void exit_handler(int signum) {
    close(si1145_i2c_file_descriptor);
    fclose(log_file);
    exit(0);
}

static void handle_i2c_error(int error_code) {
    fprintf(stderr, "I2C error: %s\n", strerror(error_code));
    exit_handler(0);
}

int main() {
    int rc;
    struct i2c_msg msgs[2];
    uint8_t buf[2];
    struct tm *timeinfo;
    time_t now;
    char timestamp[20];

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    si1145_i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (si1145_i2c_file_descriptor < 0) {
        handle_i2c_error(si1145_i2c_file_descriptor);
    }

    rc = ioctl(si1145_i2c_file_descriptor, I2C_SLAVE, SI1145_I2C_ADDR);
    if (rc < 0) {
        handle_i2c_error(rc);
    }

    log_file = fopen("uv_als_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit_handler(0);
    }

    while (1) {
        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        buf[0] = SI1145_UV_INDEX;
        msgs[0].addr = SI1145_I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = sizeof(buf[0]);
        msgs[0].buf = buf;

        buf[0] = SI1145_ALS_VISIBLE;
        msgs[1].addr = SI1145_I2C_ADDR;
        msgs[1].flags = 0;
        msgs[1].len = sizeof(buf[0]);
        msgs[1].buf = buf;

        rc = i2c_smbus_read_word_data(si1145_i2c_file_descriptor, SI1145_UV_INDEX);
        if (rc < 0) {
            handle_i2c_error(rc);
        }
        uint16_t uv_index = rc;

        rc = i2c_smbus_read_word_data(si1145_i2c_file_descriptor, SI1145_ALS_VISIBLE);
        if (rc < 0) {
            handle_i2c_error(rc);
        }
        uint16_t als_visible = rc;

        printf("UV Index: %u, Visible Ambient Light: %u\n", uv_index, als_visible);
        fprintf(log_file, "%s,%u,%u\n", timestamp, uv_index, als_visible);

        sleep(1);
    }

    exit_handler(0);
}

