#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>
#include "sensirion.h"

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SENSOR_ADDR1 0x70
#define I2C_SENSOR_ADDR2 0x71
#define GPIO_LINE 17
#define LOG_FILE "flow_log.txt"

struct gpiod_line *gpio_line;
int i2c_file;
FILE *log_file;

void handle_signal(int signum) {
    gpiod_line_set_value(gpio_line, 0);
    close(i2c_file);
    fclose(log_file);
    gpiod_line_release(gpio_line);
    exit(0);
}

int main() {
    int ret;
    struct gpiod_chip *gpio_chip;
    struct gpiod_line *gpio_line;
    struct i2c_rdwr_ioctl_data msg_data;
    struct i2c_msg msgs[2];
    uint8_t cmd = 0x00;
    uint8_t data[2];
    uint16_t flow_rate;
    uint8_t crc;
    float avg_flow_rate;

    gpio_chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_output(gpio_line, "alarm", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    i2c_file = open(I2C_DEVICE, O_RDWR);
    if (i2c_file < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(i2c_file, I2C_SLAVE, I2C_SENSOR_ADDR1);
    if (ret < 0) {
        perror("ioctl");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        avg_flow_rate = 0;
        for (int i = 0; i < 2; i++) {
            msgs[0].addr = i ? I2C_SENSOR_ADDR2 : I2C_SENSOR_ADDR1;
            msgs[0].flags = 0;
            msgs[0].len = 1;
            msgs[0].buf = &cmd;
            msgs[1].addr = msgs[0].addr;
            msgs[1].flags = I2C_M_RD;
            msgs[1].len = 2;
            msgs[1].buf = data;
            msg_data.msgs = msgs;
            msg_data.nmsgs = 2;
