#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 4
#define CIRCULAR_BUFFER_SIZE 100

struct timespec ts;
struct gpiod_line *line;
struct gpiod_chip *chip;
int *buffer;
int buffer_index = 0;
int is_buffer_full = 0;

void sigint_handler(int signum) {
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%.9ld: %d\n", ts.tv_sec, ts.tv_nsec, buffer[(buffer_index + i) % CIRCULAR_BUFFER_SIZE]);
    }
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    free(buffer);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "obstacle_detector", GPIOD_LINE_FLAG_BIAS_PULL_UP)) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buffer = malloc(CIRCULAR_BUFFER_SIZE * sizeof(int));
    if (!buffer) {
        perror("malloc");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            sigint_handler(0);
        }

        buffer[buffer_index] = value;
        buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
        if (buffer_index == 0)
            is_buffer_full = 1;

        if (value == 0)
            printf("Obstacle detected\n");

        nanosleep((const struct timespec[]){{0, 50000000}}, NULL);
    }

    return EXIT_SUCCESS;
}

