#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define POLL_TIMEOUT_US 1000000
#define STALL_DURATION 2000000

struct gpiod_chip *chip;
struct gpiod_line *sensor1, *sensor2;
FILE *log_file;
int exit_status = EXIT_SUCCESS;

void handle_signal(int signum) {
    fclose(log_file);
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_chip_close(chip);
    exit(exit_status);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit_status = EXIT_FAILURE;
        goto exit;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor1 || !sensor2) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        exit_status = EXIT_FAILURE;
        goto exit;
    }

    if (gpiod_line_request_input(sensor1, "sensor1") ||
        gpiod_line_request_input(sensor2, "sensor2")) {
        fprintf(stderr, "Failed to request GPIO lines as input\n");
        exit_status = EXIT_FAILURE;
        goto exit;
    }

    log_file = fopen("stall_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit_status = EXIT_FAILURE;
        goto exit;
    }

    struct timespec last_stall_time = { 0, 0 };
    while (1) {
        int val1 = gpiod_line_get_value(sensor1);
        int val2 = gpiod_line_get_value(sensor2);
        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Failed to read sensor values\n");
            exit_status = EXIT_FAILURE;
            goto exit;
        }

        if (val1 == 0 && val2 == 0) {
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);
            long int time_diff = (current_time.tv_sec - last_stall_time.tv_sec) * 1000000 +
                                 (current_time.tv_nsec - last_stall_time.tv_nsec) / 1000;

            if (time_diff >= STALL_DURATION) {
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));
                fprintf(log_file, "%s\n", timestamp);
                fflush(log_file);
                last_stall_time = current_time;
            }
        }
    }

exit:
    handle_signal(0);
    return 0;
}

