#include <sys/time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A

#define X_REG 0x01
#define Y_REG 0x03
#define Z_REG 0x05
#define CTRL_REG 0x07

#define CSV_FILE "magnetic_log.csv"

static struct gpiod_device *dev = NULL;
static struct gpiod_i2c *i2c = NULL;
static FILE *csv = NULL;

static void cleanup_and_exit(int signum)
{
    if (i2c)
        gpiod_i2c_close(i2c);
    if (csv)
        fclose(csv);
    exit(signum);
}

int main(void)
{
    int ret;
    struct timespec ts;
    struct tm *timeinfo;
    char timestamp[20];

    dev = gpiod_device_open_by_name("pinctrl-bcm2835");
    if (!dev) {
        fprintf(stderr, "Failed to open device: %s\n", strerror(errno));
        return errno;
    }

    i2c = gpiod_i2c_open(dev, I2C_BUS, I2C_ADDR);
    if (!i2c) {
        fprintf(stderr, "Failed to open I2C: %s\n", strerror(errno));
        ret = errno;
        goto cleanup;
    }

    ret = gpiod_i2c_write_reg(i2c, CTRL_REG, 0x01);
    if (ret < 0) {
        fprintf(stderr, "Failed to write register: %s\n", strerror(errno));
        goto cleanup;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    csv = fopen(CSV_FILE, "a");
    if (!csv) {
        fprintf(stderr, "Failed to open CSV: %s\n", strerror(errno));
        ret = errno;
        goto cleanup;
    }

    if (ftell(csv) == 0) {
        fprintf(csv, "timestamp,x,y,z\n");
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        timeinfo = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        int16_t x, y, z;
        ret = gpiod_i2c_read_reg(i2c, X_REG, &x);
        if (ret < 0) {
            fprintf(stderr, "Failed to read X: %s\n", strerror(errno));
            continue;
        }

        ret = gpiod_i2c_read_reg(i2c, Y_REG, &y);
        if (ret < 0) {
            fprintf(stderr, "Failed to read Y: %s\n", strerror(errno));
            continue;
        }

        ret = gpiod_i2c_read_reg(i2c, Z_REG, &z);
        if (ret < 0) {
            fprintf(stderr, "Failed to read Z: %s\n", strerror(errno));
            continue;
        }

        fprintf(csv, "%s,%hd,%hd,%hd\n", timestamp, x, y, z);
        fflush(csv);

        usleep(100000);
    }

cleanup:
    cleanup_and_exit(ret);
}

