#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LINE 23
#define SLEEP_TIME 2
#define LOG_FILE "flood_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *line;

void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        printf("Failed to open log file\n");
        return;
    }
    fprintf(file, "%d-%02d-%02d %02d:%02d:%02d %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(file);
}

void cleanup_and_exit(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_message("Daemon exited");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip");
        sleep(60);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_message("Failed to get GPIO line");
        gpiod_chip_close(chip);
        sleep(60);
        return -1;
    }

    if (gpiod_line_request_input(line, "Water Sensor", GPIOD_LINE_FLAG_BIAS_PULL_DOWN)) {
        log_message("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        sleep(60);
        return -1;
    }

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            log_message("Failed to read GPIO line");
            cleanup_and_exit(0);
        }

        if (value) {
            log_message("ALERT: Water detected");
        }

        sleep(SLEEP_TIME);
    }

    return 0;
}

