#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LINE 4

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;
unsigned long pulse_count;

void log_rpm(void)
{
    struct timespec ts;
    struct tm *timeinfo;
    char buffer[80];
    char str[20];

    clock_gettime(CLOCK_REALTIME, &ts);
    timeinfo = localtime(&ts.tv_sec);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    sprintf(str, " %lu", pulse_count);
    strcat(buffer, str);
    strcat(buffer, "\n");

    fwrite(buffer, strlen(buffer), 1, log_file);
    fflush(log_file);

    printf("%s", buffer);
}

void handle_signal(int signum)
{
    gpiod_line_set_alert_handler(line, NULL, NULL);
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main(void)
{
    struct gpiod_line_request_config req_config;
    struct gpiod_alert_event event;
    struct timespec ts;
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    memset(&req_config, 0, sizeof(req_config));
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    ret = gpiod_line_request_alert(line, &req_config, NULL);
    if (ret) {
        perror("gpiod_line_request_alert");
        exit(1);
    }

    log_file = fopen("rpm_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        ts.tv_sec = 1;
        ts.tv_nsec = 0;

        ret = gpiod_line_wait_for_event(line, &ts);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                log_rpm();
                pulse_count = 0;
                continue;
            }

            perror("gpiod_line_wait_for_event");
            exit(1);
        }

        ret = gpiod_line_get_alert_event(line, &event);
        if (ret) {
            perror("gpiod_line_get_alert_event");
            exit(1);
        }

        pulse_count++;
    }

    return 0;
}

