                    (ts.tv_sec / 60) % 60, ts.tv_nsec / 1000000, ts.tv_nsec / 1000);
        } else if (state1 == 0 && state2 == 1 && prev_state1 == 1 && prev_state2 == 0) {
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d.%03ld Counter-clockwise\n",
                    ts.tv_sec / 31536000 + 1970, (ts.tv_sec / 86400) % 365, (ts.tv_sec / 3600) % 24,
                    (ts.tv_sec / 60) % 60, ts.tv_nsec / 1000000, ts.tv_nsec / 1000);
        }

        prev_state1 = state1;
        prev_state2 = state2;
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    struct sigaction sigIntHandler;
    struct gpiod_line_request_config req_config;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    if (sigaction(SIGINT, &sigIntHandler, NULL) != 0 || sigaction(SIGTERM, &sigIntHandler, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (line1 == NULL || line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    req_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP | GPIOD_LINE_REQUEST_FLAG_EDGE_FALLING;

    if (gpiod_line_request_both_edges_handle_fast(line1, "rotation_sensor", &req_config, isr) != 0 ||
        gpiod_line_request_both_edges_handle_fast(line2, "rotation_sensor", &req_config, isr) != 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("rotation_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(1);
    }

    return EXIT_SUCCESS;
}
