#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <syslog.h>
#include <time.h>

#define SENSOR_GPIO 23
#define LED_GPIO 18
#define POLL_INTERVAL_MS 50

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL, *led_line = NULL;

void cleanup_and_exit(int sig)
{
    openlog("gpio_touch_sensor", LOG_CONS | LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Shutting down...");

    gpiod_line_set_value(led_line, 0);

    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (led_line)
        gpiod_line_release(led_line);
    if (chip)
        gpiod_chip_close(chip);

    closelog();

    exit(sig);
}

int main()
{
    openlog("gpio_touch_sensor", LOG_CONS | LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting up...");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        cleanup_and_exit(-1);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        syslog(LOG_ERR, "Failed to get sensor line: %m");
        cleanup_and_exit(-1);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line: %m");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_input(sensor_line, "sensor")) {
        syslog(LOG_ERR, "Failed to request sensor line: %m");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_output(led_line, "led", 0)) {
        syslog(LOG_ERR, "Failed to request LED line: %m");
        cleanup_and_exit(-1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read sensor line: %m");
            cleanup_and_exit(-1);
        }

        if (gpiod_line_set_value(led_line, value)) {
            syslog(LOG_ERR, "Failed to set LED line: %m");
            cleanup_and_exit(-1);
        }

        if (value)
            syslog(LOG_INFO, "Touch event detected");

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

