#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_TOUCH_PIN 17
#define GPIO_LED_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *touch_line, *led_line;
static struct gpiod_line_request touch_req, led_req;

static void sig_handler(int signum)
{
    gpiod_line_release(&touch_req);
    gpiod_line_release(&led_req);
    gpiod_chip_close(chip);
    exit(signum);
}

int main(void)
{
    struct gpiod_line_event ev;
    struct timespec ts = { .tv_nsec = 50000000 }; // 50 ms

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_events(&touch_req, touch_line, "touch")) {
        fprintf(stderr, "Failed to request touch line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(&led_req, led_line, "led", 0)) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        if (gpiod_line_wait_rising_edge(touch_line, &ts)) {
            fprintf(stderr, "Failed to wait for touch: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        if (gpiod_line_event_read(touch_line, &ev)) {
            fprintf(stderr, "Failed to read touch event: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_set_value(&led_req, !ev.event)) {
            fprintf(stderr, "Failed to toggle LED: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        nanosleep(&ts, NULL);
    }

    return EXIT_SUCCESS;
}

