#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define LED1_GPIO 27
#define LED2_GPIO 22
#define DEBOUNCE_TIME 50000
#define LOG_BUFFER_SIZE 100

struct gpiod_line *sensor1, *sensor2, *led1, *led2;
struct gpiod_chip *chip;
struct timespec ts;
int overflow_count = 0;

struct log_entry {
    int gpio;
    struct timespec ts;
    int state;
};

struct log_entry log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;

void handle_signal(int signum) {
    gpiod_line_set_value(led1, 0);
    gpiod_line_set_value(led2, 0);
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_line_release(led1);
    gpiod_line_release(led2);
    gpiod_chip_close(chip);
    printf("Overflow count: %d\n", overflow_count);
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        printf("GPIO: %d, Time: %ld.%09ld, State: %d\n", log_buffer[i].gpio, log_buffer[i].ts.tv_sec, log_buffer[i].ts.tv_nsec, log_buffer[i].state);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config request_config = {
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
        .consumer = "Touch Sensor Example",
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    sensor2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    led1 = gpiod_chip_get_line(chip, LED1_GPIO);
    if (!led1) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    led2 = gpiod_chip_get_line(chip, LED2_GPIO);
    if (!led2) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_input(sensor1, &request_config) < 0) {
        perror("gpiod_line_request_input");
        return 1;
    }

    if (gpiod_line_request_input(sensor2, &request_config) < 0) {
        perror("gpiod_line_request_input");
        return 1;
    }

    if (gpiod_line_request_output(led1, "LED1", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_output(led2, "LED2", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sensor1_value, sensor2_value, prev_sensor1_value = -1, prev_sensor2_value = -1;

    while (1) {
        sensor1_value = gpiod_line_get_value(sensor1);
        sensor2_value = gpiod_line_get_value(sensor2);

        if (sensor1_value != prev_sensor1_value) {
            clock_gettime(CLOCK_REALTIME, &ts);
            log_buffer[log_index].gpio = SENSOR1_GPIO;
            log_buffer[log_index].ts = ts;
            log_buffer[log_index].state = sensor1_value;
            log_index = (log_index + 1) % LOG_BUFFER_SIZE;
            if (log_index == 0) overflow_count++;
            prev_sensor1_value = sensor1_value;
        }

        if (sensor2_value != prev_sensor2_value) {
            clock_gettime(CLOCK_REALTIME, &ts);
            log_buffer[log_index].gpio = SENSOR2_GPIO;
            log_buffer[log_index].ts = ts;
            log_buffer[log_index].state = sensor2_value;
            log_index = (log_index + 1) % LOG_BUFFER_SIZE;
            if (log_index == 0) overflow_count++;
            prev_sensor2_value = sensor2_value;
        }

        gpiod_line_set_value(led1, sensor1_value);
        gpiod_line_set_value(led2, sensor2_value);

        usleep(DEBOUNCE_TIME);
    }

    return 0;
}

