#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_SLAVE_ADDR 0x10
#define I2C_FILE_NAME "/dev/i2c-1"
#define LOG_FILE_NAME "biometric_log.txt"

int i2c_file_descriptor;
FILE *log_file;

void sigint_handler(int signum) {
    close(i2c_file_descriptor);
    fclose(log_file);
    exit(0);
}

int i2c_read(unsigned char reg, unsigned char *data) {
    int ret;

    ret = ioctl(i2c_file_descriptor, I2C_SLAVE, I2C_SLAVE_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return ret;
    }

    ret = write(i2c_file_descriptor, &reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return ret;
    }

    ret = read(i2c_file_descriptor, data, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return ret;
    }

    return 0;
}

int main() {
    unsigned char data;
    struct tm *timeinfo;
    char timestamp[20];

    i2c_file_descriptor = open(I2C_FILE_NAME, O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C device file: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (i2c_read(0x01, &data) < 0) {
            continue;
        }

        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, data, data);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

