    exit(signum);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    sensor1 = gpiod_chip_get_line(chip, GPIO17);
    sensor2 = gpiod_chip_get_line(chip, GPIO18);
    alarm = gpiod_chip_get_line(chip, GPIO27);
    if (!sensor1 || !sensor2 || !alarm) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor1, "sensor1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) ||
        gpiod_line_request_input(sensor2, "sensor2", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) ||
        gpiod_line_request_output(alarm, "alarm", 0)) {
        perror("gpiod_line_request");
        return EXIT_FAILURE;
    }

    log_file = fopen("bridge_integrity.log", "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    time_t prev_sensor1_tilt = 0, prev_sensor2_tilt = 0;
    while (1) {
        int sensor1_value = gpiod_line_get_value(sensor1);
        int sensor2_value = gpiod_line_get_value(sensor2);
        if (sensor1_value < 0 || sensor2_value < 0) {
            perror("gpiod_line_get_value");
            return EXIT_FAILURE;
        }

        time_t now = time(NULL);
        if (sensor1_value && !prev_sensor1_tilt) {
            prev_sensor1_tilt = now;
            fprintf(log_file, "%s: Sensor 1 tilted\n", ctime(&now));
        } else if (!sensor1_value && prev_sensor1_tilt && now - prev_sensor1_tilt > 2) {
            prev_sensor1_tilt = 0;
            fprintf(log_file, "%s: Sensor 1 back to normal\n", ctime(&now));
        }

        if (sensor2_value && !prev_sensor2_tilt) {
            prev_sensor2_tilt = now;
            fprintf(log_file, "%s: Sensor 2 tilted\n", ctime(&now));
        } else if (!sensor2_value && prev_sensor2_tilt && now - prev_sensor2_tilt > 2) {
            prev_sensor2_tilt = 0;
            fprintf(log_file, "%s: Sensor 2 back to normal\n", ctime(&now));
        }

        if (sensor1_value || sensor2_value) {
            gpiod_line_set_value(alarm, 1);
        } else {
            gpiod_line_set_value(alarm, 0);
        }

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

