#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c.h>

#define SDA_GPIO 2
#define SCL_GPIO 3
#define LED_GPIO 17
#define SENSOR_ADDR 0x1E
#define CTRL1_REG 0x20
#define THRESHOLD 500
#define MAX_RETRIES 3

int i2c_file;
FILE *log_file;

void handle_sigint(int signum) {
    close(i2c_file);
    fclose(log_file);
    exit(0);
}

int read_sensor(int *x, int *y, int *z) {
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msgs[2];
    int retries = 0;

    while (retries <= MAX_RETRIES) {
        msgs[0].addr = SENSOR_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = (char[]){0x00};

        msgs[1].addr = SENSOR_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 6;
        msgs[1].buf = (char[]){0, 0, 0, 0, 0, 0};

        msg.msgs = msgs;
        msg.nmsgs = 2;

        if (ioctl(i2c_file, I2C_RDWR, &msg) != -1) {
            *x = (msgs[1].buf[0] << 6) | (msgs[1].buf[1] >> 2);
            *y = (msgs[1].buf[2] << 6) | (msgs[1].buf[3] >> 2);
            *z = (msgs[1].buf[4] << 6) | (msgs[1].buf[5] >> 2);
            return 0;
        }

        retries++;
        usleep(10000);
    }

    return -1;
}

int main() {
    struct i2c_msg msg;
    int x, y, z, magnitude, ctrl1_val = 0x08;
    char timestamp[20];
    struct tm *timeinfo;
    time_t now;

    signal(SIGINT, handle_sigint);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) == -1) {
        perror("Failed to set sensor address");
        return 1;
    }

    msg.addr = SENSOR_ADDR;
