void cleanup_and_exit(int signum) {
    printf("Exiting...\n");
    for (int i = 0; i < GPIO_PINS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    for (int i = 0; i < GPIO_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 4);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "Obstacle detection")) {
            perror("Failed to request GPIO line as input");
            return 1;
        }
    }

    led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(led, "LED control", 1)) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    while (1) {
        int obstacle_detected = 0;
        for (int i = 0; i < GPIO_PINS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to get line value");
                return 1;
            }
            obstacle_detected |= value;
        }

        if (gpiod_line_set_value(led, obstacle_detected)) {
            perror("Failed to set line value");
            return 1;
        }

        usleep(50000);
    }

    return 0;
}

