#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define LOG_FILE "/var/log/flame_events.log"

struct gpiod_line *lines[GPIO_LINES];
struct gpiod_chip *chip;
FILE *log_file;
volatile sig_atomic_t stop;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM)
        stop = 1;
}

void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

void log_and_exit(int status) {
    closelog();
    exit(status);
}

int main() {
    struct sigaction action;
    struct timespec delay = {0, 1000000000};
    int i, val, prev_val;
    char timestamp[20];
    time_t now;
    struct tm *utc;

    openlog("flame_monitor", LOG_PID, LOG_USER);
    log_message(LOG_INFO, "Started");

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        log_and_exit(EXIT_FAILURE);
    }

    for (i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            log_message(LOG_ERR, "Failed to get line %d", GPIO_PINS[i]);
            log_and_exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor")) {
            log_message(LOG_ERR, "Failed to request line %d", GPIO_PINS[i]);
            log_and_exit(EXIT_FAILURE);
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file");
        log_and_exit(EXIT_FAILURE);
    }

    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    while (!stop) {
        for (i = 0; i < GPIO_LINES; i++) {
            val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                log_message(LOG_ERR, "Failed to read line %d", GPIO_PINS[i]);
                continue;
            }

            if (val == 0) {
                nanosleep(&delay, NULL);
                prev_val = val;
                val = gpiod_line_get_value(lines[i]);
                if (val < 0) {
                    log_message(LOG_ERR, "Failed to read line %d", GPIO_PINS[i]);
                    continue;
                }

                if (val == 0 && prev_val == 0) {
                    now = time(NULL);
                    utc = gmtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);
                    fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, i + 1, GPIO_PINS[i]);
                    fflush(log_file);
                }
            }
        }
    }

    for (i = 0; i < GPIO_LINES; i++)
        gpiod_line_release(lines[i]);

    gpiod_chip_close(chip);
    fclose(log_file);
    log_message(LOG_INFO, "Stopped");
    closelog();
    return 0;
}

