    printf("%d-%02d-%02dT%02d:%02d:%02d ", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
}

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_line_request_config request_config = {
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE,
        .consumer = "TTP226_Touch_Detector",
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %d\n", errno);
        return 1;
    }

