        if (gpiod_line_request_input(lines[i], &request_config)) {
            fprintf(stderr, "Failed to request line %d: %d\n", bcm_gpio_pins[i], errno);
            return 1;
        }
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int state = gpiod_line_get_value(lines[i]);
            if (state < 0) {
                fprintf(stderr, "Failed to get value of line %d: %d\n", bcm_gpio_pins[i], errno);
                return 1;
