void write_log(int lux, int brightness, int error) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, lux, brightness, error);
