#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define NUM_CHANNELS 8
#define LED_GPIO 17
#define TOUCH_SENSOR_GPIOS 2, 3, 4, 5, 6, 7, 8, 9

struct gpiod_chip *chip;
struct gpiod_line *led_line, *touch_lines[NUM_CHANNELS];
FILE *log_file;
int led_state = 0;

void sig_handler(int signo) {
    if (led_state)
        gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    for (int i = 0; i < NUM_CHANNELS; i++)
        gpiod_line_release(touch_lines[i]);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec ts = {.tv_sec = 0, .tv_nsec = 50000000};
    struct tm *timeinfo;
    char buffer[26];
    int prev_touch_state[NUM_CHANNELS] = {0};

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        return 1;
    }
    if (gpiod_line_request_output(led_line, "led", 0)) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_lines[i] = gpiod_chip_get_line(chip, TOUCH_SENSOR_GPIOS);
        if (!touch_lines[i]) {
            fprintf(stderr, "Failed to get touch line %d: %s\n", i+1, strerror(errno));
            return 1;
        }
        if (gpiod_line_request_input(touch_lines[i], "touch", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN)) {
            fprintf(stderr, "Failed to request touch line %d: %s\n", i+1, strerror(errno));
            return 1;
        }
    }

    log_file = fopen("touch_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int touch_state = gpiod_line_get_value(touch_lines[i]);
            if (touch_state < 0) {
                fprintf(stderr, "Failed to get touch state for line %d: %s\n", i+1, strerror(errno));
                return 1;
            }
            if (touch_state != prev_touch_state[i]) {
                prev_touch_state[i] = touch_state;
                time_t now = time(NULL);
                timeinfo = localtime(&now);
                strftime(buffer, 26, "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_file, "%s - Channel %d %s\n", buffer, i+1, touch_state ? "Touched" : "Released");
                if (ferror(log_file)) {
                    fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                    return 1;
                }
                if (touch_state) {
                    gpiod_line_set_value(led_line, 1);
                    led_state = 1;
                } else if (led_state) {
                    int all_released = 1;
                    for (int j = 0; j < NUM_CHANNELS; j++) {
                        if (gpiod_line_get_value(touch_lines[j])) {
                            all_released = 0;
                            break;
                        }
                    }
                    if (all_released) {
                        gpiod_line_set_value(led_line, 0);
                        led_state = 0;
                    }
                }
            }
        }
        nanosleep(&ts, NULL);
    }

    return 0;
}

