#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define OPT3001_ADDR 0x44
#define OPT3001_CONFIG 0x01
#define OPT3001_LOW_THRESHOLD 0x02
#define OPT3001_HIGH_THRESHOLD 0x03
#define OPT3001_RESULT 0x00

#define I2C_BUS 1

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void check_return(int ret, const char *msg) {
    if (ret < 0) {
        fprintf(stderr, "%s: %s\n", msg, strerror(errno));
        sigint_handler(0);
    }
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    check_return(i2c_fd, "Failed to open I2C device");

    int ret = ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR);
    check_return(ret, "Failed to set I2C slave address");

    log_file = fopen("light_data.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        sigint_handler(0);
    }

    while (1) {
        // Write configuration
        uint16_t config = htobe16(0x4000); // 1 second conversion time, automatic mode
        ret = write(i2c_fd, &config, sizeof(config));
        check_return(ret, "Failed to write configuration");

        usleep(100000); // Wait at least 100 ms

        // Read result
        uint16_t result;
        ret = read(i2c_fd, &result, sizeof(result));
        check_return(ret, "Failed to read result");

        result = be16toh(result); // Convert to host byte order

        // Print and log the result
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(stdout, "%s, %.2f\n", timestamp, result / 100.0);
        fprintf(log_file, "%s, %.2f\n", timestamp, result / 100.0);
        fflush(log_file);
    }

    return 0;
}

