        fprintf(stderr, "Failed to get sensor line\n");
        cleanup_and_exit(-1);
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_GPIO);
    if (!alert_line) {
        fprintf(stderr, "Failed to get alert line\n");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_input(sensor_line, "sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line\n");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_output(alert_line, "alert", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request alert line\n");
        cleanup_and_exit(-1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(-1);
    }

    while (1) {
        ret = gpiod_line_get_value(sensor_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor line\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (!ret) {
            fprintf(log_file, "%s: Flame detected\n", timestamp);
            gpiod_line_set_value(alert_line, 1);
            sleep(1);
            gpiod_line_set_value(alert_line, 0);
        } else {
            fprintf(log_file, "%s: No flame\n", timestamp);
        }

        fflush(log_file);
        usleep(500000);
    }

    cleanup_and_exit(0);
}
