#define SENSOR_ADDRESS 0x6B
#define SENSOR_CMD 0x00
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t stop = 0;
int i2c_file = -1;
FILE* csv_file = NULL;

void handle_sigint(int signum) {
    stop = 1;
}

void write_header_to_csv() {
    fprintf(csv_file, "Timestamp,Flow Rate (ml/min),Status\n");
}

void write_to_csv(time_t timestamp, float flow_rate, int flags, const char* status) {
    fprintf(csv_file, "%ld,%.2f,%s\n", timestamp, flow_rate, status);
}

int i2c_read_bytes(unsigned char* buffer, int count) {
    if (read(i2c_file, buffer, count) != count) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int i2c_write_byte(unsigned char byte) {
    if (write(i2c_file, &byte, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int crc8(const unsigned char* buffer, int count, int init) {
    int crc = init;
    for (int i = 0; i < count; i++) {
        crc ^= buffer[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc & 0xFF;
}

void monitor_coolant_flow() {
    unsigned char buffer[3];
    time_t timestamp;
    float flow_rate;
    int flags;
    char status[10];

    signal(SIGINT, handle_sigint);

    while (!stop) {
        usleep(2000);

        if (i2c_write_byte(SENSOR_CMD) == -1) {
            write_to_csv(time(NULL), 0.0, 0, "ERROR");
            continue;
        }

        if (i2c_read_bytes(buffer, sizeof(buffer)) == -1) {
            write_to_csv(time(NULL), 0.0, 0, "ERROR");
            continue;
        }

        if (crc8(buffer, sizeof(buffer) - 1, CRC8_INIT) != buffer[2]) {
            write_to_csv(time(NULL), 0.0, 0, "ERROR");
            continue;
        }

        flow_rate = (buffer[0] << 8 | buffer[1]) / 100.0;
        if (flow_rate < 0.0 || flow_rate > 100.0) {
            strcpy(status, "INVALID");
        } else {
            strcpy(status, "VALID");
        }

        timestamp = time(NULL);
        write_to_csv(timestamp, flow_rate, 0, status);

        sleep(1);
    }
}

int main() {
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msgs[2];

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    csv_file = fopen("cooling_log.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    write_header_to_csv();
    monitor_coolant_flow();

    fclose(csv_file);
    close(i2c_file);

    return EXIT_SUCCESS;
}

