    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "flame_sensor")) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = fopen("flame_events.txt", "a");
    if (!file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpiod_line_event_wait(line, NULL)) {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char buf[100];
            sprintf(buf, "%d-%02d-%02d %02d:%02d:%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
            printf("Flame detected at %s\n", buf);
            fprintf(file, "%s\n", buf);
        }
    }

    return EXIT_SUCCESS;
}
