#include <libgpiod.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27

struct gpiod_chip *chip;
struct gpiod_line *line_gpio4, *line_gpio17, *line_gpio27;
FILE *log_file;

void sig_handler(int signo) {
    if (log_file != NULL)
        fclose(log_file);
    gpiod_line_release(line_gpio4);
    gpiod_line_release(line_gpio17);
    gpiod_line_release(line_gpio27);
    gpiod_chip_close(chip);
    exit(signo);
}

int main() {
    int ret;
    struct timespec ts;
    struct tm *timeinfo;
    char timestamp[20];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    line_gpio4 = gpiod_chip_get_line(chip, GPIO4);
    line_gpio17 = gpiod_chip_get_line(chip, GPIO17);
    line_gpio27 = gpiod_chip_get_line(chip, GPIO27);

    ret = gpiod_line_request_input(line_gpio4, "sensor1");
    ret |= gpiod_line_request_input(line_gpio17, "sensor2");
    ret |= gpiod_line_request_input(line_gpio27, "sensor3");

    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO lines.\n");
        return 1;
    }

    log_file = fopen("magnet_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    while (1) {
        int val_gpio4 = gpiod_line_get_value(line_gpio4);
        int val_gpio17 = gpiod_line_get_value(line_gpio17);
        int val_gpio27 = gpiod_line_get_value(line_gpio27);

        if (val_gpio4 < 0 || val_gpio17 < 0 || val_gpio27 < 0) {
            fprintf(stderr, "Failed to read sensor value.\n");
            continue;
        }

        time(&ts.tv_sec);
        timeinfo = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s Sensor1: %d\n", timestamp, val_gpio4);
        fprintf(log_file, "%s Sensor2: %d\n", timestamp, val_gpio17);
        fprintf(log_file, "%s Sensor3: %d\n", timestamp, val_gpio27);

        fflush(log_file);

        usleep(100000);
    }

    return 0;
}
```

This program uses the libgpiod library to interact with the GPIO pins on the Raspberry Pi. It sets up the GPIO pins as input with an internal pull-up enabled, and then continuously reads the state of the pins. If any error occurs during the reading process, it writes an error message to stderr and continues with the next iteration.

The program also installs signal handlers for SIGINT and SIGTERM, which will close the log file and release the GPIO lines before exiting.

The sensors use an open-drain output that pulls the line low when a south pole is present (magnet-present = logic low) and releases it high when the magnet is removed (magnet-removed = logic high). The program polls the pins every 100 ms and logs the state change with an ISO-8601 timestamp and the corresponding sensor identifier.

