#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SI1182_I2C_ADDR 0x60
#define SI1182_PART_ID 0x1182
#define SI1182_HW_REV 0x02

#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_HW_REV 0x01
#define SI1182_REG_IR_DATA 0x14

int i2c_file;
FILE *log_file;
volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int i2c_write_reg(int reg, int val) {
    char buf[2] = {reg, val};
    if (write(i2c_file, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int reg, int *val) {
    if (write(i2c_file, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }
    char buf[2];
    if (read(i2c_file, buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    int part_id, hw_rev;
    if (i2c_read_reg(SI1182_REG_PART_ID, &part_id) < 0 || part_id != SI1182_PART_ID) {
        fprintf(stderr, "Invalid sensor PART_ID\n");
        return 1;
    }
    if (i2c_read_reg(SI1182_REG_HW_REV, &hw_rev) < 0 || hw_rev != SI1182_HW_REV) {
        fprintf(stderr, "Invalid sensor HW_REV\n");
        return 1;
    }

    log_file = fopen("heart_rate.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int ir_data[5];
    int ir_data_idx = 0;
    while (!stop) {
        if (i2c_read_reg(SI1182_REG_IR_DATA, &ir_data[ir_data_idx]) < 0) {
            fprintf(stderr, "Failed to read sensor data, retrying\n");
            continue;
        }

        ir_data_idx = (ir_data_idx + 1) % 5;
        if (ir_data_idx == 0) {
            int avg = 0;
            for (int i = 0; i < 5; i++) {
                avg += ir_data[i];
            }
            avg /= 5;

            if (avg >= 30 && avg <= 220) {
                time_t now = time(NULL);
                struct tm *tm_now = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

                fprintf(log_file, "%s,%d\n", timestamp, avg);
                fflush(log_file);
            }
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_file);

    return 0;
}

