#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;
int exit_status = EXIT_SUCCESS;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("\nShutting down...\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(exit_status);
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        exit_status = EXIT_FAILURE;
        goto exit;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        exit_status = EXIT_FAILURE;
        goto close_chip;
    }

    if (gpiod_line_request_falling_edge_events(line, "flame_sensor")) {
        perror("gpiod_line_request_falling_edge_events");
        exit_status = EXIT_FAILURE;
        goto release_line;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit_status = EXIT_FAILURE;
        goto release_line;
    }

    while (1) {
        if (gpiod_line_event_wait(line, NULL) == 1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            printf("%s: FLAME DETECTED\n", time_str);
            fprintf(log_file, "%s: FLAME DETECTED\n", time_str);
            fflush(log_file);
        }
        usleep(100000);  // 100 ms
    }

    fclose(log_file);
release_line:
    gpiod_line_release(line);
close_chip:
    gpiod_chip_close(chip);
exit:
    exit(exit_status);
}

