#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIPSET "gpiochip0"
#define GPIO_LINES "5,6,7,8,9,10,11,12"
#define GPIO_DRIVER "gpiod"
#define LOG_FILE "touch_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *lines[8];
int counters[8];
FILE *log_file;

void cleanup_and_exit(int status) {
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(status);
}

void handle_signal(int signum) {
    for (int i = 0; i < 8; i++) {
        counters[i] = 0;
        gpiod_line_set_value(lines[i], 0);
    }
    cleanup_and_exit(0);
}

int main() {
    struct timespec ts = {.tv_sec = 0, .tv_nsec = 10000000};
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];
    int ret;

    chip = gpiod_chip_open(GPIO_CHIPSET);
    if (!chip) {
        fprintf(stderr, "Failed to open chip: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 5);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", i + 5, strerror(errno));
            cleanup_and_exit(1);
        }
        ret = gpiod_line_request_rising_edge_events(lines[i], GPIO_DRIVER);
        if (ret) {
            fprintf(stderr, "Failed to request line %d: %s\n", i + 5, strerror(errno));
            cleanup_and_exit(1);
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    nanosleep(&ts, NULL);

    while (1) {
        for (int i = 0; i < 8; i++) {
            ret = gpiod_line_event_wait(lines[i], &ts);
            if (ret < 0) {
                fprintf(stderr, "Failed to wait for event on line %d: %s\n", i + 5, strerror(errno));
                continue;
            }
            if (ret > 0) {
                counters[i] = (counters[i] + 1) % 256;
                timeinfo = gmtime(&ts.tv_sec);
                strftime(timestamp, sizeof(timestamp), "%FT%TZ", timeinfo);
                sprintf(log_entry, "%s, Channel: %d, Counter: %d\n", timestamp, i + 1, counters[i]);
                if (log_file) {
                    fputs(log_entry, log_file);
                }
                printf("Touch on channel %d | Counter: %d\n", i + 1, counters[i]);
                ret = gpiod_line_set_value(lines[i], counters[i] & (1 << i));
                if (ret) {
                    fprintf(stderr, "Failed to set value on line %d: %s\n", i + 5, strerror(errno));
                }
            }
        }
    }

    return 0;
}

