#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

struct gpiod_chip *chip = NULL;
struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL, *line4 = NULL;
FILE *file = NULL;

void write_to_file(int sig) {
    int val1, val2, val3, val4;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

    val1 = gpiod_line_get_value(line1);
    val2 = gpiod_line_get_value(line2);
    val3 = gpiod_line_get_value(line3);
    val4 = gpiod_line_get_value(line4);

    if (val1 < 0 || val2 < 0 || val3 < 0 || val4 < 0) {
        fprintf(stderr, "Failed to read GPIO line value\n");
        return;
    }

    fprintf(file, "%s,%d,%d,%d,%d\n", timestamp, val1, val2, val3, val4);
    fflush(file);
}

int main() {
    int ret;

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    line2 = gpiod_chip_get_line(chip, GPIO18);
    line3 = gpiod_chip_get_line(chip, GPIO27);
    line4 = gpiod_chip_get_line(chip, GPIO22);
    if (!line1 || !line2 || !line3 || !line4) {
        fprintf(stderr, "Failed to get GPIO line\n");
        ret = EXIT_FAILURE;
        goto err_close_chip;
    }

    ret = gpiod_line_request_input(line1, "sensor1");
    ret |= gpiod_line_request_input(line2, "sensor2");
    ret |= gpiod_line_request_input(line3, "sensor3");
    ret |= gpiod_line_request_input(line4, "sensor4");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        ret = EXIT_FAILURE;
