#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor1 = NULL, *sensor2 = NULL, *led = NULL;
FILE *log_file = NULL;

void cleanup_and_exit(int signum) {
    if (led)
        gpiod_line_set_value(led, 0);
    if (sensor1)
        gpiod_line_release(sensor1);
    if (sensor2)
        gpiod_line_release(sensor2);
    if (led)
        gpiod_line_release(led);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto error;
    }

    sensor1 = gpiod_chip_get_line(chip, GPIO17);
    if (!sensor1) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    sensor2 = gpiod_chip_get_line(chip, GPIO27);
    if (!sensor2) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    led = gpiod_chip_get_line(chip, GPIO22);
    if (!led) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_input(sensor1, "sensor1")) {
        perror("gpiod_line_request_input");
        goto error;
    }

    if (gpiod_line_request_input(sensor2, "sensor2")) {
        perror("gpiod_line_request_input");
        goto error;
    }

    if (gpiod_line_request_output(led, "led", 0)) {
        perror("gpiod_line_request_output");
        goto error;
    }

    log_file = fopen("obstacle_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        goto error;
    }

    while (1) {
        int sensor1_value = gpiod_line_get_value(sensor1);
        if (sensor1_value < 0) {
            perror("gpiod_line_get_value");
            goto error;
        }

        int sensor2_value = gpiod_line_get_value(sensor2);
        if (sensor2_value < 0) {
            perror("gpiod_line_get_value");
            goto error;
        }

        int led_value = sensor1_value && sensor2_value;
        if (gpiod_line_set_value(led, led_value)) {
            perror("gpiod_line_set_value");
            goto error;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_value, sensor2_value, led_value);
        fflush(log_file);

        usleep(100000);
    }

error:
    cleanup_and_exit(0);
    return 1;
}

