#include <stdio.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_MIC_PIN 4
#define GPIO_LED_PIN 17
#define SAMPLE_PERIOD_US 125000
#define PEAK_DURATION_US 100000

static volatile sig_atomic_t stop = 0;

static void signal_handler(int signum)
{
    stop = 1;
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *mic_line, *led_line;
    struct timespec ts;
    struct sigaction act;
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %m\n");
        return 1;
    }

    mic_line = gpiod_chip_get_line(chip, GPIO_MIC_PIN);
    if (!mic_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %m\n", GPIO_MIC_PIN);
        ret = 1;
        goto out_chip;
    }

    ret = gpiod_line_request_rising_edge_events(mic_line, "Microphone");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d: %m\n", GPIO_MIC_PIN);
        ret = 1;
        goto out_mic;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %m\n", GPIO_LED_PIN);
        ret = 1;
        goto out_mic;
    }

    ret = gpiod_line_request_output(led_line, "LED", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d: %m\n", GPIO_LED_PIN);
        ret = 1;
        goto out_led;
    }

    act.sa_handler = signal_handler;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);

    while (!stop) {
        ret = gpiod_line_event_wait(mic_line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %m\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld\n", ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

        gpiod_line_set_value(led_line, 1);
        usleep(PEAK_DURATION_US);
        gpiod_line_set_value(led_line, 0);
    }

    gpiod_line_release(led_line);
out_led:
    gpiod_line_release(mic_line);
out_mic:
    gpiod_chip_close(chip);
out_chip:
    return ret;
}

