#include <libgpiod.h>
#include <unistd.h>

#define GPIO_LINE_LEFT   17
#define GPIO_LINE_CENTER 27
#define GPIO_LINE_RIGHT  22

struct gpiod_chip *chip;
struct gpiod_line *line_left, *line_center, *line_right;

void cleanup_and_exit(int signum) {
    printf("Exiting...\n");
    gpiod_line_release(line_left);
    gpiod_line_release(line_center);
    gpiod_line_release(line_right);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line_left = gpiod_chip_get_line(chip, GPIO_LINE_LEFT);
    if (!line_left) {
        perror("Failed to get left line");
        return 1;
    }

    line_center = gpiod_chip_get_line(chip, GPIO_LINE_CENTER);
    if (!line_center) {
        perror("Failed to get center line");
        return 1;
    }

    line_right = gpiod_chip_get_line(chip, GPIO_LINE_RIGHT);
    if (!line_right) {
        perror("Failed to get right line");
        return 1;
    }

    if (gpiod_line_request_input(line_left, "left sensor", GPIOD_LINE_FLAG_BIAS_PULL_UP)) {
        perror("Failed to request left line");
        return 1;
    }

    if (gpiod_line_request_input(line_center, "center sensor", GPIOD_LINE_FLAG_BIAS_PULL_UP)) {
        perror("Failed to request center line");
        return 1;
    }

    if (gpiod_line_request_input(line_right, "right sensor", GPIOD_LINE_FLAG_BIAS_PULL_UP)) {
        perror("Failed to request right line");
        return 1;
    }

    while (1) {
        int val_left = gpiod_line_get_value(line_left);
        int val_center = gpiod_line_get_value(line_center);
        int val_right = gpiod_line_get_value(line_right);

        if (val_left < 0 || val_center < 0 || val_right < 0) {
            perror("Failed to read line value");
            return 1;
        }

        printf("Left: %d, Center: %d, Right: %d\n", val_left, val_center, val_right);
        usleep(100000);
    }

    return 0;
}
```

This code first opens the GPIO chip and gets references to the three lines corresponding to the sensor GPIO pins. It then requests each line as an active-low input with an internal pull-up resistor. The main loop reads the sensor states and prints them to the console every 100 ms. The cleanup_and_exit function is registered to handle SIGINT and SIGTERM signals, ensuring that the GPIO lines and chip are properly released when the program is interrupted or terminated.

