#include <unistd.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SI1175_I2C_ADDR 0x60
#define SI1175_COMMAND 0x80
#define SI1175_PARAM_ADDR 0xFF
#define SI1175_PARAM_COMMAND 0xA0
#define SI1175_ALS_VIS_DATA_LOW 0x2E
#define SI1175_ALS_VIS_DATA_HIGH 0x2F

int i2c_file = -1;

void cleanup_and_exit(int sig) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    printf("Exiting...\n");
    exit(sig);
}

int main() {
    int ret;
    uint8_t buf[2];
    uint16_t als_data;

    signal(SIGINT, cleanup_and_exit);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        cleanup_and_exit(-1);
    }

    ret = ioctl(i2c_file, I2C_SLAVE, SI1175_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    while (1) {
        buf[0] = SI1175_ALS_VIS_DATA_LOW;
        ret = write(i2c_file, buf, 1);
        if (ret < 0) {
            perror("Failed to write to sensor");
            cleanup_and_exit(-1);
        }

        ret = read(i2c_file, &buf[0], 2);
        if (ret < 0) {
            perror("Failed to read sensor data");
            cleanup_and_exit(-1);
        }

        als_data = (buf[1] << 8) | buf[0];
        printf("ALS data: %u\n", als_data);

        sleep(100);
    }

    cleanup_and_exit(0);
}

