    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return EXIT_FAILURE;
    }

    line_left = gpiod_chip_get_line(chip, LINE_LEFT);
    if (!line_left) {
        fprintf(stderr, "Failed to get line %d.\n", LINE_LEFT);
        ret = EXIT_FAILURE;
        goto err_close_chip;
    }

    line_middle = gpiod_chip_get_line(chip, LINE_MIDDLE);
    if (!line_middle) {
        fprintf(stderr, "Failed to get line %d.\n", LINE_MIDDLE);
        ret = EXIT_FAILURE;
        goto err_release_line_left;
    }

    line_right = gpiod_chip_get_line(chip, LINE_RIGHT);
    if (!line_right) {
        fprintf(stderr, "Failed to get line %d.\n", LINE_RIGHT);
        ret = EXIT_FAILURE;
        goto err_release_line_middle;
    }

    while (1) {
        int val_left, val_middle, val_right;

        val_left = gpiod_line_get_value(line_left);
        if (val_left < 0) {
            fprintf(stderr, "Failed to read line %d.\n", LINE_LEFT);
            ret = EXIT_FAILURE;
            goto err_release_line_right;
        }

        val_middle = gpiod_line_get_value(line_middle);
        if (val_middle < 0) {
            fprintf(stderr, "Failed to read line %d.\n", LINE_MIDDLE);
            ret = EXIT_FAILURE;
            goto err_release_line_right;
        }

        val_right = gpiod_line_get_value(line_right);
        if (val_right < 0) {
            fprintf(stderr, "Failed to read line %d.\n", LINE_RIGHT);
            ret = EXIT_FAILURE;
            goto err_release_line_right;
