#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_NAMES { "TP1", "TP2", "TP3", "TP4", "TP5", "TP6", "TP7", "TP8" }
#define LINE_OFFSETS { 5, 6, 13, 19, 26, 12, 16, 20 }
#define LINE_COUNT 8

struct gpiod_chip *chip;
struct gpiod_line *lines[LINE_COUNT];

void cleanup_and_exit(int signum) {
    for (int i = 0; i < LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    // gcc -o touch_poll touch_poll.c -lrt
    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open chip %s\n", CHIP_NAME);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, LINE_OFFSETS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", LINE_OFFSETS[i]);
            cleanup_and_exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_input(lines[i], LINE_NAMES[i])) {
            fprintf(stderr, "Failed to request line %d\n", LINE_OFFSETS[i]);
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    struct timespec ts;
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%ld.%06lds] ", ts.tv_sec, ts.tv_nsec / 1000);

        for (int i = 0; i < LINE_COUNT; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read line %d\n", LINE_OFFSETS[i]);
                cleanup_and_exit(EXIT_FAILURE);
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        // Sleep for 200 ms
        ts.tv_nsec += 200 * 1000 * 1000;
        while (ts.tv_nsec >= 1000 * 1000 * 1000) {
            ts.tv_nsec -= 1000 * 1000 * 1000;
            ts.tv_sec++;
        }
        nanosleep(&ts, NULL);
    }

    return EXIT_SUCCESS;
}

