#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_PIN_RED 17
#define GPIO_PIN_GREEN 18
#define GPIO_PIN_BLUE 27
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define INTERPOLATION_STEPS 50
#define INTERPOLATION_INTERVAL 5

struct gpiod_chip *chip;
struct gpiod_line *line_red, *line_green, *line_blue;
int fd_urandom;

void cleanup_and_exit(int signum) {
    gpiod_line_set_value(line_red, 0);
    gpiod_line_set_value(line_green, 0);
    gpiod_line_set_value(line_blue, 0);

    gpiod_line_release(line_red);
    gpiod_line_release(line_green);
    gpiod_line_release(line_blue);

    gpiod_chip_close(chip);

    close(fd_urandom);

    closelog();

    exit(signum);
}

int main() {
    openlog("led_fader", LOG_PERROR, LOG_USER);

    fd_urandom = open("/dev/urandom", O_RDONLY);
    if (fd_urandom < 0) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %m");
        closelog();
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        closelog();
        exit(EXIT_FAILURE);
    }

    line_red = gpiod_chip_get_line(chip, GPIO_PIN_RED);
    if (!line_red) {
        syslog(LOG_ERR, "Failed to get red line: %m");
        closelog();
        exit(EXIT_FAILURE);
    }

    line_green = gpiod_chip_get_line(chip, GPIO_PIN_GREEN);
    if (!line_green) {
        syslog(LOG_ERR, "Failed to get green line: %m");
        closelog();
        exit(EXIT_FAILURE);
    }

    line_blue = gpiod_chip_get_line(chip, GPIO_PIN_BLUE);
    if (!line_blue) {
        syslog(LOG_ERR, "Failed to get blue line: %m");
        closelog();
        exit(EXIT_FAILURE);
    }

    struct sigaction action;
    action.sa_handler = cleanup_and_exit;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) < 0 || sigaction(SIGTERM, &action, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %m");
        closelog();
        exit(EXIT_FAILURE);
    }

    while (1) {
        int r, g, b;
        read(fd_urandom, &r, sizeof(r));
        read(fd_urandom, &g, sizeof(g));
        read(fd_urandom, &b, sizeof(b));

        r %= PWM_RANGE + 1;
        g %= PWM_RANGE + 1;
        b %= PWM_RANGE + 1;

        for (int i = 0; i <= INTERPOLATION_STEPS; i++) {
            int r_val = r * i / INTERPOLATION_STEPS;
            int g_val = g * i / INTERPOLATION_STEPS;
            int b_val = b * i / INTERPOLATION_STEPS;

            gpiod_line_set_value(line_red, r_val);
            gpiod_line_set_value(line_green, g_val);
            gpiod_line_set_value(line_blue, b_val);

            usleep(INTERPOLATION_INTERVAL * 1000000 / INTERPOLATION_STEPS);
        }
    }

    return 0;
}

