        for (int i = 0; i <= INTERPOLATION_STEPS; i++) {
            int r_val = r * i / INTERPOLATION_STEPS;
            int g_val = g * i / INTERPOLATION_STEPS;
            int b_val = b * i / INTERPOLATION_STEPS;

            gpiod_line_set_value(line_red, r_val);
            gpiod_line_set_value(line_green, g_val);
            gpiod_line_set_value(line_blue, b_val);

            usleep(INTERPOLATION_INTERVAL * 1000000 / INTERPOLATION_STEPS);
        }
    }

    return 0;
}
