#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_ONE_TIME_H_RES 0x10
#define BH1750_READ_LENGTH 2
#define BH1750_I2C_RETRY 5

#define WS2812B_LED_COUNT 10
#define WS2812B_GPIO 18

static int i2c_file = -1;
static int pwm_file = -1;

void cleanup(int signum) {
    if (i2c_file != -1) close(i2c_file);
    if (pwm_file != -1) close(pwm_file);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C device file
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("Failed to open I2C device file");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_file, I2C_SLAVE, BH1750_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Open PWM device file
    pwm_file = open("/dev/pwm/pwmchip0/pwm0", O_RDWR);
    if (pwm_file == -1) {
        perror("Failed to open PWM device file");
        return 1;
    }

    // Enable PWM
    if (write(pwm_file, "1", 1) != 1) {
        perror("Failed to enable PWM");
        return 1;
    }

    // Set PWM period
    if (write(pwm_file, "1000000", 7) != 7) {
        perror("Failed to set PWM period");
        return 1;
    }

    // Main loop
    while (1) {
        // Send sensor command
        if (write(i2c_file, &BH1750_CMD_ONE_TIME_H_RES, 1) != 1) {
            perror("Failed to send sensor command");
            continue;
        }

        usleep(180000);

        // Read sensor data
        uint8_t data[BH1750_READ_LENGTH];
        if (read(i2c_file, data, BH1750_READ_LENGTH) != BH1750_READ_LENGTH) {
            perror("Failed to read sensor data");
            continue;
        }

        // Calculate lux value
        uint16_t lux = (data[0] << 8) | data[1];

        // Map lux to LED brightness
        int brightness = log(lux) * (WS2812B_LED_COUNT - 1) / log(65535);

        // Write brightness to PWM
        char brightness_str[3];
        sprintf(brightness_str, "%d", brightness);
        if (write(pwm_file, brightness_str, strlen(brightness_str)) != strlen(brightness_str)) {
            perror("Failed to write brightness to PWM");
            continue;
        }
    }

    return 0;
}

