#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <string.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_POWER_ON 0x03
#define BH1750_CMD_ONE_TIME_HIGH_RES 0x10
#define APA102_START_FRAME 0x00000000
#define APA102_END_FRAME 0xFFFFFFFF
#define LED_COUNT 30

int i2c_fd, spi_fd;

void handle_sigint(int signum) {
    // Turn off all LEDs
    uint32_t off_frame = 0x000000FF;
    for (int i = 0; i < LED_COUNT; i++) {
        if (write(spi_fd, &off_frame, sizeof(off_frame)) < 0) {
            perror("Failed to write to SPI device");
            exit(EXIT_FAILURE);
        }
    }
    // End frame
    if (write(spi_fd, &APA102_END_FRAME, sizeof(APA102_END_FRAME)) < 0) {
        perror("Failed to write to SPI device");
        exit(EXIT_FAILURE);
    }
    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    // Set SPI parameters
    uint32_t spi_mode = SPI_MODE_0;
    uint32_t spi_max_speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_max_speed) < 0) {
        perror("Failed to set SPI parameters");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Power on sensor
        if (write(i2c_fd, &BH1750_CMD_POWER_ON, 1) < 0) {
            perror("Failed to write to I2C device");
            exit(EXIT_FAILURE);
        }
        // Start measurement
        if (write(i2c_fd, &BH1750_CMD_ONE_TIME_HIGH_RES, 1) < 0) {
            perror("Failed to write to I2C device");
            exit(EXIT_FAILURE);
        }
        // Wait for measurement
        usleep(120000);
        // Read measurement
        uint16_t light_level;
        if (read(i2c_fd, &light_level, sizeof(light_level)) < 0) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }
        // Scale light level to LED brightness
        uint32_t brightness = (light_level * 255) / 65535;
        uint32_t led_frame = 0x00000000 | (brightness << 24) | (brightness << 16) | (brightness << 8) | 0xFF;

        // Start frame
        if (write(spi_fd, &APA102_START_FRAME, sizeof(APA102_START_FRAME)) < 0) {
            perror("Failed to write to SPI device");
            exit(EXIT_FAILURE);
        }
        // LED frames
        for (int i = 0; i < LED_COUNT; i++) {
            if (write(spi_fd, &led_frame, sizeof(led_frame)) < 0) {
                perror("Failed to write to SPI device");
                exit(EXIT_FAILURE);
            }
        }
        // End frame
        if (write(spi_fd, &APA102_END_FRAME, sizeof(APA102_END_FRAME)) < 0) {
            perror("Failed to write to SPI device");
            exit(EXIT_FAILURE);
        }
    }

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

