    printf("Startup self-test at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

    for (int i = 0; i < 2; i++) {
        gpiod_line_set_value(line_led, 1);
        usleep(500000);
        gpiod_line_set_value(line_led, 0);
        usleep(500000);
    }

    int flame_detected = 0;
    for (int i = 0; i < 5; i++) {
        int value = gpiod_line_get_value(line_flame_sensor);
        if (value < 0) {
            perror("gpiod_line_get_value");
            cleanup_and_exit(1);
        }
        if (value == 0) {
            flame_detected = 1;
        }
        usleep(100000);
    }

    if (flame_detected) {
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("Flame detected at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        gpiod_line_set_value(line_led, 1);
        gpiod_line_set_value(line_buzzer, 1);
        for (int i = 0; i < 5; i++) {
            usleep(200000);
            gpiod_line_set_value(line_buzzer, 0);
            usleep(200000);
            gpiod_line_set_value(line_buzzer, 1);
            usleep(600000);
            gpiod_line_set_value(line_buzzer, 0);
            usleep(200000);
        }
        cleanup_and_exit(1);
    }

    signal(SIGINT, cleanup_and_exit);

    int prev_value = 1;
    while (1) {
        int value = gpiod_line_get_value(line_flame_sensor);
        if (value < 0) {
            perror("gpiod_line_get_value");
            cleanup_and_exit(1);
        }
        if (value != prev_value) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Flame %s at %ld.%09ld\n", value ? "cleared" : "detected", ts.tv_sec, ts.tv_nsec);
            gpiod_line_set_value(line_led, value);
            gpiod_line_set_value(line_buzzer, value);
        }
        prev_value = value;
        usleep(50000);
    }

    return 0;
}

