#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define GPIO 17
#define NUM_SAMPLES 60

volatile sig_atomic_t stop = 0;
int i2c_file_desc, gpio_file_desc;
float samples[NUM_SAMPLES];
int sample_index = 0;
float sum = 0;

void sigint_handler(int signum) {
    stop = 1;
}

void cleanup() {
    if (gpio_file_desc > 0) {
        write(gpio_file_desc, "0", 1);
        close(gpio_file_desc);
    }
    if (i2c_file_desc > 0) {
        close(i2c_file_desc);
    }
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    i2c_file_desc = open(I2C_DEV, O_RDWR);
    if (i2c_file_desc < 0) {
        perror("Could not open I2C device");
        cleanup();
    }

    if (ioctl(i2c_file_desc, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Could not set I2C slave");
        cleanup();
    }

    gpio_file_desc = open("/sys/class/gpio/gpio" #GPIO "/value", O_RDWR);
    if (gpio_file_desc < 0) {
        perror("Could not open GPIO");
        cleanup();
    }

    while (!stop) {
        char buf[2] = {0x10, 0x00};
        if (write(i2c_file_desc, buf, 2) != 2) {
            perror("Could not write to I2C");
            continue;
        }

        usleep(18000);

        if (read(i2c_file_desc, buf, 2) != 2) {
            perror("Could not read from I2C");
            continue;
        }

        float lux = ((buf[0] << 8) | buf[1]) * 0.003125;
        samples[sample_index] = lux;
        sum += lux - samples[sample_index];
        sample_index = (sample_index + 1) % NUM_SAMPLES;

        float avg_lux = sum / NUM_SAMPLES;
        int freq = 500 + avg_lux * 4.5;
        char freq_str[5];
        sprintf(freq_str, "%d", freq);
        write(gpio_file_desc, freq_str, strlen(freq_str));

        sleep(1);
    }

    cleanup();
    return 0;
}

