#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

struct gpiod_line *led_line;
struct gpiod_line *button_line;
struct gpiod_chip *chip;
struct gpiod_line_request request;

void cleanup_and_exit(int signum)
{
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

int main()
{
    int ret;

    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_output_flags(&request, led_line, "led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output_flags");
        return 1;
    }

    button_line = gpiod_chip_get_line(chip, 18);
    if (!button_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_input_flags(&request, button_line, "button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP | GPIOD_LINE_REQUEST_FLAG_EDGE_FALLING);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags");
        return 1;
    }

    while (1) {
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            return 1;
        }

        ret = gpiod_line_event_wait(&request, 1000000000);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            return 1;
        }

        if (ret == 1) {
            struct gpiod_line_event event;

            ret = gpiod_line_event_read(&request, &event);
            if (ret < 0) {
                perror("gpiod_line_event_read");
                return 1;
            }

            printf("Button pressed!\n");
            cleanup_and_exit(0);
        }

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            return 1;
        }

        ret = gpiod_line_event_wait(&request, 1000000000);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            return 1;
        }
    }

    return 0;
}

