#include <stdio.h>
#include <unistd.h>

#define LED_GPIO 24
#define BUTTON_GPIO 22

struct gpiod_chip *chip;
struct gpiod_line *led_line, *button_line;

void cleanup_and_exit(int sig) {
    if (led_line)
        gpiod_line_release(led_line);
    if (button_line)
        gpiod_line_release(button_line);
    if (chip)
        gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        return 1;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led-demo", 0)) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input(button_line, "button-demo")) {
        fprintf(stderr, "Failed to request button line as input: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int button_value = gpiod_line_get_value(button_line);
        if (button_value < 0) {
            fprintf(stderr, "Failed to read button value: %s\n", strerror(errno));
            return 1;
        }

        if (button_value) {
            if (gpiod_line_set_value(led_line, 1)) {
                fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
                return 1;
            }
            usleep(500000);

            if (gpiod_line_set_value(led_line, 0)) {
                fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
                return 1;
            }
            usleep(500000);
        } else {
            if (gpiod_line_set_value(led_line, 0)) {
                fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
                return 1;
            }
        }
    }

    return 0;
}

