#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

struct gpiod_chip *chip;
struct gpiod_line *red, *green, *blue;

void sigint_handler(int signum) {
    gpiod_line_release(red);
    gpiod_line_release(green);
    gpiod_line_release(blue);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    srand(time(NULL));
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    red = gpiod_chip_get_line(chip, 24);
    if (!red) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    green = gpiod_chip_get_line(chip, 23);
    if (!green) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    blue = gpiod_chip_get_line(chip, 18);
    if (!blue) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    while (1) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        for (int i = 0; i < 100; i++) {
            if (i < r)
                gpiod_line_set_value(red, 1);
            else
                gpiod_line_set_value(red, 0);

            if (i < g)
                gpiod_line_set_value(green, 1);
            else
                gpiod_line_set_value(green, 0);

            if (i < b)
                gpiod_line_set_value(blue, 1);
            else
                gpiod_line_set_value(blue, 0);

            struct timespec ts = { .tv_sec = 0, .tv_nsec = 10000000 };
            clock_nanosleep(CLOCK_REALTIME, 0, &ts, NULL);
        }
    }

    return 0;
}

