#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <time.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_file;
double threshold;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_file);
    fclose(log_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    threshold = DEFAULT_THRESHOLD;
    if (argc > 1 && strncmp(argv[1], "-t", 2) == 0) {
        threshold = atof(argv[2]);
    }

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_output(line, "accel_check", 0) < 0) {
        perror("gpiod_line_request_output");
        exit(1);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, ACCEL_ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }

