#define I2C_BUS 1
#define I2C_ADDR 0x1C
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG1_VAL 0x80
#define CTRL_REG2 0x2B
#define CTRL_REG2_VAL 0x00
#define CTRL_REG4 0x2D
#define CTRL_REG4_VAL 0x80
#define OUT_X_MSB 0x33
#define OUT_Y_MSB 0x35
#define OUT_Z_MSB 0x37
#define THRESH_ACT 0x24
#define THRESH_ACT_VAL 0x08
#define DUR 0x25
#define DUR_VAL 0x01
#define ACT_EN_REG 0x27
#define ACT_EN_REG_VAL 0x01
#define IMPACT_THRESHOLD 10.0

static int i2c_file;

void sigint_handler(int signum) {
    close(i2c_file);
    exit(0);
}

int i2c_write_reg(int file, int addr, unsigned char reg, unsigned char val) {
    unsigned char buf[2] = {reg, val};
    if (write(file, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int i2c_read_reg(int file, int addr, unsigned char reg, unsigned char *val) {
    if (write(file, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    if (read(file, val, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Could not open I2C device file");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Could not set I2C device address");
        return 1;
    }

    unsigned char who_am_i;
    if (i2c_read_reg(i2c_file, I2C_ADDR, WHO_AM_I_REG, &who_am_i) < 0) {
        return 1;
    }

    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Unexpected device ID: 0x%02X\n", who_am_i);
        return 1;
    }

    if (i2c_write_reg(i2c_file, I2C_ADDR, CTRL_REG1, CTRL_REG1_VAL) < 0) {
        return 1;
    }

    if (i2c_write_reg(i2c_file, I2C_ADDR, CTRL_REG2, CTRL_REG2_VAL) < 0) {
        return 1;
    }

    if (i2c_write_reg(i2c_file, I2C_ADDR, CTRL_REG4, CTRL_REG4_VAL) < 0) {
        return 1;
    }

    if (i2c_write_reg(i2c_file, I2C_ADDR, THRESH_ACT, THRESH_ACT_VAL) < 0) {
        return 1;
    }

    if (i2c_write_reg(i2c_file, I2C_ADDR, DUR, DUR_VAL) < 0) {
        return 1;
    }

    if (i2c_write_reg(i2c_file, I2C_ADDR, ACT_EN_REG, ACT_EN_REG_VAL) < 0) {
        return 1;
    }

    FILE *impact_log = fopen("impact_log.txt", "a");
    if (impact_log == NULL) {
        perror("Could not open impact log file");
        return 1;
    }

    while (1) {
        unsigned char x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
        if (i2c_read_reg(i2c_file, I2C_ADDR, OUT_X_MSB, &x_msb) < 0) {
            return 1;
        }
        if (i2c_read_reg(i2c_file, I2C_ADDR, OUT_Y_MSB, &y_msb) < 0) {
            return 1;
        }
        if (i2c_read_reg(i2c_file, I2C_ADDR, OUT_Z_MSB, &z_msb) < 0) {
            return 1;
        }

        x_lsb = (x_msb >> 4) & 0x0F;
        y_lsb = (y_msb >> 4) & 0x0F;
        z_lsb = (z_msb >> 4) & 0x0F;

        int x = ((x_msb << 4) | x_lsb);
        int y = ((y_msb << 4) | y_lsb);
        int z = ((z_msb << 4) | z_lsb);

        if (x > 0x7FFF) x -= 0xFFFF;
        if (y > 0x7FFF) y -= 0xFFFF;
        if (z > 0x7FFF) z -= 0xFFFF;

        double magnitude = sqrt(x*x + y*y + z*z);

        if (magnitude > IMPACT_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

            fprintf(impact_log, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
        }

        usleep(50000);
    }

    fclose(impact_log);
    close(i2c_file);

    return 0;
}

