#define GYRO_ADDR 0x68
#define GYRO_WHOAMI 0x0F
#define EXPECTED_WHOAMI 0xD3
#define REG_CTRL_REG1 0x20
#define REG_OUT_X_L 0x28
#define REG_OUT_Y_L 0x2A
#define REG_OUT_Z_L 0x2C
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50
#define LOG_FILE "gyro_log.txt"

volatile sig_atomic_t stop = 0;
int i2c_file = -1;
FILE* log_file = NULL;

void cleanup_and_exit(int sig) {
    if (i2c_file != -1) close(i2c_file);
    if (log_file != NULL) fclose(log_file);
    exit(sig);
}

void signal_handler(int sig) {
    stop = 1;
    cleanup_and_exit(sig);
}

int main() {
    struct i2c_msg msgs[2];
    int i;
    float x_offset = 0, y_offset = 0, z_offset = 0;
    float x, y, z;
    char timestamp[20];
    struct tm* timeinfo;
    time_t now;
    uint8_t whoami;
    uint8_t buf[6];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, GYRO_ADDR) == -1) {
        perror("ioctl");
        cleanup_and_exit(EXIT_FAILURE);
    }

    msgs[0].addr = GYRO_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &GYRO_WHOAMI;
    msgs[1].addr = GYRO_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 1;
    msgs[1].buf = &whoami;

