        perror("read");
        exit(1);
    }

    if (buf[0] != EXPECTED_DEV_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02x\n", buf[0]);
        exit(1);
    }

    buf[0] = 0x2D;
    buf[1] = RANGE_2G | FULL_RES;
    if (write(fd, buf, 2) != 2) {
        perror("write");
        exit(1);
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    line = gpiod_chip_get_line(chip, LED_GPIO);
    gpiod_line_request_output(line, "accel_led", 0);

    led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);

    log_file = fopen("accel_log.txt", "w");

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        usleep(100000);

        buf[0] = DATAX0;
        if (write(fd, buf, 1) != 1) {
            perror("write");
            continue;
        }

        unsigned char data[6];
        if (read(fd, data, 6) != 6) {
            perror("read");
            continue;
        }

        int x = (data[1] << 8) | data[0];
        int y = (data[3] << 8) | data[2];
        int z = (data[5] << 8) | data[4];

        if (x & 0x8000 || y & 0x8000 || z & 0x8000) {
            x -= 0x10000;
            y -= 0x10000;
            z -= 0x10000;
        }

        x /= 16384.0;
        y /= 16384.0;
        z /= 16384.0;

        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char time_str[16];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tmp);

        fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", time_str, x, y, z);

        if (x > 2.0 || x < -2.0 || y > 2.0 || y < -2.0 || z > 2.0 || z < -2.0) {
            gpiod_line_set_value(line, 1);
            write(led_fd, "1", 1);
        } else {
            gpiod_line_set_value(line, 0);
            write(led_fd, "0", 1);
        }
    }

    return 0;
}

