#include <signal.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29

#define VL6180X_REG_SYSRANGE_START 0x00
#define VL6180X_REG_SYSRANGE_RESULT 0x14

static struct gpiod_device *dev;
static struct gpiod_line *line;

static volatile int stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

static int write_to_file(const char *str) {
    FILE *file = fopen("distance_log.txt", "a");
    if (!file) {
        printf("Failed to open file for writing\n");
        return -1;
    }
    fprintf(file, "%s\n", str);
    fclose(file);
    return 0;
}

static int read_distance(void) {
    int fd = open("/dev/i2c-" #I2C_BUS, O_RDWR);
    if (fd < 0) {
        printf("Failed to open I2C device\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to set I2C slave address\n");
        close(fd);
        return -1;
    }

    uint8_t reg = VL6180X_REG_SYSRANGE_START;
    uint8_t data = 0x01;
    if (write(fd, &reg, 1) != 1 || write(fd, &data, 1) != 1) {
        printf("Failed to write to VL6180X\n");
        close(fd);
        return -1;
    }

    usleep(30000);

    reg = VL6180X_REG_SYSRANGE_RESULT;
    if (write(fd, &reg, 1) != 1) {
        printf("Failed to write to VL6180X\n");
        close(fd);
        return -1;
    }

    uint16_t distance;
    if (read(fd, &distance, 2) != 2) {
        printf("Failed to read from VL6180X\n");
        close(fd);
        return -1;
    }

    close(fd);

    return distance;
}

int main(void) {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    while (!stop) {
        int distance = read_distance();
        if (distance < 0) {
            printf("Failed to read distance, re-initializing sensor\n");
            // Re-initialize sensor here
            continue;
        }

        char buffer[256];
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        sprintf(buffer, "%d-%02d-%02d %02d:%02d:%02d Distance: %d",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);

        if (write_to_file(buffer) < 0) {
            printf("Failed to write to file\n");
            break;
        }

        const char *status = distance < 100 ? "DOOR_OPEN" : "DOOR_CLOSED";
        if (write_to_file(status) < 0) {
            printf("Failed to write to file\n");
            break;
        }

        usleep(100000);
    }

    return 0;
}

