#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_GPIO 8
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define STALL_TIME 40
#define SAMPLE_TIME 100
#define CSV_FILE "imu_data.csv"
#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

volatile sig_atomic_t running = 1;

int spi_handle = -1;
FILE *csv_file = NULL;

void cleanup(void) {
    if (spi_handle != -1) {
        close(spi_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    printf("Exiting...\n");
    exit(0);
}

void handle_signal(int signum) {
    running = 0;
}

void non_blocking_delay(int microseconds) {
    struct timespec req = { .tv_sec = microseconds / 1000000, .tv_nsec = (microseconds % 1000000) * 1000 };
    while (running && nanosleep(&req, &req) == -1 && errno == EINTR) {}
}

int main(void) {
    struct spi_ioc_transfer xfer;
    uint16_t command, response;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    atexit(cleanup);

    spi_handle = open(SPI_DEV, O_RDWR);
    if (spi_handle == -1) {
        perror("open");
        return -1;
    }

    ret = ioctl(spi_handle, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(spi_handle, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("ioctl");
        return -1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    while (running) {
        for (int i = 0; i < 6; i++) {
            command = (1 << 15) | (i << 8);
            xfer.tx_buf = (unsigned long)&command;
            xfer.rx_buf = (unsigned long)&response;
            xfer.len = 2;
            xfer.delay_usecs = STALL_TIME;
            xfer.speed_hz = SPI_SPEED;
            xfer.bits_per_word = 16;

            ret = ioctl(spi_handle, SPI_IOC_MESSAGE(1), &xfer);
            if (ret == -1) {
                perror("ioctl");
                return -1;
            }

            int16_t value = (int16_t)response;
            double converted_value;

            if (i < 3) {
                converted_value = value * GYRO_SENSITIVITY;
            } else {
                converted_value = value * ACCEL_SENSITIVITY;
            }

            fprintf(csv_file, "%ld,", time(NULL));
            fprintf(csv_file, "%f,", converted_value);
        }

        fprintf(csv_file, "\n");
        non_blocking_delay(SAMPLE_TIME);
    }

    return 0;
}

