#define READ_CMD 0xA000
#define DUMMY_VAL 0x0000
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

static int spi_fd = -1;

void handle_sigint(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

int main() {
    struct spi_ioc_transfer xfer[2];
    uint16_t cmd = READ_CMD, dummy = DUMMY_VAL, data;
    float scaled_data;

    signal(SIGINT, handle_sigint);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        perror("Failed to set SPI mode");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, 0) < 0) {
        perror("Failed to set MSB first");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 16) < 0) {
        perror("Failed to set bits per word");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, GPIO_CS) < 0) {
        perror("Failed to set CS GPIO");
        return EXIT_FAILURE;
    }

    while (1) {
        xfer[0].tx_buf = (unsigned long)&cmd;
        xfer[0].rx_buf = NULL;
        xfer[0].len = 2;
        xfer[0].delay_usecs = 0;
        xfer[0].speed_hz = SPI_SPEED;
        xfer[0].bits_per_word = 16;

        xfer[1].tx_buf = (unsigned long)&dummy;
        xfer[1].rx_buf = (unsigned long)&data;
        xfer[1].len = 2;
        xfer[1].delay_usecs = 40;
        xfer[1].speed_hz = SPI_SPEED;
        xfer[1].bits_per_word = 16;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer) < 0) {
            perror("Failed to send SPI message");
            return EXIT_FAILURE;
        }

        scaled_data = (float)data * (cmd & 0x8000 ? GYRO_SCALE : ACCEL_SCALE);
        printf("Data: %u, Scaled: %.2f\n", data, scaled_data);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

