#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define ADXL345_ADDR 0x53
#define DEVICE_ID 0xE5
#define DATAX0 0x32
#define CTRL_REG1 0x2A
#define CTRL_REG4 0x2E
#define THRESH_ACT 0x24
#define ACT_INACT_CTRL 0x2C
#define LED_GPIO 17
#define I2C_BUS 1
#define THRESHOLD 256 * 2.5

int i2c_file;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    close(i2c_file);
    fclose(log_file);
    exit(signum);
}

int main() {
    log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        exit(1);
    }

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (chip == NULL) {
        printf("Failed to open GPIO chip\n");
        cleanup_and_exit(1);
    }

    line = gpiod_chip_get_line(chip, LED_GPIO);
    if (line == NULL) {
        printf("Failed to get GPIO line\n");
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_output(line, "accelerometer", 0) < 0) {
        printf("Failed to request GPIO line as output\n");
        cleanup_and_exit(1);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        printf("Failed to open I2C device\n");
        cleanup_and_exit(1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, ADXL345_ADDR) < 0) {
        printf("Failed to set I2C slave address\n");
        cleanup_and_exit(1);
    }

    if (ioctl(i2c_file, I2C_TEN, 0) < 0) {
        printf("Failed to disable I2C 10-bit addressing\n");
        cleanup_and_exit(1);
    }

    unsigned char device_id;
    if (read(i2c_file, &device_id, 1) != 1 || device_id != DEVICE_ID) {
        printf("Failed to read device ID\n");
        cleanup_and_exit(1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        usleep(10000);

        unsigned char data[6];
        if (pread(i2c_file, &data, 6, DATAX0) != 6) {
            printf("Failed to read accelerometer data\n");
            cleanup_and_exit(1);
        }

        int x = (data[1] << 8) | data[0];
        int y = (data[3] << 8) | data[2];
        int z = (data[5] << 8) | data[4];

        double magnitude = sqrt(x*x + y*y + z*z);
        if (magnitude > THRESHOLD) {
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm);

            fprintf(log_file, "%s, %f, %d, %d, %d\n", timestamp, magnitude, x, y, z);
            fflush(log_file);

            gpiod_line_set_value(line, 1);
            usleep(500000);
            gpiod_line_set_value(line, 0);
        }
    }

    cleanup_and_exit(0);
}

