#include <sys/ioctl.h>
#include <time.h>

#define IMU_ADDRESS 0x68
#define ACCEL_REG 0x3B
#define GYRO_REG 0x43
#define I2C_BUS 1
#define IMU_LOG_FILE "imu_log.csv"

static int imu_fd = -1;
static FILE *log_file = NULL;

void handle_sigint(int signum) {
    if (imu_fd != -1) {
        close(imu_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timespec ts;
    unsigned char buf[12];
    int ret;

    signal(SIGINT, handle_sigint);

    imu_fd = open("/dev/i2c-" #I2C_BUS, O_RDWR);
    if (imu_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    ret = ioctl(imu_fd, I2C_SLAVE, IMU_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave");
        return EXIT_FAILURE;
    }

    log_file = fopen(IMU_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (1) {
        ret = read(imu_fd, buf, sizeof(buf));
        if (ret < 0) {
            perror("Failed to read from IMU");
            return EXIT_FAILURE;
        }

        clock_gettime(CLOCK_REALTIME, &ts);

        fprintf(log_file, "%ld,%ld,", ts.tv_sec, ts.tv_nsec);
        for (int i = 0; i < 6; i++) {
            fprintf(log_file, "%d,", (int8_t)buf[i]);
        }
        for (int i = 6; i < 12; i++) {
            fprintf(log_file, "%d,", (int16_t)((buf[i] << 8) | buf[i + 1]));
        }
        fprintf(log_file, "\n");

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

