#define MMA8451_ADDR 0x1C
#define ID_REG 0x0D
#define ID_VAL 0x2A
#define OUT_X_MSB 0x01
#define OUT_Y_MSB 0x03
#define OUT_Z_MSB 0x05
#define GPIO_LED 17

static int fd_i2c = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

static void cleanup_and_exit(int sig) {
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (fd_i2c >= 0)
        close(fd_i2c);
    if (log_file)
        fclose(log_file);
    exit(sig);
}

int main() {
    fd_i2c = open("/dev/i2c-1", O_RDWR);
    if (fd_i2c < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd_i2c, I2C_SLAVE, MMA8451_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835.0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup_and_exit(-1);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LED);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_output(gpio_line, "accel_led", 0) < 0) {
        perror("Failed to request GPIO line");
        cleanup_and_exit(-1);
    }

    log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_and_exit(-1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    uint8_t id;
    if (read(fd_i2c, &id, 1) != 1 || id != ID_VAL) {
        fprintf(stderr, "Failed to verify sensor identity\n");
        cleanup_and_exit(-1);
    }

    while (1) {
        uint8_t buf[6];
        if (read(fd_i2c, buf, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            cleanup_and_exit(-1);
        }

        int x = (buf[1] << 8) | buf[0];
        int y = (buf[3] << 8) | buf[2];
        int z = (buf[5] << 8) | buf[4];

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "%02d:%02d:%02d, %d, %d, %d\n", tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);

        if (x > 2048 || y > 2048 || z > 2048) {
            gpiod_line_set_value(gpio_line, 1);
            usleep(500000);
            gpiod_line_set_value(gpio_line, 0);
        }

        usleep(100000);
    }

    return 0;
}

