#define ADXL345_POWER_CTL_STANDBY 0x00
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_DATA_RATE 0x2C
#define ADXL345_DATA_RATE_100HZ 0x0A
#define ADXL345_FIFO_CTL 0x31
#define ADXL345_FIFO_CTL_STREAM 0x1F
#define ADXL345_INT_ENABLE 0x1E
#define ADXL345_INT1_MAP 0x21
#define ADXL345_FMT_8BIT 0x00
#define ADXL345_FMT_16BIT 0x08
#define ADXL345_FMT_DATA_RATE 0x07

