static void write_log(struct adxl345_data *data, int x, int y, int z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(data->log_file, "%ld.%03ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
    fflush(data->log_file);
}

static void handle_interrupt(struct adxl345_data *data)
{
    int x, y, z;
    if (ioctl(data->i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("I2C_SLAVE");
        return;
    }
    if (write(data->i2c_fd, &ADXL345_REG_DATAX, 1) != 1) {
        perror("write");
        return;
    }
    if (read(data->i2c_fd, &x, 2) != 2) {
        perror("read");
        return;
    }
    if (read(data->i2c_fd, &y, 2) != 2) {
        perror("read");
        return;
    }
    if (read(data->i2c_fd, &z, 2) != 2) {
        perror("read");
        return;
    }
    write_log(data, x, y, z);
}

static void signal_handler(int signum)
{
    struct adxl345_data *data = &adxl345_data;
    if (ioctl(data->i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("I2C_SLAVE");
    }
    if (write(data->i2c_fd, &ADXL345_POWER_CTL, 1) != 1) {
        perror("write");
    }
    if (write(data->i2c_fd, &ADXL345_POWER_CTL_STANDBY, 1) != 1) {
        perror("write");
