    line_config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING;
    line_config.event_buffer_size = 10;

    ret = gpiod_line_request_event_raw(adxl345_data.line, &line_config);
    if (ret < 0) {
        perror("gpiod_line_request_event_raw");
        return 1;
    }

    adxl345_data.log_file = fopen("freefall_log.csv", "w");
    if (!adxl345_data.log_file) {
        perror("fopen");
        return 1;
    }
    fprintf(adxl345_data.log_file, "Timestamp,X,Y,Z\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (ioctl(adxl345_data.i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("I2C_SLAVE");
        return 1;
    }

    if (write(adxl345_data.i2c_fd, &ADXL345_POWER_CTL, 1) != 1) {
        perror("write");
        return 1;
    }

    if (write(adxl345_data.i2c_fd, &ADXL345_POWER_CTL_MEASURE, 1) != 1) {
        perror("write");
        return 1;
    }

    while (1) {
        ret = gpiod_line_event_read(adxl345_data.line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            return 1;
        }
        handle_interrupt(&adxl345_data);
    }

    return 0;
}

