#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define I2C_BUS 1
#define IMU_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x69
#define CTRL_REG1 0x10
#define CTRL_REG2 0x11
#define CTRL_REG3 0x12
#define CTRL_REG4 0x13
#define CTRL_REG5 0x14
#define OUT_X_L 0x18
#define OUT_Y_L 0x1A
#define OUT_Z_L 0x1C
#define FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_SIZE 1.0

enum state {IDLE, FREEFALL, IMPACT};

struct imu_data {
    struct gpiod_chip *chip;
    struct gpiod_line *scl_line;
    struct gpiod_line *sda_line;
    FILE *log_file;
    enum state state;
    struct timespec last_fall;
};

void cleanup(struct imu_data *data) {
    fclose(data->log_file);
    gpiod_line_release(data->scl_line);
    gpiod_line_release(data->sda_line);
    gpiod_chip_close(data->chip);
    free(data);
}

void handle_signal(int signum) {
    struct imu_data *data = (struct imu_data *)malloc(sizeof(struct imu_data));
    cleanup(data);
    exit(0);
}

int main() {
    struct imu_data *data = (struct imu_data *)malloc(sizeof(struct imu_data));
    data->chip = gpiod_chip_open_by_number(I2C_BUS);
    if (!data->chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }
    data->scl_line = gpiod_chip_get_line(data->chip, 3);
    data->sda_line = gpiod_chip_get_line(data->chip, 2);
    if (!data->scl_line || !data->sda_line) {
        fprintf(stderr, "Failed to get I2C lines\n");
        cleanup(data);
        return 1;
    }
    if (gpiod_line_request_i2c(data->scl_line, data->sda_line, IMU_ADDR)) {
        fprintf(stderr, "Failed to request I2C lines\n");
        cleanup(data);
        return 1;
    }
    data->log_file = fopen("motion_log.txt", "w");
    if (!data->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(data);
        return 1;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    data->state = IDLE;
    clock_gettime(CLOCK_REALTIME, &data->last_fall);
    while (1) {
        int8_t x, y, z;
        if (gpiod_line_i2c_read(data->scl_line, data->sda_line, OUT_X_L, &x, 1) ||
            gpiod_line_i2c_read(data->scl_line, data->sda_line, OUT_Y_L, &y, 1) ||
            gpiod_line_i2c_read(data->scl_line, data->sda_line, OUT_Z_L, &z, 1)) {
            fprintf(stderr, "Failed to read IMU data\n");
            cleanup(data);
            return 1;
        }
        double magnitude = sqrt(x*x + y*y + z*z);
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        double time_diff = (now.tv_sec - data->last_fall.tv_sec) +
                           (now.tv_nsec - data->last_fall.tv_nsec) * 1e-9;
        switch (data->state) {
        case IDLE:
            if (magnitude < FALL_THRESHOLD && time_diff >= WINDOW_SIZE) {
                data->state = FREEFALL;
                data->last_fall = now;
            }
            break;
        case FREEFALL:
            if (magnitude > IMPACT_THRESHOLD) {
                data->state = IMPACT;
                fprintf(data->log_file, "IMPACT at %ld.%09ld\n", now.tv_sec, now.tv_nsec);
            } else if (magnitude >= FALL_THRESHOLD) {
                data->state = IDLE;
            }
            break;
        case IMPACT:
            if (magnitude < FALL_THRESHOLD) {
                data->state = FREEFALL;
                data->last_fall = now;
            }
            break;
        }
        fprintf(data->log_file, "%ld.%09ld, %f\n", now.tv_sec, now.tv_nsec, magnitude);
    }
    return 0;
}

