    spi = spi_open_device(SPI_DEVICE, CS_GPIO, SPI_MODE, SPI_FREQUENCY);
    if (!spi) {
        printf("Failed to open SPI device\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        spi_close(spi);
        return 1;
    }

    fprintf(log_file, "timestamp,x_angle_rate,y_angle_rate,z_angle_rate\n");

    uint16_t tx_buf[2] = {0};
    uint16_t rx_buf[2] = {0};

