        printf("Unexpected device ID: 0x%04x\n", rx_buf[0]);
        spi_close(spi);
        fclose(log_file);
        return 1;
    }

    while (1) {
        tx_buf[0] = ANG_OUT_REG | 0x8000;
        if (spi_transfer(spi, tx_buf, rx_buf, 2)) {
            printf("Failed to read angular rate\n");
            spi_close(spi);
            fclose(log_file);
            return 1;
