#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c.h>

#define GYRO_ADDRESS 0x68
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG1_VAL 0x08
#define OUT_X_L 0x28
#define SAMPLE_DELAY 10000

static int fd;
static FILE *csv_file;

void sigint_handler(int signum) {
    close(fd);
    fclose(csv_file);
    exit(0);
}

int i2c_write_read(int reg, char *buf, int len) {
    struct i2c_msg msgs[] = {
        {
            .addr = GYRO_ADDRESS,
            .flags = 0,
            .len = 1,
            .buf = &reg,
        },
        {
            .addr = GYRO_ADDRESS,
            .flags = I2C_M_RD,
            .len = len,
            .buf = buf,
        },
    };

    if (ioctl(fd, I2C_RDWR, msgs) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    char buf[1];
    for (int i = 0; i < 3; i++) {
        if (i2c_write_read(WHO_AM_I_REG, buf, 1) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I register\n");
            continue;
        }

        if (buf[0] == WHO_AM_I_VAL)
            break;
    }

    if (buf[0] != WHO_AM_I_VAL) {
        fprintf(stderr, "Gyroscope not found\n");
        return 1;
    }

    if (i2c_write_read(CTRL_REG1, &CTRL_REG1_VAL, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    csv_file = fopen("gyro_log.csv", "w");
    if (csv_file == NULL) {
        perror("fopen");
        return 1;
    }

    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    while (1) {
        char data[6];
        if (i2c_write_read(OUT_X_L, data, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        fprintf(csv_file, "%ld.%09ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec,
                (float)data[0] / 114.285, (float)data[2] / 114.285, (float)data[4] / 114.285);

        fflush(csv_file);

        usleep(SAMPLE_DELAY);
    }

    return 0;
}

