#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_FLAME_SENSOR 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t stop = 0;
FILE *log_file = NULL;

void sigint_handler(int signum) {
    stop = 1;
}

void log_message(const char *message, int is_error) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);

    if (is_error && log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: could not open log file for writing\n");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d - %s\n",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
            message);

    if (is_error) {
        fclose(log_file);
        log_file = NULL;
    }

    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Error: could not initialize pigpio", 1);
        exit(EXIT_FAILURE);
    }

    gpioSetPullUpDown(GPIO_FLAME_SENSOR, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message("Error: could not open log file for writing", 1);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        int value = gpioRead(GPIO_FLAME_SENSOR);

        if (value < 0) {
            log_message("Error: could not read GPIO", 1);
            continue;
        }

        char message[100];
        sprintf(message, "Flame detected: %s", value ? "NO" : "YES");
        log_message(message, 0);

        if (!value) {
            printf("FLAME DETECTED!\n");
        }

        sleep(500);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return 0;
}

