#include <libgpiod.h>
#include <time.h>

#define GPIO17 17
#define GPIO27 27

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;
FILE *file;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("\nShutting down...\n");
        fclose(file);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    struct timespec ts;
    int ret;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        perror("gpiod_chip_get_line");
        ret = 1;
        goto err_chip;
    }

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        perror("gpiod_chip_get_line");
        ret = 1;
        goto err_line1;
    }

    ret = gpiod_line_request_input(line1, "sensor1", GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (ret) {
        perror("gpiod_line_request_input");
        ret = 1;
        goto err_line2;
    }

    ret = gpiod_line_request_input(line2, "sensor2", GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (ret) {
        perror("gpiod_line_request_input");
        ret = 1;
        goto err_line1_input;
    }

    file = fopen("conveyor_log.txt", "w");
    if (!file) {
        perror("fopen");
        ret = 1;
        goto err_line2_input;
