#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define MMA8452Q_I2C_ADDR 0x1C
#define MMA8452Q_WHO_AM_I_REG 0x0D
#define MMA8452Q_WHO_AM_I_VAL 0x2A
#define MMA8452Q_CTRL_REG1 0x2A
#define MMA8452Q_DATA_CFG 0x0E
#define CTRL_ACTIVE 0x01
#define CTRL_STANDBY 0x00
#define DATA_CFG_RATE_100HZ 0x05
#define DATA_CFG_RANGE_2G 0x00
#define X_OUT_REG 0x01
#define Y_OUT_REG 0x03
#define Z_OUT_REG 0x05
#define TILT_THRESHOLD 45

static int i2c_fd = -1;
static FILE* log_file = NULL;

void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_I2C_ADDR) == -1) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    unsigned char who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1 || who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "Failed to read WHO_AM_I register or value mismatch\n");
        cleanup_and_exit(1);
    }

    unsigned char ctrl_reg = CTRL_STANDBY;
    if (write(i2c_fd, &ctrl_reg, 1) != 1) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    unsigned char data_cfg = DATA_CFG_RATE_100HZ | DATA_CFG_RANGE_2G;
    if (write(i2c_fd, &data_cfg, 1) != 1) {
        fprintf(stderr, "Failed to write to DATA_CFG: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    ctrl_reg = CTRL_ACTIVE;
    if (write(i2c_fd, &ctrl_reg, 1) != 1) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    unsigned char data[6];
    while (1) {
        if (read(i2c_fd, &data, 6) != 6) {
            fprintf(stderr, "Failed to read data registers: %s\n", strerror(errno));
            continue;
        }

        int x = (data[0] << 8 | data[1]) >> 4;
        int y = (data[2] << 8 | data[3]) >> 4;
        int z = (data[4] << 8 | data[5]) >> 4;

        int tilt = abs(x) + abs(y) + abs(z);
        if (tilt > TILT_THRESHOLD) {
            time_t now = time(NULL);
            struct tm* timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
            fflush(log_file);
        }

        usleep(10000);
    }

    return 0;
}

