#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define I2C_FD_ERROR -1

#define MAG_SCALE 0.146e-3
#define MAG_OFFSET 0.0
#define MAG_ALERT_THRESHOLD 800.0e-3

#define RETRY_COUNT 3

static int i2c_fd = I2C_FD_ERROR;
static FILE *log_file = NULL;

static void close_resources(int sig) {
    if (i2c_fd != I2C_FD_ERROR) {
        close(i2c_fd);
        i2c_fd = I2C_FD_ERROR;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(sig);
}

static int init_i2c(void) {
    int retry = RETRY_COUNT;
    while (retry--) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd == I2C_FD_ERROR) {
            perror("Failed to open I2C device");
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            i2c_fd = I2C_FD_ERROR;
            continue;
        }
        return 0;
    }
    return -1;
}

static int read_mag_data(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (read(i2c_fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("Failed to read mag data");
        return -1;
    }
    *x = (buf[0] << 8 | buf[1]) * MAG_SCALE + MAG_OFFSET;
    *y = (buf[2] << 8 | buf[3]) * MAG_SCALE + MAG_OFFSET;
    *z = (buf[4] << 8 | buf[5]) * MAG_SCALE + MAG_OFFSET;
    return 0;
}

int main(void) {
    float x, y, z, magnitude;
    struct sigaction act;

    act.sa_handler = close_resources;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    log_file = fopen("magnetic_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        close_resources(EXIT_FAILURE);
    }

    while (1) {
        if (read_mag_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read mag data\n");
            close_resources(EXIT_FAILURE);
        }

        magnitude = sqrt(x*x + y*y + z*z);
        if (magnitude > MAG_ALERT_THRESHOLD) {
            fprintf(stderr, "Metal-detector alert: %.3f mG\n", magnitude);
        }

        fprintf(log_file, "%.3f,%.3f,%.3f\n", x, y, z);
        fflush(log_file);

        usleep(100000);  // 10 Hz
    }

    return EXIT_SUCCESS;
}

