static int spi_transfer(const char *tx_data, char *rx_data, size_t len)
{
    int retry = RETRY_COUNT;
    while (retry--) {
        int rc = write(spi_fd, tx_data, len);
        if (rc < 0) {
            perror("SPI write error");
            continue;
        }
        rc = read(spi_fd, rx_data, len);
        if (rc < 0) {
            perror("SPI read error");
            continue;
        }
        return 0;
    }
    return -1;
}

