#define GPIO17 17
#define GPIO27 27

struct gpiod_line *line1, *line2;
struct gpiod_chip *chip;
struct gpiod_line_request request;

void cleanup_and_exit(int sig) {
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    if (sig == SIGINT)
        printf("\nExiting on SIGINT\n");
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_input(line1, "sensor1", &request)) {
        perror("gpiod_line_request_input");
        exit(1);
    }

    if (gpiod_line_request_input(line2, "sensor2", &request)) {
        perror("gpiod_line_request_input");
        exit(1);
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            perror("gpiod_line_get_value");
            cleanup_and_exit(0);
        }

        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            perror("gpiod_line_get_value");
            cleanup_and_exit(0);
        }

        printf("[%ld.%09ld] Sensor 1: %s, Sensor 2: %s\n", ts.tv_sec, ts.tv_nsec, val1 ? "clear" : "obstacle", val2 ? "clear" : "obstacle");

        usleep(100000);  // 100 ms
    }

    cleanup_and_exit(0);
}

