#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define ADDR_XGYRO 0x02
#define ADDR_YGYRO 0x04
#define ADDR_ZGYRO 0x06
#define SCALE_FACTOR 0.02
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CS 8

static volatile int keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

int main() {
    int spi_fd, cs_fd;
    struct spi_ioc_transfer xfer[3];
    uint8_t addr[3] = {ADDR_XGYRO, ADDR_YGYRO, ADDR_ZGYRO};
    uint16_t data[3];
    float rates[3];
    int i, ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spi device");
        return EXIT_FAILURE;
    }

    cs_fd = gpio_request_line(GPIO_CS, GPIO_LINE_REQUEST_OUTPUT, "spi_cs");
    if (cs_fd < 0) {
        perror("gpio_request_line");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (keep_running) {
        for (i = 0; i < 3; i++) {
            memset(xfer, 0, sizeof(xfer));

            addr[i] |= 0x80;
            xfer[i].tx_buf = (unsigned long)addr + i;
            xfer[i].len = 1;
            xfer[i].cs_change = 1;

            xfer[i+1].rx_buf = (unsigned long)data + i*2;
            xfer[i+1].len = 2;
            xfer[i+1].cs_change = 1;

            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), xfer+i);
            if (ret < 0) {
                perror("SPI_IOC_MESSAGE");
                close(spi_fd);
                gpio_release_line(cs_fd);
                return EXIT_FAILURE;
            }

            rates[i] = ((int16_t)data[i]) * SCALE_FACTOR;
        }

        printf("X: %.2f, Y: %.2f, Z: %.2f\n", rates[0], rates[1], rates[2]);
        usleep(100000);
    }

    gpio_release_line(cs_fd);
    close(spi_fd);

    return EXIT_SUCCESS;
}

