#define LSM6DSR_WHO_AM_I 0x0f
#define LSM6DSR_WHO_AM_I_VAL 0x69
#define LSM6DSR_CTRL_REG1 0x10
#define LSM6DSR_CTRL_REG2 0x11

static int i2c_file = -1;

void sigint_handler(int signum) {
    if (i2c_file != -1) {
        close(i2c_file);
    }
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    int ret;
    uint8_t buf[1];

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file == -1) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    ret = ioctl(i2c_file, I2C_SLAVE, LSM6DSR_ADDR);
    if (ret == -1) {
        fprintf(stderr, "Failed to set I2C device address\n");
        return 1;
    }

    buf[0] = LSM6DSR_WHO_AM_I;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    ret = read(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to read from register\n");
        return 1;
    }

    if (buf[0] != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        return 1;
    }

    buf[0] = LSM6DSR_CTRL_REG1;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    buf[0] = 0x47;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    buf[0] = LSM6DSR_CTRL_REG2;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
