    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    ret = read(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to read from register\n");
        return 1;
    }

    if (buf[0] != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        return 1;
    }

    buf[0] = LSM6DSR_CTRL_REG1;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    buf[0] = 0x47;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    buf[0] = LSM6DSR_CTRL_REG2;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    buf[0] = 0x00;
    ret = write(i2c_file, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write to register\n");
        return 1;
    }

    while (1) {
        buf[0] = 0x28;
        ret = write(i2c_file, buf, 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to write to register\n");
            return 1;
        }

        ret = read(i2c_file, buf, 6);
        if (ret != 6) {
            fprintf(stderr, "Failed to read from register\n");
            return 1;
        }

        printf("%d %d %d %d %d %d\n", buf[0], buf[1], buf[2], buf[3], buf[4], buf[5]);
        usleep(100000);
    }

    return 0;
}
