#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1c

#define ACCEL_REG 0x00
#define MAG_REG 0x06
#define ID_REG 0x7
#define EXPECTED_ID 0xab

static int fd;
static volatile int stop;

static void cleanup(void) {
    close(fd);
}

static void sig_handler(int signum) {
    stop = 1;
}

int main(void) {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    unsigned char id;
    if (read(fd, &id, 1) != 1 || id != EXPECTED_ID) {
        fprintf(stderr, "Device not found\n");
        cleanup();
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    unsigned char buf[12];
    while (!stop) {
        if (write(fd, &ACCEL_REG, 1) != 1) {
            perror("write");
            return EXIT_FAILURE;
        }

        if (read(fd, buf, 12) != 12) {
            perror("read");
            return EXIT_FAILURE;
        }

        printf("Accel: %d, %d, %d\n",
               (int16_t)((buf[0] << 8) | buf[1]),
               (int16_t)((buf[2] << 8) | buf[3]),
               (int16_t)((buf[4] << 8) | buf[5]));

        printf("Mag: %d, %d, %d\n",
               (int16_t)((buf[6] << 8) | buf[7]),
               (int16_t)((buf[8] << 8) | buf[9]),
               (int16_t)((buf[10] << 8) | buf[11]));

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

