#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <math.h>

#define ADXL345_ADDR 0x53
#define ACCEL_DATA_ADDR 0x32
#define TILT_THRESHOLD 30.0
#define SAMPLE_RATE 100

int fd;

void cleanup_and_exit(int sig) {
    close(fd);
    exit(sig);
}

void handle_error(const char *msg) {
    perror(msg);
    cleanup_and_exit(-1);
}

double get_tilt_angle(int x, int y, int z) {
    double rad = atan2(sqrt(y*y + z*z), x);
    return rad * (180.0 / M_PI);
}

void log_tilt_event(double tilt) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    FILE *file = fopen("/var/log/tilt_events.log", "a");
    if (file == NULL) {
        handle_error("fopen");
    }
    fprintf(file, "%d-%02d-%02d %02d:%02d:%02d: Tilt angle exceeded threshold of %.1f degrees\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, tilt);
    fclose(file);
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        handle_error("open");
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        handle_error("ioctl");
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        unsigned char buf[6];
        if (read(fd, buf, 6) != 6) {
            handle_error("read");
        }

        int x = (buf[0] << 8) | buf[1];
        int y = (buf[2] << 8) | buf[3];
        int z = (buf[4] << 8) | buf[5];

        double tilt = get_tilt_angle(x, y, z);
        if (tilt > TILT_THRESHOLD) {
            log_tilt_event(tilt);
        }

        usleep(SAMPLE_RATE * 1000);
    }

    cleanup_and_exit(0);
}

