#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 17
#define WINDOW_MS 5000
#define SAMPLE_MS 1

struct gpiod_line *line;
struct gpiod_chip *chip;
int threshold;

void sig_handler(int signo) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(signo);
}

int main(int argc, char *argv[]) {
    if (argc != 2 || (threshold = atoi(argv[1])) <= 0) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(line, "sound_sensor")) {
        perror("gpiod_line_request_rising_edge_events");
        return EXIT_FAILURE;
    }

    struct timespec ts = { .tv_sec = WINDOW_MS / 1000, .tv_nsec = (WINDOW_MS % 1000) * 1000000 };
    int count;
    while (1) {
        count = 0;
        for (int i = 0; i < WINDOW_MS / SAMPLE_MS; i++) {
            if (gpiod_line_event_wait(line, &ts)) {
                perror("gpiod_line_event_wait");
                return EXIT_FAILURE;
            }
            if (gpiod_line_event_read(line))
                count++;
        }
        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        char buf[80];
        strftime(buf, 80, "%Y-%m-%d %H:%M:%S", tmp);
        printf("%s: %s\n", buf, count > threshold ? "ALERT" : "OK");
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

