#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;
FILE *log_file;
volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM)
        stop = 1;
}

void set_gpio_low(void) {
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
}

void write_log(int code) {
    time_t now = time(0);
    struct tm *time_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_file, "%s,%06d\n", buffer, code);
}

int main(void) {
    int rc;
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        fprintf(stderr, "Failed to get line 1\n");
        goto err_close_chip;
    }

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        fprintf(stderr, "Failed to get line 2\n");
        goto err_close_line1;
    }

    rc = gpiod_line_request_output(line1, "door_access", 0);
    if (rc < 0) {
        fprintf(stderr, "Failed to request line 1\n");
        goto err_close_line2;
    }

    rc = gpiod_line_request_output(line2, "door_access", 0);
    if (rc < 0) {
        fprintf(stderr, "Failed to request line 2\n");
        goto err_release_line1;
    }

    log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto err_release_line2;
    }

    while (!stop) {
        int code = rand() % 900000 + 100000;
        printf("Security code: %06d\n", code);
        int entered_code;
        char buffer[80];
        fgets(buffer, sizeof(buffer), stdin);
        if (sscanf(buffer, "%d", &entered_code) != 1) {
            printf("Invalid input\n");
            continue;
        }
        if (code == entered_code) {
            write_log(code);
            printf("Access granted\n");
            gpiod_line_set_value(line1, 1);
            gpiod_line_set_value(line2, 1);
            sleep(5);
            set_gpio_low();
        } else {
            printf("Access denied\n");
        }
    }

    fclose(log_file);
    gpiod_line_release(line2);
    gpiod_line_release(line1);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

err_release_line2:
    gpiod_line_release(line2);
err_release_line1:
    gpiod_line_release(line1);
err_close_line2:
    gpiod_line_close(line2);
err_close_line1:
    gpiod_line_close(line1);
err_close_chip:
    gpiod_chip_close(chip);

    return EXIT_FAILURE;
}

