#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define I2C_REG_ZOUT_L 0x08
#define LED_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd;
static volatile int stop;

static void cleanup(void)
{
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
}

static void handle_signal(int signum)
{
    stop = 1;
}

int main(void)
{
    struct sigaction action;
    struct gpiod_line_request_config config;
    struct i2c_msg msgs[1];
    uint8_t buf[6];
    int ret;

    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }

    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE;
    config.default_val = 0;
    strncpy(config.consumer_label, "led", sizeof(config.consumer_label));

    ret = gpiod_line_request_output(line, &config);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    msgs[0].addr = I2C_ADDRESS;
    msgs[0].flags = I2C_M_RD;
    msgs[0].len = sizeof(buf);
    msgs[0].buf = buf;

    atexit(cleanup);

    while (!stop) {
        ret = i2c_smbus_read_i2c_block_data(i2c_fd, I2C_REG_ZOUT_L, sizeof(buf));
        if (ret < 0) {
            fprintf(stderr, "i2c_smbus_read_i2c_block_data: %s\n", strerror(errno));
            continue;
        }

        // Assuming ZOUT_L is a 16-bit register, combine the two bytes and map to [0, 1]
        uint16_t z_axis = (buf[1] << 8) | buf[0];
        float brightness = (float)z_axis / 0xffff;

        // Set the LED brightness
        gpiod_line_set_value(line, brightness * 100);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

