#define I2C_FILE "/dev/i2c-1"
#define SAMPLE_SIZE 100

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    int fd, status, i;
    float avg_x = 0, avg_y = 0, avg_z = 0;
    float x_samples[SAMPLE_SIZE], y_samples[SAMPLE_SIZE], z_samples[SAMPLE_SIZE];
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    fd = open(I2C_FILE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device file");
        return EXIT_FAILURE;
    }

    status = ioctl(fd, I2C_SLAVE, HMC5883L_ADDR);
    if (status < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    for (i = 0; i < SAMPLE_SIZE; i++) {
        x_samples[i] = y_samples[i] = z_samples[i] = 0;
    }

    while (!stop) {
        int16_t x, y, z;

        status = read(fd, &x, sizeof(x));
        if (status != sizeof(x)) {
            fprintf(stderr, "Failed to read X data: %d\n", status);
            continue;
        }

        status = read(fd, &y, sizeof(y));
        if (status != sizeof(y)) {
            fprintf(stderr, "Failed to read Y data: %d\n", status);
            continue;
        }

        status = read(fd, &z, sizeof(z));
        if (status != sizeof(z)) {
            fprintf(stderr, "Failed to read Z data: %d\n", status);
            continue;
        }

        x_samples[i % SAMPLE_SIZE] = x;
        y_samples[i % SAMPLE_SIZE] = y;
        z_samples[i % SAMPLE_SIZE] = z;

        avg_x = avg_y = avg_z = 0;
        for (int j = 0; j < SAMPLE_SIZE; j++) {
            avg_x += x_samples[j];
            avg_y += y_samples[j];
            avg_z += z_samples[j];
        }
        avg_x /= SAMPLE_SIZE;
        avg_y /= SAMPLE_SIZE;
        avg_z /= SAMPLE_SIZE;

        printf("X: %.2f, Y: %.2f, Z: %.2f\n", x - avg_x, y - avg_y, z - avg_z);

        i++;
        usleep(500000);
    }

