        avg_x = avg_y = avg_z = 0;
        for (int j = 0; j < SAMPLE_SIZE; j++) {
            avg_x += x_samples[j];
            avg_y += y_samples[j];
            avg_z += z_samples[j];
        }
        avg_x /= SAMPLE_SIZE;
        avg_y /= SAMPLE_SIZE;
        avg_z /= SAMPLE_SIZE;

        printf("X: %.2f, Y: %.2f, Z: %.2f\n", x - avg_x, y - avg_y, z - avg_z);

        i++;
        usleep(500000);
    }

cleanup:
    close(fd);
    return EXIT_SUCCESS;
}
```

