#define BUF_SIZE 64
#define INTERRUPT_GPIO 23

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_file;
int circular_buffer[BUF_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
