        fprintf(stderr, "Failed to request GPIO event\n");
        exit(EXIT_FAILURE);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C device file\n");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        exit(EXIT_FAILURE);
    }
    char id;
    if (read(i2c_file, &id, 1) != 1 || id != EXPECTED_ID) {
        fprintf(stderr, "Incorrect device ID\n");
        exit(EXIT_FAILURE);
    }
    if (write(i2c_file, &EXPECTED_CTRL, 1) != 1) {
        fprintf(stderr, "Failed to write to control register\n");
        exit(EXIT_FAILURE);
    }
    if (write(i2c_file, &INT1_THS, 1) != 1 || write(i2c_file, &INT1_DUR, 1) != 1) {
        fprintf(stderr, "Failed to write to interrupt registers\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        char data[6];
        if (read(i2c_file, &data, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }
        for (int i = 0; i < 6; i++) {
            if (buffer_count == BUF_SIZE) {
                buffer_tail = (buffer_tail + 1) % BUF_SIZE;
                buffer_count--;
            }
            circular_buffer[buffer_head] = data[i];
            buffer_head = (buffer_head + 1) % BUF_SIZE;
            buffer_count++;
        }
        if (gpiod_line_event_wait(line, NULL) == 0) {
            printf("Timestamp: %ld\n", time(NULL));
            for (int i = 0; i < 10; i++) {
                printf("%d ", circular_buffer[(buffer_tail + i) % BUF_SIZE]);
            }
            printf("\n");
        }
    }

    return 0;
}

