    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO17, strerror(errno));
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO27, strerror(errno));
        return 1;
    }

    if (gpiod_line_request_output(line1, "main", 0) || gpiod_line_request_output(line2, "main", 0)) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO17, strerror(errno));
        return 1;
    }

    uart0 = fopen("/dev/serial0", "r");
    if (!uart0) {
        fprintf(stderr, "Failed to open UART0: %s\n", strerror(errno));
        return 1;
    }

    uart1 = fopen("/dev/serial1", "r");
    if (!uart1) {
        fprintf(stderr, "Failed to open UART1: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int c = fgetc(uart0);
        if (c != EOF) {
            if (c >= '0' && c <= '9') {
                strncpy(code1, code1+1, 5);
                code1[5] = c;
            } else {
                memset(code1, 0, 6);
            }
        }

        c = fgetc(uart1);
        if (c != EOF) {
            if (c >= '0' && c <= '9') {
                strncpy(code2, code2+1, 5);
                code2[5] = c;
            } else {
                memset(code2, 0, 6);
            }
        }

        if (!strcmp(code1, EXPECTED_CODE) && !strcmp(code2, EXPECTED_CODE)) {
            gpiod_line_set_value(line1, 1);
            gpiod_line_set_value(line2, 1);
            sleep(2);
            gpiod_line_set_value(line1, 0);
            gpiod_line_set_value(line2, 0);
        }
    }

    return 0;
}

