#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <time.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define PIR_ACTIVE_STATE GPIOD_LINE_ACTIVE_STATE_HIGH
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_SEC 10

struct gpiod_line *pir_line, *relay_line;
struct gpiod_chip *chip;
int failsafe_timer = 0;
int running = 1;

void shutdown_handler(int signum) {
    running = 0;
}

void failsafe() {
    syslog(LOG_WARNING, "Failsafe triggered, potential malfunction.");
    gpiod_line_set_value(relay_line, 0);
    syslog(LOG_NOTICE, "Relay de-energized.");
}

int main() {
    openlog("pir_monitor", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line: %m");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line: %m");
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir_monitor", PIR_ACTIVE_STATE)) {
        syslog(LOG_ERR, "Failed to request PIR line: %m");
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "pir_monitor", 0)) {
        syslog(LOG_ERR, "Failed to request relay line: %m");
        return 1;
    }

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    struct timespec ts;
    ts.tv_sec = POLL_INTERVAL_MS / 1000;
    ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000;

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to get PIR value: %m");
            return 1;
        }

        if (pir_value) {
            syslog(LOG_NOTICE, "Motion detected, activating relay.");
            gpiod_line_set_value(relay_line, 1);
            nanosleep(&ts, NULL);
            gpiod_line_set_value(relay_line, 0);
            syslog(LOG_NOTICE, "Relay de-energized.");
            failsafe_timer = 0;
        } else {
            failsafe_timer++;
            if (failsafe_timer > FAILSAFE_TIMEOUT_SEC * 1000 / POLL_INTERVAL_MS) {
                failsafe();
                failsafe_timer = 0;
            }
        }

        nanosleep(&ts, NULL);
    }

    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

