    if (gpiod_line_request_output(relay_line, "pir_monitor", 0)) {
        syslog(LOG_ERR, "Failed to request relay line: %m");
        return 1;
    }

    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    struct timespec ts;
    ts.tv_sec = POLL_INTERVAL_MS / 1000;
    ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000;

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to get PIR value: %m");
            return 1;
        }

        if (pir_value) {
            syslog(LOG_NOTICE, "Motion detected, activating relay.");
            gpiod_line_set_value(relay_line, 1);
            nanosleep(&ts, NULL);
            gpiod_line_set_value(relay_line, 0);
            syslog(LOG_NOTICE, "Relay de-energized.");
            failsafe_timer = 0;
        } else {
            failsafe_timer++;
            if (failsafe_timer > FAILSAFE_TIMEOUT_SEC * 1000 / POLL_INTERVAL_MS) {
                failsafe();
                failsafe_timer = 0;
            }
        }

        nanosleep(&ts, NULL);
    }

    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}
