    closelog();
    exit(EXIT_FAILURE);
}

void activate_relay(int rel) {
    if (gpiod_line_set_value(lines[rel], 0) < 0) {
        log_error_and_exit("Failed to activate relay");
    }
    syslog(LOG_INFO, "irrigation_system: Activated relay %d", rel + 1);
}

void deactivate_relay(int rel) {
    if (gpiod_line_set_value(lines[rel], 1) < 0) {
        log_error_and_exit("Failed to deactivate relay");
    }
    syslog(LOG_INFO, "irrigation_system: Deactivated relay %d", rel + 1);
}

