            log_error_and_exit("Failed to get GPIO line");
        }

        if (gpiod_line_request_output(lines[i], "irrigation_system", 1) < 0) {
            log_error_and_exit("Failed to request GPIO line");
        }
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        if (active_rel >= 0) {
            deactivate_relay(active_rel);
            sleep(PAUSE_DELAY);
        }

        active_rel = (active_rel + 1) % NUM_RELS;
        activate_relay(active_rel);
        sleep(REL_DELAY);
    }

    for (int i = 0; i < NUM_RELS; i++) {
        deactivate_relay(i);
    }

    for (int i = 0; i < NUM_RELS; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);

    closelog();

    return 0;
}

