#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define MPU6050_ADDR 0x68
#define ACCEL_REG 0x3B
#define BUF_SIZE 1000

volatile sig_atomic_t stop = 0;
int i2c_file_descriptor;

struct CircularBuffer {
    int data[BUF_SIZE];
    int head;
    int tail;
    int count;
};

struct CircularBuffer buffer;

void init_buffer() {
    buffer.head = buffer.tail = buffer.count = 0;
}

void push_buffer(int value) {
    if (buffer.count == BUF_SIZE) {
        buffer.tail = (buffer.tail + 1) % BUF_SIZE;
        buffer.count--;
    }
    buffer.data[buffer.head] = value;
    buffer.head = (buffer.head + 1) % BUF_SIZE;
    buffer.count++;
}

int pop_buffer() {
    if (buffer.count == 0) {
        return -1;
    }
    int value = buffer.data[buffer.tail];
    buffer.tail = (buffer.tail + 1) % BUF_SIZE;
    buffer.count--;
    return value;
}

void signal_handler(int signum) {
    stop = 1;
    close(i2c_file_descriptor);
    remove("/sys/kernel/mpu6050_accel/latest");
    printf("Signal received, cleaning up and exiting...\n");
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave");
        exit(EXIT_FAILURE);
    }

    init_buffer();

    struct itimerspec timer_value;
    timer_t timer_id;
    if (timer_create(CLOCK_REALTIME, NULL, &timer_id) == -1) {
        perror("Failed to create timer");
        exit(EXIT_FAILURE);
    }

    struct sigevent sev;
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGINT;
    sev.sigev_value.sival_ptr = &timer_id;
    if (timer_settime(timer_id, 0, &timer_value, NULL) == -1) {
        perror("Failed to set timer");
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        int value;
        if (read(i2c_file_descriptor, &value, sizeof(value)) != sizeof(value)) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }
        push_buffer(value);
    }

    return 0;
}

