    }
    if (chip)
        gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(signum);
}

int main() {
    struct timespec ts;
    int ret;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup_and_exit(-1);
    }

    int gpios[] = {GPIO18, GPIO23, GPIO24, GPIO25};
    int intervals[] = {2, 3, 5, 7};

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            cleanup_and_exit(-1);
        }

        ret = gpiod_line_request_output(lines[i], "toggle", 0);
        if (ret) {
            perror("gpiod_line_request_output");
            cleanup_and_exit(-1);
        }

        while (1) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }

            ret = clock_gettime(CLOCK_MONOTONIC, &ts);
            if (ret) {
                perror("clock_gettime");
                cleanup_and_exit(-1);
            }
            ts.tv_sec += intervals[i];

            ret = clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);
            if (ret) {
                perror("clock_nanosleep");
                cleanup_and_exit(-1);
            }

            ret = gpiod_line_set_value(lines[i], 0);
            if (ret) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }
        }
    }

    cleanup_and_exit(0);
}

