#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define POLL_INTERVAL_MS 100
#define RELAY_ACTIVATION_TIME_S 3

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL, *relay_line = NULL;
FILE *log_file = NULL;
int is_relay_active = 0;

void sig_handler(int signo) {
    if (relay_line && is_relay_active) {
        gpiod_line_set_value(relay_line, 0);
        is_relay_active = 0;
    }
    if (log_file)
        fclose(log_file);
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (relay_line)
        gpiod_line_release(relay_line);
    if (chip)
        gpiod_chip_close(chip);
    exit(signo);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_GPIO);
    if (!sensor_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_input(sensor_line, "sensor")) {
        perror("gpiod_line_request_input");
        goto error;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0)) {
        perror("gpiod_line_request_output");
        goto error;
    }

    log_file = fopen("alarm_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        goto error;
    }

    while (1) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto error;
        }

        if (val && !is_relay_active) {
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s: Relay activated\n", timestamp);
            fflush(log_file);

            gpiod_line_set_value(relay_line, 1);
            is_relay_active = 1;
            sleep(RELAY_ACTIVATION_TIME_S);
            gpiod_line_set_value(relay_line, 0);
            is_relay_active = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    return 0;

error:
    if (log_file)
        fclose(log_file);
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (relay_line)
        gpiod_line_release(relay_line);
    if (chip)
        gpiod_chip_close(chip);
    return 1;
}

