#include <sys/ioctl.h>

#define DEVICE_PATH "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define BUF_SIZE 100
#define GYRO_THRESHOLD 50.0

int fd;
float buf[BUF_SIZE];
int buf_idx = 0;

void cleanup(int signum) {
    close(fd);
    exit(0);
}

void check_error(int status, const char *msg) {
    if (status < 0) {
        perror(msg);
        cleanup(0);
    }
}

void read_gyro_data() {
    unsigned char data[6];
    memset(data, 0, sizeof(data));

    int status = write(fd, (unsigned char*)"\x3B", 1);
    check_error(status, "Failed to select register");

    status = read(fd, data, sizeof(data));
    check_error(status, "Failed to read gyro data");

    float x = (data[0] << 8 | data[1]) / 131.0;
    float y = (data[2] << 8 | data[3]) / 131.0;
    float z = (data[4] << 8 | data[5]) / 131.0;

    float abs_gyro = sqrt(x*x + y*y + z*z);
    buf[buf_idx++] = abs_gyro;
    buf_idx %= BUF_SIZE;

    if (abs_gyro > GYRO_THRESHOLD) {
        printf("Angular velocity exceeded threshold: %.2f\n", abs_gyro);
    }
}

int main() {
    fd = open(DEVICE_PATH, O_RDWR);
    check_error(fd, "Failed to open I2C device");

    int status = ioctl(fd, I2C_SLAVE, MPU6050_ADDR);
    check_error(status, "Failed to select MPU6050");

    signal(SIGINT, cleanup);

    while (1) {
        read_gyro_data();
        sleep(1);
    }

    return 0;
}

