#include <json-c/json.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define GPIO_TXD 14
#define GPIO_RXD 15
#define SLEEP_TIME 5
#define TIMEOUT 1000000
#define RETRIES 3
#define CMD_LEN 9
#define READ_LEN 9

struct gpiod_device *dev;
struct gpiod_line *txd, *rxd;
FILE *log_file, *error_file;

void sig_handler(int signo) {
    gpiod_line_release(txd);
    gpiod_line_release(rxd);
    fclose(log_file);
    fclose(error_file);
    exit(signo);
}

int main() {
    int ret;
    struct timespec ts;
    unsigned char cmd[CMD_LEN] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char read_buf[READ_LEN];
    struct json_object *obj;

    dev = gpiod_device_open_by_name(UART_DEVICE);
    if (!dev) {
        fprintf(stderr, "Failed to open UART device\n");
        return -1;
    }

    txd = gpiod_device_get_line(dev, GPIO_TXD);
    rxd = gpiod_device_get_line(dev, GPIO_RXD);
    if (!txd || !rxd) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return -1;
    }

    ret = gpiod_line_request_simple_io(txd, "txd");
    ret |= gpiod_line_request_input(rxd, "rxd");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        return -1;
    }

    log_file = fopen("co2_log.json", "w");
    error_file = fopen("co2_error.log", "w");
    if (!log_file || !error_file) {
        fprintf(stderr, "Failed to open log files\n");
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        for (int i = 0; i < RETRIES; i++) {
            gpiod_line_set_value(txd, cmd, CMD_LEN);
            if (nanosleep(&ts, NULL) == -1) {
                fprintf(stderr, "nanosleep failed\n");
                return -1;
            }
            ret = gpiod_line_get_value(rxd, read_buf, READ_LEN);
            if (ret == READ_LEN) {
                break;
            } else if (ret == -ETIMEDOUT) {
                fprintf(error_file, "Timeout error\n");
                fflush(error_file);
            } else if (ret < 0) {
                fprintf(error_file, "Read error\n");
                fflush(error_file);
            }
        }

        if (ret != READ_LEN) {
            fprintf(error_file, "Failed to read sensor data\n");
            fflush(error_file);
            continue;
        }

        obj = json_object_new_object();
        json_object_object_add(obj, "timestamp", json_object_new_int(time(NULL)));
        json_object_object_add(obj, "ppm", json_object_new_int(read_buf[2]));
        json_object_object_add(obj, "error", json_object_new_int(0));
        fprintf(log_file, "%s\n", json_object_to_json_string(obj));
        fflush(log_file);
        printf("%s\n", json_object_to_json_string(obj));

        sleep(SLEEP_TIME);
    }

    return 0;
}

