#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x1E
#define I2C_REGISTER 0x00
#define I2C_RETRIES 5
#define I2C_SLEEP_MS 100
#define HEADING_TARGET 90.0
#define HEADING_DEVIATION 10
#define GPIO_LINE 17
#define BUFFER_SIZE 100

struct gpiod_line *gpio_line;
struct gpiod_chip *gpio_chip;
int i2c_file;

double heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

void exit_handler(int signum) {
    gpiod_line_set_value(gpio_line, 0);
    gpiod_line_release(gpio_line);
    close(i2c_file);
    exit(0);
}

int i2c_read(void *data, size_t length) {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDRESS) == 0) {
            if (read(i2c_file, data, length) == length) {
                return 0;
            }
        }
        usleep(I2C_SLEEP_MS * 1000);
        retries++;
    }
    fprintf(stderr, "I2C read failed after %d retries\n", retries);
    exit_handler(0);
    return -1;
}

int main(void) {
    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    gpio_chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    gpiod_line_request_output(gpio_line, "main", 0);

    i2c_file = open(I2C_DEVICE, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit_handler(0);
    }

    while (1) {
        uint8_t data[3];
        if (i2c_read(data, sizeof(data)) == 0) {
            double heading = atan2(data[1], data[0]) * 180.0 / M_PI;
            heading += 100.0;
            if (heading < 0.0) {
                heading += 360.0;
            } else if (heading >= 360.0) {
                heading -= 360.0;
            }
            heading_buffer[buffer_index] = heading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            double average_heading = 0.0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                average_heading += heading_buffer[i];
            }
            average_heading /= BUFFER_SIZE;

            if (fabs(average_heading - HEADING_TARGET) > HEADING_DEVIATION) {
                gpiod_line_set_value(gpio_line, 1);
            } else {
                gpiod_line_set_value(gpio_line, 0);
            }

            usleep(I2C_SLEEP_MS * 1000);
        }
    }

    return 0;
}

