int i2c_file_descriptor = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int exit_code) {
    if (red_line)
        gpiod_line_release(red_line);
    if (green_line)
        gpiod_line_release(green_line);
    if (blue_line)
        gpiod_line_release(blue_line);
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_file_descriptor >= 0)
        close(i2c_file_descriptor);
    if (log_file)
        fclose(log_file);
    exit(exit_code);
}

int main() {
    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    red_line = gpiod_chip_get_line(chip, GPIO_RED);
    green_line = gpiod_chip_get_line(chip, GPIO_GREEN);
    blue_line = gpiod_chip_get_line(chip, GPIO_BLUE);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(red_line, "red", 0) ||
        gpiod_line_request_output(green_line, "green", 0) ||
        gpiod_line_request_output(blue_line, "blue", 0)) {
        fprintf(stderr, "Failed to request GPIO lines as outputs\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        unsigned char cmd[] = { BH1750_CMD_POWER_ON, BH1750_CMD_ONE_TIME_H_RES };
        unsigned char data[2];
        int lux;

        if (write(i2c_file_descriptor, cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(stderr, "Failed to write to I2C device\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        usleep(120000);

        if (read(i2c_file_descriptor, data, sizeof(data)) != sizeof(data)) {
            fprintf(stderr, "Failed to read from I2C device\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        lux = (data[0] << 8) | data[1];

        if (lux < LUX_THRESHOLD_1)
            gpiod_line_set_value(red_line, 1);
        else if (lux < LUX_THRESHOLD_2)
            gpiod_line_set_value(green_line, 1);
        else if (lux < LUX_THRESHOLD_3)
            gpiod_line_set_value(blue_line, 1);
        else {
            gpiod_line_set_value(red_line, 1);
            gpiod_line_set_value(green_line, 1);
            gpiod_line_set_value(blue_line, 1);
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d\n", timestamp, lux);
        fflush(log_file);

        sleep(1);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}
