#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>
#include <pthread.h>

#define GPIO_PINS 4
#define GPIO_CHIPS 1
#define PWM_FREQ 100
#define FADE_TIME 1800

struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_lines[GPIO_PINS];
int pwm_duties[GPIO_PINS];
int target_duties[GPIO_PINS];
int current_time;
FILE *schedule_file;

void exit_handler(int signum) {
    for (int i = 0; i < GPIO_PINS; i++) {
        gpiod_line_set_value(gpio_lines[i], 0);
    }
    gpiod_chip_close(gpio_chip);
    fclose(schedule_file);
    exit(0);
}

void *schedule_reader(void *arg) {
    char line[256];
    time_t t = time(NULL);
    struct tm *tmp = localtime(&t);
    int hour, minute, second, relay_number;
    char state[5];

    while (fgets(line, sizeof(line), schedule_file)) {
        sscanf(line, "%d:%d:%d,%d,%s", &hour, &minute, &second, &relay_number, state);
        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59 || relay_number < 0 || relay_number > 3) {
            printf("Invalid schedule entry: %s", line);
            continue;
        }
        if (tmp->tm_hour == hour && tmp->tm_min == minute && tmp->tm_sec == second) {
            target_duties[relay_number] = (strcmp(state, "on") == 0) ? 100 : 0;
        }
    }
    return NULL;
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip == NULL) {
        printf("Failed to open GPIO chip\n");
        exit(1);
    }

    for (int i = 0; i < GPIO_PINS; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, 4 + i);
        if (gpio_lines[i] == NULL) {
            printf("Failed to get GPIO line %d\n", 4 + i);
            exit(1);
        }
        gpiod_line_request_pwm_output(gpio_lines[i], "smart_home", PWM_FREQ * 1000, 0);
    }

    schedule_file = fopen("lighting_schedule.txt", "r");
    if (schedule_file == NULL) {
        printf("Failed to open schedule file\n");
        exit(1);
    }

    while (1) {
        pthread_t thread;
        pthread_create(&thread, NULL, schedule_reader, NULL);
        pthread_join(thread, NULL);

        for (int i = 0; i < GPIO_PINS; i++) {
            if (pwm_duties[i] < target_duties[i]) {
                pwm_duties[i]++;
            } else if (pwm_duties[i] > target_duties[i]) {
                pwm_duties[i]--;
            }
            gpiod_line_set_pwm_duty_cycle(gpio_lines[i], pwm_duties[i] * 1023 / 100);
        }

        sleep(1);
    }

    return 0;
}

