    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (!trigger_line->request_output_mode(trigger_line, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN)) {
        perror("gpiod_line_request_output_mode");
        return 1;
    }

    if (!echo_line->request_input_mode(echo_line)) {
        perror("gpiod_line_request_input_mode");
