        perror("gpiod_line_request_output_mode");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        trigger_line->set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        trigger_line->set_value(trigger_line, 0);

