        time_t start = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        while (echo_line->get_value(echo_line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            time_t now = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

