        time_t end = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        int distance = end - start;
        buzzer_freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * distance / MIN_SENSOR_READ_US;
        buzzer_line->set_value(buzzer_line, buzzer_freq);

