#include <signal.h>
#include <stdio.h>
#include <math.h>
#include <libgpiod.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE_MAX 1000000

struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

void cleanup_and_exit(int sig) {
    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);

    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);

    gpiod_chip_close(chip);

    if (sig == SIGINT) {
        printf("\nExiting on SIGINT.\n");
    }
    else {
        printf("Exiting.\n");
    }

    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    if (!red_line) {
        perror("Failed to get red line");
        return 1;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line) {
        perror("Failed to get green line");
        return 1;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line) {
        perror("Failed to get blue line");
        return 1;
    }

    if (gpiod_line_request_pwm_output(red_line, "red", PWM_FREQ) ||
        gpiod_line_request_pwm_output(green_line, "green", PWM_FREQ) ||
        gpiod_line_request_pwm_output(blue_line, "blue", PWM_FREQ)) {
        perror("Failed to request PWM output");
        return 1;
    }

    double t = 0.0;
    while (1) {
        int red_duty_cycle = PWM_DUTY_CYCLE_MAX * (sin(t) + 1.0) / 2.0;
        int green_duty_cycle = PWM_DUTY_CYCLE_MAX * (sin(t + 2.0 * M_PI / 3.0) + 1.0) / 2.0;
        int blue_duty_cycle = PWM_DUTY_CYCLE_MAX * (sin(t + 4.0 * M_PI / 3.0) + 1.0) / 2.0;

        if (gpiod_line_set_pwm_duty_cycle(red_line, red_duty_cycle) ||
            gpiod_line_set_pwm_duty_cycle(green_line, green_duty_cycle) ||
            gpiod_line_set_pwm_duty_cycle(blue_line, blue_duty_cycle)) {
            perror("Failed to set PWM duty cycle");
            return 1;
        }

        t += 2.0 * M_PI / 30.0;
        usleep(33333);
    }

    return 0;
}

