#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define DEVICE_ADDRESS 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define GYRO_SCALE 131.0f

int file_descriptor;
FILE *log_file;

void exit_handler(int signum) {
    close(file_descriptor);
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file_descriptor, I2C_SLAVE, DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C device address");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int16_t x, y, z;

        if (write(file_descriptor, &GYRO_XOUT_H, 1) != 1) {
            perror("Failed to write to I2C device");
            exit(EXIT_FAILURE);
        }

        if (read(file_descriptor, &x, 2) != 2) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }

        if (write(file_descriptor, &GYRO_YOUT_H, 1) != 1) {
            perror("Failed to write to I2C device");
            exit(EXIT_FAILURE);
        }

        if (read(file_descriptor, &y, 2) != 2) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }

        if (write(file_descriptor, &GYRO_ZOUT_H, 1) != 1) {
            perror("Failed to write to I2C device");
            exit(EXIT_FAILURE);
        }

        if (read(file_descriptor, &z, 2) != 2) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld %f %f %f\n", ts.tv_sec, ts.tv_nsec, x / GYRO_SCALE, y / GYRO_SCALE, z / GYRO_SCALE);
        fflush(log_file);

        usleep(100000);
    }

    return 0;
}

