#include <stdio.h>
#include <signal.h>
#include <libgpiod.h>
#include <errno.h>
#include <unistd.h>

#define GPIO_BTN 17
#define GPIO_BUZZER 18
#define DEBOUNCE_TIME 50000
#define MELODY_LENGTH 10
#define PWM_DUTY_CYCLE 50

const int melody[MELODY_LENGTH] = {523, 587, 659, 698, 783, 880, 988, 1046, 1175, 1319}; // Melody lookup table

struct gpiod_chip *chip;
struct gpiod_line *btn, *buzzer;
int pwm_id;
volatile int button_pressed = 0;

void isr(struct gpiod_line *line, void *data)
{
    button_pressed = 1;
}

void stop_pwm(int signum)
{
    gpiod_line_set_pwm(buzzer, 0, 0);
    gpiod_line_release(btn);
    gpiod_line_release(buzzer);
    gpiod_chip_close(chip);
    printf("Shutdown\n");
    exit(0);
}

int main()
{
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        printf("Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    btn = gpiod_chip_get_line(chip, GPIO_BTN);
    if (!btn) {
        printf("Failed to get button line: %s\n", strerror(errno));
        return 1;
    }

    buzzer = gpiod_chip_get_line(chip, GPIO_BUZZER);
    if (!buzzer) {
        printf("Failed to get buzzer line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_both_edges_events(btn, "button", isr, NULL)) {
        printf("Failed to request button events: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_pwm_output(buzzer, "buzzer", &pwm_id)) {
        printf("Failed to request buzzer PWM output: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, stop_pwm);
    signal(SIGTERM, stop_pwm);

    while (1) {
        usleep(DEBOUNCE_TIME);
        if (button_pressed) {
            button_pressed = 0;
            for (int i = 0; i < MELODY_LENGTH; i++) {
                gpiod_line_set_pwm(buzzer, pwm_id, PWM_DUTY_CYCLE, 1000000 / melody[i]);
                usleep(500000);
            }
        }
    }

    return 0;
}

