#define LOG_FILE_NAME "vibration_events.log"
#define GPIO_LINE 17
#define DEFAULT_TIMEOUT_MS 1000

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;
int should_exit;
int high_count;
int event_window[5];
int window_index;

void log_event(int value) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

void handle_signal(int signum) {
    should_exit = 1;
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    if (argc > 1) {
        char *end;
        long val = strtol(argv[1], &end, 10);
        if (*end == '\0' && val > 0) {
            timeout_ms = val;
        }
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_both_edges_events(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Error requesting edge events: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, timeout_ms) < 0) {
            if (errno == EINTR) {
                break;
            }
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading event: %s\n", strerror(errno));
            break;
        }

        log_event(event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0);

        event_window[window_index] = event.event_type;
        window_index = (window_index + 1) % sizeof(event_window);

        high_count = 0;
        for (int i = 0; i < sizeof(event_window); i++) {
            if (event_window[i] == GPIOD_LINE_EVENT_RISING_EDGE) {
                high_count++;
            }
        }

        if (high_count >= 3) {
            printf("EARTHQUAKE ALERT\n");
        }
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

