#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDRESS 0x1E
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

static int i2c_file_descriptor;
static FILE *csv_file;

static void write_to_csv(int x, int y, int z, int heading) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    fprintf(csv_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%d\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            x, y, z, heading);
}

static void sig_handler(int signo) {
    close(i2c_file_descriptor);
    fclose(csv_file);
    exit(signo);
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave");
        exit(EXIT_FAILURE);
    }

    csv_file = fopen("mag_log.csv", "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    if (fseek(csv_file, 0, SEEK_END) != 0 || ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    while (1) {
        int x, y, z;
        if (read(i2c_file_descriptor, &x, sizeof(x)) != sizeof(x) ||
            read(i2c_file_descriptor, &y, sizeof(y)) != sizeof(y) ||
            read(i2c_file_descriptor, &z, sizeof(z))) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        x -= X_OFFSET;
        y -= Y_OFFSET;
        z -= Z_OFFSET;

        int heading = (atan2(y, x) * (180 / M_PI) + 360) % 360;
        write_to_csv(x, y, z, heading);

        const char *direction;
        if (heading < 22.5 || heading >= 337.5) direction = "N";
        else if (heading < 67.5) direction = "NE";
        else if (heading < 112.5) direction = "E";
        else if (heading < 157.5) direction = "SE";
        else if (heading < 202.5) direction = "S";
        else if (heading < 247.5) direction = "SW";
        else if (heading < 292.5) direction = "W";
        else direction = "NW";

        printf("Heading: %s (%d degrees)\n", direction, heading);

        sleep(1);
    }

    return 0;
}

