void log_state(int state) {
    struct tm *timeinfo;
    time_t now = time(0);
    char buffer[20];

    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    struct json_object *obj = json_object_new_object();
    json_object_object_add(obj, "timestamp", json_object_new_string(buffer));
    json_object_object_add(obj, "relay_state", json_object_new_string(state ? "ON" : "OFF"));

    fprintf(log_file, "%s\n", json_object_to_json_string(obj));
    json_object_put(obj);
}

void interrupt_handler(int signum) {
    gpiod_line_set_value(relay_line, 0);
    log_state(0);

    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_both_edges_events(sensor_line, "sensor")) {
        perror("gpiod_line_request_both_edges_events");
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    log_file = fopen("relay_log.json", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, interrupt_handler);

    struct timespec last_touch = { 0, 0 };

    while (1) {
        if (gpiod_line_event_wait(sensor_line, NULL)) {
            perror("gpiod_line_event_wait");
            return 1;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if ((now.tv_sec - last_touch.tv_sec) * 1000000000 + (now.tv_nsec - last_touch.tv_nsec) < DEBOUNCE_TIME)
            continue;

        last_touch = now;

        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            return 1;
        }

        if (value) {
            if (gpiod_line_set_value(relay_line, 1)) {
                perror("gpiod_line_set_value");
                return 1;
            }

            log_state(1);
        }
    }
}

