#define GPIO_LINE_17 17
#define GPIO_LINE_23 23
#define GPIO_LINE_24 24
#define GPIO_LINE_25 25

#define LOG_FILE "irrigation_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line_17, *line_23, *line_24, *line_25;
static FILE *log_file;

static void activate_relay(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        exit(EXIT_FAILURE);
    }
}

static void log_irrigation(int relay, int moisture)
{
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    sprintf(timestamp, "%d-%02d-%02dT%02d:%02d:%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    if (fprintf(log_file, "%s, relay %d, moisture %d\n", timestamp, relay, moisture) < 0) {
        perror("fprintf");
        exit(EXIT_FAILURE);
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        exit(EXIT_FAILURE);
    }
}

static void deactivate_all_relays(void)
{
    activate_relay(line_17, 1);
    activate_relay(line_23, 1);
    activate_relay(line_24, 1);
    activate_relay(line_25, 1);
}

static void close_log_file(void)
{
    if (fclose(log_file) != 0) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }
}

static void release_gpios(void)
{
    gpiod_line_release(line_17);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);
    gpiod_line_release(line_25);
    gpiod_chip_close(chip);
}

static void handle_signal(int signum)
{
    deactivate_all_relays();
    close_log_file();
    release_gpios();
    exit(EXIT_SUCCESS);
}

int main(void)
{
    srand(time(NULL));
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }
    line_17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    line_23 = gpiod_chip_get_line(chip, GPIO_LINE_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_LINE_24);
    line_25 = gpiod_chip_get_line(chip, GPIO_LINE_25);
    if (gpiod_line_request_output(line_17, "relay_17", 1) < 0 ||
        gpiod_line_request_output(line_23, "relay_23", 1) < 0 ||
        gpiod_line_request_output(line_24, "relay_24", 1) < 0 ||
        gpiod_line_request_output(line_25, "relay_25", 1) < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
