#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define MPU6050_ADDR 0x68
#define DEV_NAME "/dev/i2c-1"
#define GYRO_X_REG 0x43
#define GYRO_Y_REG 0x45
#define GYRO_Z_REG 0x47
#define SAMPLE_RATE 10

static int dev_fd = -1;
static FILE* log_file = NULL;

void exit_handler(int signum) {
    if (dev_fd != -1) {
        close(dev_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = exit_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    dev_fd = open(DEV_NAME, O_RDWR);
    if (dev_fd < 0) {
        perror("Failed to open I2C device");
        exit_handler(EXIT_FAILURE);
    }

    if (ioctl(dev_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave");
        exit_handler(EXIT_FAILURE);
    }

    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit_handler(EXIT_FAILURE);
    }

    while (1) {
        int16_t x, y, z;
        if (read(dev_fd, &x, sizeof(x)) != sizeof(x)) {
            perror("Failed to read gyro X");
            exit_handler(EXIT_FAILURE);
        }
        if (read(dev_fd, &y, sizeof(y)) != sizeof(y)) {
            perror("Failed to read gyro Y");
            exit_handler(EXIT_FAILURE);
        }
        if (read(dev_fd, &z, sizeof(z)) != sizeof(z)) {
            perror("Failed to read gyro Z");
            exit_handler(EXIT_FAILURE);
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%hd,%hd,%hd\n", ts.tv_sec, ts.tv_nsec, x, y, z);
        fflush(log_file);

        sleep(1 / SAMPLE_RATE);
    }

    exit_handler(EXIT_SUCCESS);
}

