#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define STEP_DELAY 3000
#define STEPS_PER_REV 512

struct gpiod_chip *chip;
struct gpiod_line *lines[4];
int step_dir, step_pulse;

void sigint_handler(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 0);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, 4 + i);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            return 1;
        }
        if (gpiod_line_request_output(lines[i], "stepper", 0)) {
            perror("gpiod_line_request_output");
            return 1;
        }
    }

    struct gpiod_line *lock_btn = gpiod_chip_get_line(chip, 24);
    struct gpiod_line *unlock_btn = gpiod_chip_get_line(chip, 23);
    if (!lock_btn || !unlock_btn) {
        perror("gpiod_chip_get_line");
        return 1;
    }
    if (gpiod_line_request_input(lock_btn, "lock_btn", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        perror("gpiod_line_request_input");
        return 1;
    }
    if (gpiod_line_request_input(unlock_btn, "unlock_btn", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        perror("gpiod_line_request_input");
        return 1;
    }

    while (1) {
        int lock_val = gpiod_line_get_value(lock_btn);
        int unlock_val = gpiod_line_get_value(unlock_btn);
        if (lock_val < 0 || unlock_val < 0) {
            perror("gpiod_line_get_value");
            return 1;
        }

        if (lock_val == 0) {
            printf("Locking the door...\n");
            step_dir = 0;
            step_pulse = 1;
            for (int i = 0; i < STEPS_PER_REV; i++) {
                for (int j = 0; j < 4; j++) {
                    gpiod_line_set_value(lines[j], (j == step_dir) ? step_pulse : 0);
                }
                step_dir = (step_dir + 1) % 4;
                usleep(STEP_DELAY);
            }
        } else if (unlock_val == 0) {
            printf("Unlocking the door...\n");
            step_dir = 0;
            step_pulse = 1;
            for (int i = 0; i < STEPS_PER_REV; i++) {
                for (int j = 0; j < 4; j++) {
                    gpiod_line_set_value(lines[j], (j == step_dir) ? step_pulse : 0);
                }
                step_dir = (step_dir + 3) % 4;
                usleep(STEP_DELAY);
            }
        }
    }

    return 0;
}

