struct gpiod_line *trigger, *echo;
FILE *log_file;

void cleanup_and_exit(int signum) {
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    trigger = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    if (!trigger) {
        fprintf(stderr, "Failed to get trigger line.\n");
        return 1;
    }

    echo = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line.\n");
        return 1;
    }

    if (gpiod_line_request_output(trigger, "Ultrasonic Sensor", 0)) {
        fprintf(stderr, "Failed to request trigger line as output.\n");
        return 1;
    }

    if (gpiod_line_request_input(echo, "Ultrasonic Sensor")) {
        fprintf(stderr, "Failed to request echo line as input.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    struct timespec ts;
    while (1) {
        gpiod_line_set_value(trigger, 1);
        nanosleep((const struct timespec[]){{0, TRIGGER_PULSE_US * 1000}}, &ts);
        gpiod_line_set_value(trigger, 0);

        int64_t start = gpiod_line_wait_for_rising_edge(echo, TIMEOUT_US);
        if (start < 0) {
            fprintf(stderr, "Failed to detect echo rising edge.\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        int64_t end = gpiod_line_wait_for_falling_edge(echo, TIMEOUT_US);
        if (end < 0) {
            fprintf(stderr, "Failed to detect echo falling edge.\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            continue;
        }

        int distance = (end - start) / 2 / 29 / 1000;
        fprintf(log_file, "%d\n", distance);
        fflush(log_file);

        usleep(SLEEP_BETWEEN_MEASUREMENTS_MS * 1000);
    }

    return 0;
}

