#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_RESET_PIN 18

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

static void cleanup_and_exit(int sig) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0);
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    exit(sig);
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_RESET_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "main", 0) < 0) {
        perror("Failed to request GPIO line for output");
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance
        uint16_t distance;
        if (read(i2c_fd, &distance, sizeof(distance)) != sizeof(distance)) {
            perror("Failed to read distance");
            return 1;
        }

        // Print distance
        printf("Distance: %u\n", distance);

        // Set relay state
        if (distance <= 50)
            gpiod_line_set_value(gpio_line, 1);
        else
            gpiod_line_set_value(gpio_line, 0);

        // Sleep
        usleep(100000);
    }

    return 0;
}

