#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP "gpiochip0"
#define OFFSET1 17
#define OFFSET2 18
#define OFFSET3 27
#define OFFSET4 22
#define LINE_COUNT 4
#define LOG_FILE "watering_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *lines[LINE_COUNT];
FILE *log_file;

void sig_handler(int signo) {
    for (int i = 0; i < LINE_COUNT; i++) {
        gpiod_line_set_value(lines[i], 1);
    }
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(signo);
}

int main() {
    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 17);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(lines[i], "watering", 1)) {
            perror("gpiod_line_request_output");
            exit(EXIT_FAILURE);
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    time_t now;
    struct tm *time_info;
    char buffer[80];

    while (1) {
        for (int i = 0; i < LINE_COUNT; i++) {
            gpiod_line_set_value(lines[i], 0);
            sleep(5);
            gpiod_line_set_value(lines[i], 1);
        }

        now = time(0);
        time_info = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
        fprintf(log_file, "%s: Watering cycle completed\n", buffer);
        fflush(log_file);

        sleep(86400);
    }

    return 0;
}

