#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define PWM_CHANNEL_1 17
#define PWM_CHANNEL_2 18
#define PWM_CHANNEL_3 27
#define PWM_CHANNEL_4 22

#define PWM_PERIOD 1000
#define MAX_DUTY_CYCLE 255
#define SLEEP_TIME 1
#define LOG_FILE "smart_lighting.log"

struct gpiod_chip *chip;
struct gpiod_line *pwm_channel_1, *pwm_channel_2, *pwm_channel_3, *pwm_channel_4;
FILE *log_file;

void log_event(const char *event) {
    time_t t = time(NULL);
    char *time_str = ctime(&t);
    time_str[strlen(time_str) - 1] = '\0';
    fprintf(log_file, "%s: %s\n", time_str, event);
    fflush(log_file);
}

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        log_event("Received termination signal, shutting down...");
        gpiod_line_release(pwm_channel_1);
        gpiod_line_release(pwm_channel_2);
        gpiod_line_release(pwm_channel_3);
        gpiod_line_release(pwm_channel_4);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(0);
    }
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    pwm_channel_1 = gpiod_chip_get_line(chip, PWM_CHANNEL_1);
    pwm_channel_2 = gpiod_chip_get_line(chip, PWM_CHANNEL_2);
    pwm_channel_3 = gpiod_chip_get_line(chip, PWM_CHANNEL_3);
    pwm_channel_4 = gpiod_chip_get_line(chip, PWM_CHANNEL_4);

    if (!pwm_channel_1 || !pwm_channel_2 || !pwm_channel_3 || !pwm_channel_4) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_pwm_mode(pwm_channel_1, PWM_PERIOD, 0) ||
        gpiod_line_request_pwm_mode(pwm_channel_2, PWM_PERIOD, 0) ||
        gpiod_line_request_pwm_mode(pwm_channel_3, PWM_PERIOD, 0) ||
        gpiod_line_request_pwm_mode(pwm_channel_4, PWM_PERIOD, 0)) {
        perror("gpiod_line_request_pwm_mode");
        exit(1);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    log_event("Starting smart lighting sunrise effect...");

    for (int i = 0; i <= MAX_DUTY_CYCLE; i++) {
        if (gpiod_line_set_pwm_duty_cycle(pwm_channel_1, i) ||
            gpiod_line_set_pwm_duty_cycle(pwm_channel_2, i) ||
            gpiod_line_set_pwm_duty_cycle(pwm_channel_3, i) ||
            gpiod_line_set_pwm_duty_cycle(pwm_channel_4, i)) {
            perror("gpiod_line_set_pwm_duty_cycle");
            exit(1);
        }
        sleep(SLEEP_TIME);
    }

    log_event("Smart lighting sunrise effect completed.");

    gpiod_line_release(pwm_channel_1);
    gpiod_line_release(pwm_channel_2);
    gpiod_line_release(pwm_channel_3);
    gpiod_line_release(pwm_channel_4);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

