#include <libgpiod.h>
#include <spi/spi.h>

#define SPI_DEV "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define MAX_RETRIES 3

struct spi_device *spi;
struct gpiod_line *gpio_line;
FILE *log_file;

void cleanup_and_exit(int signum) {
    spi_close(spi);
    gpiod_line_release(gpio_line);
    fclose(log_file);
    exit(0);
}

int main() {
    struct spi_init_opts opts;
    struct timespec ts;
    char buf[100];
    int retries = 0;
    int rc;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    spi = spi_open_device(SPI_DEV, SPI_MODE, SPI_SPEED, SPI_BITS);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    gpio_line = gpiod_line_request_by_offset(GPIO_CHIP, GPIO_LINE, "spi_cs");
    if (!gpio_line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        rc = gpiod_line_set_value(gpio_line, 0);
        if (rc < 0) {
            fprintf(stderr, "Failed to assert GPIO line\n");
            return 1;
        }

        rc = spi_transfer_data(spi, NULL, buf, sizeof(buf));
        if (rc < 0) {
            if (retries < MAX_RETRIES) {
                retries++;
                continue;
            } else {
                fprintf(stderr, "Failed to read from SPI device\n");
                return 1;
            }
        }

        rc = gpiod_line_set_value(gpio_line, 1);
        if (rc < 0) {
            fprintf(stderr, "Failed to deassert GPIO line\n");
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%s\n", ts.tv_sec, ts.tv_nsec, buf);

        rc = fflush(log_file);
        if (rc < 0) {
            fprintf(stderr, "Failed to flush log file\n");
            return 1;
        }

        usleep(10000);
    }

    return 0;
}

