    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!line) {
        printf("Failed to get GPIO line\n");
        return -1;
    }

