                tx_buf[0] = 0x03 | 0x80;
                tx_buf[1] = 0x00;
                tx_buf[2] = 0x00;
                spi_transfer(spi, &xfer);
                ts = time(NULL) * 1000000 + clock() / (CLOCKS_PER_SEC / 1000000);
                fprintf(csv_file, "%d\n", (rx_buf[1] << 8) | rx_buf[2]);

                fflush(csv_file);
            }
        } else {
            if (retries++ >= MAX_RETRIES) {
                printf("Too many retries, exiting...\n");
                return -1;
            }
            sleep(1);
        }
    }

    return 0;
}

