#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CS 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define LED_GPIO 17
#define ADDR_READ 0x80
#define GYRO_ADDR 0x0
#define GYRO_THRESHOLD 20.0
#define BUF_SIZE 100

struct buf_entry {
    struct timespec ts;
    float rate;
};

struct app_state {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    struct gpiod_line *sclk_line;
    struct gpiod_line *mosi_line;
    struct gpiod_line *miso_line;
    struct gpiod_line *led_line;
    struct buf_entry buf[BUF_SIZE];
    int buf_head;
    int buf_tail;
    pthread_mutex_t buf_lock;
};

static struct app_state state;

static void sig_handler(int signum)
{
    close(state.spi_fd);
    gpiod_line_set_value(state.led_line, 0);
    gpiod_line_release(state.cs_line);
    gpiod_line_release(state.sclk_line);
    gpiod_line_release(state.mosi_line);
    gpiod_line_release(state.miso_line);
    gpiod_line_release(state.led_line);
    gpiod_chip_close(state.chip);
    exit(0);
}

static int spi_transfer(const char *data, char *buf, size_t len)
{
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = 8,
    };

    if (ioctl(state.spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return 0;
}

static void *read_thread(void *arg)
{
    char tx_buf[2] = { ADDR_READ | GYRO_ADDR, 0 };
    char rx_buf[2];
    struct timespec ts;
    float rate;

    while (1) {
        gpiod_line_set_value(state.cs_line, 1);
        if (spi_transfer(tx_buf, rx_buf, sizeof(rx_buf)) < 0)
            return NULL;
        gpiod_line_set_value(state.cs_line, 0);

        rate = (rx_buf[0] << 8 | rx_buf[1]) / 131.0;

        clock_gettime(CLOCK_MONOTONIC, &ts);

        pthread_mutex_lock(&state.buf_lock);
        state.buf[state.buf_head].ts = ts;
        state.buf[state.buf_head].rate = rate;
        state.buf_head = (state.buf_head + 1) % BUF_SIZE;
        if (state.buf_head == state.buf_tail)
            state.buf_tail = (state.buf_tail + 1) % BUF_SIZE;
