#include <fcntl.h>

#define MPR121_I2C_ADDR 0x5A
#define MPR121_TOUCH_STATUS_REG 0x0
#define MPR121_ELECTRODE_0_TOUCHED 0x01
#define MPR121_GPIO_PIN 17

#define LOG_FILE "touch_relay.log"

static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int i2c_file = -1;
static FILE *log_file = NULL;

void log_error(const char *msg) {
    time_t t = time(NULL);
    char *time_str = ctime(&t);
    time_str[strlen(time_str) - 1] = '\0';  // remove trailing newline
    fprintf(log_file, "%s: %s\n", time_str, msg);
    fflush(log_file);
}

void cleanup_and_exit(int signum) {
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_file >= 0)
        close(i2c_file);
    if (log_file)
        fclose(log_file);
    exit(signum);
}

int main() {
    int ret;
    uint8_t buf[1];

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!gpio_chip) {
        log_error("Failed to open GPIO chip");
        cleanup_and_exit(-1);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, MPR121_GPIO_PIN);
    if (!gpio_line) {
        log_error("Failed to get GPIO line");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_output(gpio_line, "touch_relay", 0);
    if (ret < 0) {
        log_error("Failed to request GPIO line");
        cleanup_and_exit(-1);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        log_error("Failed to open I2C device file");
        cleanup_and_exit(-1);
    }

    ret = ioctl(i2c_file, I2C_SLAVE, MPR121_I2C_ADDR);
    if (ret < 0) {
        log_error("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        usleep(10000);  // sleep for 10 ms

        buf[0] = MPR121_TOUCH_STATUS_REG;
        ret = write(i2c_file, buf, 1);
        if (ret < 0) {
            log_error("Failed to write to I2C device");
            cleanup_and_exit(-1);
        }

        ret = read(i2c_file, buf, 1);
        if (ret < 0) {
            log_error("Failed to read from I2C device");
            cleanup_and_exit(-1);
        }

        if (buf[0] & MPR121_ELECTRODE_0_TOUCHED) {
            usleep(100000);  // debounce for 100 ms

            buf[0] = MPR121_TOUCH_STATUS_REG;
            ret = write(i2c_file, buf, 1);
            if (ret < 0) {
                log_error("Failed to write to I2C device");
                cleanup_and_exit(-1);
            }

            ret = read(i2c_file, buf, 1);
            if (ret < 0) {
                log_error("Failed to read from I2C device");
                cleanup_and_exit(-1);
            }

            if (buf[0] & MPR121_ELECTRODE_0_TOUCHED) {
                gpiod_line_set_value(gpio_line, !gpiod_line_get_value(gpio_line));
            }
        }
    }

    return 0;
}
