#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define DISPENSE_DURATION 1000
#define LOG_FILE "dispense_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *solenoid1, *solenoid2;
FILE *log_file;

void sigint_handler(int signum) {
    gpiod_line_set_value(solenoid1, 0);
    gpiod_line_set_value(solenoid2, 0);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main(void) {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    solenoid1 = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    solenoid2 = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!solenoid1 || !solenoid2) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_output(solenoid1, "solenoid1", 0) ||
        gpiod_line_request_output(solenoid2, "solenoid2", 0)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        struct timespec start, end;
        long duration;

        clock_gettime(CLOCK_MONOTONIC, &start);

        gpiod_line_set_value(solenoid1, 1);
        usleep(DISPENSE_DURATION / 2 * 1000);
        gpiod_line_set_value(solenoid1, 0);

        gpiod_line_set_value(solenoid2, 1);
        usleep(DISPENSE_DURATION / 2 * 1000);
        gpiod_line_set_value(solenoid2, 0);

        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;

        fprintf(log_file, "%ld, %d, %d, %ld\n", time(NULL), SOLENOID1_PIN, SOLENOID2_PIN, duration);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

