#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <math.h>

#define GPIO_MOTOR_A_FWD 17
#define GPIO_MOTOR_A_REV 18
#define GPIO_MOTOR_B_FWD 22
#define GPIO_MOTOR_B_REV 23
#define GPIO_ENA 24
#define GPIO_ENB 25

#define PWM_MAX 255
#define PWM_REVERSE_THRESHOLD 20

struct gpiod_chip *chip;
struct gpiod_line *lines[5];
int pwm_values[2];
FILE *log_file;

void cleanup_and_exit(int sig) {
    for (int i = 0; i < 5; i++)
        gpiod_line_release(lines[i]);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    srand(time(NULL));

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (int i = 0; i < 5; i++) {
        lines[i] = gpiod_chip_get_line(chip, i < 2 ? i + GPIO_MOTOR_A_FWD : i == 2 ? GPIO_ENA : i == 3 ? GPIO_MOTOR_B_FWD : GPIO_ENB);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            cleanup_and_exit(0);
        }

        if (gpiod_line_request_output(lines[i], "balance_robot", i < 2 || i == 4 ? 0 : 1)) {
            perror("gpiod_line_request_output");
            cleanup_and_exit(0);
        }
    }

    log_file = fopen("balance_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        cleanup_and_exit(0);
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        int tilt_error = rand() % 21 - 10;
        float distance = rand() % 399 + 200;

        if (distance < PWM_REVERSE_THRESHOLD) {
            pwm_values[0] = pwm_values[1] = PWM_MAX / 2;
        } else {
            pwm_values[0] = pwm_values[1] = PWM_MAX;
        }

        for (int i = 0; i < 2; i++) {
            gpiod_line_set_value(lines[i], pwm_values[i] > 0);
            gpiod_line_set_value(lines[i + 2], abs(pwm_values[i]));
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d,%.1f,%d,%d\n", timestamp, tilt_error, distance, pwm_values[0], pwm_values[1]);
        fflush(log_file);

        usleep(50000);
    }

    return 0;
}

