#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY 50000 /* 50 ms */

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL, *relay_line = NULL;

void cleanup_and_exit(int sig)
{
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (relay_line)
        gpiod_line_release(relay_line);
    if (chip)
        gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(sig);
}

int main()
{
    int ret;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup_and_exit(-1);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_input(sensor_line, "sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_request_input");
        cleanup_and_exit(-1);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
