#include <fcntl.h>

#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_AIEN 0x10
#define TCS34725_ENABLE_WEN 0x08
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ATIME 0x01
#define TCS34725_ENABLE_POWERON (TCS34725_COMMAND_BIT | TCS34725_ENABLE)
#define TCS34725_ENABLE_AEN_PON (TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN)
#define TCS34725_ATIME_154MS 0xB6

static int i2c_file_descriptor = -1;
static FILE *csv_file = NULL;

void sig_handler(int signo) {
    if (i2c_file_descriptor != -1) {
        close(i2c_file_descriptor);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(signo);
}

int main() {
    int ret;
    unsigned char buf[2];
    unsigned short c, r, g, b;
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if ((ret = sigaction(SIGINT, &action, NULL)) < 0 ||
        (ret = sigaction(SIGTERM, &action, NULL)) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(ret));
        return 1;
    }

    i2c_file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Failed to open i2c device: %s\n", strerror(i2c_file_descriptor));
        return 1;
    }

    if ((ret = ioctl(i2c_file_descriptor, I2C_SLAVE, TCS34725_ADDR)) < 0) {
        fprintf(stderr, "Failed to set slave address: %s\n", strerror(ret));
        return 1;
    }

    buf[0] = TCS34725_ENABLE_POWERON;
    if ((ret = write(i2c_file_descriptor, buf, 1)) < 0) {
        fprintf(stderr, "Failed to write to sensor: %s\n", strerror(ret));
        return 1;
    }

    buf[0] = TCS34725_ATIME_154MS;
    if ((ret = write(i2c_file_descriptor, buf, 1)) < 0) {
        fprintf(stderr, "Failed to write to sensor: %s\n", strerror(ret));
        return 1;
    }

    buf[0] = TCS34725_ENABLE_AEN_PON;
    if ((ret = write(i2c_file_descriptor, buf, 1)) < 0) {
        fprintf(stderr, "Failed to write to sensor: %s\n", strerror(ret));
        return 1;
    }

    csv_file = fopen("color_data.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    fprintf(csv_file, "timestamp,c,r,g,b\n");

    while (1) {
        usleep(500000);

        buf[0] = TCS34725_COMMAND_BIT | 0x12;
        if ((ret = write(i2c_file_descriptor, buf, 1)) < 0) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(ret));
            c = r = g = b = 0;
        } else {
            if ((ret = read(i2c_file_descriptor, &b, 2)) < 0) {
                fprintf(stderr, "Failed to read from sensor: %s\n", strerror(ret));
                c = r = g = b = 0;
            }
            if ((ret = read(i2c_file_descriptor, &g, 2)) < 0) {
                fprintf(stderr, "Failed to read from sensor: %s\n", strerror(ret));
                c = r = g = b = 0;
            }
            if ((ret = read(i2c_file_descriptor, &r, 2)) < 0) {
                fprintf(stderr, "Failed to read from sensor: %s\n", strerror(ret));
                c = r = g = b = 0;
            }
            if ((ret = read(i2c_file_descriptor, &c, 2)) < 0) {
                fprintf(stderr, "Failed to read from sensor: %s\n", strerror(ret));
                c = r = g = b = 0;
            }
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[26];
        strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(csv_file, "%s,%hu,%hu,%hu,%hu\n", timestamp, c, r, g, b);
    }

    return 0;
}

