#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_LINE 17
#define DEBOUNCE_TIME 200000000LL
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

struct gpiod_line *line;
FILE *log_file;

void sigint_handler(int signum) {
    fclose(log_file);
    gpiod_line_release(line);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct timespec ts;
    struct tm *timeinfo;
    char filename[64];
    char cmd[128];
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_rising_edge_events(line, "motion_sensor");
    if (ret) {
        perror("gpiod_line_request_rising_edge_events");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            return 1;
        }

        if (ret == 0)
            continue;

        clock_gettime(CLOCK_REALTIME, &ts);
        timeinfo = localtime(&ts.tv_sec);

        strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", timeinfo);
        sprintf(cmd, "raspivid -o %s%s -t 5000", VIDEO_DIR, filename);

        ret = system(cmd);
        if (ret) {
            fprintf(stderr, "Video capture failed\n");
            return 1;
        }

        fprintf(log_file, "%ld.%09ld: Motion detected\n", ts.tv_sec, ts.tv_nsec);

        ts.tv_nsec += DEBOUNCE_TIME;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_nsec -= 1000000000;
            ts.tv_sec++;
        }
    }

    return 0;
}

