#define MPU6050_ADDR 0x68
#define MPU6050_GYRO_XOUT_REG 0x43
#define MPU6050_SMPLRT_DIV_REG 0x19
#define MPU6050_CONFIG_REG 0x1A
#define MPU6050_GYRO_CONFIG_REG 0x1B
#define MPU6050_ACCEL_CONFIG_REG 0x1C

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

static void cleanup_and_exit(int signum) {
    if (log_file)
        fclose(log_file);
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 18);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_input(line, "MPU6050 I2C")) {
        perror("Failed to request GPIO line");
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        int x, y, z;
        for (int i = 0; i < 3; i++) {
            if (gpiod_line_read(line, &x) && gpiod_line_read(line, &y) && gpiod_line_read(line, &z)) {
                fprintf(stderr, "Failed to read from MPU6050: %s\n", strerror(errno));
                continue;
            }

            fprintf(log_file, "%ld.%03ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
            fflush(log_file);

            usleep(10000);
        }
    }

    return 0;
}

