#define MAX_ECHO_PULSEWIDTH 23200000LL
#define LOG_FILE "distance_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *trig_line, *echo_line;
FILE *log_file;
pthread_mutex_t mutex;

struct timespec start_time;
long long echo_pulsewidth = -1;
volatile int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void trigger_sensor() {
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);
}

void echo_rising_handler(struct gpiod_line *line, void *data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    echo_pulsewidth = ts.tv_nsec - start_time.tv_nsec;
    pthread_mutex_lock(&mutex);
}

void echo_falling_handler(struct gpiod_line *line, void *data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    echo_pulsewidth = ts.tv_nsec - start_time.tv_nsec + echo_pulsewidth;
    pthread_mutex_unlock(&mutex);
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_GPIO);
    if (!trig_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_rising_edge_events(echo_line, "echo_rising_handler", echo_rising_handler, NULL)) {
        perror("gpiod_line_request_rising_edge_events");
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(echo_line, "echo_falling_handler", echo_falling_handler, NULL)) {
        perror("gpiod_line_request_falling_edge_events");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    if (pthread_mutex_init(&mutex, NULL)) {
        perror("pthread_mutex_init");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        trigger_sensor();
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        for (int i = 0; i < 200000; i++) {
            if (!running) break;
            if (echo_pulsewidth >= 0) {
                if (echo_pulsewidth <= MAX_ECHO_PULSEWIDTH) {
                    fprintf(log_file, "%lld,%lld\n", start_time.tv_nsec, echo_pulsewidth);
                }
                echo_pulsewidth = -1;
                break;
            }
            usleep(10);
        }
        if (echo_pulsewidth != -1) {
            fprintf(stderr, "Timeout error\n");
            echo_pulsewidth = -1;
        }
        usleep(200000);
    }

    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);

    return 0;
}

