#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define GPIO_BCM_17 17

#define LIS3DH_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33

#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG1_VAL 0x0F

#define LIS3DH_OUT_X_L 0x28

#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

static int buzzer_gpio;
static int i2c_fd;
static volatile int running = 1;

static void handle_sigint(int signum) {
    running = 0;
}

static int i2c_write_reg(unsigned char reg, unsigned char val) {
    struct i2c_msg msgs[2] = {
        {I2C_ADDR, 0, 1, &reg},
        {I2C_ADDR, 0, 1, &val},
    };
    if (ioctl(i2c_fd, I2C_RDWR, msgs) < 0) {
        perror("i2c_write_reg");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(unsigned char reg, unsigned char *val) {
    struct i2c_msg msgs[2] = {
        {I2C_ADDR, 0, 1, &reg},
        {I2C_ADDR, I2C_M_RD, 1, val},
    };
    if (ioctl(i2c_fd, I2C_RDWR, msgs) < 0) {
        perror("i2c_read_reg");
        return -1;
    }
    return 0;
}

static int init_i2c() {
    char device_name[20];
    sprintf(device_name, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(device_name, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("set i2c slave");
        return -1;
    }
    return 0;
}

static int init_buzzer() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    buzzer_gpio = gpiod_chip_get_line(chip, GPIO_BCM_17);
    if (buzzer_gpio < 0) {
        perror("gpiod_chip_get_line");
        return -1;
    }
    if (gpiod_line_request_output(buzzer_gpio, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }
    return 0;
}

static void cleanup() {
    gpiod_line_release(buzzer_gpio);
    close(i2c_fd);
}

int main(int argc, char *argv[]) {
    if (argc > 3) {
        fprintf(stderr, "Usage: %s [free_fall_threshold] [impact_threshold]\n", argv[0]);
        return 1;
    }
    double free_fall_threshold = argc > 1 ? atof(argv[1]) : FREE_FALL_THRESHOLD;
    double impact_threshold = argc > 2 ? atof(argv[2]) : IMPACT_THRESHOLD;

    if (init_i2c() < 0 || init_buzzer() < 0) {
        cleanup();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    unsigned char who_am_i;
    if (i2c_read_reg(LIS3DH_WHO_AM_I, &who_am_i) < 0 || who_am_i != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "Failed to detect LIS3DH\n");
        cleanup();
        return 1;
    }

    if (i2c_write_reg(LIS3DH_CTRL_REG1, LIS3DH_CTRL_REG1_VAL) < 0) {
        fprintf(stderr, "Failed to initialize LIS3DH\n");
        cleanup();
        return 1;
    }

    while (running) {
        unsigned char x_l;
        if (i2c_read_reg(LIS3DH_OUT_X_L, &x_l) < 0) {
            fprintf(stderr, "Failed to read LIS3DH\n");
            continue;
        }
        double accel = (double)x_l / 16384.0;
        if (accel < free_fall_threshold) {
            printf("Free fall detected\n");
        } else if (accel > impact_threshold) {
            printf("Impact detected\n");
            gpiod_line_set_value(buzzer_gpio, 1);
            sleep(1);
            gpiod_line_set_value(buzzer_gpio, 0);
        }
    }

    cleanup();
    return 0;
}

