#include <sys/socket.h>
#include <arpa/inet.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define TCP_PORT 5000

struct gpiod_chip *chip;
struct gpiod_line *line;
int sockfd, newsockfd;
FILE *log_file;

void sig_handler(int signo) {
    if (chip && line)
        gpiod_line_set_value(line, 0);
    if (sockfd)
        close(sockfd);
    if (newsockfd)
        close(newsockfd);
    if (log_file)
        fclose(log_file);
    exit(signo);
}

int main() {
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t cli_len;
    char client_message[1024];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "relay-driver", 0)) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    memset(&serv_addr, '0', sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(TCP_PORT);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    if (listen(sockfd, 5) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    cli_len = sizeof(cli_addr);
    newsockfd = accept(sockfd, (struct sockaddr *)&cli_addr, &cli_len);
    if (newsockfd < 0) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("relay_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        memset(client_message, 0, sizeof(client_message));
        if (recv(newsockfd, client_message, sizeof(client_message), 0) < 0) {
            perror("recv");
            exit(EXIT_FAILURE);
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        char *command = strtok(client_message, " \n");
        if (!strcasecmp(command, "ON")) {
            gpiod_line_set_value(line, 1);
            fprintf(log_file, "%s: Relay turned ON\n", timestamp);
        } else if (!strcasecmp(command, "OFF")) {
            gpiod_line_set_value(line, 0);
            fprintf(log_file, "%s: Relay turned OFF\n", timestamp);
        } else {
            fprintf(log_file, "%s: Invalid command received\n", timestamp);
        }

        fflush(log_file);
    }

    return 0;
}

