        perror("gpiod_line_request_output");
        return 1;
    }

    i2c_sensor1 = open("/dev/i2c-1", O_RDWR);
    if (i2c_sensor1 == -1) {
        perror("open i2c-1");
        return 1;
    }

    i2c_sensor2 = open("/dev/i2c-1", O_RDWR);
    if (i2c_sensor2 == -1) {
        perror("open i2c-1");
        return 1;
    }

    if (ioctl(i2c_sensor1, I2C_SLAVE, SENSOR1_ADDR) == -1) {
        perror("ioctl");
        return 1;
    }

    if (ioctl(i2c_sensor2, I2C_SLAVE, SENSOR2_ADDR) == -1) {
        perror("ioctl");
        return 1;
    }

    if (write(i2c_sensor1, SLF3S_MEASURE_CMD, sizeof(SLF3S_MEASURE_CMD)) != sizeof(SLF3S_MEASURE_CMD)) {
        perror("write");
        return 1;
    }

    if (write(i2c_sensor2, SLF3S_MEASURE_CMD, sizeof(SLF3S_MEASURE_CMD)) != sizeof(SLF3S_MEASURE_CMD)) {
        perror("write");
        return 1;
    }

    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    while (1) {
        uint8_t data1[3], data2[3];
        if (read(i2c_sensor1, data1, sizeof(data1)) != sizeof(data1) ||
            slf3s_check_crc(data1, sizeof(data1)) != 0) {
            fprintf(stderr, "Read or CRC error on sensor 1\n");
            continue;
        }

        if (read(i2c_sensor2, data2, sizeof(data2)) != sizeof(data2) ||
            slf3s_check_crc(data2, sizeof(data2)) != 0) {
            fprintf(stderr, "Read or CRC error on sensor 2\n");
            continue;
        }

        float flow1 = slf3s_data_to_flow(data1);
        float flow2 = slf3s_data_to_flow(data2);

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld %.1f %.1f\n", ts.tv_sec, ts.tv_nsec, flow1, flow2);
        fflush(log_file);

        if (flow1 < 5.0 || flow2 < 5.0) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        usleep(100000);
    }

    return 0;
}

