#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_RAIN_SENSOR 17
#define GPIO_MOTOR_ENA 22
#define GPIO_MOTOR_IN1 23
#define GPIO_MOTOR_IN2 24

#define POLL_INTERVAL_MS 200
#define MOTOR_DURATION_SEC 5

struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL, *ena_line = NULL, *in1_line = NULL, *in2_line = NULL;
int sensor_val = 1, consecutive_dry = 0;

void start_motor(void) {
    if (gpiod_line_set_value(ena_line, 1) || gpiod_line_set_value(in1_line, 1) || gpiod_line_set_value(in2_line, 0)) {
        syslog(LOG_ERR, "Failed to start motor");
        exit(EXIT_FAILURE);
    }
    syslog(LOG_INFO, "Started motor");
    sleep(MOTOR_DURATION_SEC);
    if (gpiod_line_set_value(ena_line, 0) || gpiod_line_set_value(in1_line, 0) || gpiod_line_set_value(in2_line, 0)) {
        syslog(LOG_ERR, "Failed to stop motor");
        exit(EXIT_FAILURE);
    }
    syslog(LOG_INFO, "Stopped motor");
}

void sig_handler(int signo) {
    if (gpiod_line_set_value(ena_line, 0) || gpiod_line_set_value(in1_line, 0) || gpiod_line_set_value(in2_line, 0)) {
        syslog(LOG_ERR, "Failed to stop motor on signal");
    }
    syslog(LOG_INFO, "Stopped motor on signal");
    closelog();
    exit(EXIT_SUCCESS);
}

int main(void) {
    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting rain window control");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_RAIN_SENSOR);
    ena_line = gpiod_chip_get_line(chip, GPIO_MOTOR_ENA);
    in1_line = gpiod_chip_get_line(chip, GPIO_MOTOR_IN1);
    in2_line = gpiod_chip_get_line(chip, GPIO_MOTOR_IN2);

    if (!sensor_line || !ena_line || !in1_line || !in2_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(sensor_line, "Rain Sensor") ||
        gpiod_line_request_output(ena_line, "Motor ENA", 0) ||
        gpiod_line_request_output(in1_line, "Motor IN1", 0) ||
        gpiod_line_request_output(in2_line, "Motor IN2", 0)) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        sensor_val = gpiod_line_get_value(sensor_line);
        if (sensor_val == 0) {
            consecutive_dry = 0;
            if (gpiod_line_get_value(sensor_line)) {
                start_motor();
            }
        } else {
            consecutive_dry++;
            if (consecutive_dry >= 3) {
                sensor_val = 1;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(ena_line);
    gpiod_line_release(in1_line);
    gpiod_line_release(in2_line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

