#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define MPR121_I2C_ADDR 0x5A
#define MPR121_TOUCH_STATUS_REG 0x00
#define MPR121_FIRST_ELEC_REG 0x01
#define MPR121_LAST_ELEC_REG 0x0C
#define MPR121_ELEC_CFG_REG 0x41
#define MPR121_CDT0_LOW_REG 0x5B
#define MPR121_CDT0_HIGH_REG 0x5C
#define MPR121_CDT1_LOW_REG 0x5D
#define MPR121_CDT1_HIGH_REG 0x5E
#define MPR121_DEBOUNCE_REG 0x2B
#define MPR121_INT_CLR_REG 0x21
#define MPR121_SOFT_RESET_REG 0x80

#define MPR121_TOUCH_STATUS_TOUCHED 0x01
#define MPR121_ELEC_CFG_VAL 0x24
#define MPR121_CDT_VAL 0x08
#define MPR121_DEBOUNCE_VAL 0x28

#define GPIO_PIN 17

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

static void cleanup_and_exit(int sig) {
    if (gpio_line)
        gpiod_line_set_value(gpio_line, 0);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_fd != -1)
        close(i2c_fd);
    exit(sig);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    gpio_chip = gpiod_chip_open_by_name("pinctrl-bcm2711");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup_and_exit(-1);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_output(gpio_line, "mpr121", 0)) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) == -1) {
        perror("ioctl");
        cleanup_and_exit(-1);
    }

    unsigned char reg[2] = {MPR121_SOFT_RESET_REG, 0xAA};
    if (write(i2c_fd, reg, 2) != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    reg[0] = MPR121_ELEC_CFG_REG;
    reg[1] = MPR121_ELEC_CFG_VAL;
    if (write(i2c_fd, reg, 2) != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    reg[0] = MPR121_CDT0_LOW_REG;
    reg[1] = MPR121_CDT_VAL;
    if (write(i2c_fd, reg, 2) != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    reg[0] = MPR121_CDT0_HIGH_REG;
    reg[1] = MPR121_CDT_VAL;
    if (write(i2c_fd, reg, 2) != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    reg[0] = MPR121_CDT1_LOW_REG;
    reg[1] = MPR121_CDT_VAL;
    if (write(i2c_fd, reg, 2) != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    reg[0] = MPR121_CDT1_HIGH_REG;
    reg[1] = MPR121_CDT_VAL;
    if (write(i2c_fd, reg, 2) != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    reg[0] = MPR121_DEBOUNCE_REG;
    reg[1] = MPR121_DEBOUNCE_VAL;
    if (write(i2c_fd, reg, 2) != 2) {
        perror("write");
        cleanup_and_exit(-1);
    }

    unsigned char status;
    while (1) {
        if (read(i2c_fd, &status, 1) != 1) {
            perror("read");
            cleanup_and_exit(-1);
        }

        if ((status & MPR121_TOUCH_STATUS_TOUCHED) == MPR121_TOUCH_STATUS_TOUCHED) {
            if (gpiod_line_set_value(gpio_line, 1)) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }
            usleep(200000);
            if (gpiod_line_set_value(gpio_line, 0)) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }
        }
    }

    return 0;
}

