#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <libgpiod.h>

#define LOG_FILE "/var/log/security.log"
#define LOG_SIZE 256
#define GPIO_SERVO 17
#define GPIO_PIR 4
#define PORT 5000

struct gpiod_chip *chip;
struct gpiod_line *line_servo, *line_pir;
int fd_log, fd_socket;

void log_event(const char *fmt, ...) {
    char buf[LOG_SIZE];
    va_list args;
    va_start(args, fmt);
    vsnprintf(buf, LOG_SIZE, fmt, args);
    va_end(args);
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    dprintf(fd_log, "%s %s\n", timestamp, buf);
    syslog(LOG_USER | LOG_INFO, "%s", buf);
}

void handle_error(const char *fmt, ...) {
    char buf[LOG_SIZE];
    va_list args;
    va_start(args, fmt);
    vsnprintf(buf, LOG_SIZE, fmt, args);
    va_end(args);
    log_event("Error: %s", buf);
    exit(EXIT_FAILURE);
}

void cleanup_and_exit(int signum) {
    gpiod_line_release(line_servo);
    gpiod_line_release(line_pir);
    gpiod_chip_close(chip);
    close(fd_log);
    shutdown(fd_socket, SHUT_RDWR);
    exit(EXIT_SUCCESS);
}

int main() {
    openlog("gpio_servo_pir", LOG_CONS | LOG_PERROR, LOG_USER);
    fd_log = open(LOG_FILE, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd_log < 0)
        handle_error("Failed to open log file: %s", strerror(errno));

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
        handle_error("Failed to open GPIO chip: %s", strerror(errno));

    line_servo = gpiod_chip_get_line(chip, GPIO_SERVO);
    if (!line_servo)
        handle_error("Failed to get GPIO line %d: %s", GPIO_SERVO, strerror(errno));

    if (gpiod_line_request_output(line_servo, "servo", 0))
        handle_error("Failed to request GPIO line %d: %s", GPIO_SERVO, strerror(errno));

    line_pir = gpiod_chip_get_line(chip, GPIO_PIR);
    if (!line_pir)
        handle_error("Failed to get GPIO line %d: %s", GPIO_PIR, strerror(errno));

    if (gpiod_line_request_input(line_pir, "pir"))
        handle_error("Failed to request GPIO line %d: %s", GPIO_PIR, strerror(errno));

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    struct sockaddr_in addr;
    fd_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (fd_socket < 0)
        handle_error("Failed to create socket: %s", strerror(errno));

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(PORT);

    if (bind(fd_socket, (struct sockaddr *)&addr, sizeof(addr)) < 0)
        handle_error("Failed to bind socket: %s", strerror(errno));

    if (listen(fd_socket, 5) < 0)
        handle_error("Failed to listen on socket: %s", strerror(errno));

    while (1) {
        int fd_client = accept(fd_socket, NULL, NULL);
        if (fd_client < 0)
            handle_error("Failed to accept client connection: %s", strerror(errno));

        char buf[100];
        int n = read(fd_client, buf, sizeof(buf) - 1);
        if (n < 0)
            handle_error("Failed to read from client: %s", strerror(errno));

        buf[n] = '\0';
        log_event("Received command: %s", buf);

        if (strncmp(buf, "PIR", 3) == 0) {
            int val = gpiod_line_get_value(line_pir);
            sprintf(buf, "PIR:%d", val);
            n = write(fd_client, buf, strlen(buf));
            if (n < 0)
                handle_error("Failed to write to client: %s", strerror(errno));
        }
        else {
            int angle = atoi(buf);
            if (angle < 0 || angle > 180)
                handle_error("Invalid angle: %d", angle);

            // TODO: generate a software PWM signal at 50 Hz with a 1-2 ms pulse width
        }

        close(fd_client);
    }

    return 0;
}

