#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_POWER_OFF 0x00
#define BH1750_CMD_RESET 0x07
#define BH1750_CMD_HIGH_RES_CONT 0x10
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define RELAY_GPIO 23

struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;
int i2c_file = -1;
FILE *log_file = NULL;

void cleanup_and_exit(int sig) {
    if (line)
        gpiod_line_set_value(line, 0);
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_file >= 0)
        close(i2c_file);
    if (log_file)
        fclose(log_file);
    exit(sig);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup_and_exit(-1);
    }

    line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(-1);
    }

    if (gpiod_line_request_output(line, "grow_light", 1)) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(-1);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("open");
        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, BH1750_ADDR)) {
        perror("ioctl");
        cleanup_and_exit(-1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup_and_exit(-1);
    }

    while (1) {
        if (write(i2c_file, &BH1750_CMD_POWER_ON, 1) != 1 ||
            write(i2c_file, &BH1750_CMD_RESET, 1) != 1 ||
            write(i2c_file, &BH1750_CMD_HIGH_RES_CONT, 1) != 1) {
            perror("write");
            continue;
        }

        usleep(120000);

        unsigned char buf[2];
        if (read(i2c_file, buf, 2) != 2) {
            perror("read");
            continue;
        }

        int lux = (buf[0] << 8) | buf[1];
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s, %d\n", timestamp, lux);
        fflush(log_file);

        if (lux < LUX_THRESHOLD) {
            if (gpiod_line_set_value(line, 1)) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }
        } else {
            if (gpiod_line_set_value(line, 0)) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(-1);
            }
        }

        sleep(2);
    }

    cleanup_and_exit(0);
}

