#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_DOUT 23
#define GPIO_SCK 24
#define GPIO_LOCK 25

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

struct gpiod_line *dout, *sck, *lock;
struct gpiod_chip *chip;
int threshold = DEFAULT_THRESHOLD;
double scale = DEFAULT_SCALE;
int duration = DEFAULT_DURATION;
int exit_flag = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        exit_flag = 1;
    }
}

void hx711_read(unsigned int *val) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_nsec += 1000000000;

    unsigned int sum = 0;
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck, 1);
        gpiod_line_set_value(sck, 0);

        if (gpiod_line_get_value(dout)) {
            sum |= 1 << (23 - i);
        }

        if (clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL) != 0) {
            syslog(LOG_ERR, "Timeout waiting for DOUT to go LOW");
            exit(EXIT_FAILURE);
        }
    }

    *val = sum;
}

void hx711_tare() {
    unsigned int sum = 0;
    for (int i = 0; i < 10; i++) {
        unsigned int val;
        hx711_read(&val);
        sum += val;
    }

    unsigned int tare = sum / 10;
    syslog(LOG_INFO, "Tare value: %u", tare);
}

int main(int argc, char *argv[]) {
    openlog("load_cell", LOG_PERROR, LOG_USER);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    dout = gpiod_chip_get_line(chip, GPIO_DOUT);
    sck = gpiod_chip_get_line(chip, GPIO_SCK);
    lock = gpiod_chip_get_line(chip, GPIO_LOCK);

    if (!dout || !sck || !lock) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(dout, "DOUT") ||
        gpiod_line_request_output(sck, "SCK", 0) ||
        gpiod_line_request_output(lock, "LOCK", 0)) {
        syslog(LOG_ERR, "Failed to request GPIO line directions");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    hx711_tare();

    while (!exit_flag) {
        unsigned int sum = 0;
        for (int i = 0; i < 5; i++) {
            unsigned int val;
            hx711_read(&val);
            sum += val;
        }

        int weight = (sum / 5) * scale;
        syslog(LOG_INFO, "Weight: %d", weight);

        if (weight > threshold) {
            gpiod_line_set_value(lock, 1);
            usleep(duration * 1000);
            gpiod_line_set_value(lock, 0);
        }

        sleep(0.5);
    }

    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(lock);
    gpiod_chip_close(chip);

    closelog();

    return 0;
}

