#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <mosquitto.h>

#define GPIO_LINE 17
#define MQTT_QOS 0
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENTID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_BROKER "localhost"

struct gpiod_line *line;
struct mosquitto *mosq;

void sig_handler(int signo) {
    if (mosquitto_disconnect(mosq) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to disconnect from MQTT broker");
    }
    mosquitto_destroy(mosq);
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_ctx_close();
    closelog();
    exit(signo);
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_connack_string(rc));
        return;
    }
    syslog(LOG_INFO, "Connected to MQTT broker");
    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic");
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (!msg->payloadlen || strncmp(msg->payload, "ON", msg->payloadlen) && strncmp(msg->payload, "OFF", msg->payloadlen)) {
        syslog(LOG_ERR, "Invalid payload: %.*s", (int)msg->payloadlen, (char *)msg->payload);
        return;
    }
    gpiod_line_set_value(line, !strncmp(msg->payload, "ON", msg->payloadlen));
}

int main() {
    openlog("mqtt_relay", LOG_CONS | LOG_NDELAY | LOG_PID, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    line = gpiod_line_request(GPIO_LINE, GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!line) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
    gpiod_line_set_value(line, 0);

    mosq = mosquitto_new(MQTT_CLIENTID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    while (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE) != MOSQ_ERR_SUCCESS) {
        sleep(5);
    }

    mosquitto_loop_forever(mosq, -1, 1);

    return 0;
}

