#include <unistd.h>
#include <pigpio.h>

#define GPIO_SERVO_1 7
#define GPIO_SERVO_2 8
#define GPIO_SERVO_3 9
#define GPIO_SERVO_4 10
#define GPIO_SERVO_5 11

#define PULSE_WIDTH_1 1000
#define PULSE_WIDTH_2 1500
#define PULSE_WIDTH_3 2000
#define PULSE_WIDTH_4 500
#define PULSE_WIDTH_5 2500

int main() {
    int servo_pins[5] = {GPIO_SERVO_1, GPIO_SERVO_2, GPIO_SERVO_3, GPIO_SERVO_4, GPIO_SERVO_5};
    int pulse_widths[5] = {PULSE_WIDTH_1, PULSE_WIDTH_2, PULSE_WIDTH_3, PULSE_WIDTH_4, PULSE_WIDTH_5};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 5; i++) {
        if (gpioSetPWMfrequency(servo_pins[i], 50) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMrange(servo_pins[i], 2000) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioPWM(servo_pins[i], pulse_widths[i]) < 0) {
            fprintf(stderr, "Failed to set PWM value for GPIO %d.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    sleep(3);

    for (int i = 0; i < 5; i++) {
        if (gpioPWM(servo_pins[i], 0) < 0) {
            fprintf(stderr, "Failed to stop PWM for GPIO %d.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio library.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

