#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_ONE_TIME_HIGH_RES 0x10

#define GPIO_PIN 17

int i2c_file;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;
FILE *log_file;

void cleanup_and_exit(int sig) {
    if (gpio_line)
        gpiod_line_release(gpio_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (i2c_file)
        close(i2c_file);
    if (log_file)
        fclose(log_file);
    exit(sig);
}

int main() {
    int ret;
    unsigned int lux;
    int relay_state = 0;

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Open I2C device
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        cleanup_and_exit(-1);
    }

    // Set I2C slave address
    ret = ioctl(i2c_file, I2C_SLAVE, BH1750_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    // Power on BH1750
    ret = write(i2c_file, &BH1750_CMD_POWER_ON, 1);
    if (ret < 0) {
        perror("Failed to power on BH1750");
        cleanup_and_exit(-1);
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup_and_exit(-1);
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup_and_exit(-1);
    }

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_and_exit(-1);
    }

    while (1) {
        // Read lux from BH1750
        ret = write(i2c_file, &BH1750_CMD_ONE_TIME_HIGH_RES, 1);
        if (ret < 0) {
            perror("Failed to issue BH1750 command");
            cleanup_and_exit(-1);
        }
        usleep(180000);
        ret = read(i2c_file, &lux, 2);
        if (ret < 0) {
            perror("Failed to read lux from BH1750");
            cleanup_and_exit(-1);
        }
        lux = (lux >> 2) * 1.2;

        // Update relay state
        if (lux < 50 && !relay_state) {
            gpiod_line_set_value(gpio_line, 1);
            relay_state = 1;
        } else if (lux > 200 && relay_state) {
            gpiod_line_set_value(gpio_line, 0);
            relay_state = 0;
        }

        // Log lux and relay state
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s: Lux = %u, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file);

        // Wait before next measurement
        sleep(5);
    }

    cleanup_and_exit(0);
}

