struct gpiod_chip *chip;
struct gpiod_line *touch_sensor, *relay;

int sensor_value, last_sensor_value, relay_state;

void sigint_handler(int signum) {
    gpiod_line_set_value(relay, 0);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    struct timespec ts;
    struct tm *timeinfo;
    time_t rawtime;
    char buffer[80];

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    touch_sensor = gpiod_chip_get_line(chip, 4);
    if (!touch_sensor) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    relay = gpiod_chip_get_line(chip, 17);
    if (!relay) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_input(touch_sensor, "touch_sensor")) {
        perror("gpiod_line_request_input");
        return 1;
    }

    if (gpiod_line_request_output(relay, "relay", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        sensor_value = gpiod_line_get_value(touch_sensor);

        if (sensor_value != last_sensor_value) {
            if (sensor_value == 1) {
                last_sensor_value = sensor_value;
                nanosleep((const struct timespec[]){{0, 50000000}}, &ts);
                sensor_value = gpiod_line_get_value(touch_sensor);
                if (sensor_value == last_sensor_value) {
                    relay_state = !relay_state;
                    gpiod_line_set_value(relay, relay_state);
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                    printf("%s: Relay is now %s\n", buffer, relay_state ? "ON" : "OFF");
                }
            } else {
                last_sensor_value = sensor_value;
            }
        }

        nanosleep((const struct timespec[]){{0, 10000000}}, &ts);
    }

    gpiod_line_release(relay);
    gpiod_line_release(touch_sensor);
    gpiod_chip_close(chip);

    return 0;
}

