#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define GPIO_FLOW_SENSOR 17
#define GPIO_SOLENOID 27
#define LPM_THRESHOLD_LOW 4.5
#define LPM_THRESHOLD_HIGH 5.0
#define LOG_FILE "water_flow.log"

struct gpiod_chip *chip;
struct gpiod_line *flow_sensor, *solenoid;
FILE *log_file;
pthread_mutex_t pulse_counter_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long pulse_counter = 0;

void log_message(const char *message) {
    time_t t = time(NULL);
    char *time_str = ctime(&t);
    time_str[strlen(time_str) - 1] = '\0';
    fprintf(log_file, "%s: %s\n", time_str, message);
    fflush(log_file);
}

void sig_handler(int signo) {
    log_message(signo == SIGINT ? "SIGINT received, shutting off solenoid" : "SIGTERM received, shutting off solenoid");
    gpiod_line_set_value(solenoid, 1);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_counter_mutex);
    gpiod_line_release(flow_sensor);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (chip == NULL) {
        log_message("Failed to open GPIO chip");
        goto cleanup;
    }

    flow_sensor = gpiod_chip_get_line(chip, GPIO_FLOW_SENSOR);
    if (flow_sensor == NULL) {
        log_message("Failed to get flow sensor line");
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(flow_sensor, "flow_sensor")) {
        log_message("Failed to request flow sensor events");
        goto cleanup;
    }

