#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *relay_line;
int debounce_time = 50;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("\nExiting...\n");
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    if (argc > 2) {
        printf("Usage: %s [-d debounce_time]\n", argv[0]);
        return -1;
    }
    if (argc == 2 && strncmp(argv[1], "-d", 2) == 0) {
        debounce_time = atoi(argv[1] + 2);
        if (debounce_time <= 0) {
            printf("Invalid debounce time\n");
            return -1;
        }
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    sensor_line = gpiod_chip_get_line(chip, 4);
    if (!sensor_line) {
        printf("Failed to get sensor line\n");
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, 17);
    if (!relay_line) {
        printf("Failed to get relay line\n");
        return -1;
    }

    if (gpiod_line_request_both_edges_events(sensor_line, "sensor")) {
        printf("Failed to request sensor line\n");
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0)) {
        printf("Failed to request relay line\n");
        return -1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int state = 0;
    struct timespec ts;
    while (1) {
        if (gpiod_line_event_wait(sensor_line, NULL)) {
            struct tm *timeinfo;
            time_t timer = time(NULL);
            char buffer[26];

            timeinfo = localtime(&timer);
            strftime(buffer, 26, "%Y-%m-%d %H:%M:%S", timeinfo);

            if (gpiod_line_get_value(sensor_line) == 1) {
                state = !state;
                gpiod_line_set_value(relay_line, state);
                printf("%s Relay: %s\n", buffer, state ? "ON" : "OFF");
            }
            nanosleep(&ts, NULL);
        }
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

