#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define PULSE_WIDTH_500 500
#define PULSE_WIDTH_2500 2500
#define PULSE_WIDTH_DEFAULT 1500
#define PULSE_WIDTH_INCREMENT 100
#define PULSE_WIDTH_MIN (PULSE_WIDTH_DEFAULT - (180 / 10 * PULSE_WIDTH_INCREMENT))
#define PULSE_WIDTH_MAX (PULSE_WIDTH_DEFAULT + (180 / 10 * PULSE_WIDTH_INCREMENT))

struct gpiod_chip *chip;
struct gpiod_line *line;
struct termios old_tio, new_tio;

int pw = PULSE_WIDTH_DEFAULT;

void exit_handler(int sig) {
    tcsetattr(STDIN_FILENO, TCSANOW, &old_tio);
    gpiod_line_set_pwm_duty_cycle(line, PULSE_WIDTH_DEFAULT);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, exit_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_pwm_mode(line, 50, PULSE_WIDTH_DEFAULT)) {
        perror("gpiod_line_request_pwm_mode");
        exit(1);
    }

    tcgetattr(STDIN_FILENO, &old_tio);
    new_tio = old_tio;
    new_tio.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_tio);

    while (1) {
        char c = getchar();
        switch (c) {
        case '+':
            if (pw + PULSE_WIDTH_INCREMENT <= PULSE_WIDTH_MAX)
                pw += PULSE_WIDTH_INCREMENT;
            break;
        case '-':
            if (pw - PULSE_WIDTH_INCREMENT >= PULSE_WIDTH_MIN)
                pw -= PULSE_WIDTH_INCREMENT;
            break;
        case 'q':
            exit_handler(0);
        }

        if (gpiod_line_set_pwm_duty_cycle(line, pw)) {
            perror("gpiod_line_set_pwm_duty_cycle");
            exit(1);
        }

        printf("Angle: %d\n", (pw - PULSE_WIDTH_DEFAULT + (180 / 10 * PULSE_WIDTH_INCREMENT)) / (PULSE_WIDTH_INCREMENT));
    }

    exit_handler(0);
}

