#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_LINE 17
#define DEBOUNCE_US 2000
#define INTERVAL_SEC 5

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;

void cleanup_and_exit(int signum)
{
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main(void)
{
    struct timespec start_time, current_time;
    unsigned long long pulse_count = 0;
    double elapsed_time, rpm;
    char log_line[100];
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_rising_edge_events(line, "conveyor_motor");
    if (ret) {
        fprintf(stderr, "Failed to request rising edge events: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_set_debounce(line, DEBOUNCE_US);
    if (ret) {
        fprintf(stderr, "Failed to set debounce: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen("motor_rpm.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            return 1;
        }

        pulse_count++;

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                       (current_time.tv_nsec - start_time.tv_nsec) * 1e-9;

        if (elapsed_time >= INTERVAL_SEC) {
            rpm = pulse_count / elapsed_time;

            strftime(log_line, sizeof(log_line), "%Y-%m-%dT%H:%M:%S", localtime(&current_time.tv_sec));
            snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line),
                     ", %.2f\n", rpm);

            fputs(log_line, log_file);
            fflush(log_file);

            printf("Current RPM: %.2f\n", rpm);

            pulse_count = 0;
            start_time = current_time;
        }
    }

    return 0;
}

