#include <stdio.h>
#include <signal.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_SENSOR 4
#define GPIO_RELAY 17

struct gpiod_chip *chip;
struct gpiod_line *sensor, *relay;

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int main() {
    struct timespec ts = {0, 50000000}; // 50 ms
    struct gpiod_line_request sensor_req, relay_req;
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2711");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    sensor = gpiod_chip_get_line(chip, GPIO_SENSOR);
    if (!sensor) {
        perror("gpiod_chip_get_line");
        ret = 1;
        goto cleanup_chip;
    }

    relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay) {
        perror("gpiod_chip_get_line");
        ret = 1;
        goto cleanup_sensor;
    }

    ret = gpiod_line_request_input(sensor, "sensor", &sensor_req);
    if (ret < 0) {
        perror("gpiod_line_request_input");
        goto cleanup_lines;
    }

    ret = gpiod_line_request_output(relay, "relay", &relay_req, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        goto cleanup_sensor_req;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        int sensor_val = gpiod_line_get_value(sensor);
        if (sensor_val < 0) {
            perror("gpiod_line_get_value");
            ret = 1;
            goto cleanup_relay_req;
        }

        nanosleep(&ts, NULL);

        int sensor_val_new = gpiod_line_get_value(sensor);
        if (sensor_val_new < 0) {
            perror("gpiod_line_get_value");
            ret = 1;
            goto cleanup_relay_req;
        }

        if (sensor_val == 0 && sensor_val_new == 1) {
            ret = gpiod_line_set_value(relay, !gpiod_line_get_value(relay));
            if (ret < 0) {
                perror("gpiod_line_set_value");
                ret = 1;
                goto cleanup_relay_req;
            }
        }
    }

cleanup_relay_req:
    gpiod_line_release(&relay_req);

cleanup_sensor_req:
    gpiod_line_release(&sensor_req);

cleanup_lines:
    gpiod_line_close(relay);
    gpiod_line_close(sensor);

cleanup_sensor:
    gpiod_line_close(sensor);

cleanup_chip:
    gpiod_chip_close(chip);

    return ret;
}

