#define MPR121_I2C_ADDR 0x5A
#define MPR121_TOUCH_STATUS_REG 0x04
#define MPR121_SOFT_RESET_REG 0x80
#define MPR121_SOFT_RESET_VAL 0x63
#define MPR121_FILTER_REG 0x2B
#define MPR121_TOUCH_THRESHOLD_REG 0x41
#define MPR121_RELEASE_THRESHOLD_REG 0x46
#define MPR121_CONFIG_REG 0x80
#define MPR121_CONFIG_VAL 0x00
#define MPR121_RUN_MODE 0x01

#define GPIO_PIN 17

int i2c_file;
int gpio_file;
int log_file;

void sigint_handler(int signum) {
    close(i2c_file);
    fprintf(log_file, "%s: Relay set to LOW due to SIGINT\n", asctime(localtime(&time(NULL))));
    fflush(log_file);
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    unsigned char reg[1] = {MPR121_SOFT_RESET_REG};
    unsigned char val[1] = {MPR121_SOFT_RESET_VAL};

    if (write(i2c_file, reg, 1) != 1 || write(i2c_file, val, 1) != 1) {
        perror("Failed to write to I2C device");
        return 1;
    }

    reg[0] = MPR121_FILTER_REG;
    val[0] = 0x0A;

    if (write(i2c_file, reg, 1) != 1 || write(i2c_file, val, 1) != 1) {
        perror("Failed to write to I2C device");
        return 1;
    }

    for (int i = 0; i < 12; i++) {
        reg[0] = MPR121_TOUCH_THRESHOLD_REG + i;
        val[0] = 0x14;

        if (write(i2c_file, reg, 1) != 1 || write(i2c_file, val, 1) != 1) {
            perror("Failed to write to I2C device");
            return 1;
        }

        reg[0] = MPR121_RELEASE_THRESHOLD_REG + i;
        val[0] = 0x0E;

        if (write(i2c_file, reg, 1) != 1 || write(i2c_file, val, 1) != 1) {
            perror("Failed to write to I2C device");
            return 1;
        }
    }

    reg[0] = MPR121_CONFIG_REG;
    val[0] = MPR121_CONFIG_VAL;

    if (write(i2c_file, reg, 1) != 1 || write(i2c_file, val, 1) != 1) {
        perror("Failed to write to I2C device");
        return 1;
    }

    reg[0] = MPR121_RUN_MODE;

    if (write(i2c_file, reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return 1;
    }

    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    unsigned char touch_status[1];
    int prev_state = 0;

    while (1) {
        if (read(i2c_file, touch_status, 1) != 1) {
            perror("Failed to read from I2C device");
            return 1;
        }

        int curr_state = *touch_status & 0x01;

        if (curr_state != prev_state) {
            if (curr_state) {
                fprintf(log_file, "%s: Relay set to HIGH\n", asctime(localtime(&time(NULL))));
            } else {
                fprintf(log_file, "%s: Relay set to LOW\n", asctime(localtime(&time(NULL))));
            }

            fflush(log_file);
            prev_state = curr_state;
        }

        usleep(50000);
    }

    return 0;
}

