#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_ADDRESS 0x5A
#define I2C_FILE "/dev/i2c-1"
#define GPIO_FILE "/sys/class/gpio/gpio17/value"

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

int i2c_write(int file, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(file, buf, 2) != 2) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(int file, uint8_t reg, uint8_t *val) {
    if (write(file, &reg, 1) != 1) {
        perror("i2c_read (write reg)");
        return -1;
    }
    if (read(file, val, 1) != 1) {
        perror("i2c_read (read val)");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    int i2c_file = open(I2C_FILE, O_RDWR);
    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return -1;
    }

    int gpio_file = open(GPIO_FILE, O_RDWR);

    if (i2c_write(i2c_file, 0x2B, 0x00) < 0 || // Set all touch thresholds to 0
        i2c_write(i2c_file, 0x2C, 0x00) < 0 || // Set all release thresholds to 0
        i2c_write(i2c_file, 0x2E, 0x00) < 0 || // Set filter to none
        i2c_write(i2c_file, 0x2F, 0x00) < 0 || // Set charge time to 100us
        i2c_write(i2c_file, 0x30, 0x00) < 0) { // Set electrode current to 1 uA
        return -1;
    }

    sleep(1);

    if (i2c_write(i2c_file, 0x4F, 0x00) < 0) { // Switch to run mode
        return -1;
    }

    while (!stop) {
        uint8_t touch_status;
        if (i2c_read(i2c_file, 0x0, &touch_status) < 0) {
            return -1;
        }

        if (touch_status > 0) {
            char gpio_val = '0' + (getchar() == '1');
            if (write(gpio_file, &gpio_val, 1) != 1) {
                perror("write GPIO");
                return -1;
            }
            printf("Relay toggled to %c\n", gpio_val);
        }

