void log_message(const char *message) {
    time_t t = time(NULL);
    char *time_str = ctime(&t);
    time_str[strlen(time_str) - 1] = '\0'; // remove trailing newline
    syslog(LOG_INFO, "%s: %s", time_str, message);
}

void cleanup_and_exit(int exit_code) {
    gpiod_line_set_value(motor_in1, 0);
    gpiod_line_set_value(motor_in2, 0);
    gpiod_line_release(motor_in1);
