#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <unistd.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define TIMEOUT_US 10000
#define WEIGHT_THRESHOLD 100
#define LOCK_DURATION 5

struct gpiod_chip *chip;
struct gpiod_line *dt_line, *sck_line, *lock_line;
FILE *log_file;

void log_message(const char *msg) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

void cleanup_and_exit(int signum) {
    gpiod_line_release(dt_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(lock_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    dt_line = gpiod_chip_get_line(chip, DT_PIN);
    if (!dt_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    if (!sck_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_input(dt_line, "DT", TIMEOUT_US) < 0) {
        perror("gpiod_line_request_input");
        return 1;
    }

    if (gpiod_line_request_output(sck_line, "SCK", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_request_output(lock_line, "LOCK", 0) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    log_file = fopen("stock_events.txt", "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        int weight = 0;
        for (int i = 0; i < 24; i++) {
            gpiod_line_set_value(sck_line, 1);
            usleep(TIMEOUT_US);
            gpiod_line_set_value(sck_line, 0);
            usleep(TIMEOUT_US);
            weight = (weight << 1) | gpiod_line_get_value(dt_line);
        }

        log_message(weight < WEIGHT_THRESHOLD ? "Low stock level" : "Normal stock level");

        if (weight < WEIGHT_THRESHOLD) {
            gpiod_line_set_value(lock_line, 1);
            log_message("Activating solenoid lock");
            sleep(LOCK_DURATION);
            gpiod_line_set_value(lock_line, 0);
            log_message("Deactivating solenoid lock");
        }
    }

    return 0;
}

