#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_DATA 4
#define GPIO_CLOCK 17
#define GPIO_LOCK 27
#define THRESHOLD 5000000

struct gpiod_chip *chip;
struct gpiod_line *data, *clock, *lock;
FILE *calibration_file, *log_file;
int calibration_factor;

void cleanup_and_exit(int signum) {
    fclose(log_file);
    gpiod_line_set_value(lock, 0);
    gpiod_line_release(data);
    gpiod_line_release(clock);
    gpiod_line_release(lock);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    data = gpiod_chip_get_line(chip, GPIO_DATA);
    clock = gpiod_chip_get_line(chip, GPIO_CLOCK);
    lock = gpiod_chip_get_line(chip, GPIO_LOCK);
    if (!data || !clock || !lock) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_output(data, "data", 0) ||
        gpiod_line_request_output(clock, "clock", 0) ||
        gpiod_line_request_output(lock, "lock", 0)) {
        perror("gpiod_line_request_output");
        return 1;
    }

    calibration_file = fopen("calibration.txt", "r");
    if (!calibration_file) {
        perror("fopen");
        return 1;
    }
    fscanf(calibration_file, "%d", &calibration_factor);
    fclose(calibration_file);

    log_file = fopen("security.log", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, cleanup_and_exit);

    while (1) {
        int value = 0;
        for (int i = 0; i < 24; i++) {
            gpiod_line_set_value(clock, 1);
            usleep(1);
            value |= gpiod_line_get_value(data) << (23 - i);
            gpiod_line_set_value(clock, 0);
            usleep(1);
        }

        if (value > THRESHOLD * calibration_factor) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s %d\n", timestamp, value / calibration_factor);

            gpiod_line_set_value(lock, 1);
            sleep(5);
            gpiod_line_set_value(lock, 0);
        }
    }

    cleanup_and_exit(0);
    return 0;
}

