#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *relay_line;
FILE *log_file;

void handle_signal(int signum) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;
    struct timespec ts;
    struct tm *timeinfo;
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_input(sensor_line, "sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line: %s\n", strerror(errno));
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request relay line: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        ret = gpiod_line_get_value(sensor_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor: %s\n", strerror(errno));
            continue;
        }

        if (ret) {
            clock_gettime(CLOCK_REALTIME, &ts);
            timeinfo = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            gpiod_line_set_value(relay_line, !gpiod_line_get_value(relay_line));

            fprintf(log_file, "%s: Relay toggled to %s\n", timestamp, gpiod_line_get_value(relay_line) ? "ON" : "OFF");
            fflush(log_file);
        }
    }

    return 0;
}

