#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

struct gpiod_chip *chip;
struct gpiod_line *line;
int conf_duration;
volatile sig_atomic_t sig_flag = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        sig_flag = 1;
    }
}

void parse_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    char line_buf[256];
    if (!fgets(line_buf, sizeof(line_buf), file)) {
        fprintf(stderr, "Error reading file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    char *end;
    conf_duration = strtol(line_buf, &end, 10);
    if (end == line_buf || *end != '\n' || conf_duration < 1 || conf_duration > 3600) {
        fprintf(stderr, "Invalid duration in file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

void setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 18);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(line, "valve_controller", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line to low\n");
        exit(EXIT_FAILURE);
    }

    printf("Valve is off\n");
}

void run_controller() {
    while (!sig_flag) {
        int ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line to high\n");
            exit(EXIT_FAILURE);
        }

        printf("Valve is on for %d seconds\n", conf_duration);
        sleep(conf_duration);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line to low\n");
            exit(EXIT_FAILURE);
        }

        printf("Valve is off\n");
    }
}

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

int main() {
    parse_config("watering.conf");
    setup_gpio();

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    run_controller();
    cleanup();

    return 0;
}

