#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pthread.h>

#define LOG_FILE_NAME "trace_log.txt"
#define SENSOR_FREQ_HZ 100
#define PWM_FREQ_HZ 1000
#define STRAIGHT_SPEED 150
#define MAX_SPEED 255

struct gpiod_chip *chip;
struct gpiod_line *sensor_lines[3];
struct gpiod_line *pwm_lines[4];
FILE *log_file;
pthread_t sensor_thread;
volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

void log_data(int sensor_states[3], int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm *local = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", local);
    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, sensor_states[0], sensor_states[1], sensor_states[2], left_speed, right_speed);
}

void *sensor_loop(void *unused) {
    int sensor_states[3];
    int left_speed, right_speed;
    while (!stop_flag) {
        for (int i = 0; i < 3; i++)
            sensor_states[i] = !gpiod_line_get_value(sensor_lines[i]);
        if (sensor_states[1]) {
            left_speed = right_speed = STRAIGHT_SPEED;
        } else if (sensor_states[0]) {
            left_speed = STRAIGHT_SPEED / 2;
            right_speed = STRAIGHT_SPEED;
        } else if (sensor_states[2]) {
            left_speed = STRAIGHT_SPEED;
            right_speed = STRAIGHT_SPEED / 2;
        } else {
            left_speed = right_speed = 0;
        }
        gpiod_line_set_value(pwm_lines[0], left_speed > 0);
        gpiod_line_set_value(pwm_lines[1], right_speed > 0);
        log_data(sensor_states, left_speed, right_speed);
        usleep((1000000 / SENSOR_FREQ_HZ) * 1000);
    }
    gpiod_line_set_value(pwm_lines[0], 0);
    gpiod_line_set_value(pwm_lines[1], 0);
    return NULL;
}

int main() {
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }
    sensor_lines[0] = gpiod_chip_get_line(chip, 4);
    sensor_lines[1] = gpiod_chip_get_line(chip, 17);
    sensor_lines[2] = gpiod_chip_get_line(chip, 27);
    pwm_lines[0] = gpiod_chip_get_line(chip, 22);
    pwm_lines[1] = gpiod_chip_get_line(chip, 23);
    pwm_lines[2] = gpiod_chip_get_line(chip, 24);
    pwm_lines[3] = gpiod_chip_get_line(chip, 25);
    if (!sensor_lines[0] || !sensor_lines[1] || !sensor_lines[2] || !pwm_lines[0] || !pwm_lines[1] || !pwm_lines[2] || !pwm_lines[3]) {
        perror("gpiod_chip_get_line");
        return EXIT_FAILURE;
    }
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_input(sensor_lines[i])) {
            perror("gpiod_line_request_input");
            return EXIT_FAILURE;
        }
    }
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(pwm_lines[i], "pwm", 0)) {
            perror("gpiod_line_request_output");
            return EXIT_FAILURE;
        }
    }
    log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    signal(SIGINT, sigint_handler);
    pthread_create(&sensor_thread, NULL, sensor_loop, NULL);
    pthread_join(sensor_thread, NULL);
    fclose(log_file);
    for (int i = 0; i < 3; i++)
        gpiod_line_release(sensor_lines[i]);
    for (int i = 0; i < 4; i++)
        gpiod_line_release(pwm_lines[i]);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

