    exit(0);
}

int main() {
    int i2c_file, lux;
    char buf[2];
    struct i2c_msg msgs[] = {
        {BH1750_ADDR, I2C_M_WR, 1, &BH1750_CMD_ONE_TIME_H_RES},
        {BH1750_ADDR, I2C_M_RD, 2, buf},
    };

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        exit(1);
    }

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        log_message("Failed to open I2C device file.");
        exit(1);
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip.");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, 23);
    if (!line) {
        log_message("Failed to get GPIO line.");
        exit(1);
    }

    if (gpiod_line_request_output(line, "grow_lamp", GPIO_RESET_VALUE)) {
        log_message("Failed to request GPIO line as output.");
        exit(1);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (i2c_transfer(i2c_file, sizeof(msgs) / sizeof(msgs[0]), msgs) < 0) {
            log_message("Failed to read lux from BH1750 sensor.");
            continue;
        }

        lux = (buf[0] << 8) | buf[1];
        log_message("Lux reading: ");
        log_message(lux);

        if (lux < LUX_THRESHOLD) {
            if (gpiod_line_get_value(line) == GPIO_RESET_VALUE) {
                gpiod_line_set_value(line, !GPIO_RESET_VALUE);
                log_message("Lux level below threshold, turning on relay.");
            }
        } else {
            if (gpiod_line_get_value(line) != GPIO_RESET_VALUE) {
                gpiod_line_set_value(line, GPIO_RESET_VALUE);
                log_message("Lux level above threshold, turning off relay.");
            }
        }

        usleep(BH1750_MEASURE_DELAY);
    }

    return 0;
}
