            if (gpiod_line_get_value(gpio_sound_sensor) == 0) {
                zmq_send(zmq_socket, ZMQ_SOUND_ALERTS, strlen(ZMQ_SOUND_ALERTS), 0);
            }
            usleep(10000);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        gpio_alarm_led = gpiod_chip_get_line(GPIO_CHIP, GPIO_ALARM_LED);
        if (!gpio_alarm_led) {
            printf("Failed to get alarm led line\n");
            return -1;
