        if (gpiod_line_request_output(gpio_alarm_led, "alarm_led", 0)) {
            printf("Failed to request output for alarm led\n");
            return -1;
        }

        zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            printf("Failed to create zmq context\n");
            return -1;
        }

        zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (!zmq_socket) {
            printf("Failed to create zmq socket\n");
            return -1;
        }

        if (zmq_connect(zmq_socket, ZMQ_SOCKET_ADDR) == -1) {
            printf("Failed to connect zmq socket\n");
            return -1;
