        if (zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, ZMQ_SOUND_ALERTS, strlen(ZMQ_SOUND_ALERTS)) == -1) {
            printf("Failed to set zmq socket option\n");
            return -1;
        }

        signal(SIGINT, cleanup_and_exit);
        signal(SIGTERM, cleanup_and_exit);

        while (1) {
            char buffer[100];
            zmq_recv(zmq_socket, buffer, 100, 0);
            if (strcmp(buffer, ZMQ_SOUND_ALERTS) == 0) {
                gpiod_line_set_value(gpio_alarm_led, 1);
                usleep(1000000);
                gpiod_line_set_value(gpio_alarm_led, 0);
            }
        }
    } else {
        printf("Invalid mode\n");
        return -1;
    }

    return 0;
}

