#include <paho_mqtt/subscribe.h>

#define GPIO_LINE 17
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

struct gpiod_line *line;
struct gpiod_chip *chip;
struct mqtt_client *client;

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        stop = 1;
    }
}

void decode_ir(struct gpiod_line *line) {
    // TODO: Implement IR decoding and checksum validation
}

void publish_command(uint32_t command) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"command\": %u}", command);

    struct mqtt_publish_param param;
    param.dup = 0;
    param.qos = MQTT_QOS0;
    param.retain = 0;
    param.topic = MQTT_TOPIC;
    param.payload = payload;
    param.payloadlen = strlen(payload);

    int rc = mqtt_publish(client, &param);
    if (rc != MQTT_OK) {
        syslog(LOG_ERR, "Failed to publish command: %d", rc);
    }
}

int main() {
    openlog("ir_decoder", LOG_PERROR, LOG_USER);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %m");
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(line, "ir_decoder")) {
        syslog(LOG_ERR, "Failed to request falling edge events: %m");
        return 1;
    }

    struct mqtt_connect_param param;
    param.client_id = "ir_decoder";
    param.clean_session = 1;
    param.keep_alive = 10;
    param.will = NULL;
    param.username = NULL;
    param.password = NULL;

    client = mqtt_client_new();
    if (!client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return 1;
    }

    if (mqtt_client_connect(client, "localhost", MQTT_PORT, &param) != MQTT_OK) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        if (gpiod_line_event_wait(line, NULL) == 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event)) {
                syslog(LOG_ERR, "Failed to read GPIO event: %m");
                continue;
            }

            decode_ir(line);
        }

        mqtt_client_yield(client, 100);
    }

    mqtt_client_disconnect(client);
    mqtt_client_free(client);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    closelog();

    return 0;
}

