#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_ONCE 0x10
#define BH1750_SLEEP_MS 180
#define UDP_PORT 5005
#define UDP_MULTICAST_ADDR "239.255.255.250"

volatile sig_atomic_t terminate = 0;

void handle_signal(int signum) {
    terminate = 1;
}

int main() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c-1");
        return EXIT_FAILURE;
    }

    int udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_PORT);

    if (connect(udp_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(i2c_fd);
        close(udp_fd);
        return EXIT_FAILURE;
    }

    struct ip_mreq mreq;
    mreq.imr_multiaddr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);
    if (setsockopt(udp_fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("setsockopt");
        close(i2c_fd);
        close(udp_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char buffer[100];
    int len;
    while (!terminate) {
        for (int i = 0; i < 4; i++) {
            if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR + i) < 0) {
                fprintf(stderr, "ioctl I2C_SLAVE failed for sensor %d\n", i);
                sprintf(buffer + strlen(buffer), "%d,NaN;", i);
                continue;
            }

            if (write(i2c_fd, &BH1750_CMD_ONCE, 1) != 1) {
                fprintf(stderr, "write failed for sensor %d\n", i);
                sprintf(buffer + strlen(buffer), "%d,NaN;", i);
                continue;
            }

            usleep(BH1750_SLEEP_MS * 1000);

            if (read(i2c_fd, buffer + strlen(buffer), 2) != 2) {
                fprintf(stderr, "read failed for sensor %d\n", i);
                sprintf(buffer + strlen(buffer), "%d,NaN;", i);
                continue;
            }

            int lux = (buffer[strlen(buffer) - 2] << 8) | buffer[strlen(buffer) - 1];
            sprintf(buffer + strlen(buffer), "%d,%d;", i, lux);
        }

        len = strlen(buffer);
        buffer[len - 1] = '\0';  // remove trailing semicolon
        if (send(udp_fd, buffer, strlen(buffer), 0) != strlen(buffer)) {
            perror("send");
        }

        buffer[0] = '\0';
        sleep(1);
    }

    close(i2c_fd);
    close(udp_fd);
    return EXIT_SUCCESS;
}

