#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define SENSOR_ADDRESS 0x30
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "airflow_log.txt"

static FILE *log_file;
static int i2c_fd;

void sigint_handler(int signum) {
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    while (1) {
        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) == -1) {
            fprintf(stderr, "Failed to set sensor address: %s\n", strerror(errno));
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        unsigned char buffer[2];
        int retries = 0;
        while (retries < 3) {
            if (write(i2c_fd, NULL, 0) == -1) {
                if (errno == EIO || errno == ENXIO) {
                    fprintf(stderr, "Transient I2C error, retrying: %s\n", strerror(errno));
                    usleep(100000);
                    retries++;
                } else {
                    fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
                    fclose(log_file);
                    close(i2c_fd);
                    return 1;
                }
            } else {
                break;
            }
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        int airflow = (buffer[0] << 8) | buffer[1];
        airflow &= 0x3FFF;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d SLPM\n", timestamp, airflow);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

