#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>

#define AS7341_ADDR 0x39
#define ID_REG 0x00
#define EXPECTED_ID 0x41
#define ENABLE_REG 0x02
#define CFG6_REG 0x0C
#define SP_EN_BIT 0x01
#define PON_BIT 0x02
#define NUM_CHANNELS 10

int fd, log_fd;
volatile sig_atomic_t stop;

void cleanup(void) {
    close(fd);
    fdatasync(log_fd);
    close(log_fd);
    exit(0);
}

void handle_sigint(int signum) {
    stop = 1;
}

int i2c_read(int reg, uint8_t *buf, int len) {
    struct i2c_msg msgs[] = {
        {AS7341_ADDR, 0, 1, &reg},
        {AS7341_ADDR, I2C_M_RD, len, buf},
    };
    if(i2c_rdwr(fd, msgs, 2) != 2) {
        perror("i2c_rdwr");
        return -1;
    }
    return 0;
}

int i2c_write(int reg, uint8_t val) {
    struct i2c_msg msgs[] = {
        {AS7341_ADDR, 0, 2, (uint8_t[]){reg, val}},
    };
    if(i2c_rdwr(fd, msgs, 1) != 1) {
        perror("i2c_rdwr");
        return -1;
    }
    return 0;
}

int main(void) {
    fd = open("/dev/i2c-1", O_RDWR);
    if(fd < 0) {
        perror("open");
        return 1;
    }

    if(ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    uint8_t id;
    if(i2c_read(ID_REG, &id, 1) < 0 || id != EXPECTED_ID) {
        fprintf(stderr, "AS7341 not found\n");
        return 1;
    }

    if(i2c_write(ENABLE_REG, PON_BIT) < 0)
        return 1;

    if(i2c_write(CFG6_REG, 0x00) < 0)
        return 1;

    if(i2c_write(ENABLE_REG, PON_BIT | SP_EN_BIT) < 0)
        return 1;

    log_fd = open("spectral_log.csv", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if(log_fd < 0) {
        perror("open");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    atexit(cleanup);

    uint8_t spectral_data[NUM_CHANNELS];
    while(!stop) {
        if(i2c_read(0x86, spectral_data, NUM_CHANNELS) < 0)
            continue;

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        dprintf(log_fd, "%s,", timestamp);
        for(int i = 0; i < NUM_CHANNELS; i++)
            dprintf(log_fd, "%u,", spectral_data[i]);
        dprintf(log_fd, "\n");

        sleep(5);
    }

    return 0;
}

