#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <errno.h>

#define DEFAULT_I2C_ADDRESS 0x28
#define DEFAULT_SAMPLE_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"

#define RETRY_COUNT 3
#define BACKOFF_US 10000

int i2c_fd = -1;
FILE *csv_file = NULL;
FILE *error_file = NULL;

int i2c_address = DEFAULT_I2C_ADDRESS;
int sample_interval = DEFAULT_SAMPLE_INTERVAL;
char *filename = DEFAULT_FILENAME;

void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    exit(signum);
}

void handle_sigint(int signum) {
    cleanup_and_exit(signum);
}

void handle_sigterm(int signum) {
    cleanup_and_exit(signum);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sample_interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
