#define BH1750_ADDR 0x23
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_ONE_TIME_HIGH_RES 0x10

#define I2C_DEV_PATH "/dev/i2c-1"
#define UDP_MCAST_ADDR "239.255.255.250"
#define UDP_MCAST_PORT 5000

static int i2c_fd = -1;
static int sock_fd = -1;

static void cleanup_and_exit(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (sock_fd != -1) {
        close(sock_fd);
    }
    exit(signum);
}

int main() {
    struct sockaddr_in mcast_addr;
    struct ip_mreq mreq;
    struct sigaction act;
    int retry_count = 0;

    act.sa_handler = cleanup_and_exit;
    sigemptyset(&act.sa_mask);
    act.sa_flags = 0;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    i2c_fd = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        cleanup_and_exit(-1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        cleanup_and_exit(-1);
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd == -1) {
        perror("Failed to create socket");
        cleanup_and_exit(-1);
    }

    mcast_addr.sin_family = AF_INET;
    mcast_addr.sin_port = htons(UDP_MCAST_PORT);
    mcast_addr.sin_addr.s_addr = inet_addr(UDP_MCAST_ADDR);

    if (connect(sock_fd, (struct sockaddr*)&mcast_addr, sizeof(mcast_addr)) == -1) {
        perror("Failed to connect socket to multicast address");
        cleanup_and_exit(-1);
    }

    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &(int){1}, sizeof(int)) == -1) {
        perror("Failed to set socket TTL");
        cleanup_and_exit(-1);
    }

    mreq.imr_multiaddr.s_addr = inet_addr(UDP_MCAST_ADDR);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);

    if (setsockopt(sock_fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) == -1) {
        perror("Failed to join multicast group");
        cleanup_and_exit(-1);
    }

    while (1) {
        char buf[2];
        float lux;

        if (write(i2c_fd, &BH1750_CMD_POWER_ON, 1) != 1 ||
            write(i2c_fd, &BH1750_CMD_ONE_TIME_HIGH_RES, 1) != 1) {
            fprintf(stderr, "I2C write error, retrying\n");
            sleep(1);
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read error, retrying\n");
            sleep(1);
            continue;
        }

        lux = (buf[0] << 8 | buf[1]) * 0.045;
        char msg[32];
        sprintf(msg, "%f", lux);

        if (send(sock_fd, msg, strlen(msg), 0) != strlen(msg)) {
            fprintf(stderr, "Failed to send UDP message\n");
        }

        sleep(1);
    }

    return 0;
}

