        printf("Failed to get UART options: %s\n", strerror(errno));
        return errno;
    }

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~(PARENB | PARODD);
    options.c_cflag |= CS8;
    cfsetispeed(&options, BAUD);
    cfsetospeed(&options, BAUD);

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        printf("Failed to set UART options: %s\n", strerror(errno));
        return errno;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    char line_buf[LINE_BUF_SIZE];
    int line_buf_len = 0;

    while (1) {
        struct timeval timeout;
        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = TIMEOUT_USEC;

        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        int select_result = select(fd + 1, &fds, NULL, NULL, &timeout);
        if (select_result < 0) {
            printf("Select failed: %s\n", strerror(errno));
            return errno;
        } else if (select_result == 0) {
            printf("Select timed out\n");
            continue;
        }

        char buf[1];
        int read_result = read(fd, buf, 1);
        if (read_result < 0) {
            printf("Read failed: %s\n", strerror(errno));
            return errno;
        } else if (read_result == 0) {
            printf("Read timed out\n");
            continue;
        }

        if (buf[0] == '\n') {
            line_buf[line_buf_len] = '\0';
            char *line = strdup(line_buf);
            if (!line) {
                printf("Failed to duplicate line: %s\n", strerror(errno));
                return errno;
            }

            char *timestamp_str = strtok(line, ",");
            char *range_str = strtok(NULL, ",");
            if (!timestamp_str || !range_str) {
                printf("Invalid line format\n");
                free(line);
                continue;
            }

            time_t timestamp = atol(timestamp_str);
            double range = atof(range_str);

            struct tm *timeinfo = localtime(&timestamp);
            char timestamp_buf[30];
            strftime(timestamp_buf, 30, "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("Timestamp: %s, Range: %.2f meters\n", timestamp_buf, range);

            free(line);
            line_buf_len = 0;
        } else {
            if (line_buf_len >= LINE_BUF_SIZE - 1) {
                printf("Line buffer overflow\n");
                line_buf_len = 0;
            } else {
                line_buf[line_buf_len++] = buf[0];
            }
        }
    }

    return 0;
}
